def _app_dir() -> Path:
    """Return the directory next to the script/executable — persistent across restarts.
    When frozen by PyInstaller, __file__ points to a temp _MEIxxxxxx folder that is
    deleted on exit. sys.executable points to the actual .exe, which is what we want."""
    if getattr(sys, 'frozen', False):
        return Path(sys.executable).resolve().parent
    return Path(__file__).resolve().parent

# ── Logging ───────────────────────────────────────────────────────────────────
def _setup_logging() -> logging.Logger:
    log_path = _app_dir() / 'speedtest_monitor.log'
    logger = logging.getLogger('NM')
    logger.setLevel(logging.DEBUG)
    if logger.handlers:
        return logger  # already configured
    fmt = logging.Formatter(
        '%(asctime)s [%(levelname)s] %(threadName)s | %(message)s',
        datefmt='%Y-%m-%d %H:%M:%S')
    # Rotating file handler — max 5 MB, keep 3 backups
    try:
        from logging.handlers import RotatingFileHandler
        fh = RotatingFileHandler(log_path, maxBytes=5*1024*1024,
                                 backupCount=3, encoding='utf-8')
        # INFO by default; the Settings "Debug logging" toggle raises this to
        # DEBUG, which turns on full tracebacks for swallowed exceptions.
        fh.setLevel(logging.INFO)
        fh.setFormatter(fmt)
        fh.set_name('nm_file')
        logger.addHandler(fh)
    except Exception as e:
        print(f'[NM] Could not open log file {log_path}: {e}')
    # Console handler — INFO+ only so the terminal isn't flooded
    ch = logging.StreamHandler(sys.stdout)
    ch.setLevel(logging.INFO)
    ch.setFormatter(fmt)
    logger.addHandler(ch)
    logger.info(f'Logging started — log file: {log_path}')
    return logger

log = _setup_logging()


def _nm_set_debug_logging(enabled: bool):
    """Turn verbose debug logging (incl. swallowed-exception tracebacks) on or
    off at runtime by adjusting the log FILE handler. The console stays at INFO
    so the terminal is never flooded. Returns the level actually applied."""
    lvl = logging.DEBUG if enabled else logging.INFO
    try:
        for h in log.handlers:
            if getattr(h, 'name', '') == 'nm_file' or h.__class__.__name__ == 'RotatingFileHandler':
                h.setLevel(lvl)
        log.info('Debug logging %s', 'ENABLED' if enabled else 'disabled')
    except Exception:
        _exc('_nm_set_debug_logging')
    return lvl

def _exc(context: str = ''):
    """Log the current exception with full traceback. Call from except blocks."""
    msg = f'{context}: {traceback.format_exc().strip()}' if context else traceback.format_exc().strip()
    log.error(msg)


# Ready-made Berkeley Packet Filter capture expressions, shared by the EtherApe
# and Wireshark capture windows. Blank = capture everything. Both dropdowns are
# editable, so a custom expression can still be typed.
# ── VPN tunnel detection ─────────────────────────────────────────────────────
# The previous attempt looked for a process called nordvpn* with an ESTABLISHED
# connection. That never worked: the NordVPN *service* keeps connections open to
# Nord's own API (account checks, server lists) even while you are disconnected,
# so it reported ACTIVE permanently. net_connections() also needs admin on
# Windows and silently returned AccessDenied.
#
# Adapter presence is not enough either — NordLynx stays up and keeps its IP
# when disconnected. The deciding signal is whether the tunnel interface is
# actually moving bytes, so that is what this measures.
_NM_VPN_PATTERNS = [
    (r'nordlynx|nordvpn',            'NordVPN'),
    (r'proton',                      'Proton VPN'),
    (r'expressvpn',                  'ExpressVPN'),
    (r'mullvad',                     'Mullvad'),
    (r'tailscale|\bts\d',            'Tailscale'),
    (r'wireguard|\bwg\d',            'WireGuard'),
    (r'openvpn|tap-windows|\btap\b', 'OpenVPN'),
    (r'\btun\d*\b',                  'VPN tunnel'),
]
_NM_VPN_STATE = {'samples': {}, 'last_traffic': {}}
_NM_VPN_IDLE_GRACE = 20.0     # only used when the machine is completely idle
_NM_VPN_BYPASS_RATE = 2048    # physical-NIC bytes/s that counts as "real traffic"


def _nm_vpn_status():
    """Report whether a VPN tunnel is up and carrying traffic.

    Returns {'active', 'iface', 'provider', 'reason', 'rx_rate', 'ip'}.
    Safe to call often; it keeps a small amount of state between calls so it
    can measure throughput.
    """
    import re as _re
    now = time.time()
    out = {'active': False, 'iface': '', 'provider': '', 'ip': '',
           'rx_rate': 0, 'reason': 'no VPN adapter present'}
    try:
        import psutil as _ps
        stats = _ps.net_if_stats()
        addrs = _ps.net_if_addrs()
        io = _ps.net_io_counters(pernic=True)
    except Exception:
        out['reason'] = 'psutil unavailable'
        return out

    cands, physical = [], []
    for nic in stats:
        low = str(nic).lower()
        hit = None
        for pat, prov in _NM_VPN_PATTERNS:
            try:
                if _re.search(pat, low):
                    hit = prov
                    break
            except Exception:
                continue
        if hit:
            cands.append((nic, hit))
        elif not _re.search(r'^lo$|loopback|^docker|^br-|^veth', low):
            physical.append(nic)
    if not cands:
        return out

    # Throughput on the ordinary adapters. If they are busy while the tunnel is
    # silent, traffic is bypassing the tunnel — that is a disconnect, and it is
    # provable on the very next poll instead of waiting for a timeout.
    phys_rate = 0
    for nic in physical:
        c = io.get(nic)
        if not c:
            continue
        rx, tx = int(getattr(c, 'bytes_recv', 0) or 0), int(getattr(c, 'bytes_sent', 0) or 0)
        prev = _NM_VPN_STATE['samples'].get('phys:' + nic)
        _NM_VPN_STATE['samples']['phys:' + nic] = (rx, tx, now)
        if prev and now > prev[2]:
            phys_rate += max(0, int(((rx - prev[0]) + (tx - prev[1])) / (now - prev[2])))

    best = None
    for nic, prov in cands:
        st = stats.get(nic)
        up = bool(st and getattr(st, 'isup', False))
        ip = ''
        for a in addrs.get(nic, []) or []:
            fam = getattr(a.family, 'name', str(a.family))
            addr = getattr(a, 'address', '') or ''
            # APIPA means the tunnel never got a lease — treat as no address
            if fam == 'AF_INET' and addr and not addr.startswith(('169.254.', '0.')):
                ip = addr
                break
        counters = io.get(nic)
        rx = int(getattr(counters, 'bytes_recv', 0) or 0)
        tx = int(getattr(counters, 'bytes_sent', 0) or 0)
        prev = _NM_VPN_STATE['samples'].get(nic)
        _NM_VPN_STATE['samples'][nic] = (rx, tx, now)
        rate = 0
        if prev and now > prev[2]:
            dt = now - prev[2]
            rate = max(0, int(((rx - prev[0]) + (tx - prev[1])) / dt))
        if rate > 0:
            _NM_VPN_STATE['last_traffic'][nic] = now
        rec = {'iface': nic, 'provider': prov, 'up': up, 'ip': ip,
               'rx_rate': rate, 'seen': prev is not None,
               'recent': (now - _NM_VPN_STATE['last_traffic'].get(nic, 0)) < _NM_VPN_IDLE_GRACE}
        key = (rec['up'], bool(rec['ip']), rec['recent'], rec['rx_rate'])
        if best is None or key > (best['up'], bool(best['ip']), best['recent'], best['rx_rate']):
            best = rec

    out.update({'iface': best['iface'], 'provider': best['provider'],
                'ip': best['ip'], 'rx_rate': best['rx_rate']})
    if not best['up']:
        out['reason'] = 'tunnel adapter is down'
    elif not best['ip']:
        out['reason'] = 'tunnel has no address (not connected)'
    elif best['rx_rate'] > 0:
        out['active'] = True
        out['reason'] = 'carrying traffic (%s/s)' % _nm_human_bytes(best['rx_rate'])
    elif phys_rate >= _NM_VPN_BYPASS_RATE:
        # Decisive: the machine is busy but none of it is going through the
        # tunnel, so nothing is being tunnelled right now.
        _NM_VPN_STATE['last_traffic'].pop(best['iface'], None)
        out['reason'] = ('not connected \u2014 %s/s is bypassing the tunnel'
                         % _nm_human_bytes(phys_rate))
    elif best['recent']:
        out['active'] = True
        out['reason'] = 'connected, currently idle'
    elif not best['seen']:
        out['reason'] = 'measuring tunnel throughput\u2026'
    else:
        out['reason'] = 'adapter up but no traffic \u2014 not connected'
    out['phys_rate'] = phys_rate
    return out


def _nm_human_bytes(n):
    n = float(n or 0)
    for u in ('B', 'KB', 'MB', 'GB'):
        if n < 1024 or u == 'GB':
            return '%d%s' % (n, u) if u == 'B' or n >= 10 else '%.1f%s' % (n, u)
        n /= 1024.0
    return '%dB' % n


