class SpeedDB:
    """Thread-safe SQLite wrapper. One instance per process."""

    def __init__(self, db_path: str):
        self.db_path = db_path
        self._local = threading.local()
        # Bumped on every write. Readers (e.g. the 1 Hz graph redraw) use it to
        # skip re-querying the database when nothing has actually changed.
        self.version = 0
        self._ensure_schema()

    # ── Connection management ─────────────────────────────────────────────────

    def _conn(self) -> sqlite3.Connection:
        """Return a per-thread connection (created on first use)."""
        if not hasattr(self._local, 'conn') or self._local.conn is None:
            conn = sqlite3.connect(self.db_path, timeout=10,
                                   check_same_thread=False)
            conn.row_factory = sqlite3.Row
            conn.execute("PRAGMA journal_mode=WAL")   # concurrent reads
            conn.execute("PRAGMA synchronous=NORMAL")  # fast + safe
            conn.execute("PRAGMA cache_size=-8000")    # 8 MB cache
            self._local.conn = conn
        return self._local.conn

    _MIGRATIONS = [
        ("readings", "jitter",      "REAL"),
        ("readings", "loss_pct",    "REAL"),
        ("readings", "bloat_ms",    "REAL"),
        ("readings", "bloat_grade", "TEXT"),
        ("flows",    "port",        "INTEGER"),
        ("flows",    "cc",          "TEXT"),
    ]

    def _ensure_schema(self):
        with self._conn() as c:
            c.executescript(_DB_SCHEMA)
            # CREATE TABLE IF NOT EXISTS silently does nothing on an existing
            # table, so new columns must be ALTERed in or every write breaks
            # for anyone upgrading with a DB already on disk.
            for table, col, typ in self._MIGRATIONS:
                try:
                    have = {r[1] for r in c.execute(f"PRAGMA table_info({table})")}
                except Exception:
                    continue
                if not have:
                    continue                      # table doesn't exist yet
                if col not in have:
                    try:
                        c.execute(f"ALTER TABLE {table} ADD COLUMN {col} {typ}")
                        log.info(f"[db] migrated: {table}.{col}")
                    except Exception:
                        _exc('_ensure_schema.migrate')

    # ── Writes ────────────────────────────────────────────────────────────────

    def insert_reading(self, ts: str, download: float, upload: float, ping: float,
                       jitter=None, loss_pct=None, bloat_ms=None, bloat_grade=None):
        with self._conn() as c:
            c.execute(
                "INSERT INTO readings (ts, download, upload, ping, jitter, loss_pct,"
                " bloat_ms, bloat_grade) VALUES (?,?,?,?,?,?,?,?)",
                (ts, download, upload, ping, jitter, loss_pct, bloat_ms, bloat_grade)
            )
        self.version += 1

    # ── Honeypot persistence ────────────────

    def insert_honeypot_hit(self, rec):
        """Persist one honeypot hit so history survives a restart."""
        with self._conn() as c:
            c.execute(
                "INSERT INTO honeypot_hits (ts, ip, port, proto, service, known,"
                " sample, tool) VALUES (?,?,?,?,?,?,?,?)",
                (rec.get('time'), rec.get('ip'), rec.get('port'),
                 rec.get('proto', 'tcp'), rec.get('service'),
                 1 if rec.get('known') else 0, rec.get('sample'),
                 rec.get('tool')))

    def honeypot_hits(self, since=None, limit=1000):
        """Recent hits, newest first. `since` is an epoch timestamp."""
        q = ("SELECT ts, ip, port, proto, service, known, sample, tool"
             " FROM honeypot_hits")
        args = []
        if since is not None:
            q += " WHERE ts >= ?"
            args.append(since)
        q += " ORDER BY ts DESC LIMIT ?"
        args.append(limit)
        with self._conn() as c:
            rows = c.execute(q, args).fetchall()
        return [{'time': r[0], 'ip': r[1], 'port': r[2], 'proto': r[3],
                 'service': r[4], 'known': bool(r[5]), 'sample': r[6],
                 'tool': r[7]} for r in rows]

    def honeypot_top_sources(self, since=None, limit=20):
        """Sources ranked by hit count, with first/last seen."""
        q = ("SELECT ip, COUNT(*), MIN(ts), MAX(ts) FROM honeypot_hits")
        args = []
        if since is not None:
            q += " WHERE ts >= ?"
            args.append(since)
        q += " GROUP BY ip ORDER BY COUNT(*) DESC LIMIT ?"
        args.append(limit)
        with self._conn() as c:
            rows = c.execute(q, args).fetchall()
        return [{'ip': r[0], 'hits': r[1], 'first': r[2], 'last': r[3]}
                for r in rows]

    def honeypot_stats(self, since=None):
        q = "SELECT COUNT(*), COUNT(DISTINCT ip) FROM honeypot_hits"
        args = []
        if since is not None:
            q += " WHERE ts >= ?"
            args.append(since)
        with self._conn() as c:
            row = c.execute(q, args).fetchone()
        return {'total': row[0] or 0, 'unique_ips': row[1] or 0}

    # ── Flow persistence ─────────────────────────────────────────────────────

    def insert_flows(self, ts: str, flows):
        """Bulk-persist a snapshot of live flows. flows = iterable of dicts."""
        rows = []
        for f in flows:
            try:
                rows.append((ts, f.get('src'), f.get('dst'), f.get('proto'),
                             int(f['port']) if f.get('port') else None,
                             f.get('cc'),
                             int(f.get('bytes') or 0), int(f.get('pkts') or 0)))
            except Exception:
                continue
        if not rows:
            return 0
        with self._conn() as c:
            c.executemany(
                "INSERT INTO flows (ts, src, dst, proto, port, cc, bytes, pkts)"
                " VALUES (?,?,?,?,?,?,?,?)", rows)
        return len(rows)

    def flow_totals(self, hours=24, limit=25):
        """Bytes per destination over a window — 'what used my bandwidth'."""
        since = (datetime.now() - timedelta(hours=hours)).isoformat()
        with self._conn() as c:
            return [dict(r) for r in c.execute(
                "SELECT dst, SUM(bytes) AS bytes, SUM(pkts) AS pkts,"
                " COUNT(*) AS samples, MAX(ts) AS last_ts"
                " FROM flows WHERE ts >= ? AND dst IS NOT NULL"
                " GROUP BY dst ORDER BY bytes DESC LIMIT ?", (since, limit))]

    def flow_series(self, dst=None, hours=24):
        """Time series of bytes, optionally for one destination."""
        since = (datetime.now() - timedelta(hours=hours)).isoformat()
        q = ("SELECT ts, SUM(bytes) AS bytes FROM flows WHERE ts >= ?"
             + (" AND dst = ?" if dst else "")
             + " GROUP BY ts ORDER BY ts")
        args = (since, dst) if dst else (since,)
        with self._conn() as c:
            return [dict(r) for r in c.execute(q, args)]

    def flow_span(self, hours=24):
        """(earliest, latest) flow timestamps in the window, or (None, None)."""
        since = (datetime.now() - timedelta(hours=hours)).isoformat()
        with self._conn() as c:
            r = c.execute("SELECT MIN(ts) AS a, MAX(ts) AS b FROM flows"
                          " WHERE ts >= ?", (since,)).fetchone()
        if not r or not r['a']:
            return None, None
        return datetime.fromisoformat(r['a']), datetime.fromisoformat(r['b'])

    def flows_between(self, start, end):
        """Flows recorded in [start, end) — one replay frame of the capture."""
        with self._conn() as c:
            return [dict(r) for r in c.execute(
                "SELECT src, dst, proto, cc, SUM(bytes) AS bytes, SUM(pkts) AS pkts"
                " FROM flows WHERE ts >= ? AND ts < ?"
                " GROUP BY src, dst, proto ORDER BY bytes DESC LIMIT 400",
                (start.isoformat(), end.isoformat()))]

    def flow_baseline(self, days=7):
        """(known destinations, per-dst {mean,sd}) — the anomaly baseline."""
        since = (datetime.now() - timedelta(days=days)).isoformat()
        known, stats = set(), {}
        with self._conn() as c:
            for r in c.execute(
                    "SELECT dst, AVG(bytes) AS m, COUNT(*) AS n,"
                    " AVG(bytes*bytes) AS m2 FROM flows"
                    " WHERE ts >= ? AND dst IS NOT NULL GROUP BY dst", (since,)):
                d = r['dst']; known.add(d)
                m = float(r['m'] or 0); m2 = float(r['m2'] or 0)
                var = max(0.0, m2 - m * m)
                stats[d] = {'mean': m, 'sd': var ** 0.5, 'n': int(r['n'])}
        return known, stats

    def country_seen(self, cc, days=7):
        since = (datetime.now() - timedelta(days=days)).isoformat()
        with self._conn() as c:
            r = c.execute("SELECT 1 FROM flows WHERE cc = ? AND ts >= ? LIMIT 1",
                          (cc, since)).fetchone()
        return r is not None

    def purge_flows(self, keep_days=30):
        cut = (datetime.now() - timedelta(days=keep_days)).isoformat()
        with self._conn() as c:
            c.execute("DELETE FROM flows WHERE ts < ?", (cut,))

    # ── Maintenance ──────────────────────────────────────────────────────────
    # `_NM_MAX_SANE_MBPS` / `_nm_sane_speed` are defined later in the module
    # (used by every read path to filter these values out of charts/stats).
    # Referencing the global here is fine — this only runs at call time, well
    # after the whole module has loaded.

    def count_corrupt_readings(self):
        """(#download, #upload) rows currently outside the plausible Mbps range.

        Preview for the Settings "Purge corrupt speed readings" button, so the
        confirmation dialog can say how many rows are affected before anything
        is changed.
        """
        with self._conn() as c:
            n_dl = c.execute(
                "SELECT COUNT(*) FROM readings WHERE download IS NOT NULL"
                " AND (download < 0 OR download > ?)", (_NM_MAX_SANE_MBPS,)
            ).fetchone()[0]
            n_ul = c.execute(
                "SELECT COUNT(*) FROM readings WHERE upload IS NOT NULL"
                " AND (upload < 0 OR upload > ?)", (_NM_MAX_SANE_MBPS,)
            ).fetchone()[0]
        return n_dl, n_ul

    def purge_corrupt_readings(self):
        """Null out download/upload values outside the plausible Mbps range.

        Clears only the corrupt field(s) on an affected row — timestamp, ping,
        jitter, loss, bufferbloat and every other column are left untouched, so
        this can't turn a partially-good reading into a missing one. Mirrors
        the same 0..MAX sanity window `_nm_sane_speed` already applies on every
        read path (charts, averages, the dashboard) — this makes the exclusion
        permanent on disk instead of just filtering it out each time it's read.
        Returns (#download cleared, #upload cleared).
        """
        with self._conn() as c:
            n_dl = c.execute(
                "UPDATE readings SET download = NULL WHERE download IS NOT NULL"
                " AND (download < 0 OR download > ?)", (_NM_MAX_SANE_MBPS,)
            ).rowcount
            n_ul = c.execute(
                "UPDATE readings SET upload = NULL WHERE upload IS NOT NULL"
                " AND (upload < 0 OR upload > ?)", (_NM_MAX_SANE_MBPS,)
            ).rowcount
        if n_dl or n_ul:
            self.version += 1
        return n_dl, n_ul

    # ── Device inventory ─────────────────────────────────────────────────────

    def upsert_device(self, ip, mac=None, ts=None):
        ts = ts or datetime.now().isoformat()
        with self._conn() as c:
            c.execute(
                "INSERT INTO devices (ip, mac, first_seen, last_seen)"
                " VALUES (?,?,?,?)"
                " ON CONFLICT(ip) DO UPDATE SET"
                "   mac       = COALESCE(excluded.mac, devices.mac),"
                "   last_seen = excluded.last_seen",
                (ip, mac, ts, ts))

    def set_device_label(self, ip, label):
        with self._conn() as c:
            c.execute(
                "INSERT INTO devices (ip, label, first_seen, last_seen)"
                " VALUES (?,?,?,?)"
                " ON CONFLICT(ip) DO UPDATE SET label = excluded.label",
                (ip, label, datetime.now().isoformat(), datetime.now().isoformat()))

    def get_device(self, ip):
        with self._conn() as c:
            return c.execute("SELECT * FROM devices WHERE ip = ?", (ip,)).fetchone()

    def list_devices(self):
        with self._conn() as c:
            return [dict(r) for r in c.execute(
                "SELECT * FROM devices ORDER BY last_seen DESC")]

    def insert_dns(self, ts: str, avg_ms: float, breakdown: dict):
        with self._conn() as c:
            c.execute(
                "INSERT INTO dns_readings (ts, avg_ms, breakdown) VALUES (?,?,?)",
                (ts, avg_ms, json.dumps(breakdown))
            )
        self.version += 1

    # ── Reads ─────────────────────────────────────────────────────────────────

    def load_data(self, limit: int = 10000) -> dict:
        """Return dict matching the old JSON structure for full compatibility."""
        conn = self._conn()
        rows = conn.execute(
            "SELECT ts, download, upload, ping FROM readings "
            "ORDER BY ts DESC LIMIT ?", (limit,)
        ).fetchall()
        rows = list(reversed(rows))

        dns_rows = conn.execute(
            "SELECT ts, avg_ms, breakdown FROM dns_readings "
            "ORDER BY ts DESC LIMIT 500"
        ).fetchall()
        dns_rows = list(reversed(dns_rows))

        return {
            'timestamps':     [r['ts']       for r in rows],
            'download':       [r['download']  for r in rows],
            'upload':         [r['upload']    for r in rows],
            'ping':           [r['ping']      for r in rows],
            'dns_timestamps': [r['ts']        for r in dns_rows],
            'dns_values':     [r['avg_ms']    for r in dns_rows],
        }

    def load_range(self, ts_from: str, ts_to: str) -> dict:
        """Load only readings within a timestamp range — fast for view filtering."""
        conn = self._conn()
        rows = conn.execute(
            "SELECT ts, download, upload, ping FROM readings "
            "WHERE ts >= ? AND ts <= ? ORDER BY ts",
            (ts_from, ts_to)
        ).fetchall()
        dns_rows = conn.execute(
            "SELECT ts, avg_ms FROM dns_readings "
            "WHERE ts >= ? AND ts <= ? ORDER BY ts",
            (ts_from, ts_to)
        ).fetchall()
        return {
            'timestamps':     [r['ts']      for r in rows],
            'download':       [r['download'] for r in rows],
            'upload':         [r['upload']   for r in rows],
            'ping':           [r['ping']     for r in rows],
            'dns_timestamps': [r['ts']       for r in dns_rows],
            'dns_values':     [r['avg_ms']   for r in dns_rows],
        }

    def latest(self) -> dict:
        """Return only the most recent reading for status displays."""
        conn = self._conn()
        row = conn.execute(
            "SELECT ts, download, upload, ping FROM readings ORDER BY ts DESC LIMIT 1"
        ).fetchone()
        dns = conn.execute(
            "SELECT avg_ms FROM dns_readings ORDER BY ts DESC LIMIT 1"
        ).fetchone()
        if not row:
            return {}
        return {
            'ts': row['ts'], 'download': row['download'],
            'upload': row['upload'], 'ping': row['ping'],
            'dns': dns['avg_ms'] if dns else None,
        }

    def count(self) -> dict:
        conn = self._conn()
        return {
            'readings': conn.execute("SELECT COUNT(*) FROM readings").fetchone()[0],
            'dns':      conn.execute("SELECT COUNT(*) FROM dns_readings").fetchone()[0],
        }

    # ── Migration ─────────────────────────────────────────────────────────────

    def import_from_json(self, json_path: str) -> int:
        """Import existing JSON data file. Returns number of rows inserted."""
        p = Path(json_path)
        if not p.exists():
            return 0
        with open(p) as f:
            d = json.load(f)
        ts_list  = d.get('timestamps', [])
        dl_list  = d.get('download', [])
        ul_list  = d.get('upload', [])
        pg_list  = d.get('ping', [])
        dns_ts   = d.get('dns_timestamps', [])
        dns_vals = d.get('dns_values', [])
        n = min(len(ts_list), len(dl_list), len(ul_list), len(pg_list))
        conn = self._conn()
        # Skip rows already in DB (by timestamp)
        existing = set(
            r[0] for r in conn.execute("SELECT ts FROM readings").fetchall()
        )
        rows = [
            (ts_list[i], dl_list[i], ul_list[i], pg_list[i])
            for i in range(n)
            if ts_list[i] not in existing
        ]
        conn.executemany(
            "INSERT INTO readings (ts, download, upload, ping) VALUES (?,?,?,?)", rows
        )
        existing_dns = set(
            r[0] for r in conn.execute("SELECT ts FROM dns_readings").fetchall()
        )
        n_dns = min(len(dns_ts), len(dns_vals))
        dns_rows = [
            (dns_ts[i], dns_vals[i], '{}')
            for i in range(n_dns)
            if dns_ts[i] not in existing_dns
        ]
        conn.executemany(
            "INSERT INTO dns_readings (ts, avg_ms, breakdown) VALUES (?,?,?)", dns_rows
        )
        conn.commit()
        self.version += 1
        print(f"  Imported {len(rows)} speed readings, {len(dns_rows)} DNS readings from {json_path}")
        return len(rows)

    def export_to_json(self, json_path: str):
        """Export entire DB back to JSON — the revert path."""
        d = self.load_data(limit=100000)
        with open(json_path, 'w') as f:
            json.dump(d, f, indent=2)
        print(f"  Exported {len(d['timestamps'])} readings to {json_path}")


