_ea_instances = []  # Global registry of open EtherApeWindow instances

def _prune_ea_instances():
    global _ea_instances
    _ea_instances = [e for e in _ea_instances if not getattr(e, '_closed', True)]

def _active_ea():
    """Return the best EtherApeWindow: capturing with nodes > capturing > has nodes > open > alive."""
    def _open(e):
        return not getattr(e, '_closed', True)
    def _cap(e):  return getattr(e, '_capturing', False)
    def _nodes(e): return len(getattr(e, '_nodes', {})) > 0

    _prune_ea_instances()
    log.debug(f'[_active_ea] instances={len(_ea_instances)} '
              f'states={[{"closed":getattr(e,"_closed","?"),"cap":getattr(e,"_capturing","?"),"nodes":len(getattr(e,"_nodes",{}))} for e in _ea_instances]}')

    for pred in [
        lambda e: _open(e) and _cap(e) and _nodes(e),
        lambda e: _open(e) and _cap(e),
        lambda e: _open(e) and _nodes(e),
        lambda e: _open(e),
    ]:
        ea = next((e for e in reversed(_ea_instances) if pred(e)), None)
        if ea:
            ea._closed = False
            log.debug(f'[_active_ea] found: closed={ea._closed} cap={ea._capturing} nodes={len(ea._nodes)}')
            return ea
    log.warning(f'[_active_ea] no active instance found from {len(_ea_instances)} registered')
    return None
