# Multi-part public suffixes we must not chop in half (co.uk, com.au, ...)
_NM_TWO_LEVEL_TLDS = {
    'co.uk','org.uk','ac.uk','gov.uk','me.uk','net.uk',
    'com.au','net.au','org.au','co.nz','co.za','co.jp','ne.jp','or.jp',
    'com.br','com.mx','com.cn','com.tr','co.in','co.kr','com.sg',
}

_NM_SPECIAL_IPS = {
    '224.0.0.251':     'mDNS (multicast)',
    '224.0.0.252':     'LLMNR (multicast)',
    '224.0.0.1':       'All hosts (multicast)',
    '224.0.0.22':      'IGMP (multicast)',
    '239.255.255.250': 'SSDP / UPnP',
    '255.255.255.255': 'Broadcast',
    '8.8.8.8':         'Google DNS',
    '8.8.4.4':         'Google DNS',
    '1.1.1.1':         'Cloudflare DNS',
    '1.0.0.1':         'Cloudflare DNS',
    '9.9.9.9':         'Quad9 DNS',
    '208.67.222.222':  'OpenDNS',
}


def _nm_special_ip(ip):
    """Well-known addresses that reverse-DNS either can't or shouldn't name."""
    if ip in _NM_SPECIAL_IPS:
        return _NM_SPECIAL_IPS[ip]
    if ip.endswith('.255'):
        return 'Broadcast'
    if ip.startswith('224.') or ip.startswith('239.'):
        return 'Multicast'
    return ''


def _nm_registrable_domain(host):
    """example -> 'btopenworld.com' / 'bbc.co.uk'. Never cuts mid-label."""
    parts = [p for p in host.strip('.').split('.') if p]
    if len(parts) < 2:
        return host
    if len(parts) >= 3 and '.'.join(parts[-2:]) in _NM_TWO_LEVEL_TLDS:
        return '.'.join(parts[-3:])
    return '.'.join(parts[-2:])


def _nm_friendly_host(ip, raw='', maxlen=24):
    """Turn an IP + whatever DNS gave us into something a human can read."""
    sp = _nm_special_ip(ip)
    if sp:
        return sp
    raw = (raw or '').strip().rstrip('.').lower()
    if not raw or raw == ip:
        return ip

    # Known organisation? Match on suffix so sub-domains still resolve to the org.
    for suffix, org in _NM_ORG_MAP:
        if raw == suffix or raw.endswith('.' + suffix):
            return org

    # A real forward-DNS name (the host looked this up) is already meaningful —
    # keep it, minus a leading www.
    if raw.startswith('www.'):
        raw = raw[4:]
    if len(raw) <= maxlen:
        return raw

    # Otherwise it's a long PTR record: show the registrable domain, which is
    # the only part of it that carries meaning.
    reg = _nm_registrable_domain(raw)
    return reg if len(reg) <= maxlen else reg[:maxlen - 1] + '\u2026'


# ══════════════════════════════════════════════════════════════════════════════
#  TOOLS  —  embedded MobaXterm
#
#  The binaries are NOT base64'd into this file: 49MB of exe/plugins becomes
#  ~65MB of base64 text, which would make the source unopenable and force Python
#  to parse a 65MB string literal at every launch. They are bundled by PyInstaller
#  instead (see _nm_resource_path), which is what "included in the executable"
#  actually needs. Build command is in the TOOLS window's Help text.
#
#  MobaXterm is a closed Win32 binary — its own widgets can't be re-themed. What
#  we can do is reparent its top-level window into one of our Tk frames, so it
#  sits inside our chrome (header, status bar, colours) instead of floating as a
#  separate OS window.
# ══════════════════════════════════════════════════════════════════════════════

# (glob pattern, friendly name, required?) — matching an exact filename was too
# brittle: any MobaXterm build other than 26_4 (or a renamed download) simply
# "wasn't found", with no hint as to why.
_NM_TOOL_PATTERNS = (
    ('MobaXterm*.exe',   'MobaXterm executable', True),
    ('CygUtils.plugin',  'CygUtils plugin',      False),
    ('CygUtils64.plugin','CygUtils64 plugin',    False),
)
_nm_tool_proc = None            # live MobaXterm process, so QUIT can reap it


def _nm_tool_search_dirs():
    """Every directory we'll look in for the bundled tools, in priority order.

    Searching only the script's own folder was too narrow: people keep the tools
    next to the build script / .bat / .exe rather than next to the .py, and when
    launched from a shortcut the working directory is different again. Look in
    all the plausible places and be able to REPORT them, so a miss is diagnosable
    instead of a flat 'not found'.
    """
    import os as _os
    roots = []

    base = getattr(sys, '_MEIPASS', None)          # PyInstaller unpack dir
    if base:
        roots.append(Path(base))

    # Explicit override always wins
    for m in _monitor_instances:
        try:
            td = (m.config.get('tools_dir') or '').strip()
            if td:
                roots.insert(0, Path(td))
        except Exception:
            _exc_debug('_nm_tool_search_dirs')

    try:
        roots.append(Path(__file__).resolve().parent)   # next to the .py
    except Exception:
        _exc_debug('_nm_tool_search_dirs')
    try:
        roots.append(Path(sys.executable).resolve().parent)  # next to the .exe
    except Exception:
        _exc_debug('_nm_tool_search_dirs')
    try:
        roots.append(Path(_os.getcwd()))                # where we were launched
    except Exception:
        _exc_debug('_nm_tool_search_dirs')

    # ...and one level up from each, which catches the common layout of
    # tools/ living beside build_installer.bat in a parent/build folder.
    for r in list(roots):
        try:
            roots.append(r.parent)
        except Exception:
            _exc_debug('_nm_tool_search_dirs')

    dirs, seen = [], set()
    for r in roots:
        for cand in (r / 'tools', r):
            try:
                key = str(cand.resolve()).lower()
            except Exception:
                key = str(cand).lower()
            if key not in seen:
                seen.add(key)
                dirs.append(cand)
    return dirs


def _nm_resource_path(pattern):
    """Find a bundled file by glob pattern, across every search dir."""
    for d in _nm_tool_search_dirs():
        try:
            if not d.is_dir():
                continue
            for c in sorted(d.glob(pattern)):
                if c.is_file():
                    return c
        except Exception:
            continue
    return None


def _nm_stage_tools():
    """Copy the bundled tool files somewhere stable and writable.

    MobaXterm needs its .plugin files sitting next to the .exe, and it writes
    state beside itself — so it can't run from PyInstaller's read-only temp
    unpack dir (nor from Program Files, which is not user-writable). Stage once
    into LOCALAPPDATA and reuse.
    """
    import os as _os, shutil as _sh
    root = Path(_os.environ.get('LOCALAPPDATA') or Path.home()) / 'NetworkMonitor' / 'tools'
    root.mkdir(parents=True, exist_ok=True)
    exe_dst = None
    missing = []
    for pattern, friendly, required in _NM_TOOL_PATTERNS:
        srcp = _nm_resource_path(pattern)
        if srcp is None:
            if required:
                missing.append(f'{friendly}  ({pattern})')
            continue
        dst = root / srcp.name
        try:
            if (not dst.exists()) or dst.stat().st_size != srcp.stat().st_size:
                _sh.copy2(srcp, dst)
        except Exception:
            _exc('_nm_stage_tools')
        if srcp.suffix.lower() == '.exe':
            exe_dst = dst
    return exe_dst, root, missing


# ── Win32 window embedding ───────────────────────────────────────────────────

def _nm_find_window_for_pid(pid, timeout=30.0):
    """Wait for a process to show a visible, titled, top-level window."""
    import ctypes
    from ctypes import wintypes
    u32 = ctypes.windll.user32
    found = []

    WNDENUMPROC = ctypes.WINFUNCTYPE(ctypes.c_bool, wintypes.HWND, wintypes.LPARAM)

    def _cb(hwnd, _lp):
        owner = ctypes.c_ulong()
        u32.GetWindowThreadProcessId(hwnd, ctypes.byref(owner))
        if owner.value != pid:
            return True
        if not u32.IsWindowVisible(hwnd):
            return True
        if u32.GetParent(hwnd):                    # child windows aren't the shell
            return True
        if u32.GetWindowTextLengthW(hwnd) <= 0:    # splash screens have no title
            return True
        found.append(hwnd)
        return False

    cb = WNDENUMPROC(_cb)                          # keep a ref: GC'ing it crashes
    deadline = time.time() + timeout
    while time.time() < deadline and not found:
        u32.EnumWindows(cb, 0)
        if found:
            break
        time.sleep(0.25)
    return found[0] if found else None


def _nm_embed_window(hwnd, container_hwnd, w, h):
    """Reparent a foreign top-level window into one of our Tk frames.

    Every Win32 call here declares argtypes/restype explicitly. Without that,
    ctypes assumes signed 32-bit ints — and window styles legitimately use bit 31
    (WS_POPUP = 0x80000000), so GetWindowLongW hands back a NEGATIVE value.
    Doing |= / &= on that in Python (arbitrary precision) drifts the result below
    -2^31, and ctypes then refuses to convert it back:
        "argument 3: OverflowError: int too long to convert"
    The bit pattern was right all along; the Python integer was simply out of
    range. Fix: mask to 32 bits either side of the arithmetic, and be explicit
    about every type. HWNDs are pointers too, so they need HWND, not c_int.
    """
    import ctypes
    from ctypes import wintypes

    u32 = ctypes.windll.user32
    is64 = ctypes.sizeof(ctypes.c_void_p) == 8
    LONG_PTR = ctypes.c_ssize_t

    GWL_STYLE      = -16
    WS_CHILD       = 0x40000000
    WS_POPUP       = 0x80000000
    WS_CAPTION     = 0x00C00000
    WS_THICKFRAME  = 0x00040000
    WS_MINIMIZEBOX = 0x00020000
    WS_MAXIMIZEBOX = 0x00010000
    SW_SHOW        = 5

    # On 64-bit, the *Ptr variants are the correct entry points.
    if is64 and hasattr(u32, 'GetWindowLongPtrW'):
        _get, _set = u32.GetWindowLongPtrW, u32.SetWindowLongPtrW
    else:
        _get, _set = u32.GetWindowLongW, u32.SetWindowLongW
    _get.argtypes = [wintypes.HWND, ctypes.c_int]
    _get.restype  = LONG_PTR
    _set.argtypes = [wintypes.HWND, ctypes.c_int, LONG_PTR]
    _set.restype  = LONG_PTR

    u32.SetParent.argtypes  = [wintypes.HWND, wintypes.HWND]
    u32.SetParent.restype   = wintypes.HWND
    u32.MoveWindow.argtypes = [wintypes.HWND, ctypes.c_int, ctypes.c_int,
                               ctypes.c_int, ctypes.c_int, wintypes.BOOL]
    u32.MoveWindow.restype  = wintypes.BOOL
    u32.ShowWindow.argtypes = [wintypes.HWND, ctypes.c_int]
    u32.ShowWindow.restype  = wintypes.BOOL

    hwnd = wintypes.HWND(int(hwnd))
    cont = wintypes.HWND(int(container_hwnd))

    style = _get(hwnd, GWL_STYLE) & 0xFFFFFFFF          # -> unsigned, always
    style |= WS_CHILD
    style &= ~(WS_POPUP | WS_CAPTION | WS_THICKFRAME |
               WS_MINIMIZEBOX | WS_MAXIMIZEBOX)
    style &= 0xFFFFFFFF                                  # keep it 32-bit
    if style >= 0x80000000:                              # back to signed LONG
        style -= 0x100000000

    _set(hwnd, GWL_STYLE, style)
    u32.SetParent(hwnd, cont)
    u32.MoveWindow(hwnd, 0, 0, max(1, int(w)), max(1, int(h)), True)
    u32.ShowWindow(hwnd, SW_SHOW)
    return True


def _nm_open_tools(monitor, parent=None):
    """TOOLS window: our chrome, MobaXterm hosted inside it."""
    global _nm_tool_proc
    import tkinter as tk
    from tkinter import ttk as _ttk

    BG, PANEL, ACC, DIM = '#0a0e18', '#0d1828', '#38b8f0', '#6a9ab8'

    win = tk.Toplevel(parent) if parent is not None else tk.Toplevel()
    win.title('Tools — MobaXterm')
    win.configure(bg=BG)
    win.geometry('1280x820')
    _nm_apply_ttk_theme(win)

    # ── Our header bar (this is the "same look and feel" part) ───────────────
    hdr = tk.Frame(win, bg=PANEL, height=42)
    hdr.pack(fill='x', side='top')
    hdr.pack_propagate(False)
    tk.Label(hdr, text='  \u2692  TOOLS', bg=PANEL, fg=ACC,
             font=(_NM_MONO, 11, 'bold')).pack(side='left', padx=(10, 14))
    tk.Frame(hdr, bg='#1a2535', width=1).pack(side='left', fill='y', pady=8)
    status = tk.StringVar(value='Starting MobaXterm\u2026')
    tk.Label(hdr, textvariable=status, bg=PANEL, fg=DIM,
             font=(_NM_MONO, 9)).pack(side='left', padx=14)

    btns = tk.Frame(hdr, bg=PANEL)
    btns.pack(side='right', padx=8)

    def _mk(text, cmd, col=ACC):
        b = tk.Button(btns, text=text, command=cmd, bg='#0a1828', fg=col,
                      activebackground='#16324a', activeforeground='white',
                      relief='flat', font=(_NM_MONO, 8), cursor='hand2',
                      padx=10, pady=3, bd=0, highlightthickness=1,
                      highlightbackground='#1a3a5a')
        b.pack(side='left', padx=3)
        return b

    # ── Content area: MobaXterm gets reparented into this frame ──────────────
    host = tk.Frame(win, bg='#050d1a', highlightthickness=1,
                    highlightbackground='#1a2535')
    host.pack(fill='both', expand=True, padx=6, pady=(0, 6))

    state = {'hwnd': None, 'proc': None, 'closed': False}

    def _msg(text, colour=DIM):
        for w in host.winfo_children():
            w.destroy()
        lbl = tk.Label(host, text=text, bg='#050d1a', fg=colour,
                       font=(_NM_MONO, 10), justify='left')
        lbl.pack(expand=True, padx=30, pady=30)

    def _resize(_e=None):
        if state['hwnd'] and not state['closed']:
            try:
                import ctypes
                from ctypes import wintypes
                _mw = ctypes.windll.user32.MoveWindow
                _mw.argtypes = [wintypes.HWND, ctypes.c_int, ctypes.c_int,
                                ctypes.c_int, ctypes.c_int, wintypes.BOOL]
                _mw(wintypes.HWND(int(state['hwnd'])), 0, 0,
                    max(1, host.winfo_width()), max(1, host.winfo_height()), True)
            except Exception:
                _exc_debug('_resize')
    host.bind('<Configure>', _resize)

    def _on_close():
        state['closed'] = True
        _stop()
        try: win.destroy()
        except Exception: _exc_debug('_on_close')
    win.protocol('WM_DELETE_WINDOW', _on_close)

    def _stop():
        global _nm_tool_proc
        p = state.get('proc')
        state['hwnd'] = None
        if p and p.poll() is None:
            try: p.terminate()
            except Exception: _exc('_nm_open_tools.stop')
        state['proc'] = None
        _nm_tool_proc = None

    def _launch(embed=True):
        global _nm_tool_proc
        _stop()
        exe, root, missing = _nm_stage_tools()
        if exe is None:
            _looked = '\n'.join('    ' + str(d) for d in _nm_tool_search_dirs()[:10])
            for w in host.winfo_children():
                w.destroy()
            box = tk.Frame(host, bg='#050d1a')
            box.pack(expand=True, padx=30, pady=24)
            tk.Label(box, text='MobaXterm was not found.', bg='#050d1a', fg='#ff9f43',
                     font=(_NM_MONO, 11, 'bold')).pack(anchor='w')
            tk.Label(box, text='Missing: ' + (', '.join(missing) or 'MobaXterm*.exe'),
                     bg='#050d1a', fg='#ff9f43', font=(_NM_MONO, 9)).pack(anchor='w', pady=(6, 0))
            tk.Label(box, text='Looked for MobaXterm*.exe in:\n' + _looked,
                     bg='#050d1a', fg=DIM, font=(_NM_MONO, 8),
                     justify='left').pack(anchor='w', pady=(10, 12))

            def _pick():
                from tkinter import filedialog as _fd
                d = _fd.askdirectory(parent=win,
                                     title='Folder containing MobaXterm*.exe')
                if not d:
                    return
                hits = sorted(Path(d).glob('MobaXterm*.exe'))
                if not hits:
                    status.set('No MobaXterm*.exe in that folder')
                    return
                try:
                    monitor.config['tools_dir'] = d      # remembered for next time
                    monitor._save_config()
                except Exception:
                    _exc('_nm_open_tools.pick')
                _launch(True)

            tk.Button(box, text='  \U0001F4C1  Locate MobaXterm folder\u2026  ',
                      command=_pick, bg='#0a2f4a', fg=ACC, activebackground='#0f3f63',
                      activeforeground='white', relief='flat', font=(_NM_MONO, 9, 'bold'),
                      cursor='hand2', padx=12, pady=6, bd=0, highlightthickness=1,
                      highlightbackground=ACC).pack(anchor='w')
            tk.Label(box, text='(saved to Settings \u2192 Tools folder, so it sticks)',
                     bg='#050d1a', fg='#2a4a6a', font=(_NM_MONO, 8)).pack(anchor='w', pady=(6, 0))
            status.set('MobaXterm not found')
            log.error('[tools] not found. searched: %s',
                      ' | '.join(str(d) for d in _nm_tool_search_dirs()))
            return
        if sys.platform != 'win32':
            _msg('MobaXterm is a Windows application.\n'
                 f'Staged at: {exe}', '#ff9f43')
            status.set('Windows only')
            return

        try:
            flags = getattr(subprocess, 'CREATE_NO_WINDOW', 0)
            p = subprocess.Popen([str(exe)], cwd=str(root), creationflags=flags)
        except Exception as ex:
            _exc('_nm_open_tools.launch')
            _msg(f'Could not start MobaXterm:\n{ex}', '#ff4444')
            status.set('Launch failed')
            return
        state['proc'] = p
        _nm_tool_proc = p
        status.set('MobaXterm starting\u2026')
        _msg('Waiting for MobaXterm to open\u2026')

        if not embed:
            status.set('Running in its own window')
            _msg('MobaXterm is running as a separate window.', ACC)
            return

        def _wait():
            hwnd = _nm_find_window_for_pid(p.pid, timeout=40)
            if state['closed']:
                return
            if not hwnd:
                win.after(0, lambda: (
                    status.set('Running detached (could not embed)'),
                    _msg('MobaXterm is running, but its window could not be\n'
                         'embedded — it is open as a separate window.\n\n'
                         'This happens if MobaXterm was already running:\n'
                         'it hands off to the existing instance and exits.',
                         '#ff9f43')))
                return

            def _do():
                if state['closed']:
                    return
                for w in host.winfo_children():
                    w.destroy()
                try:
                    _nm_embed_window(hwnd, host.winfo_id(),
                                     host.winfo_width(), host.winfo_height())
                    state['hwnd'] = hwnd
                    status.set('MobaXterm \u2014 embedded')
                    _resize()
                except Exception as ex:
                    _exc('_nm_open_tools.embed')
                    _msg(f'Embed failed, running detached:\n{ex}', '#ff9f43')
                    status.set('Running detached')
            win.after(0, _do)

        threading.Thread(target=_wait, daemon=True).start()

    _mk('\u21bb RESTART', lambda: _launch(True))
    _mk('\u2197 DETACH',  lambda: _launch(False), '#f7cc73')
    _mk('\u2715 CLOSE',   _on_close, '#ff4444')

    _launch(True)
    return win


# ══════════════════════════════════════════════════════════════════════════════
#  NETWORK QUALITY / ALERTING / PERSISTENCE / INVENTORY / ANOMALY
# ══════════════════════════════════════════════════════════════════════════════

# ── 1. Ping-based quality: jitter, loss, latency spread ──────────────────────

_NM_PING_RE = re.compile(r'time[=<]\s*([\d.]+)\s*ms', re.I)


def _nm_ping_once(host, timeout_s=2):
    """One ICMP echo. Returns RTT in ms, or None if lost."""
    import subprocess as _sp
    win = (sys.platform == 'win32')
    flags = getattr(_sp, 'CREATE_NO_WINDOW', 0) if win else 0
    cmd = (['ping', '-n', '1', '-w', str(int(timeout_s * 1000)), host] if win
           else ['ping', '-c', '1', '-W', str(int(timeout_s)), host])
    try:
        r = _sp.run(cmd, capture_output=True, text=True,
                    timeout=timeout_s + 1.5, creationflags=flags)
        m = _NM_PING_RE.search(r.stdout or '')
        return float(m.group(1)) if m else None
    except Exception:
        return None


def _nm_ping_samples(host='1.1.1.1', count=10, timeout_s=2):
    return [_nm_ping_once(host, timeout_s) for _ in range(count)]


def _nm_quality_stats(rtts):
    """Jitter (mean abs consecutive delta), loss %, min/avg/max."""
    good = [r for r in rtts if r is not None]
    n = len(rtts)
    loss = (100.0 * (n - len(good)) / n) if n else 0.0
    if not good:
        return {'loss_pct': loss, 'jitter_ms': 0.0, 'min_ms': 0.0,
                'avg_ms': 0.0, 'max_ms': 0.0, 'n': n}
    diffs = [abs(good[i] - good[i - 1]) for i in range(1, len(good))]
    return {
        'loss_pct':  loss,
        'jitter_ms': (sum(diffs) / len(diffs)) if diffs else 0.0,
        'min_ms':    min(good),
        'avg_ms':    sum(good) / len(good),
        'max_ms':    max(good),
        'n':         n,
    }


# ── 2. Bufferbloat: latency under load ───────────────────────────────────────

class _NmLoadPinger:
    """Pings continuously in a background thread. Used to sample latency WHILE
    the speedtest saturates the link — that delta is bufferbloat."""

    def __init__(self, host='1.1.1.1'):
        self.host = host
        self._stop = threading.Event()
        self._rtts = []
        self._t = None

    def _run(self):
        while not self._stop.is_set():
            rtt = _nm_ping_once(self.host, timeout_s=2)
            if rtt is not None:
                self._rtts.append(rtt)
            if self._stop.wait(0.15):
                break

    def start(self):
        self._t = threading.Thread(target=self._run, daemon=True)
        self._t.start()
        return self

    def stop(self):
        self._stop.set()
        if self._t:
            self._t.join(timeout=3)
        return list(self._rtts)


def _nm_bloat_grade(delta_ms):
    """Waveform-style grade from added latency under load."""
    d = max(0.0, delta_ms)
    if   d <   5: return 'A+'
    elif d <  30: return 'A'
    elif d <  60: return 'B'
    elif d < 200: return 'C'
    elif d < 400: return 'D'
    else:         return 'F'


_NM_BLOAT_COLORS = {'A+': '#39ff14', 'A': '#7bed4a', 'B': '#f7cc73',
                    'C': '#ff9f43', 'D': '#ff6b4a', 'F': '#ff4444'}


# ── 3. Alerting: desktop toast + webhook, debounced ──────────────────────────

_nm_alert_last = {}          # rule -> monotonic time of last fire


def _nm_toast(title, message):
    """Windows toast, best effort. Never raises."""
    try:
        if sys.platform == 'win32':
            import subprocess as _sp
            t = str(title).replace("'", "")
            m = str(message).replace("'", "")
            ps = (
                "[Windows.UI.Notifications.ToastNotificationManager,Windows.UI.Notifications,"
                "ContentType=WindowsRuntime]>$null;"
                "$x=[Windows.UI.Notifications.ToastNotificationManager]::GetTemplateContent(1);"
                f"$x.GetElementsByTagName('text')[0].AppendChild($x.CreateTextNode('{t}'))>$null;"
                f"$x.GetElementsByTagName('text')[1].AppendChild($x.CreateTextNode('{m}'))>$null;"
                "$n=[Windows.UI.Notifications.ToastNotification]::new($x);"
                "[Windows.UI.Notifications.ToastNotificationManager]::CreateToastNotifier"
                "('Vanguard Flow NetSentinel').Show($n);"
            )
            _sp.Popen(['powershell', '-NoProfile', '-WindowStyle', 'Hidden', '-Command', ps],
                      creationflags=getattr(_sp, 'CREATE_NO_WINDOW', 0),
                      stdout=_sp.DEVNULL, stderr=_sp.DEVNULL)
            return True
    except Exception:
        _exc('_nm_toast')
    log.warning(f'[ALERT] {title}: {message}')
    return False


def _nm_webhook(url, payload):
    """POST JSON to a webhook (Slack/Discord/Teams/generic). Never raises."""
    if not url:
        return
    def _send():
        try:
            import urllib.request as _u
            req = _u.Request(url, data=json.dumps(payload).encode('utf-8'),
                             headers={'Content-Type': 'application/json'})
            _u.urlopen(req, timeout=8).read()
        except Exception:
            _exc('_nm_webhook')
    threading.Thread(target=_send, daemon=True).start()


def _nm_check_alerts(monitor, dl=None, ul=None, ping=None, jitter=None,
                     loss=None, bloat_ms=None, outage=False):
    """Evaluate thresholds; fire toast + webhook. Debounced per rule."""
    cfg = getattr(monitor, 'config', {}) or {}
    if not cfg.get('alerts_enabled'):
        return []
    hook = str(cfg.get('alert_webhook') or '').strip()
    try:
        debounce = float(cfg.get('alert_debounce_min') or 15) * 60.0
    except Exception:
        debounce = 900.0
    now = time.monotonic()
    fired = []

    def _num(key):
        try:
            v = float(cfg.get(key) or 0)
            return v if v > 0 else None
        except Exception:
            return None

    def _fire(rule, title, msg):
        last = _nm_alert_last.get(rule)
        # Must be `is None`, not `get(rule, 0)`: monotonic() counts from boot,
        # so on a freshly-started machine `now - 0 < debounce` is true and the
        # FIRST alert of every rule would be silently swallowed.
        if last is not None and now - last < debounce:
            return
        _nm_alert_last[rule] = now
        fired.append((rule, title, msg))
        _nm_toast(title, msg)
        if hook:
            _nm_webhook(hook, {'text': f'{title} — {msg}', 'rule': rule,
                               'ts': datetime.now().isoformat()})

    if outage:
        _fire('outage', 'Network Outage', 'Connection is down.')
    t = _num('alert_dl_below')
    if t and dl is not None and dl < t:
        _fire('dl_low', 'Slow Download', f'{dl:.1f} Mbps (below {t:.0f})')
    t = _num('alert_ul_below')
    if t and ul is not None and ul < t:
        _fire('ul_low', 'Slow Upload', f'{ul:.1f} Mbps (below {t:.0f})')
    t = _num('alert_ping_above')
    if t and ping is not None and ping > t:
        _fire('ping_high', 'High Latency', f'{ping:.0f} ms (above {t:.0f})')
    t = _num('alert_jitter_above')
    if t and jitter is not None and jitter > t:
        _fire('jitter_high', 'High Jitter', f'{jitter:.1f} ms (above {t:.0f})')
    t = _num('alert_loss_above')
    if t and loss is not None and loss > t:
        _fire('loss_high', 'Packet Loss', f'{loss:.0f}% (above {t:.0f}%)')
    t = _num('alert_bloat_above')
    if t and bloat_ms is not None and bloat_ms > t:
        _fire('bloat_high', 'Bufferbloat',
              f'+{bloat_ms:.0f} ms under load (above {t:.0f})')
    return fired


# ── 4. Device inventory: IP/MAC -> friendly name ─────────────────────────────

_nm_dev_cache = {}          # ip -> {'name':..., 'mac':...}
_nm_dev_lock  = threading.Lock()


def _nm_arp_table():
    """Parse the OS ARP cache -> {ip: mac}. Never raises."""
    import subprocess as _sp
    out = {}
    try:
        win = (sys.platform == 'win32')
        flags = getattr(_sp, 'CREATE_NO_WINDOW', 0) if win else 0
        r = _sp.run(['arp', '-a'], capture_output=True, text=True,
                    timeout=8, creationflags=flags)
        for line in (r.stdout or '').splitlines():
            m = re.search(
                r'(\d{1,3}(?:\.\d{1,3}){3})\s+([0-9a-fA-F]{2}[:-](?:[0-9a-fA-F]{2}[:-]){4}[0-9a-fA-F]{2})',
                line)
            if m:
                out[m.group(1)] = m.group(2).replace('-', ':').lower()
    except Exception:
        _exc('_nm_arp_table')
    return out


# ── LAN Scan (active discovery + port scan + full name resolution) ─────────
# Everything below backs the "LAN SCAN" button on the Topology window: a
# one-shot, on-demand active scan of the local /24 -- separate from the rest
# of this app, which only ever *observes* traffic passively. Nothing here
# runs unless the user clicks the button.

# ~1000 TCP ports to probe per host. NOT nmap's frequency-ranked "top 1000"
# list -- nmap isn't bundled with this app, and reproducing its exact list
# from memory would be guessing. This is a plain, transparent superset
# instead: every well-known port (1-1024) plus a curated set of higher ports
# that commonly show up in practice (databases, remote desktop, dev/web
# servers, NAS/IoT services, etc.). ~1,140 ports total.
_NM_SCAN_PORTS_HIGH = [
    1080,1194,1433,1434,1521,1723,2049,2082,2083,2086,2087,2181,2375,2376,
    2483,2484,3000,3001,3128,3306,3389,3690,4000,4444,4567,4848,5000,5001,
    5060,5061,5222,5353,5432,5555,5601,5672,5900,5901,5985,5986,6000,6379,
    6443,6666,6667,6881,7000,7001,7070,7077,7199,7474,7547,8000,8008,8009,
    8080,8081,8086,8088,8090,8091,8095,8096,8140,8161,8200,8222,8291,8333,
    8443,8500,8600,8649,8834,8880,8883,8888,8983,9000,9001,9042,9090,9091,
    9092,9100,9200,9300,9418,9443,9527,9999,10000,10001,10250,10255,11211,
    12345,15672,16992,16993,17185,18245,19999,20000,25565,27015,27017,28017,
    32400,32764,32768,49152,50000,54321,62078,
]
_NM_SCAN_PORTS = sorted(set(range(1, 1025)) | set(_NM_SCAN_PORTS_HIGH))


def _nm_local_subnet():
    """Best-effort local IPv4 /24 the active interface sits on.

    Uses the classic UDP-connect-to-a-public-IP trick: connecting a UDP
    socket sends no packet, it just makes the OS pick a route/interface, so
    reading the socket's own address back gives the local IP without needing
    netifaces or platform-specific interface parsing. Returns
    (network_cidr, my_ip), or (None, None) if there's no route out at all
    (no network, VPN with no default route, etc.).
    """
    try:
        _s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        _s.settimeout(0.5)
        _s.connect(('8.8.8.8', 80))
        myip = _s.getsockname()[0]
        _s.close()
        import ipaddress as _ipa
        iface = _ipa.ip_interface(f'{myip}/24')
        return str(iface.network), myip
    except Exception:
        _exc('_nm_local_subnet')
        return None, None


def _nm_ping_sweep(network_cidr, on_progress=None):
    """Parallel ping sweep of a /24 (or smaller) CIDR, then read back the OS
    ARP cache the pings just populated. Returns {ip: mac}.

    Pinging is only the trigger, not the detection mechanism -- ARP is the
    source of truth here, since a host can (and often does) drop ICMP while
    still answering ARP on the same LAN segment. `on_progress(done, total)`
    is called from the calling (worker) thread as pings complete, not the
    Tk main thread -- callers must hop back via `.after()` themselves.
    """
    import ipaddress as _ipa
    import concurrent.futures as _cf
    try:
        net = _ipa.ip_network(network_cidr, strict=False)
    except Exception:
        _exc('_nm_ping_sweep')
        return {}
    targets = list(net.hosts())
    win = (sys.platform == 'win32')
    flags = getattr(subprocess, 'CREATE_NO_WINDOW', 0) if win else 0

    def _ping_one(ip):
        try:
            cmd = (['ping', '-n', '1', '-w', '400', str(ip)] if win
                   else ['ping', '-c', '1', '-W', '1', str(ip)])
            subprocess.run(cmd, capture_output=True, timeout=2, creationflags=flags)
        except Exception:
            pass  # a timed-out/unreachable ping is an expected, silent outcome here

    done = [0]
    if targets:
        # 160 workers covers a full /24 (254 hosts) in 2 rounds instead of 4 --
        # each round costs one ping timeout (worst case), so this halves the
        # discovery phase's worst-case wall-clock for no accuracy trade-off
        # (still one real ping per address, just more of them run at once).
        with _cf.ThreadPoolExecutor(max_workers=160) as ex:
            futs = [ex.submit(_ping_one, ip) for ip in targets]
            for _ in _cf.as_completed(futs):
                done[0] += 1
                if on_progress:
                    try: on_progress(done[0], len(targets))
                    except Exception: _exc('_nm_ping_sweep_progress')
    return _nm_arp_table()


def _nm_scan_ports(ip, ports=None, timeout=0.5, max_workers=200, on_progress=None):
    """TCP connect-scan a single host across `ports` (default `_NM_SCAN_PORTS`,
    ~1,140 ports). Returns a sorted list of open port ints. `on_progress` has
    the same calling-thread caveat as in `_nm_ping_sweep`.
    """
    import concurrent.futures as _cf
    ports = ports if ports is not None else _NM_SCAN_PORTS
    open_ports = []

    def _try(port):
        try:
            s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            s.settimeout(timeout)
            r = s.connect_ex((ip, port))
            s.close()
            return port if r == 0 else None
        except Exception:
            return None

    done = [0]
    with _cf.ThreadPoolExecutor(max_workers=max_workers) as ex:
        futs = [ex.submit(_try, p) for p in ports]
        for fut in _cf.as_completed(futs):
            done[0] += 1
            res = fut.result()
            if res:
                open_ports.append(res)
            if on_progress:
                try: on_progress(done[0], len(ports))
                except Exception: _exc('_nm_scan_ports_progress')
    return sorted(open_ports)


def _nbns_encode_name(name, pad_to=16):
    """NetBIOS first-level name encoding: each byte of the (space-padded)
    16-byte name becomes two ASCII letters (nibble + 'A'). Computed rather
    than hand-transcribed so a copy/paste slip can't corrupt the packet.
    """
    raw = name.encode('ascii')[:pad_to].ljust(pad_to, b' ')
    out = bytearray()
    for b in raw:
        out.append(0x41 + (b >> 4))
        out.append(0x41 + (b & 0x0F))
    return bytes(out)


def _nbns_skip_name(data, offset):
    """Skip one DNS/NBNS-style name field, honoring compression pointers."""
    length = data[offset]
    if (length & 0xC0) == 0xC0:
        return offset + 2
    while True:
        length = data[offset]
        if length == 0:
            return offset + 1
        if (length & 0xC0) == 0xC0:
            return offset + 2
        offset += 1 + length


def _nm_nbns_query(ip, timeout=1.0):
    """Minimal NetBIOS Name Service (NBSTAT) query on UDP/137 -- no
    third-party deps, just the raw protocol. Fallback name source for local
    Windows/SMB hosts that have no reverse-DNS (PTR) record, which is common
    on a home/office LAN. Returns '' on any failure or non-answer; this is
    best-effort only and was implemented from protocol documentation, not
    verified against a live NBNS responder (this sandbox has no LAN to test
    against) -- it fails closed (silent '') rather than raising, so a bad
    parse just means no name, never a crash.
    """
    try:
        txn_id = os.urandom(2)
        header = txn_id + b'\x00\x00\x00\x01\x00\x00\x00\x00\x00\x00'
        encoded = _nbns_encode_name('*')
        question = b'\x20' + encoded + b'\x00' + b'\x00\x21\x00\x01'
        packet = header + question
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.settimeout(timeout)
        s.sendto(packet, (ip, 137))
        data, _addr = s.recvfrom(2048)
        s.close()
        if len(data) < 13:
            return ''
        offset = _nbns_skip_name(data, 12)   # skip the answer's name field
        offset += 2 + 2 + 4                  # type(2) + class(2) + ttl(4)
        if offset + 2 > len(data):
            return ''
        offset += 2                          # rdlength(2) -- not needed, trust the walk
        if offset + 1 > len(data):
            return ''
        num_names = data[offset]
        offset += 1
        for _ in range(num_names):
            if offset + 18 > len(data):
                break
            raw_name = data[offset:offset+15].decode('ascii', 'ignore').strip()
            suffix = data[offset+15]
            if raw_name and suffix == 0x00:   # 0x00 = workstation/hostname record
                return raw_name
            offset += 18
        return ''
    except Exception:
        return ''


def _nm_full_resolve(ip, timeout=1.5):
    """Best-effort full hostname resolution for a scanned host: reverse DNS
    (PTR) first, wrapped in a hard timeout (`socket.gethostbyaddr` has no
    native timeout and can hang on a slow/misbehaving resolver), then a raw
    NetBIOS query as a LAN-local fallback. Returns '' if neither answers.
    This is deliberately separate from `EtherApeWindow._resolve()` (the
    passive-view resolver), which is async/fire-and-forget and PTR-only --
    a one-shot active scan can afford to wait briefly per host instead.
    """
    result = {}
    def _ptr():
        try:
            result['name'] = socket.gethostbyaddr(ip)[0].rstrip('.')
        except Exception:
            pass
    t = threading.Thread(target=_ptr, daemon=True)
    t.start()
    t.join(timeout)
    name = result.get('name')
    if name and name != ip:
        return name
    return _nm_nbns_query(ip, timeout=1.0)


_NM_ROUTER_VENDORS = ('tp-link', 'netgear', 'd-link', 'asus', 'ubiquiti',
                      'mikrotik', 'linksys', 'arris', 'technicolor', 'huawei',
                      'zte', 'actiontec', 'sagemcom', 'belkin', 'aruba',
                      'ruckus', 'cisco', 'juniper', 'motorola')


def _nm_guess_device_type(ports, vendor, hostname):
    """Best-effort GUESS at what kind of device this is, from open TCP
    ports + MAC vendor + hostname only -- picks which icon to draw on the
    LAN Scan map. This is inference, not verification: nothing here queries
    the device about what it actually is, so it is always presented to the
    user as a guess (icon caption says so), never as a confirmed fact.
    Caller is responsible for the 'router' (default gateway) and 'self'
    (this machine) cases, which are contextual rather than port-based.
    """
    portset = set(ports or [])
    v = (vendor or '').lower()
    h = (hostname or '').lower()
    if (portset & {9100, 631, 515}) or 'printer' in h or 'printer' in v:
        return 'printer'
    if 'synology' in v or 'qnap' in v or 'nas' in h or (portset & {5000, 5001, 548}):
        return 'nas'
    if any(rv in v for rv in _NM_ROUTER_VENDORS) and not (portset - {80, 443, 22, 53}):
        return 'router'
    if portset & {3389, 445, 135, 139}:
        return 'windows'
    if 22 in portset:
        return 'server'
    if portset:
        return 'iot'    # something is listening but matches no known pattern
    return 'device'      # nothing open -- phone/tablet/IoT that doesn't listen


