def _nm_device_name(db, ip, mac=None):
    """Friendly name for an IP. User-set label wins, then OUI, then hostname."""
    with _nm_dev_lock:
        hit = _nm_dev_cache.get(ip)
    if hit and hit.get('name'):
        return hit['name']

    label = None
    if db is not None:
        try:
            row = db.get_device(ip)
            if row and row['label']:
                label = row['label']
                mac = mac or row['mac']
        except Exception:
            _exc('_nm_device_name.db')

    if not label and mac:
        pref = mac.lower()[:8]
        if pref in _NM_OUI:
            label = f'{_NM_OUI[pref]} ({ip.split(".")[-1]})'

    if not label:
        label = ip

    with _nm_dev_lock:
        _nm_dev_cache[ip] = {'name': label, 'mac': mac}
    return label


# ip -> resolved name ('' means "looked it up, nothing found" — a terminal
# state, not "try again"). Separate from _nm_dev_cache because most firewall
# entries are internet addresses an ARP scan will never see, and unlike the
# device inventory this cache should never fall back to returning the IP —
# the caller already has the IP in its own column.
_nm_fw_name_cache = {}
_nm_fw_name_lock  = threading.Lock()


def _nm_fw_names(ips, db=None):
    """Best-effort {ip: name} for a list of firewall-listed addresses.

    Tries, in order: a user-set device label, a known LAN vendor from the
    ARP table (OUI), a well-known special address, then a cached
    reverse-DNS (PTR) name. Never blocks on network I/O: a PTR lookup that
    hasn't completed yet is kicked off on a background thread and simply
    omitted from this call's result — the page polls every few seconds, so
    the next call picks it up once resolved. IPs with nothing found are
    just absent from the returned dict, never mapped to the IP itself.
    """
    out = {}
    arp = _nm_arp_table()
    to_resolve = []
    for ip in ips:
        name = None
        if db is not None:
            try:
                row = db.get_device(ip)
                if row and row['label']:
                    name = row['label']
            except Exception:
                _exc_debug('_nm_fw_names.db')
        if not name:
            mac = arp.get(ip)
            if mac:
                pref = mac.lower()[:8]
                if pref in _NM_OUI:
                    name = f'{_NM_OUI[pref]} ({ip.split(".")[-1]})'
        if not name:
            name = _nm_special_ip(ip)
        if not name:
            with _nm_fw_name_lock:
                cached = _nm_fw_name_cache.get(ip)
            if cached:
                name = cached
            elif cached is None:
                to_resolve.append(ip)
        if name:
            out[ip] = name
    for ip in to_resolve:
        with _nm_fw_name_lock:
            if ip in _nm_fw_name_cache:
                continue
            _nm_fw_name_cache[ip] = ''   # placeholder so we don't fire duplicate lookups
        def _resolve(ip=ip):
            try:
                raw = socket.gethostbyaddr(ip)[0].rstrip('.')
                name = _nm_friendly_host(ip, raw)
                if name == ip:
                    name = ''
            except Exception:
                name = ''
            with _nm_fw_name_lock:
                _nm_fw_name_cache[ip] = name
        threading.Thread(target=_resolve, daemon=True).start()
    return out


def _nm_scan_devices(db):
    """Refresh the device table from ARP. Returns count seen."""
    arp = _nm_arp_table()
    if not arp or db is None:
        return 0
    ts = datetime.now().isoformat()
    for ip, mac in arp.items():
        try:
            db.upsert_device(ip, mac, ts)
        except Exception:
            _exc('_nm_scan_devices')
    with _nm_dev_lock:
        _nm_dev_cache.clear()
    return len(arp)


# ── 5. Statistical anomaly scoring (no AI needed) ────────────────────────────

_NM_ODD_PORTS = {
    23: 'Telnet', 445: 'SMB', 3389: 'RDP', 1433: 'MSSQL', 3306: 'MySQL',
    5900: 'VNC', 4444: 'Metasploit default', 6667: 'IRC', 1080: 'SOCKS',
    9001: 'Tor', 9050: 'Tor', 22: 'SSH',
}


def _nm_score_flows(db, flows, window_days=7):
    """Score flows for oddness using history. Returns [(score, reasons, flow)].

    Signals:
      * destination never seen before in the window   (+3)
      * volume is a statistical outlier vs that dest  (+z, capped)
      * destination port is one that rarely belongs on a home network (+2)
      * flow is to a brand-new country                (+2)
    """
    if not flows:
        return []
    known = set()
    stats = {}
    if db is not None:
        try:
            known, stats = db.flow_baseline(window_days)
        except Exception:
            _exc('_nm_score_flows')

    out = []
    vols = [float(f.get('bytes') or 0) for f in flows]
    mean = (sum(vols) / len(vols)) if vols else 0.0
    var = (sum((v - mean) ** 2 for v in vols) / len(vols)) if vols else 0.0
    sd = var ** 0.5

    for f in flows:
        dst = f.get('dst') or ''
        score = 0.0
        why = []

        if dst and known and dst not in known:
            score += 3.0
            why.append('never seen before')

        b = float(f.get('bytes') or 0)
        st = stats.get(dst)
        if st and st['sd'] > 0:
            z = (b - st['mean']) / st['sd']
            if z > 2:
                score += min(4.0, z)
                why.append(f'volume {z:.1f}sigma above its own norm')
        elif sd > 0:
            z = (b - mean) / sd
            if z > 2.5:
                score += min(3.0, z - 0.5)
                why.append(f'{z:.1f}sigma above other flows')

        port = f.get('port')
        try:
            port = int(port) if port else None
        except Exception:
            port = None
        if port in _NM_ODD_PORTS:
            score += 2.0
            why.append(f'port {port} ({_NM_ODD_PORTS[port]})')

        cc = (f.get('cc') or '').upper()
        if cc and db is not None:
            try:
                if not db.country_seen(cc, window_days):
                    score += 2.0
                    why.append(f'first traffic to {cc}')
            except Exception:
                _exc_debug('_nm_score_flows')

        if score > 0:
            out.append((round(score, 1), why, f))

    out.sort(key=lambda t: -t[0])
    return out


def _nm_quality_history(db, days=7):
    """Readings that carry quality metrics."""
    if db is None:
        return []
    since = (datetime.now() - timedelta(days=days)).isoformat()
    try:
        with db._conn() as c:
            return [dict(r) for r in c.execute(
                "SELECT ts, download, upload, ping, jitter, loss_pct, bloat_ms,"
                " bloat_grade FROM readings WHERE ts >= ? AND jitter IS NOT NULL"
                " ORDER BY ts", (since,))]
    except Exception:
        _exc('_nm_quality_history')
        return []


def _nm_fmt_bytes(b):
    b = float(b or 0)
    for unit in ('B', 'KB', 'MB', 'GB', 'TB'):
        if b < 1024 or unit == 'TB':
            return f'{b:,.1f} {unit}'
        b /= 1024


def _nm_open_quality(monitor):
    """Bufferbloat grade, jitter/loss trends, bandwidth by destination,
    device inventory and anomaly scoring — the stuff a speed number can't tell you."""
    import tkinter as tk
    from tkinter import ttk, simpledialog

    BG, PANEL, ACC, TEXT, DIM = '#050d1a', '#0a1828', '#38b8f0', '#c8dff0', '#6a9ab8'
    db = getattr(monitor, '_db', None)

    win = tk.Toplevel()
    win.title('Network Quality')
    win.configure(bg=BG)
    win.geometry('1080x720')
    _nm_apply_ttk_theme(win)

    nb = ttk.Notebook(win)
    nb.pack(fill='both', expand=True, padx=8, pady=8)

    # ── Tab 1: Quality (bufferbloat grade + jitter/loss trend) ───────────────
    t1 = tk.Frame(nb, bg=BG); nb.add(t1, text='  Quality  ')

    hero = tk.Frame(t1, bg=PANEL); hero.pack(fill='x', padx=10, pady=10)
    q = getattr(monitor, 'last_quality', None) or {}
    grade = q.get('grade')
    gcol = _NM_BLOAT_COLORS.get(grade, DIM)

    tk.Label(hero, text=grade or '—', bg=PANEL, fg=gcol,
             font=(_NM_MONO, 56, 'bold')).pack(side='left', padx=(24, 18), pady=14)
    info = tk.Frame(hero, bg=PANEL); info.pack(side='left', pady=14, anchor='w')
    tk.Label(info, text='BUFFERBLOAT GRADE', bg=PANEL, fg=DIM,
             font=(_NM_MONO, 9, 'bold')).pack(anchor='w')
    _bm = q.get('bloat_ms')
    tk.Label(info, bg=PANEL, fg=TEXT, font=(_NM_MONO, 11), anchor='w',
             text=(f"+{_bm:.0f} ms added latency under load"
                   if _bm is not None else 'run a speed test to measure')
             ).pack(anchor='w', pady=(2, 0))
    tk.Label(info, bg=PANEL, fg=DIM, font=(_NM_MONO, 9), anchor='w', justify='left',
             text=('idle %.0f ms · jitter %.1f ms · loss %.0f%%'
                   % (q.get('idle_ms', 0), q.get('jitter', 0), q.get('loss', 0))
                   if q else 'This is what breaks calls and games — not raw speed.')
             ).pack(anchor='w', pady=(4, 0))

    tk.Label(t1, bg=BG, fg=DIM, font=(_NM_MONO, 8), justify='left', anchor='w',
             text=('Grades: A+ <5ms · A <30ms · B <60ms · C <200ms · D <400ms · F 400ms+   '
                   '(latency added while the link is saturated)')
             ).pack(fill='x', padx=12)

    chart = tk.Frame(t1, bg=BG); chart.pack(fill='both', expand=True, padx=10, pady=8)
    rows = _nm_quality_history(db, days=14)
    if not rows:
        tk.Label(chart, bg=BG, fg=DIM, font=(_NM_MONO, 10),
                 text='\nNo quality readings yet.\nThey are recorded from the next speed test onward.'
                 ).pack(expand=True)
    else:
        try:
            from matplotlib.figure import Figure
            from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg
            fig = Figure(figsize=(9, 4), dpi=96, facecolor=BG)
            xs = [datetime.fromisoformat(r['ts']) for r in rows]

            ax1 = fig.add_subplot(211, facecolor=PANEL)
            ax1.plot(xs, [r['jitter'] or 0 for r in rows], color='#a371f7', lw=1.4, label='jitter ms')
            ax1.plot(xs, [r['bloat_ms'] or 0 for r in rows], color='#ff9f43', lw=1.4, label='bufferbloat ms')
            ax1.legend(facecolor=PANEL, edgecolor=DIM, labelcolor=TEXT, fontsize=7, loc='upper left')

            ax2 = fig.add_subplot(212, facecolor=PANEL, sharex=ax1)
            ax2.plot(xs, [r['loss_pct'] or 0 for r in rows], color='#ff4444', lw=1.4)
            ax2.set_ylabel('loss %', color=TEXT, fontsize=8)

            for ax in (ax1, ax2):
                ax.tick_params(colors=DIM, labelsize=7)
                for s in ax.spines.values():
                    s.set_color(DIM)
                ax.grid(alpha=0.15, color=DIM)
            fig.autofmt_xdate()
            fig.tight_layout()
            cv = FigureCanvasTkAgg(fig, master=chart)
            cv.draw()
            cv.get_tk_widget().pack(fill='both', expand=True)
        except Exception:
            _exc('_nm_open_quality.chart')

    # ── Tab 2: Bandwidth by destination ──────────────────────────────────────
    t2 = tk.Frame(nb, bg=BG); nb.add(t2, text='  Bandwidth  ')
    bar = tk.Frame(t2, bg=BG); bar.pack(fill='x', padx=10, pady=(10, 4))
    tk.Label(bar, text='Window:', bg=BG, fg=DIM, font=(_NM_MONO, 9)).pack(side='left')
    win_var = tk.StringVar(value='24')
    for lbl, hrs in (('1h', '1'), ('12h', '12'), ('24h', '24'), ('7d', '168'), ('30d', '720')):
        ttk.Radiobutton(bar, text=lbl, value=hrs, variable=win_var).pack(side='left', padx=3)

    bw = ttk.Treeview(t2, columns=('dst', 'bytes', 'pkts', 'last'),
                      show='headings', height=20)
    for c_, w_, t_ in (('dst', 380, 'Destination'), ('bytes', 130, 'Data'),
                       ('pkts', 110, 'Packets'), ('last', 170, 'Last seen')):
        bw.heading(c_, text=t_); bw.column(c_, width=w_, anchor='w')
    bw.pack(fill='both', expand=True, padx=10, pady=6)

    bw_status = tk.Label(t2, bg=BG, fg=DIM, font=(_NM_MONO, 8), anchor='w')
    bw_status.pack(fill='x', padx=12, pady=(0, 8))

    def _load_bw(*_a):
        bw.delete(*bw.get_children())
        if db is None:
            bw_status.config(text='Database is disabled — flows are not being recorded.')
            return
        try:
            hrs = int(win_var.get())
            tot = db.flow_totals(hours=hrs, limit=50)
        except Exception:
            _exc('_load_bw'); return
        if not tot:
            bw_status.config(text='No flows recorded yet. Start an EtherApe capture — '
                                  'flows are written to the database every 60 seconds.')
            return
        for r in tot:
            name = _nm_device_name(db, r['dst']) if r['dst'] else '?'
            last = (r['last_ts'] or '')[:19].replace('T', ' ')
            bw.insert('', 'end', values=(name, _nm_fmt_bytes(r['bytes']),
                                         f"{r['pkts']:,}", last))
        grand = sum(r['bytes'] for r in tot)
        bw_status.config(text=f'{len(tot)} destinations · {_nm_fmt_bytes(grand)} total '
                              f'over the last {win_var.get()}h')
    win_var.trace_add('write', _load_bw)

    # ── Tab 3: Devices ───────────────────────────────────────────────────────
    t3 = tk.Frame(nb, bg=BG); nb.add(t3, text='  Devices  ')
    dv = ttk.Treeview(t3, columns=('ip', 'mac', 'label', 'seen'),
                      show='headings', height=20)
    for c_, w_, t_ in (('ip', 150, 'IP'), ('mac', 180, 'MAC'),
                       ('label', 280, 'Name'), ('seen', 170, 'Last seen')):
        dv.heading(c_, text=t_); dv.column(c_, width=w_, anchor='w')
    dv.pack(fill='both', expand=True, padx=10, pady=(10, 4))

    def _load_dev():
        dv.delete(*dv.get_children())
        if db is None:
            return
        for d in db.list_devices():
            dv.insert('', 'end', iid=d['ip'],
                      values=(d['ip'], d['mac'] or '—',
                              d['label'] or _nm_device_name(db, d['ip'], d['mac']),
                              (d['last_seen'] or '')[:19].replace('T', ' ')))

    def _rename():
        sel = dv.selection()
        if not sel or db is None:
            return
        ip = sel[0]
        cur = dv.item(ip, 'values')[2]
        new = simpledialog.askstring('Rename device',
                                     f'Friendly name for {ip}:',
                                     initialvalue=cur, parent=win)
        if new:
            db.set_device_label(ip, new.strip())
            with _nm_dev_lock:
                _nm_dev_cache.pop(ip, None)
            _load_dev()

    def _scan():
        n = _nm_scan_devices(db)
        _load_dev()
        dstat.config(text=f'ARP scan found {n} device(s).')

    drow = tk.Frame(t3, bg=BG); drow.pack(fill='x', padx=10, pady=(0, 4))
    ttk.Button(drow, text='⟳ Scan network', command=_scan).pack(side='left')
    ttk.Button(drow, text='✎ Rename selected', command=_rename).pack(side='left', padx=6)
    dstat = tk.Label(t3, bg=BG, fg=DIM, font=(_NM_MONO, 8), anchor='w',
                     text='Names set here are used everywhere an IP is shown.')
    dstat.pack(fill='x', padx=12, pady=(0, 8))
    dv.bind('<Double-1>', lambda e: _rename())

    # ── Tab 4: Anomalies ─────────────────────────────────────────────────────
    t4 = tk.Frame(nb, bg=BG); nb.add(t4, text='  Anomalies  ')
    an = ttk.Treeview(t4, columns=('score', 'dst', 'bytes', 'why'),
                      show='headings', height=20)
    for c_, w_, t_ in (('score', 70, 'Score'), ('dst', 240, 'Destination'),
                       ('bytes', 110, 'Data'), ('why', 480, 'Why it stands out')):
        an.heading(c_, text=t_); an.column(c_, width=w_, anchor='w')
    an.pack(fill='both', expand=True, padx=10, pady=(10, 4))
    an.tag_configure('hi', foreground='#ff6b6b')
    an.tag_configure('md', foreground='#ff9f43')
    an.tag_configure('lo', foreground='#f7cc73')

    astat = tk.Label(t4, bg=BG, fg=DIM, font=(_NM_MONO, 8), anchor='w', justify='left',
                     text='Scored on: destinations never seen before, volume outliers, '
                          'odd ports, and first-ever traffic to a country. No API key needed.')
    astat.pack(fill='x', padx=12, pady=(0, 8))

    def _load_anom():
        an.delete(*an.get_children())
        if db is None:
            return
        recent = db.flow_totals(hours=24, limit=200)
        flows = [{'dst': r['dst'], 'bytes': r['bytes'], 'port': None, 'cc': None}
                 for r in recent]
        scored = _nm_score_flows(db, flows, window_days=7)
        if not scored:
            astat.config(text='Nothing unusual in the last 24 hours.')
            return
        for score, why, f in scored[:60]:
            tag = 'hi' if score >= 5 else ('md' if score >= 3 else 'lo')
            an.insert('', 'end', tags=(tag,),
                      values=(f'{score:.1f}',
                              _nm_device_name(db, f['dst']) if f['dst'] else '?',
                              _nm_fmt_bytes(f['bytes']), ', '.join(why)))
        astat.config(text=f'{len(scored)} flow(s) scored above zero. '
                          'Higher is stranger, not necessarily malicious.')

    arow = tk.Frame(t4, bg=BG); arow.pack(fill='x', padx=10, pady=(0, 4))
    ttk.Button(arow, text='⟳ Rescan', command=_load_anom).pack(side='left')

    _load_bw(); _load_dev(); _load_anom()
    return win


# ── ISP evidence pack ────────────────────────────────────────────────────────

def _nm_evidence_pack(monitor, days=30, path=None):
    """One-click PDF: uptime %, median vs advertised, outage log.

    Everything here is already computed elsewhere — this just puts it in a form
    you can email to an ISP without arguing about screenshots."""
    from matplotlib.backends.backend_pdf import PdfPages
    from matplotlib.figure import Figure

    # ── Dark theme, matching the rest of the app (same hex values used by
    # the heatmap / quality windows) — plus the user's own download / upload
    # / ping colours from the active colour theme, so the pack's charts use
    # the same three colours as the live gauges and dashboard charts do.
    _EV_BG, _EV_PANEL = '#0a0e18', '#0d1828'
    _EV_FG, _EV_DIM, _EV_ACC, _EV_EDGE = '#c8dff0', '#6a9ab8', '#38b8f0', '#1a2535'
    _EV_GOOD, _EV_WARN, _EV_BAD = '#39ff14', '#ff9f43', '#ff6b6b'
    try:
        _ev_c = monitor.colors
        _EV_DL, _EV_UL, _EV_PG = _ev_c['download'], _ev_c['upload'], _ev_c['ping']
    except Exception:
        _EV_DL, _EV_UL, _EV_PG = '#00d4aa', '#a371f7', '#f7cc73'

    def _ev_page(figsize):
        """A fresh dark-themed page — every page starts from this."""
        f = Figure(figsize=figsize, dpi=100, facecolor=_EV_BG)
        return f

    def _ev_style_axes(ax):
        """Apply the app's dark chart styling to one Axes."""
        ax.set_facecolor(_EV_PANEL)
        ax.tick_params(colors=_EV_DIM, labelsize=8)
        ax.xaxis.label.set_color(_EV_DIM)
        ax.yaxis.label.set_color(_EV_DIM)
        ax.title.set_color(_EV_FG)
        for sp in ax.spines.values():
            sp.set_color(_EV_EDGE)
        ax.grid(alpha=0.25, color=_EV_EDGE)

    def _ev_legend(ax, **kw):
        leg = ax.legend(fontsize=9, facecolor=_EV_PANEL, edgecolor=_EV_EDGE,
                        labelcolor=_EV_FG, **kw)
        return leg

    def _ev_save(pdf, fig):
        pdf.savefig(fig, facecolor=fig.get_facecolor())

    def _ev_textblock(fig, x, y0, lines, fontsize=10, linespacing=1.5):
        """Render a list of monospace lines top-to-bottom, colouring ALL-CAPS
        section headers in the accent colour and '>>' callouts in warn amber,
        so these pages read like the rest of the app instead of a plain
        printout — one fig.text() per line so each can take its own colour."""
        fig_h_in = fig.get_size_inches()[1]
        line_h = (fontsize / 72.0) / fig_h_in * linespacing
        y = y0
        for line in lines:
            stripped = line.strip()
            # Ignore parenthetical units/ranges like "(Mbps)" or "(20:00-22:00)"
            # when deciding if a line is an all-caps section header — those
            # are deliberately mixed-case/numeric and shouldn't disqualify an
            # otherwise all-caps heading such as "DOWNLOAD SPEED (Mbps)".
            _core = re.sub(r'\([^)]*\)', '', stripped)
            is_header = (stripped and not line.startswith(' ')
                         and _core.strip() == _core.strip().upper()
                         and any(ch.isalpha() for ch in _core))
            is_callout = stripped.startswith('>>')
            if is_header:
                fig.text(x, y, line, fontsize=fontsize, family='monospace',
                         va='top', color=_EV_ACC, fontweight='bold')
            elif is_callout:
                fig.text(x, y, line, fontsize=fontsize, family='monospace',
                         va='top', color=_EV_WARN, fontweight='bold')
            elif stripped:
                fig.text(x, y, line, fontsize=fontsize, family='monospace',
                         va='top', color=_EV_FG)
            y -= line_h

    db = getattr(monitor, '_db', None)
    since = datetime.now() - timedelta(days=days)

    if db is not None:
        with db._conn() as c:
            rows = [dict(r) for r in c.execute(
                "SELECT ts, download, upload, ping FROM readings"
                " WHERE ts >= ? ORDER BY ts", (since.isoformat(),))]
    else:
        rows = []
        for i, t in enumerate(monitor.data.get('timestamps', [])):
            try:
                if datetime.fromisoformat(t) >= since:
                    rows.append({'ts': t,
                                 'download': monitor.data['download'][i],
                                 'upload':   monitor.data['upload'][i],
                                 'ping':     monitor.data['ping'][i]})
            except Exception:
                continue
    if not rows:
        raise ValueError('No readings in the selected period.')

    ts   = [datetime.fromisoformat(r['ts']) for r in rows]
    # Drop implausible speed readings before any statistic is computed, so a
    # single mis-parsed upload cannot produce an average of -2.2e11.
    #
    # Each metric is filtered INDEPENDENTLY (a row with a bad download
    # value can still have a perfectly good upload/ping reading, and vice
    # versa), so dls/uls/pgs can each end up shorter than — and containing
    # a different subset of rows than — the full `ts` list above. That
    # means dls/uls/pgs must never be plotted or zipped directly against
    # the unfiltered `ts`: the lengths won't match (that's the exact
    # "x and y must have same first dimension" crash from mismatched
    # array shapes) and even when they happen to match in length, pairing
    # by position would silently attach the wrong timestamp to the wrong
    # reading. Each metric therefore gets its own timestamp list, built in
    # lockstep with its own values, and every plot/zip below uses the
    # matching pair — never the bare `ts` (which is kept only for the
    # overall measurement-window range, computed from ALL rows).
    def _series(key, sane):
        out_t, out_v = [], []
        for r, t in zip(rows, ts):
            v = sane(r[key])
            if v is None:
                continue
            out_t.append(t); out_v.append(v)
        return out_t, out_v

    dl_ts, dls = _series('download', _nm_sane_speed)
    ul_ts, uls = _series('upload',   _nm_sane_speed)
    pg_ts, pgs = _series('ping', lambda v: float(v) if v is not None else None)

    def _median(v):
        s = sorted(v)
        n = len(s)
        return 0.0 if not n else (s[n // 2] if n % 2 else (s[n // 2 - 1] + s[n // 2]) / 2)

    def _pct(v, p):
        s = sorted(v)
        return s[max(0, min(len(s) - 1, int(len(s) * p / 100)))] if s else 0.0

    def _mean(v):
        return sum(v) / len(v) if v else 0.0

    def _max(v):
        # Plain max()/min() raise on an empty sequence — reachable if every
        # reading for one metric in the window happened to be filtered out
        # above (e.g. every download test that period was implausible).
        return max(v) if v else 0.0

    def _min(v):
        return min(v) if v else 0.0

    def _stdev(v):
        n = len(v)
        if n < 2:
            return 0.0
        m = sum(v) / n
        return (sum((x - m) ** 2 for x in v) / (n - 1)) ** 0.5

    try:
        _iv = float(monitor._interval_minutes)
    except Exception:
        _iv = 5.0
    outages = (_nm_find_outages(db, _iv, days=days) or []) if db is not None else []
    down_min = sum(o[2] for o in outages)
    span_min = max(1.0, (ts[-1] - ts[0]).total_seconds() / 60.0)
    uptime = 100.0 * (1 - min(1.0, down_min / span_min))

    try:
        adv_d = float(monitor.config.get('advertised_down') or 0)
        adv_u = float(monitor.config.get('advertised_up') or 0)
    except Exception:
        adv_d = adv_u = 0.0

    med_d, med_u = _median(dls), _median(uls)
    path = path or str(Path(_app_dir()) /
                       f'ISP_Evidence_{datetime.now():%Y%m%d_%H%M}.pdf')

    # ── Derived statistics (verbose) ────────────────────────────────────────
    n = len(rows)
    mean_d, std_d = _mean(dls), _stdev(dls)
    mean_u = _mean(uls)
    med_p, mean_p = _median(pgs), _mean(pgs)
    jit = (_mean([abs(pgs[i] - pgs[i - 1]) for i in range(1, len(pgs))])
           if len(pgs) > 1 else 0.0)
    zero_d = sum(1 for x in dls if x <= 0)
    below90 = below75 = below50 = 0
    if adv_d > 0:
        below90 = sum(1 for x in dls if x < 0.90 * adv_d)
        below75 = sum(1 for x in dls if x < 0.75 * adv_d)
        below50 = sum(1 for x in dls if x < 0.50 * adv_d)
    # Ofcom-style evening peak window 20:00–22:00 — paired with dl_ts, the
    # timestamp list that actually matches dls index-for-index (see above).
    peak_d = [d for t, d in zip(dl_ts, dls) if 20 <= t.hour < 22]
    off_d = [d for t, d in zip(dl_ts, dls) if not (20 <= t.hour < 22)]
    med_peak, med_off = _median(peak_d), _median(off_d)
    longest = max((o[2] for o in outages), default=0.0)
    mean_out = _mean([o[2] for o in outages]) if outages else 0.0
    # Built from each metric's own (timestamp, value) pairs rather than a
    # single zip(ts, dls, uls, pgs) — that would silently misalign a day's
    # download figure with another day's upload/ping whenever the three
    # series had dropped different rows.
    daily = {}
    for t, d in zip(dl_ts, dls):
        daily.setdefault(t.date(), {'d': [], 'u': [], 'p': []})['d'].append(d)
    for t, u in zip(ul_ts, uls):
        daily.setdefault(t.date(), {'d': [], 'u': [], 'p': []})['u'].append(u)
    for t, p in zip(pg_ts, pgs):
        daily.setdefault(t.date(), {'d': [], 'u': [], 'p': []})['p'].append(p)

    with PdfPages(path) as pdf:
        # ── Page 1: availability + download detail ──────────────────────────
        fig = _ev_page((8.27, 11.69))   # A4
        fig.suptitle('Broadband Performance Evidence Pack',
                     fontsize=17, fontweight='bold', y=0.965, color=_EV_FG)
        fig.text(0.08, 0.935, 'Page 1 of 8  —  Summary: Availability & Download',
                 fontsize=9, style='italic', color=_EV_DIM)

        lines = [
            f'Report generated    {datetime.now():%d %B %Y, %H:%M}',
            f'Measurement window  {ts[0]:%d %b %Y %H:%M}  to  {ts[-1]:%d %b %Y %H:%M}',
            f'Nominal period      {days} days  ({span_min / 60 / 24:.1f} days of samples)',
            f'Total speed tests   {n:,}   (approx. 1 every {_iv:.0f} min)',
            f'Failed / 0-result   {zero_d:,} tests',
            '',
            'SERVICE AVAILABILITY',
            f'    Uptime                      {uptime:.2f}%',
            f'    Recorded outages            {len(outages)}',
            f'    Total time without service  {down_min:.0f} min  ({down_min / 60:.1f} h)',
            f'    Longest single outage       {longest:.0f} min',
            f'    Average outage length       {mean_out:.0f} min',
            '',
            'DOWNLOAD SPEED (Mbps)',
            (f'    Advertised                  {adv_d:.0f}' if adv_d else
             '    Advertised                  (not configured)'),
            f'    Median achieved             {med_d:.1f}',
            f'    Mean achieved               {mean_d:.1f}   (std dev {std_d:.1f})',
            f'    Best / worst test           {_max(dls):.1f} / {_min(dls):.1f}',
            f'    Percentiles  P5/P10/P25     {_pct(dls, 5):.1f} / {_pct(dls, 10):.1f} / {_pct(dls, 25):.1f}',
            f'                 P75/P90/P95    {_pct(dls, 75):.1f} / {_pct(dls, 90):.1f} / {_pct(dls, 95):.1f}',
        ]
        if adv_d > 0:
            pctv = 100.0 * med_d / adv_d
            lines += [
                f'    Median as % of advertised   {pctv:.0f}%',
                f'    Tests below 90% advertised  {below90:,} of {n:,}  ({100 * below90 / max(1, n):.0f}%)',
                f'    Tests below 75% advertised  {below75:,}  ({100 * below75 / max(1, n):.0f}%)',
                f'    Tests below 50% advertised  {below50:,}  ({100 * below50 / max(1, n):.0f}%)',
            ]
            if pctv < 90:
                lines.append(f'    >> Median is {100 - pctv:.0f}% BELOW the advertised download speed.')
        if peak_d:
            lines += [
                '',
                'PEAK-HOURS DOWNLOAD  (20:00–22:00)',
                f'    Median during peak          {med_peak:.1f} Mbps  ({len(peak_d):,} tests)',
                f'    Median outside peak         {med_off:.1f} Mbps',
            ]
            if med_off > 0 and med_peak < med_off:
                lines.append(f'    >> {100 * (1 - med_peak / med_off):.0f}% slower during the evening peak.')

        _ev_textblock(fig, 0.08, 0.905, lines, fontsize=10, linespacing=1.5)
        _ev_save(pdf, fig)

        # ── Page 2: upload + latency + notes ────────────────────────────────
        figS2 = _ev_page((8.27, 11.69))
        figS2.suptitle('Broadband Performance Evidence Pack',
                       fontsize=17, fontweight='bold', y=0.965, color=_EV_FG)
        figS2.text(0.08, 0.935, 'Page 2 of 8  —  Summary: Upload, Latency & Method',
                   fontsize=9, style='italic', color=_EV_DIM)
        lines2 = [
            'UPLOAD SPEED (Mbps)',
            (f'    Advertised                  {adv_u:.0f}' if adv_u else
             '    Advertised                  (not configured)'),
            f'    Median achieved             {med_u:.1f}',
            f'    Mean achieved               {mean_u:.1f}',
            f'    Best / worst test           {_max(uls):.1f} / {_min(uls):.1f}',
            f'    Percentiles P10/P50/P90     {_pct(uls, 10):.1f} / {_pct(uls, 50):.1f} / {_pct(uls, 90):.1f}',
        ]
        if adv_u > 0:
            lines2.append(f'    Median as % of advertised   {100.0 * med_u / adv_u:.0f}%')
        lines2 += [
            '',
            'LATENCY / PING (ms)',
            f'    Median                      {med_p:.0f}',
            f'    Mean                        {mean_p:.0f}',
            f'    Best / worst                {_min(pgs):.0f} / {_max(pgs):.0f}',
            f'    P90 / P95 / P99             {_pct(pgs, 90):.0f} / {_pct(pgs, 95):.0f} / {_pct(pgs, 99):.0f}',
            f'    Jitter (avg variation)      {jit:.0f}',
            '',
            'METHOD & NOTES',
            '    - Speeds measured with Ookla Speedtest CLI against the',
            '      nearest server, from a wired connection where available.',
            '    - "Advertised" figures are those entered in the app config;',
            '      leave them set to your provider\'s quoted line speed.',
            '    - Providers typically advertise an average speed measured at',
            '      peak time (20:00–22:00). The peak-hours figures on page 1',
            '      are directly comparable to that basis.',
            '    - Uptime is derived from gaps between successful tests at the',
            f'      configured {_iv:.0f}-minute interval; red bands on the charts',
            '      mark periods with no successful measurement.',
            '    - Raw per-test data (CSV) is available on request.',
        ]
        _ev_textblock(figS2, 0.08, 0.905, lines2, fontsize=10, linespacing=1.5)
        _ev_save(pdf, figS2)

        # ── Page 3: download over time ──────────────────────────────────────
        fig2 = _ev_page((11.69, 8.27))
        ax = fig2.add_subplot(111)
        _ev_style_axes(ax)
        ax.plot(dl_ts, dls, lw=0.9, color=_EV_DL, label='Download (Mbps)')
        ax.axhline(med_d, color=_EV_GOOD, ls='--', lw=1.2,
                   label=f'Median {med_d:.1f} Mbps')
        if adv_d > 0:
            ax.axhline(adv_d, color=_EV_WARN, ls='-', lw=1.4,
                       label=f'Advertised {adv_d:.0f} Mbps')
        for _st, _en, _mn in outages:
            try:
                ax.axvspan(_st, _en, color=_EV_BAD, alpha=0.25)
            except Exception:
                continue
        ax.set_title('Download speed over the measurement period '
                     '(red bands = no service)', fontsize=12, color=_EV_FG)
        ax.set_ylabel('Mbps', color=_EV_DIM)
        _ev_legend(ax)
        fig2.autofmt_xdate()
        fig2.tight_layout()
        _ev_save(pdf, fig2)

        # ── Page 4: upload over time ────────────────────────────────────────
        figU = _ev_page((11.69, 8.27))
        axU = figU.add_subplot(111)
        _ev_style_axes(axU)
        axU.plot(ul_ts, uls, lw=0.9, color=_EV_UL, label='Upload (Mbps)')
        axU.axhline(med_u, color=_EV_GOOD, ls='--', lw=1.2,
                    label=f'Median {med_u:.1f} Mbps')
        if adv_u > 0:
            axU.axhline(adv_u, color=_EV_WARN, ls='-', lw=1.4,
                        label=f'Advertised {adv_u:.0f} Mbps')
        for _st, _en, _mn in outages:
            try:
                axU.axvspan(_st, _en, color=_EV_BAD, alpha=0.25)
            except Exception:
                continue
        axU.set_title('Upload speed over the measurement period '
                      '(red bands = no service)', fontsize=12, color=_EV_FG)
        axU.set_ylabel('Mbps', color=_EV_DIM)
        _ev_legend(axU)
        figU.autofmt_xdate()
        figU.tight_layout()
        _ev_save(pdf, figU)

        # ── Page 5: latency over time ───────────────────────────────────────
        figL = _ev_page((11.69, 8.27))
        axL = figL.add_subplot(111)
        _ev_style_axes(axL)
        axL.plot(pg_ts, pgs, lw=0.9, color=_EV_PG, label='Ping (ms)')
        axL.axhline(med_p, color=_EV_GOOD, ls='--', lw=1.2,
                    label=f'Median {med_p:.0f} ms')
        axL.axhline(_pct(pgs, 95), color=_EV_WARN, ls=':', lw=1.2,
                    label=f'P95 {_pct(pgs, 95):.0f} ms')
        axL.set_title('Latency (ping) over the measurement period', fontsize=12, color=_EV_FG)
        axL.set_ylabel('ms', color=_EV_DIM)
        _ev_legend(axL)
        figL.autofmt_xdate()
        figL.tight_layout()
        _ev_save(pdf, figL)

        # ── Page 6: download distribution ───────────────────────────────────
        figH = _ev_page((11.69, 8.27))
        axH = figH.add_subplot(111)
        _ev_style_axes(axH)
        axH.hist(dls, bins=40, color=_EV_DL, alpha=0.85, edgecolor=_EV_BG)
        axH.axvline(med_d, color=_EV_GOOD, ls='--', lw=1.4,
                    label=f'Median {med_d:.1f} Mbps')
        if adv_d > 0:
            axH.axvline(adv_d, color=_EV_WARN, lw=1.4,
                        label=f'Advertised {adv_d:.0f} Mbps')
        axH.axvline(_pct(dls, 10), color=_EV_UL, ls=':', lw=1.2,
                    label=f'Slowest 10% below {_pct(dls, 10):.1f} Mbps')
        axH.set_title('Distribution of download-speed results', fontsize=12, color=_EV_FG)
        axH.set_xlabel('Mbps', color=_EV_DIM)
        axH.set_ylabel('Number of tests', color=_EV_DIM)
        _ev_legend(axH)
        figH.tight_layout()
        _ev_save(pdf, figH)

        # ── Page 7: daily breakdown ─────────────────────────────────────────
        figD = _ev_page((8.27, 11.69))
        figD.suptitle('Daily Breakdown', fontsize=15, fontweight='bold', y=0.96,
                      color=_EV_FG)
        dbody = [f'{"Date":<14}{"Tests":>6}{"Med DL":>10}{"Med UL":>10}{"Med ms":>9}',
                 '-' * 49]
        for k in list(daily.keys())[:31]:
            dd = daily[k]
            dbody.append(f'{k:%d %b %Y}   {len(dd["d"]):>4}'
                         f'{_median(dd["d"]):>10.1f}{_median(dd["u"]):>10.1f}'
                         f'{_median(dd["p"]):>9.0f}')
        if len(daily) > 31:
            dbody.append(f'... and {len(daily) - 31} more days')
        _ev_textblock(figD, 0.09, 0.90, dbody, fontsize=9, linespacing=1.5)
        _ev_save(pdf, figD)

        # ── Page 8: the outage log ──────────────────────────────────────────
        fig3 = _ev_page((8.27, 11.69))
        fig3.suptitle('Outage Log', fontsize=15, fontweight='bold', y=0.96,
                      color=_EV_FG)
        if outages:
            body = [f'{"#":>3}  {"Start":<18}{"End":<18}{"Duration":>10}', '-' * 52]
            for _i, (_st, _en, _mn) in enumerate(outages[:80], 1):
                body.append(f'{_i:>3}  {_st:%d %b %H:%M}      {_en:%d %b %H:%M}      '
                            f'{_mn:>6.0f} min')
            if len(outages) > 80:
                body.append(f'... and {len(outages) - 80} more')
            body += [
                '',
                f'Total outages    {len(outages)}',
                f'Total downtime   {down_min:.0f} min  ({down_min / 60:.1f} h)',
                f'Longest outage   {longest:.0f} min',
                f'Average outage   {mean_out:.0f} min',
            ]
        else:
            body = ['No outages recorded in this period.']
        _ev_textblock(fig3, 0.08, 0.90, body, fontsize=9.5, linespacing=1.5)
        fig3.text(0.08, 0.06,
                  'Measurements taken with Ookla Speedtest CLI against the nearest server,\n'
                  'from a wired connection where available. Raw data available on request.',
                  fontsize=8, style='italic', color=_EV_DIM)
        _ev_save(pdf, fig3)

    log.info(f'[evidence] wrote {path}')
    return path


def _nm_open_evidence(monitor, parent=None):
    """Ask for a period, build the PDF, open it."""
    import tkinter as tk
    from tkinter import ttk, messagebox

    BG, DIM, TEXT = '#050d1a', '#6a9ab8', '#c8dff0'
    dlg = tk.Toplevel(parent) if parent else tk.Toplevel()
    dlg.title('ISP Evidence Pack')
    dlg.configure(bg=BG)
    dlg.geometry('460x230')
    _nm_apply_ttk_theme(dlg)

    tk.Label(dlg, text='ISP Evidence Pack', bg=BG, fg=TEXT,
             font=(_NM_MONO, 13, 'bold')).pack(pady=(16, 4))
    tk.Label(dlg, bg=BG, fg=DIM, font=(_NM_MONO, 9), justify='left',
             text='A PDF showing uptime, median speed against what you\npay for, '
                  'and every outage with timestamps.'
             ).pack(pady=(0, 12))

    row = tk.Frame(dlg, bg=BG); row.pack()
    tk.Label(row, text='Period:', bg=BG, fg=DIM, font=(_NM_MONO, 9)).pack(side='left')
    per = tk.StringVar(value='30')
    ttk.Combobox(row, textvariable=per, width=10, state='readonly',
                 values=('7', '14', '30', '60', '90')).pack(side='left', padx=6)
    tk.Label(row, text='days', bg=BG, fg=DIM, font=(_NM_MONO, 9)).pack(side='left')

    stat = tk.Label(dlg, bg=BG, fg=DIM, font=(_NM_MONO, 8))
    stat.pack(pady=(10, 0))

    def _go():
        stat.config(text='Building…', fg=DIM)
        dlg.update_idletasks()
        try:
            p = _nm_evidence_pack(monitor, days=int(per.get()))
        except Exception as ex:
            _exc('_nm_open_evidence')
            stat.config(text=str(ex)[:60], fg='#ff6b6b')
            return
        stat.config(text=Path(p).name, fg='#39ff14')
        try:
            import os as _os
            if sys.platform == 'win32':
                _os.startfile(p)                                 # noqa: S606
            else:
                subprocess.Popen(['xdg-open', p])
        except Exception:
            messagebox.showinfo('Saved', f'Written to:\n{p}', parent=dlg)

    ttk.Button(dlg, text='Generate PDF', command=_go).pack(pady=12)
    return dlg


class SpeedTestMonitor:
    def __init__(self):
        self.AGENTS_FILE = str(_app_dir() / 'agents.json')
        self.config  = self._load_config()
        # ── Database init + auto-migration ────────────────────────────────
        self._stopping = False
        _monitor_instances.append(self)
        self._db = SpeedDB(DB_FILE) if USE_DB else None
        if self._db:
            n = self._db.import_from_json(DATA_FILE)
            if n > 0:
                import shutil
                shutil.copy2(DATA_FILE, DATA_FILE + '.bak')
                print(f'  Migrated {n} records to SQLite. JSON backed up as {DATA_FILE}.bak')
        self.data    = self._load_data()
        self.current_view   = "Today"
        self.history_offset = 0
        self._fig           = None
        self._d_dl   = 0.0
        self._d_ul   = 0.0
        self._d_ping = 0.0
        self._d_dns  = 0.0
        self._dns_history  = []
        self._dns_per_host = []
        self._dns_dirty    = False  # signals on_tick to redraw chart
        self._running_dns    = False
        self._running_manual = False

    # ── Config / data persistence ──────────────────────────────────────────────
    def _load_config(self):
        defs = {"theme": "Ocean", "custom": None,
                "speedtest_path": "", "tshark_path": "", "dns_hosts": "", "interval_minutes": 5, "web_port": 8765,
                "advertised_down": 0, "advertised_up": 0, "tools_dir": "",
                # Alerting
                "alerts_enabled": "", "alert_webhook": "", "alert_debounce_min": "15",
                "alert_dl_below": "", "alert_ul_below": "", "alert_ping_above": "",
                "alert_jitter_above": "", "alert_loss_above": "", "alert_bloat_above": "",
                "bloat_host": "1.1.1.1",
                # Diagnostics
                "debug_logging": False,
                "skip_privilege_warning": False,
                # Keep Windows Firewall dropped-connection logging on, so the
                # report can count attempts against your block rules. Enabled by
                # default; the app re-applies it at startup if the OS reset it.
                "firewall_drop_logging": True}
        if Path(CONFIG_FILE).exists():
            try:
                with open(CONFIG_FILE) as f:
                    loaded = json.load(f)
                if isinstance(loaded.get('theme'), str):
                    if loaded['theme'] in ('Ocean', 'Sunset', 'Neon', 'Pastel', 'Mono', None):
                        defs['theme'] = loaded['theme']
                if isinstance(loaded.get('custom'), dict):
                    custom = loaded['custom']
                    safe = {}
                    for k in ('download', 'upload', 'ping'):
                        v = custom.get(k, '')
                        if isinstance(v, str) and len(v) == 7 and v.startswith('#'):
                            if all(c in '0123456789abcdefABCDEF' for c in v[1:]):
                                safe[k] = v
                    if len(safe) == 3:
                        defs['custom'] = safe
                for key in ('speedtest_path', 'tshark_path', 'dns_hosts', 'interval_minutes', 'web_port',
                            'advertised_down', 'advertised_up', 'tools_dir',
                            'alert_webhook', 'alert_debounce_min',
                            'alert_dl_below', 'alert_ul_below', 'alert_ping_above',
                            'alert_jitter_above', 'alert_loss_above', 'alert_bloat_above',
                            'bloat_host'):
                    v = loaded.get(key, '')
                    # Accept numbers as well as strings. web_port and
                    # interval_minutes are SAVED as ints, so an isinstance(str)
                    # test silently discarded them and they reverted to the
                    # defaults on every restart.
                    if isinstance(v, str):
                        defs[key] = v.strip()
                    elif isinstance(v, (int, float)) and not isinstance(v, bool):
                        defs[key] = v
                # alerts_enabled is a bool, not a string — the isinstance(str)
                # filter above would silently drop it and alerting would never
                # survive a restart.
                # Boolean keys need restoring explicitly for the same reason.
                for _bkey in ('alerts_enabled', 'debug_logging',
                              'skip_privilege_warning', 'firewall_drop_logging'):
                    if _bkey in loaded:
                        defs[_bkey] = bool(loaded[_bkey])
            except Exception:
                _exc('_load_config')
        return defs

    def _save_config(self):
        with open(CONFIG_FILE, 'w') as f:
            json.dump(self.config, f, indent=2)

    @property
    def _speedtest_exe(self):
        p = self.config.get('speedtest_path', '').strip()
        return p if p else _DEFAULT_SPEEDTEST_PATH

    @property
    def _tshark_exe(self):
        p = self.config.get('tshark_path', '').strip()
        return p if p else _DEFAULT_TSHARK_PATH

    @property
    def _interval_minutes(self):
        try:
            v = int(self.config.get('interval_minutes', INTERVAL_MINUTES))
            return max(1, min(v, 1440))  # clamp 1 min – 24 h
        except (ValueError, TypeError):
            return INTERVAL_MINUTES

    def _load_data(self):
        if USE_DB and getattr(self, '_db', None):
            try:
                d = self._db.load_data()
                self._dns_history = list(zip(d['dns_timestamps'], d['dns_values']))
                return d
            except Exception as e:
                print(f'  DB load error: {e}, falling back to JSON')
        # JSON fallback
        if Path(DATA_FILE).exists():
            try:
                with open(DATA_FILE) as f:
                    raw = f.read()
                    d = json.loads(raw) if raw else self._empty()
                    if not isinstance(d, dict):
                        return self._empty()
                    for key in ('timestamps', 'download', 'upload', 'ping',
                                'dns_timestamps', 'dns_values'):
                        if not isinstance(d.get(key), list):
                            d[key] = []
                    d.setdefault('dns_timestamps', [])
                    d.setdefault('dns_values', [])
                    for key in ('timestamps', 'download', 'upload', 'ping'):
                        d[key] = d[key][-10000:]
                    d['dns_timestamps'] = d['dns_timestamps'][-500:]
                    d['dns_values']     = d['dns_values'][-500:]
                    n = min(len(d['timestamps']), len(d['download']),
                            len(d['upload']), len(d['ping']))
                    for key in ('timestamps', 'download', 'upload', 'ping'):
                        d[key] = d[key][:n]
                    n_dns = min(len(d['dns_timestamps']), len(d['dns_values']))
                    d['dns_timestamps'] = d['dns_timestamps'][:n_dns]
                    d['dns_values']     = d['dns_values'][:n_dns]
                    self._dns_history = list(zip(d['dns_timestamps'], d['dns_values']))
                    return d
            except Exception:
                _exc('_load_data')
        return self._empty()

    def _empty(self):
        return {'timestamps': [], 'download': [], 'upload': [], 'ping': [],
                'dns_timestamps': [], 'dns_values': []}

    def _save_data(self):
        self.data['dns_timestamps'] = [ts for ts, _ in self._dns_history]
        self.data['dns_values']     = [v  for _, v in self._dns_history]
        if USE_DB and getattr(self, '_db', None):
            return  # DB writes happen immediately in run_speedtest/run_dns_check
        with open(DATA_FILE, 'w') as f:
            json.dump(self.data, f, indent=2)

    def export_range(self, start_dt, end_dt, fmt='csv'):
        rows = []
        for ts, dl, ul, pg in zip(
                self.data['timestamps'], self.data['download'],
                self.data['upload'], self.data['ping']):
            t = datetime.fromisoformat(ts)
            if start_dt <= t <= end_dt:
                rows.append({'timestamp': ts, 'download_mbps': dl,
                             'upload_mbps': ul, 'ping_ms': pg})
        stamp = datetime.now().strftime('%Y%m%d_%H%M%S')
        if fmt == 'json':
            out = Path(DATA_FILE).parent / f"speedtest_export_{stamp}.json"
            with open(out, 'w') as f:
                json.dump(rows, f, indent=2)
        else:
            out = Path(DATA_FILE).parent / f"speedtest_export_{stamp}.csv"
            with open(out, 'w', newline='') as f:
                writer = csv.DictWriter(
                    f, fieldnames=['timestamp','download_mbps','upload_mbps','ping_ms'])
                writer.writeheader(); writer.writerows(rows)
        return str(out), len(rows)

    @property
    def colors(self):
        if self.config.get("custom"):
            return self.config["custom"]
        return THEMES.get(self.config.get("theme", "Ocean"), THEMES["Ocean"])

    # ── Speed test ─────────────────────────────────────────────────────────────
    def run_speedtest(self):
        log.info("run_speedtest: starting")
        try:
            ts = datetime.now().strftime('%H:%M:%S')
            print(f"[{ts}] Running speed test...")
            exe = self._speedtest_exe
            if not exe or not Path(exe).exists():
                # Fall back to any supported CLI on PATH before giving up, so a
                # Linux install with librespeed-cli works with no configuration.
                found, _eng = _nm_st_find()
                if found:
                    exe = found
                    log.info('run_speedtest: using %s (%s)', found, _eng)
                else:
                    raise FileNotFoundError(
                        'No speed-test CLI found. On Linux:  sudo apt install '
                        'speedtest-cli   (or download librespeed-cli from '
                        'github.com/librespeed/speedtest-cli). Then set the path '
                        'in Settings if it is not on PATH. Looked for: %s' % exe)
            dl = ul = pg = None

            # ── Bufferbloat prep: idle latency BEFORE we saturate the link ──
            _bhost = (self.config.get('bloat_host') or '1.1.1.1').strip() or '1.1.1.1'
            _idle_rtts = _nm_ping_samples(_bhost, count=8)
            _qual = _nm_quality_stats(_idle_rtts)
            _idle_ms = _qual['avg_ms']
            _pinger = _NmLoadPinger(_bhost).start()   # keeps pinging under load

            # Engine-agnostic: librespeed-cli and speedtest-cli are open source,
            # so a build can ship without Ookla's proprietary CLI. Ookla is still
            # supported for anyone who already has it.
            _eng = _nm_st_engine(exe)
            if _eng in ('librespeed', 'sivel'):
                _res = _nm_st_measure(exe, _eng, timeout=180)
                print(f"   {_eng}: ok={_res['ok']} {_res['error'][:80]}")
                if _res['ok']:
                    dl, ul, pg = _res['download'], _res['upload'], _res['ping']
                else:
                    print(f"   {_eng} failed: {_res['error'][:120]}")

            if dl is None:
                r = subprocess.run(
                    [exe, "--format=json", "--accept-license", "--accept-gdpr"],
                    capture_output=True, text=True, timeout=150)
                print(f"   JSON attempt: exit={r.returncode}")
                if r.stderr.strip():
                    print(f"   stderr: {r.stderr.strip()[:300]}")
                if r.returncode == 0:
                    try:
                        st = json.loads(r.stdout.strip())
                        if 'bandwidth' in st.get('download', {}):
                            dl = round(st['download']['bandwidth'] / 125000, 2)
                            ul = round(st['upload']['bandwidth']   / 125000, 2)
                            pg = st['ping']['latency']
                        elif 'download' in st:
                            dl = round(st['download'] / 1e6, 2) if st['download'] > 1000 else float(st['download'])
                            ul = round(st['upload']   / 1e6, 2) if st['upload']   > 1000 else float(st['upload'])
                            pg = float(st.get('ping', 0))
                        else:
                            print("   JSON parsed but no download key found")
                    except (json.JSONDecodeError, KeyError, TypeError) as e:
                        print(f"   JSON parse failed: {e}")
                else:
                    print(f"   JSON mode not supported (exit {r.returncode}), trying plain-text...")
            if dl is None:
                r2 = subprocess.run(
                    [exe, "--accept-license", "--accept-gdpr"],
                    capture_output=True, text=True, timeout=150)
                txt = r2.stdout + r2.stderr
                dl = self._rx(txt, r'Download[^:]*:\s*([\d.]+)')
                ul = self._rx(txt, r'Upload[^:]*:\s*([\d.]+)')
                pg = self._rx(txt, r'(?:Latency|Ping)[^:]*:\s*([\d.]+)')
            if dl is None:
                r3 = subprocess.run([exe], capture_output=True, text=True, timeout=150)
                txt3 = r3.stdout + r3.stderr
                dl = self._rx(txt3, r'Download[^:]*:\s*([\d.]+)')
                ul = self._rx(txt3, r'Upload[^:]*:\s*([\d.]+)')
                pg = self._rx(txt3, r'(?:Latency|Ping)[^:]*:\s*([\d.]+)')
            # ── Bufferbloat: latency measured DURING the transfer ──────────
            _loaded = _pinger.stop()
            _bloat_ms = _bgrade = None
            if _idle_ms > 0 and _loaded:
                # Median of the worst half: a single spike isn't bufferbloat,
                # but a sustained rise under load is.
                _sorted = sorted(_loaded)
                _upper = _sorted[len(_sorted) // 2:]
                _loaded_ms = sum(_upper) / len(_upper)
                _bloat_ms = max(0.0, _loaded_ms - _idle_ms)
                _bgrade = _nm_bloat_grade(_bloat_ms)

            if dl is None:
                raise ValueError("All attempts failed – could not read speed values.")
            pg = pg if pg is not None else 0.0
            ul = ul if ul is not None else 0.0
            _jit  = round(_qual['jitter_ms'], 2)
            _loss = round(_qual['loss_pct'], 1)

            _ts = datetime.now().isoformat()
            self.data['timestamps'].append(_ts)
            # Clamp before storing: a mis-parsed upload (wrong units from the
            # CLI) must never reach the data, or it wrecks the chart axis and
            # every average forever after. An implausible value is dropped to 0
            # rather than poisoning the series.
            if _nm_sane_speed(dl) is None:
                log.warning('[speedtest] implausible download %r discarded', dl); dl = 0.0
            if _nm_sane_speed(ul) is None:
                log.warning('[speedtest] implausible upload %r discarded', ul); ul = 0.0
            self.data['download'].append(dl)
            self.data['upload'].append(ul)
            self.data['ping'].append(pg)
            self.last_quality = {'jitter': _jit, 'loss': _loss,
                                 'bloat_ms': _bloat_ms, 'grade': _bgrade,
                                 'idle_ms': _idle_ms}
            if USE_DB and getattr(self, '_db', None):
                self._db.insert_reading(_ts, dl, ul, pg, jitter=_jit,
                                        loss_pct=_loss, bloat_ms=_bloat_ms,
                                        bloat_grade=_bgrade)
            else:
                for key in ('timestamps', 'download', 'upload', 'ping'):
                    if len(self.data[key]) > 10000:
                        self.data[key] = self.data[key][-10000:]
                self._save_data()

            _bt = f" | Bloat +{_bloat_ms:.0f}ms ({_bgrade})" if _bloat_ms is not None else ""
            print(f" ✓ DL {dl} Mbps | UL {ul} Mbps | Ping {pg} ms"
                  f" | Jitter {_jit}ms | Loss {_loss}%{_bt}")

            try:
                _nm_check_alerts(self, dl=dl, ul=ul, ping=pg, jitter=_jit,
                                 loss=_loss, bloat_ms=_bloat_ms)
            except Exception:
                _exc('run_speedtest.alerts')

            self._data_dirty = True   # signal on_tick to reload charts
        except Exception as e:
            try:
                _pinger.stop()
            except Exception:
                _exc_debug('run_speedtest')
            print(f" ✗ {e}")
            # A failed speedtest with no connectivity is an outage worth alerting on.
            try:
                if _nm_ping_once('1.1.1.1') is None:
                    _nm_check_alerts(self, outage=True)
            except Exception:
                _exc('run_speedtest.outage')

    DNS_HOSTS = ['google.com', 'cloudflare.com', 'microsoft.com',
                 'amazon.com', 'bbc.co.uk', 'github.com']

    def run_dns_check(self):
        log.info("run_dns_check: starting")
        per_host = {}  # host -> ms or None
        configured = self.config.get('dns_hosts', '').strip()
        hosts_to_check = (
            [h.strip() for h in configured.split(',') if h.strip()]
            if configured else self.DNS_HOSTS
        )
        for host in hosts_to_check:
            try:
                t0 = time.perf_counter()
                socket.getaddrinfo(host, None)
                per_host[host] = round((time.perf_counter() - t0) * 1000, 2)
            except OSError:
                per_host[host] = None
        results = [v for v in per_host.values() if v is not None]
        if not results:
            print('   DNS: all hosts failed')
            return None
        avg_ms = round(sum(results) / len(results), 2)
        ts = datetime.now().isoformat()
        self._dns_history.append((ts, avg_ms))
        # Store per-host breakdown alongside history
        if not hasattr(self, '_dns_per_host'):
            self._dns_per_host = []
        self._dns_per_host.append((ts, per_host))
        if len(self._dns_history) > 500:
            self._dns_history   = self._dns_history[-500:]
            self._dns_per_host  = self._dns_per_host[-500:]
        if USE_DB and getattr(self, '_db', None):
            self._db.insert_dns(ts, avg_ms, per_host)
        ok  = len(results)
        tot = len(hosts_to_check)
        breakdown = '  '.join(
            f'{h.split(".")[0]}:{v:.0f}ms' if v else f'{h.split(".")[0]}:FAIL'
            for h, v in per_host.items()
        )
        print(f'   DNS avg: {avg_ms:.1f} ms  ({ok}/{tot})  {breakdown}')
        if not (USE_DB and getattr(self, '_db', None)):
            self._save_data()
        self._dns_dirty = True
        return avg_ms

    def _rx(self, text, pat):
        m = re.search(pat, text, re.IGNORECASE)
        if m:
            v = m.group(1) or (m.lastindex >= 2 and m.group(2))
            return float(v) if v else None
        return None

    @staticmethod
    # ── Licence manager ─────────────────────────────────────────────────────────
    def _open_license_manager(self, parent=None):
        """Generate and review floating, perpetual client licence keys."""
        import tkinter as tk
        BG = '#060f1c'; ACC = '#38b8f0'; FG = '#c8dff0'
        GRN = '#39ff14'; MUT = '#6a9ab8'; ENT = '#040810'
        win = tk.Toplevel()
        win.title('Licence Manager'); win.configure(bg=BG); win.geometry('600x470')
        # The Settings dialog is modal (grab_set), so it swallows all input.
        # Take the grab so THIS window can receive keystrokes/clicks, and hand it
        # back to Settings when we close (otherwise the note field and buttons
        # here are dead).
        if parent is not None:
            try: win.transient(parent)
            except Exception: _exc_debug('_open_license_manager')
        try: win.grab_set(); win.focus_force()
        except Exception: _exc_debug('_open_license_manager')

        def _close():
            try:
                if parent is not None and parent.winfo_exists():
                    parent.grab_set()
            except Exception:
                _exc_debug('_open_license_manager')
            win.destroy()
        win.protocol('WM_DELETE_WINDOW', _close)
        tk.Label(win, text='  \u25c8  Client Licences', fg=ACC, bg='#020810',
                 font=(_NM_MONO, 10, 'bold')).pack(fill='x', ipady=8)

        top = tk.Frame(win, bg=BG); top.pack(fill='x', padx=12, pady=(10, 4))
        tk.Label(top, text='Note (who is this for):', fg=FG, bg=BG,
                 font=(_NM_MONO, 9)).pack(side='left')
        note_var = tk.StringVar()
        tk.Entry(top, textvariable=note_var, width=24, bg=ENT, fg=FG,
                 insertbackground=FG, relief='flat',
                 font=(_NM_MONO, 9)).pack(side='left', padx=6)

        key_var = tk.StringVar(value='')
        keyrow = tk.Frame(win, bg=BG); keyrow.pack(fill='x', padx=12, pady=(2, 6))
        tk.Entry(keyrow, textvariable=key_var, bg=ENT, fg=GRN, relief='flat',
                 font=(_NM_MONO, 11, 'bold'), state='readonly',
                 readonlybackground=ENT).pack(side='left', fill='x', expand=True, ipady=4)

        def _copy():
            k = key_var.get()
            if not k:
                return
            try:
                win.clipboard_clear(); win.clipboard_append(k)
                status.config(text='Key copied to clipboard.', fg=GRN)
            except Exception:
                _exc_debug('_open_license_manager')
        tk.Button(keyrow, text='Copy', command=_copy, bg='#0d2235', fg=ACC,
                  relief='flat', font=(_NM_MONO, 9, 'bold'), padx=10,
                  cursor='hand2').pack(side='left', padx=(6, 0))

        lst = tk.Listbox(win, bg=ENT, fg=FG, relief='flat', font=(_NM_MONO, 9),
                         selectbackground='#123049', highlightthickness=0)
        lst.pack(fill='both', expand=True, padx=12, pady=(4, 4))

        def _refresh():
            import datetime
            lst.delete(0, 'end')
            for rec in reversed(_nm_license_log_load()):
                when = ''
                try:
                    when = datetime.datetime.fromtimestamp(
                        rec.get('issued', 0)).strftime('%Y-%m-%d %H:%M')
                except Exception:
                    _exc_debug('_open_license_manager')
                lst.insert('end', '%s   %s   %s'
                           % (rec.get('key', ''), (rec.get('note') or '-'), when))

        def _gen():
            key, _rec = _nm_license_make(note_var.get().strip())
            key_var.set(key); note_var.set('')
            status.config(text='Generated. Paste this into the client on the other machine.',
                          fg=GRN)
            _refresh()

        def _copy_selected(_e=None):
            try:
                sel = lst.get(lst.curselection()[0])
                k = sel.split()[0]
                win.clipboard_clear(); win.clipboard_append(k)
                key_var.set(k); status.config(text='Selected key copied.', fg=GRN)
            except Exception:
                _exc_debug('_open_license_manager')
        lst.bind('<Double-Button-1>', _copy_selected)

        btns = tk.Frame(win, bg=BG); btns.pack(fill='x', padx=12, pady=(2, 4))
        tk.Button(btns, text='\u2795  Generate key', command=_gen, bg='#08221a',
                  fg=GRN, relief='flat', font=(_NM_MONO, 9, 'bold'),
                  padx=12, pady=5, cursor='hand2').pack(side='left')
        tk.Label(btns, text='Floating & perpetual \u00b7 double-click a row to copy',
                 fg=MUT, bg=BG, font=(_NM_MONO, 8)).pack(side='left', padx=10)

        status = tk.Label(win, text='Secret stays on this machine; only the key leaves.',
                          fg=MUT, bg=BG, font=(_NM_MONO, 8), anchor='w')
        status.pack(fill='x', padx=12, pady=(0, 8))
        _refresh()

    # ── Settings dialog ────────────────────────────────────────────────────────
    def _open_settings_dialog(self, on_saved=None):
        """Dark-themed Settings dialog for configuring executable paths."""
        import tkinter as tk
        from tkinter import filedialog
        import shutil as _shutil

        # Toplevel shares the existing Tk root that matplotlib already created.
        # Using tk.Tk() a second time breaks StringVar updates and filedialog.
        dlg = tk.Toplevel()
        dlg.title('Settings')
        dlg.configure(bg='#0a1828')
        dlg.grab_set()
        dlg.lift()
        dlg.focus_force()

        FG = '#c8dff0'; BG2 = '#0a1828'; ENT = '#0d2235'
        ACC = '#38b8f0'; WARN = '#ff9f43'

        # The dialog is taller than it used to be, so it must scroll rather than
        # size itself to its content — otherwise the Save button falls off the
        # bottom of the screen on shorter displays.
        _btn_bar = tk.Frame(dlg, bg=BG2)
        _btn_bar.pack(side='bottom', fill='x')      # packed FIRST => never hidden
        tk.Frame(dlg, bg='#1a3050', height=1).pack(side='bottom', fill='x')

        _cv_wrap = tk.Frame(dlg, bg=BG2)
        _cv_wrap.pack(side='top', fill='both', expand=True)
        _cv = tk.Canvas(_cv_wrap, bg=BG2, highlightthickness=0, bd=0)
        _sb = tk.Scrollbar(_cv_wrap, orient='vertical', command=_cv.yview,
                           bg=BG2, troughcolor='#060f1c', activebackground=ACC,
                           relief='flat', bd=0, width=12)
        _cv.configure(yscrollcommand=_sb.set)
        _sb.pack(side='right', fill='y')
        _cv.pack(side='left', fill='both', expand=True)

        # `win` is the scroll body from here on, so every widget below keeps
        # working unchanged — it just lands inside the scrollable area.
        win = tk.Frame(_cv, bg=BG2)
        _win_id = _cv.create_window((0, 0), window=win, anchor='nw')

        def _on_body(_e=None):
            _cv.configure(scrollregion=_cv.bbox('all'))
        def _on_cv(e):
            _cv.itemconfigure(_win_id, width=e.width)   # body tracks canvas width
        win.bind('<Configure>', _on_body)
        _cv.bind('<Configure>', _on_cv)

        def _wheel(e):
            _cv.yview_scroll(-1 * (e.delta // 120 if e.delta else
                                   (-1 if e.num == 5 else 1)), 'units')
        for _w, _ev in ((dlg, '<MouseWheel>'), (dlg, '<Button-4>'), (dlg, '<Button-5>')):
            _w.bind_all(_ev, _wheel, add='+')
        dlg.bind('<Destroy>', lambda e: (e.widget is dlg) and (
            dlg.unbind_all('<MouseWheel>'), dlg.unbind_all('<Button-4>'),
            dlg.unbind_all('<Button-5>')))

        # Size to content, but never taller than the screen.
        def _fit(_tries=0):
            """Size the dialog to its content.

            winfo_reqwidth/reqheight return 1 until the geometry manager has
            actually laid the widgets out. On Windows that has usually happened
            by now; under other window managers it often has not, and the dialog
            ends up 1x1 - which looks like a completely blank Settings window.
            So: sanity-check the numbers and retry rather than trust them.
            """
            try:
                dlg.update_idletasks()
                need_h = win.winfo_reqheight() + _btn_bar.winfo_reqheight() + 8
                need_w = win.winfo_reqwidth() + 24
                if (need_w < 200 or need_h < 200) and _tries < 12:
                    dlg.after(60, lambda: _fit(_tries + 1))
                    return
                screen_h = dlg.winfo_screenheight() or 1000
                screen_w = dlg.winfo_screenwidth() or 1280
                need_w = max(560, min(need_w, int(screen_w * 0.95)))
                need_h = max(480, min(need_h, int(screen_h * 0.88)))
                dlg.geometry('%dx%d' % (need_w, need_h))
                dlg.minsize(min(need_w, 520), 420)
            except Exception:
                _exc('_open_settings_dialog._fit')
                try:
                    dlg.geometry('820x760')     # never leave it unusable
                except Exception:
                    pass

        def lbl(parent, text, fg=FG, **kw):
            return tk.Label(parent, text=text, fg=fg, bg=BG2,
                            font=(_NM_MONO, 9), **kw)

        def mk_entry(parent, width=46):
            return tk.Entry(parent, width=width,
                            bg=ENT, fg=FG, insertbackground=FG, relief='flat',
                            font=(_NM_MONO, 9), highlightthickness=1,
                            highlightcolor=ACC, highlightbackground='#1a3050')

        tk.Label(win, text='⚙  Settings', fg=ACC, bg=BG2,
                 font=(_NM_MONO, 12, 'bold')).pack(pady=(14, 4), padx=14, anchor='w')
        tk.Frame(win, bg='#1a3050', height=1).pack(fill='x', padx=12)

        # ── speedtest.exe ─────────────────────────────────────────────────────
        tk.Label(win, text='  Speedtest CLI', fg=ACC, bg='#060f1c',
                 font=(_NM_MONO, 9, 'bold')).pack(fill='x', pady=(10, 0))
        tk.Frame(win, bg='#060f1c', height=1).pack(fill='x')
        sf = tk.Frame(win, bg=BG2); sf.pack(fill='x', padx=10, pady=4)
        sf.columnconfigure(1, weight=1)

        lbl(sf, 'speedtest.exe').grid(row=0, column=0, sticky='w', padx=(4, 6), pady=3)
        st_entry = mk_entry(sf)
        st_entry.insert(0, self.config.get('speedtest_path', ''))
        st_entry.grid(row=0, column=1, padx=(0, 4), pady=3, sticky='ew')
        bf1 = tk.Frame(sf, bg=BG2); bf1.grid(row=0, column=2, padx=(0, 4))

        st_status = tk.StringVar(value='')

        def _browse_st():
            p = filedialog.askopenfilename(parent=win, title='Locate speedtest.exe',
                filetypes=[('Executable', '*.exe'), ('All files', '*.*')])
            if p:
                st_entry.delete(0, 'end')
                st_entry.insert(0, p)
                st_status.set('')

        def _test_st():
            exe = st_entry.get().strip() or _DEFAULT_SPEEDTEST_PATH
            st_status.set('Testing…')
            def _w():
                if not Path(exe).exists():
                    win.after(0, lambda: st_status.set('✗  Not found')); return
                try:
                    flags = subprocess.CREATE_NO_WINDOW if sys.platform == 'win32' else 0
                    r = subprocess.run([exe, '--version'], capture_output=True,
                                       text=True, timeout=10, creationflags=flags)
                    ver = (r.stdout + r.stderr).strip().splitlines()
                    win.after(0, lambda: st_status.set(
                        f'✓  {ver[0][:55]}' if ver else '✓  OK'))
                except Exception as ex:
                    _m = str(ex)
                    win.after(0, lambda m=_m: st_status.set(f'✗  {m}'))
            threading.Thread(target=_w, daemon=True).start()

        tk.Button(bf1, text='Browse…', bg=ENT, fg=ACC, relief='flat',
                  font=(_NM_MONO, 8), cursor='hand2',
                  command=_browse_st).pack(side='left', padx=(0, 3))
        tk.Button(bf1, text='Test', bg=ENT, fg='#38f0a8', relief='flat',
                  font=(_NM_MONO, 8), cursor='hand2',
                  command=_test_st).pack(side='left')

        lbl(sf, f'Default: {_DEFAULT_SPEEDTEST_PATH}', fg='#2a4a6a').grid(
            row=1, column=1, sticky='w', padx=(0, 4))
        tk.Label(sf, textvariable=st_status, fg='#38f0a8', bg=BG2,
                 font=(_NM_MONO, 8)).grid(row=2, column=1, sticky='w',
                                            padx=(0, 4), pady=(0, 6))

        # ── tshark.exe ────────────────────────────────────────────────────────
        tk.Label(win, text='  Wireshark / tshark', fg=ACC, bg='#060f1c',
                 font=(_NM_MONO, 9, 'bold')).pack(fill='x', pady=(8, 0))
        tk.Frame(win, bg='#060f1c', height=1).pack(fill='x')
        tf = tk.Frame(win, bg=BG2); tf.pack(fill='x', padx=10, pady=4)
        tf.columnconfigure(1, weight=1)

        lbl(tf, 'tshark.exe').grid(row=0, column=0, sticky='w', padx=(4, 6), pady=3)
        tsh_entry = mk_entry(tf)
        tsh_entry.insert(0, self.config.get('tshark_path', ''))
        tsh_entry.grid(row=0, column=1, padx=(0, 4), pady=3, sticky='ew')
        bf2 = tk.Frame(tf, bg=BG2); bf2.grid(row=0, column=2, padx=(0, 4))

        tsh_status = tk.StringVar(value='')

        def _browse_tsh():
            cur = tsh_entry.get().strip()
            init = str(Path(cur).parent) if cur else r'C:\Program Files\Wireshark'
            p = filedialog.askopenfilename(parent=win, title='Locate tshark.exe',
                initialdir=init, filetypes=[('Executable', '*.exe'), ('All files', '*.*')])
            if p:
                tsh_entry.delete(0, 'end')
                tsh_entry.insert(0, p)
                tsh_status.set('')

        def _test_tsh():
            exe = tsh_entry.get().strip() or _DEFAULT_TSHARK_PATH
            tsh_status.set('Testing…')
            def _w():
                if not Path(exe).exists():
                    win.after(0, lambda: tsh_status.set('✗  Not found')); return
                try:
                    flags = subprocess.CREATE_NO_WINDOW if sys.platform == 'win32' else 0
                    r = subprocess.run([exe, '--version'], capture_output=True,
                                       text=True, timeout=10, creationflags=flags)
                    ver = (r.stdout + r.stderr).strip().splitlines()
                    win.after(0, lambda: tsh_status.set(
                        f'✓  {ver[0][:55]}' if ver else '✓  OK'))
                except Exception as ex:
                    _m = str(ex)
                    win.after(0, lambda m=_m: tsh_status.set(f'✗  {m}'))
            threading.Thread(target=_w, daemon=True).start()

        def _auto_detect():
            # Run in thread so "Searching" label renders before result arrives
            tsh_status.set('Searching…')
            def _w():
                candidates = [
                    r'C:\Program Files\Wireshark\tshark.exe',
                    r'C:\Program Files (x86)\Wireshark\tshark.exe',
                    '/usr/bin/tshark',
                    '/usr/local/bin/tshark',
                    '/snap/bin/tshark',
                ]
                in_path = _shutil.which('tshark')
                if in_path:
                    candidates.insert(0, in_path)
                found = next((c for c in candidates if Path(c).exists()), None)
                def _upd():
                    if found:
                        tsh_entry.delete(0, 'end')
                        tsh_entry.insert(0, found)
                        tsh_status.set(f'✓  Found: {found}')
                    else:
                        tsh_status.set('✗  Not found — ' + (
                            'sudo apt install tshark' if not _NM_IS_WIN
                            else 'install Wireshark from wireshark.org'))
                win.after(0, _upd)
            threading.Thread(target=_w, daemon=True).start()

        tk.Button(bf2, text='Browse…', bg=ENT, fg=ACC, relief='flat',
                  font=(_NM_MONO, 8), cursor='hand2',
                  command=_browse_tsh).pack(side='left', padx=(0, 3))
        tk.Button(bf2, text='Test', bg=ENT, fg='#38f0a8', relief='flat',
                  font=(_NM_MONO, 8), cursor='hand2',
                  command=_test_tsh).pack(side='left')

        lbl(tf, f'Default: {_DEFAULT_TSHARK_PATH}', fg='#2a4a6a').grid(
            row=1, column=1, sticky='w', padx=(0, 4))
        tk.Label(tf, textvariable=tsh_status, fg='#38f0a8', bg=BG2,
                 font=(_NM_MONO, 8)).grid(row=2, column=1, sticky='w',
                                            padx=(0, 4), pady=(0, 4))
        tk.Button(tf, text='⊙  Auto-detect', bg=ENT, fg=WARN, relief='flat',
                  font=(_NM_MONO, 8), cursor='hand2',
                  command=_auto_detect).grid(row=3, column=1, sticky='w',
                                             padx=(0, 4), pady=(0, 8))

        # ── Theme section ─────────────────────────────────────────────────────
        tk.Label(win, text='  Colour Theme', fg=ACC, bg='#060f1c',
                 font=(_NM_MONO, 9, 'bold')).pack(fill='x', pady=(8, 0))
        tk.Frame(win, bg='#060f1c', height=1).pack(fill='x')
        theme_f = tk.Frame(win, bg=BG2); theme_f.pack(fill='x', padx=10, pady=8)

        theme_var = tk.StringVar(value=self.config.get('theme') or 'Ocean')
        SWATCH_SIZE = 16

        def _swatch(parent, dl_col, ul_col, pg_col):
            c = tk.Canvas(parent, width=54, height=SWATCH_SIZE, bg=BG2, highlightthickness=0)
            for i, col in enumerate([dl_col, ul_col, pg_col]):
                c.create_rectangle(i*18, 1, i*18+16, SWATCH_SIZE-1, fill=col, outline='')
            return c

        # Grid of themes - 4 per row
        theme_names = list(THEMES.keys())
        COLS = 4
        for i, name in enumerate(theme_names):
            col = i % COLS; row_idx = i // COLS
            cell = tk.Frame(theme_f, bg=BG2, padx=8, pady=4)
            cell.grid(row=row_idx, column=col, sticky='w', padx=4, pady=2)
            rb = tk.Radiobutton(cell, text=name, variable=theme_var, value=name,
                           fg=FG, bg=BG2, selectcolor='#0d2235',
                           activebackground=BG2, activeforeground=ACC,
                           font=(_NM_MONO, 9))
            rb.pack(side='top', anchor='w')
            t = THEMES[name]
            _swatch(cell, t['download'], t['upload'], t['ping']).pack(side='top', pady=(2,0))

        # ── DNS Hosts section ─────────────────────────────────────────────────
        tk.Label(win, text='  DNS Check Hosts', fg=ACC, bg='#060f1c',
                 font=(_NM_MONO, 9, 'bold')).pack(fill='x', pady=(8, 0))
        tk.Frame(win, bg='#060f1c', height=1).pack(fill='x')
        df = tk.Frame(win, bg=BG2); df.pack(fill='x', padx=10, pady=6)
        lbl(df, 'Hosts').grid(row=0, column=0, sticky='w', padx=(4, 6), pady=3)
        dns_entry = mk_entry(df, width=52)
        current_hosts = self.config.get('dns_hosts', '').strip()
        dns_entry.insert(0, current_hosts)
        dns_entry.grid(row=0, column=1, padx=(0, 4), pady=3, sticky='ew')
        df.columnconfigure(1, weight=1)
        default_hosts = ', '.join(self.DNS_HOSTS)
        lbl(df, f'Default: {default_hosts}', fg='#2a4a6a').grid(
            row=1, column=1, sticky='w', padx=(0, 4))
        lbl(df, 'Comma-separated hostnames. Leave blank to use the defaults above.',
            fg='#2a4a6a').grid(row=2, column=1, sticky='w', padx=(0, 4), pady=(0, 4))

        def _reset_dns_hosts():
            dns_entry.delete(0, 'end')
            dns_status.set('✓  Reset to defaults')
        dns_status = tk.StringVar(value='')
        bf_dns = tk.Frame(df, bg=BG2); bf_dns.grid(row=3, column=1, sticky='w', pady=(0, 4))
        tk.Button(bf_dns, text='Reset to defaults', bg=ENT, fg='#ff9f43', relief='flat',
                  font=(_NM_MONO, 8), cursor='hand2',
                  command=_reset_dns_hosts).pack(side='left', padx=(0, 6))
        tk.Label(bf_dns, textvariable=dns_status, fg='#38f0a8', bg=BG2,
                 font=(_NM_MONO, 8)).pack(side='left')


        # ── Test interval ──────────────────────────────────────────────────
        tk.Label(win, text='  Speed Test Schedule', fg=ACC, bg='#060f1c',
                 font=(_NM_MONO, 9, 'bold')).pack(fill='x', pady=(8, 0))
        tk.Frame(win, bg='#060f1c', height=1).pack(fill='x')
        ivf = tk.Frame(win, bg=BG2); ivf.pack(fill='x', padx=10, pady=8)
        ivf.columnconfigure(1, weight=1)
        lbl(ivf, 'Run every').grid(row=0, column=0, sticky='w', padx=(4, 6), pady=3)
        iv_frame = tk.Frame(ivf, bg=BG2); iv_frame.grid(row=0, column=1, sticky='w')
        iv_entry = mk_entry(iv_frame, width=6)
        iv_entry.insert(0, str(self.config.get('interval_minutes', INTERVAL_MINUTES)))
        iv_entry.pack(side='left', padx=(0, 6), ipady=3)
        lbl(iv_frame, 'minutes  (1 – 1440)', fg='#2a4a6a').pack(side='left')
        pb = tk.Frame(ivf, bg=BG2); pb.grid(row=1, column=1, sticky='w', pady=(4, 0))
        for _iv_lbl, _iv_val in [('1m',1),('5m',5),('10m',10),('15m',15),('30m',30),('1h',60),('2h',120)]:
            tk.Button(pb, text=_iv_lbl, bg=ENT, fg=ACC, relief='flat',
                      font=(_NM_MONO, 8), cursor='hand2', padx=5,
                      activebackground='#0a3a60',
                      command=lambda v=_iv_val: (iv_entry.delete(0,'end'), iv_entry.insert(0,str(v)))
                      ).pack(side='left', padx=2)
        lbl(ivf, 'Takes effect after the current interval completes.',
            fg='#2a4a6a').grid(row=2, column=1, sticky='w', pady=(3, 0))

        # Web port row
        lbl(ivf, 'Web port').grid(row=3, column=0, sticky='w', padx=(4, 6), pady=(8, 3))
        wp_frame = tk.Frame(ivf, bg=BG2); wp_frame.grid(row=3, column=1, sticky='w')
        wp_entry = mk_entry(wp_frame, width=6)
        wp_entry.insert(0, str(self.config.get('web_port', 8765)))
        wp_entry.pack(side='left', padx=(0, 6), ipady=3)
        lbl(wp_frame, 'Browser dashboard  (restart to apply)', fg='#2a4a6a').pack(side='left')

        # ── ISP Evidence Pack (advertised speed) ────────────────────────────
        tk.Label(win, text='  ISP Evidence Pack', fg=ACC, bg='#060f1c',
                 font=(_NM_MONO, 9, 'bold')).pack(fill='x', pady=(10, 0))
        tk.Frame(win, bg='#060f1c', height=1).pack(fill='x')
        adf = tk.Frame(win, bg=BG2); adf.pack(fill='x', padx=10, pady=6)
        adf.columnconfigure(1, weight=1)

        lbl(adf, 'Advertised download').grid(row=0, column=0, sticky='w', padx=(4, 6), pady=3)
        adv_dl_frame = tk.Frame(adf, bg=BG2); adv_dl_frame.grid(row=0, column=1, sticky='w')
        adv_dl_entry = mk_entry(adv_dl_frame, width=8)
        adv_dl_entry.insert(0, str(self.config.get('advertised_down', '') or ''))
        adv_dl_entry.pack(side='left', padx=(0, 6), ipady=3)
        lbl(adv_dl_frame, 'Mbps', fg='#2a4a6a').pack(side='left')

        lbl(adf, 'Advertised upload').grid(row=1, column=0, sticky='w', padx=(4, 6), pady=3)
        adv_ul_frame = tk.Frame(adf, bg=BG2); adv_ul_frame.grid(row=1, column=1, sticky='w')
        adv_ul_entry = mk_entry(adv_ul_frame, width=8)
        adv_ul_entry.insert(0, str(self.config.get('advertised_up', '') or ''))
        adv_ul_entry.pack(side='left', padx=(0, 6), ipady=3)
        lbl(adv_ul_frame, 'Mbps', fg='#2a4a6a').pack(side='left')

        lbl(adf, 'What your plan promises. Used by the ⏏ Evidence Pack PDF to '
                 'compare against what you actually measured — leave both blank '
                 'to skip that comparison.',
            fg='#2a4a6a', wraplength=480, justify='left').grid(
            row=2, column=1, sticky='w', padx=(0, 4), pady=(2, 4))

        # ── Tools folder (MobaXterm) ──────────────────────────────────────────
        tk.Label(win, text='  Tools', fg=ACC, bg='#060f1c',
                 font=(_NM_MONO, 9, 'bold')).pack(fill='x', pady=(10, 0))
        tk.Frame(win, bg='#060f1c', height=1).pack(fill='x')
        tf = tk.Frame(win, bg=BG2); tf.pack(fill='x', padx=10, pady=4)
        tf.columnconfigure(1, weight=1)

        lbl(tf, 'Tools folder').grid(row=0, column=0, sticky='w', padx=(4, 6), pady=3)
        tools_entry = mk_entry(tf)
        tools_entry.insert(0, self.config.get('tools_dir', ''))
        tools_entry.grid(row=0, column=1, padx=(0, 4), pady=3, sticky='ew')
        tf_bf = tk.Frame(tf, bg=BG2); tf_bf.grid(row=0, column=2, padx=(0, 4))
        tools_status = tk.StringVar(value='')

        def _browse_tools():
            d = filedialog.askdirectory(parent=win,
                                        title='Folder containing MobaXterm + plugins')
            if d:
                tools_entry.delete(0, 'end'); tools_entry.insert(0, d)
                tools_status.set('')

        def _test_tools():
            d = tools_entry.get().strip()
            if not d:
                tools_status.set('Empty — auto-search will be used'); return
            pth = Path(d)
            if not pth.is_dir():
                tools_status.set('\u2717  Not a folder'); return
            exes = sorted(pth.glob('MobaXterm*.exe'))
            plugs = sorted(pth.glob('CygUtils*.plugin'))
