    # Wireshark ships "extcap" helper plugins that appear in `tshark -D` exactly
    # like real adapters, but they are not capturable without extra parameters
    # (wifidump needs --remote-host, sshdump needs a server, and so on). Picking
    # one produces "There is no device named .../fifo" and zero packets, which
    # looks like a permissions problem but is not.
    _EXTCAP_NAMES = (
        'ciscodump', 'dpauxmon', 'randpktdump', 'sdjournal', 'sshdump',
        'udpdump', 'wifidump', 'etwdump', 'sysdig', 'androiddump', 'busdump',
    )
    _EXTCAP_HINTS = (
        'remote capture', 'random packet generator', 'journal export',
        'aux channel', 'event tracing', 'displayport',
    )

    @classmethod
    def _is_extcap(cls, raw):
        """True when this `tshark -D` entry is a helper plugin, not an adapter."""
        low = (raw or '').lower()
        head = low.split('(')[0].strip()
        if any(head == n or head.startswith(n) for n in cls._EXTCAP_NAMES):
            return True
        if any(n in head for n in cls._EXTCAP_NAMES):
            return True
        return any(h in low for h in cls._EXTCAP_HINTS)

    def _load_interfaces(self):
        def _worker():
            flags = subprocess.CREATE_NO_WINDOW if sys.platform == 'win32' else 0
            ifaces = []
            # Try tshark -D
            try:
                rd = subprocess.run([self.TSHARK, '-D'],
                                    capture_output=True, text=True, timeout=8, creationflags=flags)
                out = rd.stdout or rd.stderr or ''
                skipped = []
                for line in out.splitlines():
                    m = re.match(r'^(\d+)\.\s+(.+)$', line.strip())
                    if m:
                        num = m.group(1); raw = m.group(2).strip()
                        if self._is_extcap(raw):
                            skipped.append(raw)
                            continue
                        name = self._friendly_name(raw, int(num))
                        ifaces.append((num, raw, name))
                if skipped:
                    log.info('[capture] ignoring %d extcap helper(s): %s',
                             len(skipped), ', '.join(skipped[:6]))
            except Exception:
                _exc('_worker')
            # Fallback: psutil
            if not ifaces:
                try:
                    import psutil as _psu
                    for i, nm in enumerate(_psu.net_if_stats().keys(), start=1):
                        if nm.lower() in ('lo', 'loopback'): continue
                        ifaces.append((str(i), nm, nm))  # use name as-is
                except Exception:
                    _exc('_worker')
            # Final fallback: ipconfig parsing on Windows
            if not ifaces and sys.platform == 'win32':
                try:
                    r2 = subprocess.run(['ipconfig'], capture_output=True, text=True,
                                        creationflags=flags, timeout=5)
                    seen = set()
                    for ln in r2.stdout.splitlines():
                        m2 = re.match(r'^([A-Za-z][^:]{2,40}):', ln)
                        if m2:
                            nm = m2.group(1).strip()
                            if nm not in seen and 'adapter' not in nm.lower():
                                seen.add(nm)
                                ifaces.append((str(len(ifaces)+1), nm, nm))
                except Exception:
                    _exc('_worker')
            # Sort WiFi first
            ifaces.sort(key=lambda x: (
                0 if re.search(r'wi.?fi|wireless|wlan|wi_fi', x[2], re.I) else
                1 if re.search(r'ethernet|lan|gigabit', x[2], re.I) else
                9 if re.search(r'loopback|virtual|vmware|vpn|veth|docker', x[2], re.I) else 5))
            def _upd():
                self._interfaces = ifaces
                self._iface_cb['values'] = [f'{n}. {name}' for n, _, name in ifaces]
                if ifaces: self._iface_cb.current(0)
                self._status.set(
                    f'Found {len(ifaces)} interface(s)' if ifaces else
                    '⚠  No interfaces found — install Wireshark + npcap')
            self.root.after(0, _upd)
        threading.Thread(target=_worker, daemon=True).start()

    @staticmethod
    def _friendly_name(raw_desc,index):
        m=re.search(r'\(([^)]+)\)\s*$',raw_desc)
        base=m.group(1).strip() if m else raw_desc.strip()
        base=re.sub(r'^\\\\[^\\]+\\[^\\]+\\?','',base).strip()
        base=re.sub(r'^\{[A-F0-9\-]+\}','',base,flags=re.I).strip()
        if not base: base=raw_desc.strip()
        hints=[(r'wi.?fi|wireless|wlan|802\.11|wlp','Wi-Fi'),(r'ethernet|eth|local area|lan|gigabit|intel|realtek','Ethernet'),(r'loopback|npcap loopback|lo\b','Loopback'),(r'bluetooth','Bluetooth'),(r'vpn|tun|tap|nordvpn|expressvpn|openvpn','VPN'),(r'virtual|vmware|virtualbox|hyper.?v|veth','Virtual'),(r'mobile|cellular|lte|4g|5g|ndis','Mobile Broadband'),(r'usb','USB Network')]
        lo=base.lower()
        for pattern,label in hints:
            if re.search(pattern,lo,re.I):
                if len(base)<60 and not re.search(r'\{[A-F0-9\-]+\}',base,re.I): return base
                return f'{label} {index}'
        if len(base)<=48 and not re.search(r'\{[A-F0-9\-]+\}',base,re.I): return base
        return f'Interface {index}'

    # ── Timeline scrubber ────────────────────────────────────────────────────
    #  Flows are persisted every 60s with timestamps, so the capture window can
    #  be replayed. LIVE is the default; dragging the slider rebuilds nodes and
    #  flows from the database for that minute and hands them to the renderer.

    def _toggle_attack_sim(self):
        """Toggle the shared drill. Same state the web views read, so all three
        show the same hostiles."""
        try:
            on = _nm_attack_set(not _NM_ATTACK_ON)
        except Exception:
            _exc_debug('_toggle_attack_sim')
            return
        b = getattr(self, '_atk_btn', None)
        if b is None:
            return
        if on:
            b.config(text='\u2620  ATTACK: ON', fg='#ffd0a0', bg='#4a1a06',
                     highlightbackground='#a04010')
        else:
            b.config(text='\u2620  ATTACK SIM', fg='#ff8a4a', bg='#2a1206',
                     highlightbackground='#5a2a10')

    def _kill_refresh(self):
        b = getattr(self, '_kill_btn', None)
        if b is None:
            return
        if getattr(self, '_kill_active', False):
            b.config(text='\u23fb  RE-ENABLE CONNECTION', bg='#0a2a12', fg='#39ff14',
                     activebackground='#0f3a1a', highlightbackground='#1a4a2a')
        else:
            b.config(text='\u23fb  KILL CONNECTION', bg='#2a0a0a', fg='#ff5555',
                     activebackground='#3a0f0f', highlightbackground='#5a1a1a')

    def _kill_probe(self):
        """Startup check: a rule may survive a restart, so reflect the real state."""
        try:
            act = _nm_killswitch_active()
        except Exception:
            _exc_debug('_kill_probe')
            return

        def _apply():
            self._kill_active = act
            self._kill_refresh()
        try:
            self.root.after(0, _apply)
        except Exception:
            _exc_debug('_kill_probe')

    def _kill_toggle(self):
        """Cut or restore all network traffic (Windows Firewall block-all)."""
        from tkinter import messagebox
        turning_on = not getattr(self, '_kill_active', False)
        if turning_on and not messagebox.askyesno(
                'Kill network connection?',
                'This blocks ALL inbound and outbound network traffic on this '
                'machine.\n\n'
                'Local dashboards on 127.0.0.1 keep working, and pressing the '
                'button again restores the connection.\n\n'
                'Requires Administrator.\n\nCut the connection now?',
                parent=self.root):
            return
        b = getattr(self, '_kill_btn', None)
        if b is not None:
            b.config(state='disabled', text='\u23fb  working\u2026')

        def _work():
            ok, err = _nm_killswitch_set(turning_on)

            def _done():
                if b is not None:
                    b.config(state='normal')
                if ok:
                    self._kill_active = turning_on
                else:
                    try:
                        from tkinter import messagebox as _mb
                        _mb.showerror('Kill switch failed',
                                      err or 'netsh failed - run as Administrator.',
                                      parent=self.root)
                    except Exception:
                        _exc_debug('_kill_toggle')
                self._kill_refresh()
            try:
                self.root.after(0, _done)
            except Exception:
                _exc_debug('_kill_toggle')
        threading.Thread(target=_work, daemon=True).start()

    def _tl_set_range(self):
        """Grow the slider range without moving the user's position."""
        sc = getattr(self, '_tl_scale', None)
        if sc is None:
            return
        try:
            self._tl_syncing = True
            sc.config(to=max(0, len(self._tl_hist) - 1))
        finally:
            self._tl_syncing = False

    def _tl_sync_live(self):
        """Pin the slider to the newest frame while following live capture."""
        n = len(self._tl_hist)
        sc = getattr(self, '_tl_scale', None)
        if sc is not None:
            try:
                self._tl_syncing = True
                sc.config(to=max(0, n - 1))
                sc.set(max(0, n - 1))
            finally:
                self._tl_syncing = False
        self._tl_idx = max(0, n - 1)
        lbl = getattr(self, '_tl_time_lbl', None)
        if lbl is not None:
            lbl.config(text='live' if n >= 2 else 'buffering\u2026')

    def _tl_btn_update(self):
        b = getattr(self, '_tl_live_btn', None)
        sc = getattr(self, '_tl_scale', None)
        if sc is not None:
            try:
                sc.config(bg='#38b8f0' if self._tl_live else '#ffb000')
            except Exception:
                _exc_debug('_tl_btn_update')
        if b is None:
            return
        if self._tl_live:
            b.config(text='\u25cf LIVE', fg='#39ff14', highlightbackground='#1a4a2a')
        else:
            b.config(text='\u25b6 GO LIVE', fg='#ffb000', highlightbackground='#5a4a1a')

    def _tl_push(self, nodes, flows):
        """Buffer a topology snapshot (throttled to TL_INTERVAL)."""
        now = time.time()
        if now - self._tl_last < self.TL_INTERVAL:
            return
        self._tl_last = now
        # Copy so later live mutation can't rewrite stored history.
        snap_n = {ip: dict(nd) for ip, nd in nodes.items()}
        snap_f = {k: dict(v) for k, v in flows.items()}
        self._tl_hist.append((now, snap_n, snap_f))
        if self._tl_live:
            while len(self._tl_hist) > self.TL_MAX_FRAMES:
                self._tl_hist.pop(0)
            self._tl_sync_live()
        else:
            # Paused: keep buffering, but don't drop frames under the user's cursor.
            if len(self._tl_hist) > 3000:
                self._tl_hist.pop(0)
                self._tl_idx = max(0, self._tl_idx - 1)
            self._tl_set_range()

    def _tl_on_scrub(self, val):
        """User dragged the timeline slider — freeze on that frame."""
        if getattr(self, '_tl_syncing', False):
            return
        try:
            idx = int(float(val))
        except Exception:
            return
        n = len(self._tl_hist)
        self._tl_idx = max(0, min(idx, n - 1)) if n else 0
        self._tl_live = (n == 0) or (idx >= n - 1)
        self._tl_btn_update()
        lbl = getattr(self, '_tl_time_lbl', None)
        if lbl is None:
            return
        if self._tl_live:
            lbl.config(text='live' if n >= 2 else 'buffering\u2026')
        elif 0 <= self._tl_idx < n:
            lbl.config(text=time.strftime('%H:%M:%S',
                                          time.localtime(self._tl_hist[self._tl_idx][0])))

    def _tl_go_live(self):
        """Snap back to following the live capture."""
        self._tl_live = True
        while len(self._tl_hist) > self.TL_MAX_FRAMES:
            self._tl_hist.pop(0)
        self._tl_sync_live()
        self._tl_btn_update()

    def _render_data(self):
        """Nodes/flows the view should draw: live, or a replayed slice."""
        rp = getattr(self, '_replay', None)
        if rp is None:
            return self._nodes, self._flows
        return rp

    def _replay_db(self):
        for m in _monitor_instances:
            db = getattr(m, '_db', None)
            if db is not None:
                return db
        return None

    def _build_replay_bar(self, parent):
        tk = self._tk
        bar = tk.Frame(parent, bg='#06101e', height=30)
        bar.pack(fill='x', side='bottom')
        bar.pack_propagate(False)

        self._replay = None
        self._replay_span = (None, None)

        self._replay_btn = tk.Button(
            bar, text='⏱ REPLAY', command=self._toggle_replay,
            bg='#0a1828', fg=self._TICK, activebackground='#16324a',
            activeforeground='white', relief='flat', font=(_NM_MONO, 8),
            cursor='hand2', padx=8, pady=1, bd=0, highlightthickness=1,
            highlightbackground='#1a3a5a')
        self._replay_btn.pack(side='left', padx=(8, 8), pady=3)

        self._replay_scale = tk.Scale(
            bar, from_=0, to=100, orient='horizontal', showvalue=False,
            command=self._on_scrub, bg='#06101e', fg=self._TEXT,
            troughcolor='#0a1828', activebackground=self._ACC,
            highlightthickness=0, bd=0, sliderrelief='flat', length=400,
            state='disabled')
        self._replay_scale.pack(side='left', fill='x', expand=True, padx=(0, 8))

        self._replay_lbl = tk.Label(
            bar, text='LIVE', bg='#06101e', fg='#39ff14',
            font=(_NM_MONO, 8, 'bold'), width=22, anchor='w')
        self._replay_lbl.pack(side='left', padx=(0, 8))
        return bar

    def _toggle_replay(self):
        if getattr(self, '_replay', None) is not None:
            self._go_live()
            return
        db = self._replay_db()
        if db is None:
            self._replay_lbl.config(text='no database', fg='#ff6b6b')
            return
        try:
            a, b = db.flow_span(hours=24)
        except Exception:
            _exc('_toggle_replay'); return
        if not a or (b - a).total_seconds() < 60:
            self._replay_lbl.config(text='not enough history', fg='#ff9f43')
            return
        self._replay_span = (a, b)
        self._replay_scale.config(state='normal')
        self._replay_btn.config(text='⏹ LIVE', fg='#f7cc73',
                                highlightbackground='#5a4a1a')
        self._replay_scale.set(100)
        self._on_scrub(100)

    def _go_live(self):
        self._replay = None
        try:
            self._replay_scale.config(state='disabled')
            self._replay_btn.config(text='⏱ REPLAY', fg=self._TICK,
                                    highlightbackground='#1a3a5a')
            self._replay_lbl.config(text='LIVE', fg='#39ff14')
        except Exception:
            _exc_debug('_go_live')

    def _on_scrub(self, val):
        a, b = getattr(self, '_replay_span', (None, None))
        if not a:
            return
        db = self._replay_db()
        if db is None:
            return
        try:
            frac = float(val) / 100.0
        except (TypeError, ValueError):
            return

        total = (b - a).total_seconds()
        t0 = a + timedelta(seconds=total * frac)
        t1 = t0 + timedelta(minutes=5)          # 5-minute replay window

        try:
            rows = db.flows_between(t0, t1)
        except Exception:
            _exc('_on_scrub'); return

        # Rebuild node/flow dicts in exactly the shape the renderer expects,
        # reusing live positions so replayed hosts don't teleport.
        nodes, flows = {}, {}
        for r in rows:
            src, dst = r['src'], r['dst']
            proto = r['proto'] or 'other'
            by, pk = float(r['bytes'] or 0), int(r['pkts'] or 0)
            for ip in (src, dst):
                if not ip:
                    continue
                if ip not in nodes:
                    live = self._nodes.get(ip)
                    if live:
                        pos = live['pos']
                    else:
                        _h = hash(ip) & 0xFFFFFF
                        ang = (_h % 1000) / 1000.0 * 2 * np.pi
                        rr = 0.28 + ((_h >> 12) % 200) / 1000.0
                        pos = (0.5 + rr * np.cos(ang), 0.5 + rr * np.sin(ang))
                    nodes[ip] = {'bytes': 0.0, 'pkts': 0, 'pos': pos,
                                 'proto': proto, 'age': 0}
                nodes[ip]['bytes'] += by
                nodes[ip]['pkts'] += pk
                nodes[ip]['proto'] = proto
            if src and dst:
                flows[(src, dst, proto)] = {'bytes': by, 'pkts': pk,
                                            'proto': proto, 'age': 0}

        self._replay = (nodes, flows)
        self._replay_lbl.config(
            text=f'{t0:%d %b %H:%M}' + ('  (no data)' if not rows else ''),
            fg='#f7cc73' if rows else '#6a9ab8')

    def _proto_tag(self,protos):
        if not protos: return 'other'
        parts=set(protos.split(':'))
        for p in self.PROTO_PRIORITY:
            if p in parts: return p
        return 'other'

    def _start_capture(self):
        if self._capturing: return
        cb_text=self._iface_var.get().strip()
        m_iface=re.match(r'^(\d+)\.',cb_text)
        if not m_iface:
            self._show_error_dialog('No Interface','No interface selected.'); return
        iface_num=m_iface.group(1)
        sel=self._iface_cb.current()
        friendly=self._interfaces[sel][2] if 0<=sel<len(self._interfaces) else cb_text
        self._pkts_this_run=0; self._capturing=True
        self._start_btn.config(state='disabled'); self._stop_btn.config(state='normal')
        self._status.set(f'◎  Starting capture on {friendly}...')
        threading.Thread(target=self._launch_tshark,args=(iface_num,friendly),daemon=True).start()

    def _launch_tshark(self,iface_num,friendly):
        log.info(f"launch_tshark: iface={iface_num} ({friendly})")
        self._last_iface_num = iface_num
        self._last_iface_friendly = friendly
        flags=subprocess.CREATE_NO_WINDOW if sys.platform=='win32' else 0
        cmd=[self.TSHARK,'-i',iface_num,'-l','-n','-T','fields',
             '-e','ip.src','-e','ip.dst','-e','ipv6.src','-e','ipv6.dst',
             '-e','eth.src','-e','eth.dst','-e','frame.protocols','-e','frame.len',
             '-e','dns.qry.name','-e','dns.a','-e','dns.aaaa',
             '-E','separator=\t','-E','quote=n','-E','occurrence=f']
        cf=getattr(self,'_cfilt_var',None)
        if cf:
            v=cf.get().strip()
            if v: cmd+=['-f',v]
        try:
            proc=subprocess.Popen(cmd,stdout=subprocess.PIPE,stderr=subprocess.PIPE,creationflags=flags)
        except FileNotFoundError:
            self._capturing=False
            msg=f'tshark.exe not found at:\n{self.TSHARK}\n\nUpdate path in \u2699 Settings or install Wireshark.'
            self.root.after(0,lambda:self._show_error_dialog('tshark Not Found',msg))
            self.root.after(0,self._reset_buttons); return
        except Exception as ex:
            self._capturing=False
            _m=str(ex)
            self.root.after(0,lambda m=_m:self._show_error_dialog('Launch Error',m))
            self.root.after(0,self._reset_buttons); return
        self._cap_proc=proc
        self.root.after(0,lambda:self._status.set(f'\u25ce  Capturing on {friendly}...'))
        stderr_lines=[]
        def _drain_stderr():
            try:
                for raw in proc.stderr: stderr_lines.append(raw.decode('utf-8',errors='replace').rstrip())
            except Exception: _exc('_drain_stderr')
        threading.Thread(target=_drain_stderr,daemon=True).start()
        self._capture_loop(proc,stderr_lines,friendly)

    def _capture_loop(self,proc,stderr_lines,friendly):
        got_packets=False; user_stopped=False
        try:
            while self._capturing:
                line=proc.stdout.readline()
                if not line: break
                raw=line.decode('utf-8',errors='replace').rstrip('\r\n')
                if not raw: continue
                parts=raw.split('\t')
                while len(parts)<11: parts.append('')
                src=parts[0] or parts[2] or parts[4] or ''
                dst=parts[1] or parts[3] or parts[5] or ''
                protos=parts[6].lower()
                length=int(parts[7]) if parts[7].isdigit() else 0
                # DNS fields: parts[8]=dns.qry.name, parts[9]=dns.a, parts[10]=dns.aaaa
                dns_name=parts[8].strip(); dns_a=parts[9].strip(); dns_aaaa=parts[10].strip()
                if dns_name and (dns_a or dns_aaaa):
                    for resolved_ip in (dns_a+','+dns_aaaa).split(','):
                        resolved_ip=resolved_ip.strip()
                        if not resolved_ip: continue
                        # Forward DNS beats a PTR record, and must be allowed to
                        # overwrite the placeholder _resolve() seeds. The old
                        # 'not in cache' guard meant the good name never landed.
                        if self._dns_src.get(resolved_ip) == 'dns': continue
                        _fwd = dns_name.rstrip('.')
                        self._dns_raw[resolved_ip]   = _fwd
                        self._dns_cache[resolved_ip] = _nm_friendly_host(resolved_ip, _fwd)
                        self._dns_src[resolved_ip]   = 'dns'
                if src and dst:
                    got_packets=True; self._pkts_this_run+=1
                    self._pkt_queue.append((src,dst,protos,length))
            user_stopped=not self._capturing
        except Exception: _exc('_capture_loop')
        import time as _t; _t.sleep(0.3)
        ret=proc.poll()
        if not user_stopped and not got_packets:
            err='\n'.join(stderr_lines).strip() or '(no error output from tshark)'
            lo=err.lower()
            # Give advice that matches the platform AND the actual error. The
            # old text always said "Run as Administrator", which is wrong on
            # Linux and useless when the real cause is an extcap helper.
            _tip = '\n\n\U0001f4a1 '
            if 'extcap' in lo or 'fifo' in lo or 'remote-host' in lo:
                hint = (_tip + 'That entry is a Wireshark helper plugin, not a real '
                        'adapter. Pick a normal interface such as '
                        + ('Wi-Fi or Ethernet.' if _NM_IS_WIN else 'eth0, wlan0 or any.'))
            elif 'permission' in lo or 'access' in lo or 'denied' in lo or 'operation not permitted' in lo:
                hint = (_tip + 'Run as Administrator.' if _NM_IS_WIN else
                        _tip + 'Add yourself to the wireshark group:\n'
                        '   sudo dpkg-reconfigure wireshark-common   (answer YES)\n'
                        '   sudo usermod -aG wireshark <your-username>\n'
                        'then log out and back in.')
            elif 'npcap' in lo or 'winpcap' in lo:
                hint = _tip + 'Install Npcap from npcap.com'
            elif 'no such device' in lo or 'no device named' in lo:
                hint = (_tip + 'That interface no longer exists. Press the interface '
                        'dropdown to re-scan.')
            elif not _NM_IS_WIN and ('not found' in lo or 'no such file' in lo):
                hint = _tip + 'tshark is not installed:  sudo apt install tshark'
            else:
                hint = (_tip + 'Try right-click \u2192 Run as Administrator.' if _NM_IS_WIN
                        else _tip + 'Check the interface is up, and that you are in the '
                        'wireshark group (see: id).')
            msg=f'tshark exited (code {ret}) without packets.\n\nstderr:\n{err}{hint}'
            self.root.after(0,lambda m=msg:self._show_error_dialog('Capture Failed',m))
        self.root.after(0,self._on_ended)
        # Auto-restart tshark if it died unexpectedly (not stopped by user)
        if self._capturing and got_packets and not user_stopped:
            log.warning('tshark exited unexpectedly — restarting in 3s')
            import time as _t; _t.sleep(3)
            if self._capturing:
                iface_num = getattr(self,'_last_iface_num', None)
                iface_friendly = getattr(self,'_last_iface_friendly', friendly)
                if iface_num:
                    threading.Thread(target=self._launch_tshark,
                                     args=(iface_num, iface_friendly),
                                     daemon=True).start()

    def _show_error_dialog(self,title,message):
        tk=self._tk
        win=tk.Toplevel(self.root); win.title(title); win.configure(bg=self._BG)
        win.geometry('620x340'); win.resizable(True,True); win.grab_set()
        tk.Label(win,text=f'  \u26a0  {title}',bg='#200808',fg='#ff6b6b',font=(_NM_MONO, 11,'bold')).pack(fill='x')
        tk.Frame(win,bg='#3a0808',height=1).pack(fill='x')
        fc=tk.Frame(win,bg=self._PANEL); fc.pack(fill='both',expand=True,padx=8,pady=8)
        txt=tk.Text(fc,bg='#04080e',fg=self._TEXT,font=(_NM_MONO, 9),relief='flat',wrap='word',state='normal')
        vsb=self._ttk.Scrollbar(fc,orient='vertical',command=txt.yview)
        txt.configure(yscrollcommand=vsb.set); vsb.pack(side='right',fill='y'); txt.pack(fill='both',expand=True)
        txt.insert('end',message); txt.config(state='disabled')
        tk.Button(win,text='  OK  ',command=win.destroy,bg='#062040',fg=self._ACC,
                  font=(_NM_MONO, 10,'bold'),relief='flat',cursor='hand2').pack(pady=(0,8))

    def _reset_buttons(self):
        if self._closed: return
        try:
            self._start_btn.config(state='normal'); self._stop_btn.config(state='disabled')
        except Exception: _exc('_reset_buttons')
        self._status.set('Ready')

    def _stop_capture(self):
        self._capturing=False
        if self._cap_proc:
            try: self._cap_proc.terminate()
            except Exception: _exc('_stop_capture')
            self._cap_proc=None

    def _on_ended(self):
        self._capturing=False
        if self._closed: return
        try: self._reset_buttons()
        except Exception: _exc('_on_ended')
        try:
            pkts=getattr(self,'_pkts_this_run',0)
            if pkts>0: self._status.set(f'Capture stopped \u2014 {pkts:,} packet{"s" if pkts!=1 else ""} captured')
        except Exception: _exc('_on_ended')

    def _clear(self):
        self._pkt_queue.clear(); self._nodes.clear(); self._flows.clear()
        self._total_bytes=0; self._total_pkts=0
        self._label_cache.clear(); self._last_node_set.clear()
        self._ids_suspicious.clear()
        self._flow_seg_map.clear()
        self._status.set('Cleared')

    def _open_pcap_replay(self):
        from tkinter import filedialog
        path=filedialog.askopenfilename(title='Open PCAP for Replay',parent=self.root,
            filetypes=[('PCAP / PCAPNG','*.pcap *.pcapng *.cap *.pcap.gz'),('All files','*.*')])
        if not path: return
        self._pcap_replay_path=path
        name=path.split('/')[-1].split('\\')[-1]
        self._replay_file_var.set(f'  {name}')
        self._replay_btn.config(state='normal')
        self._status.set(f'PCAP loaded: {name}  \u2014 click \u23f5 Replay to start')

    def _start_replay(self):
        if self._replaying or self._capturing: return
        path=getattr(self,'_pcap_replay_path',None)
        if not path: return
        self._stop_replay(); self._clear(); self._replaying=True
        self._replay_btn.config(state='disabled'); self._stop_replay_btn.config(state='normal')
        self._start_btn.config(state='disabled')
        speed=self._replay_speed if self._replay_speed>0 else 1.0
        self._replay_thread=threading.Thread(target=self._replay_loop,args=(path,speed),daemon=True)
        self._replay_thread.start()

    def _stop_replay(self): self._replaying=False

    def _replay_loop(self,path,speed):
        import time as _t
        flags=subprocess.CREATE_NO_WINDOW if sys.platform=='win32' else 0
        cmd=[self.TSHARK,'-r',path,'-n','-T','fields','-e','frame.time_relative',
             '-e','ip.src','-e','ip.dst','-e','ipv6.src','-e','ipv6.dst',
             '-e','eth.src','-e','eth.dst','-e','frame.protocols','-e','frame.len',
             '-E','separator=\t','-E','quote=n','-E','occurrence=f']
        try:
            proc=subprocess.Popen(cmd,stdout=subprocess.PIPE,stderr=subprocess.PIPE,creationflags=flags)
        except FileNotFoundError:
            if not self._closed:
                self.root.after(0,lambda:self._show_error_dialog('tshark Not Found',f'Not found at {self.TSHARK}'))
                self.root.after(0,self._replay_ended)
            return
        except Exception as ex:
            _m=str(ex)
            if not self._closed: self.root.after(0,lambda m=_m:self._show_error_dialog('Replay Error',m))
            self.root.after(0,self._replay_ended); return
        threading.Thread(target=lambda:proc.stderr.read(),daemon=True).start()
        prev_ts=None; wall_prev=None; pkt_count=0
        try:
            for raw_line in proc.stdout:
                if not self._replaying: proc.terminate(); break
                raw=raw_line.decode('utf-8',errors='replace').rstrip('\r\n')
                if not raw: continue
                parts=raw.split('\t')
                while len(parts)<9: parts.append('')
                ts_str=parts[0]; src=parts[1] or parts[3] or parts[5] or ''
                dst=parts[2] or parts[4] or parts[6] or ''; protos=parts[7].lower()
                length=int(parts[8]) if parts[8].isdigit() else 0
                try: ts=float(ts_str)
                except Exception: ts=None
                now=_t.perf_counter()
                if ts is not None and prev_ts is not None and wall_prev is not None:
                    gap=(ts-prev_ts)/speed; elapsed=now-wall_prev; sleep_for=gap-elapsed
                    if sleep_for>0: _t.sleep(min(sleep_for,2.0))
                prev_ts=ts; wall_prev=_t.perf_counter()
                if src and dst:
                    pkt_count+=1; self._pkt_queue.append((src,dst,protos,length))
        except Exception: _exc('_replay_loop')
        if not self._closed: self.root.after(0,self._replay_ended)

    def _replay_ended(self):
        self._replaying=False; self._replay_btn.config(state='normal')
        self._stop_replay_btn.config(state='disabled'); self._start_btn.config(state='normal')
        path=getattr(self,'_pcap_replay_path','')
        name=path.split('/')[-1].split('\\')[-1] if path else ''
        self._status.set(f'Replay finished \u2014 {name}  ({self._total_pkts:,} pkts processed)')

    def _sort_hosts(self,col):
        items=[(self._host_tree.item(i,'values'),i) for i in self._host_tree.get_children()]
        rev=getattr(self,'_host_sort_rev',False); idx=('ip','name','pkts','bytes','proto').index(col)
        def _k(x):
            v=x[0][idx]
            try: return float(v.replace(',','').replace('KB','').replace('MB',''))
            except Exception: return v.lower()
        items.sort(key=_k,reverse=not rev)
        for i,(_,iid) in enumerate(items): self._host_tree.move(iid,'',i)
        self._host_sort_rev=not rev

    def _schedule_render(self):
        if self._closed: return
        try: self.root.after(self.RENDER_MS,self._render_tick)
        except Exception: _exc('_schedule_render')

    def _schedule_table_update(self):
        if self._closed: return
        try: self.root.after(self.TABLE_MS,self._table_tick)
        except Exception: _exc('_schedule_table_update')

    def _render_tick(self):
        if self._closed: return
        try: self._render_tick_inner()
        except Exception: _exc('_render_tick')
        self._schedule_render()

    def _blit_frame(self, force=False):
        """Draw a frame by blitting: restore a cached bitmap of the static scene
        and repaint only the packets on top.

        A full canvas redraw repaints ribbons, nodes, labels and grid every
        frame — ~20ms at 14x9 and worse on a big window, which blows the 50ms
        budget and makes the motion stutter. None of that content changes
        between animation frames, so we snapshot it once and reuse it.
        """
        cv = self._canvas
        if not self._blit_ok:
            try: cv.draw_idle()
            except Exception: _exc('_blit_frame')
            return
        now = time.time()
        view = (round(self._zoom, 4), round(self._pan_x, 4), round(self._pan_y, 4))
        # Refresh the snapshot when the geometry or the view changes, and on a
        # slow timer so the ribbon activity-fade and labels stay current.
        need = (force or self._bg is None
                or self._bg_sig != self._ribbon_sig
                or self._bg_view != view
                or (now - self._bg_t) > 0.40)
        try:
            if need:
                _vis = self._pkt_arrows.get_visible()
                self._pulse_sc.set_visible(False)   # keep packets OUT of the snapshot
                self._pkt_arrows.set_visible(False)
                cv.draw()
                self._bg = cv.copy_from_bbox(self._ax.bbox)
                self._bg_sig = self._ribbon_sig
                self._bg_view = view
                self._bg_t = now
                self._pulse_sc.set_visible(True)
                self._pkt_arrows.set_visible(_vis)
            cv.restore_region(self._bg)
            self._ax.draw_artist(self._pkt_arrows)
            self._ax.draw_artist(self._pulse_sc)
            cv.blit(self._ax.bbox)
        except Exception:
            # Any backend that can't blit -> degrade to the old path, don't crash.
            _exc('_blit_frame')
            self._blit_ok = False
            self._bg = None
            try:
                self._pulse_sc.set_visible(True)
                cv.draw_idle()
            except Exception:
                _exc_debug('_blit_frame')

    def _toggle_layout(self):
        """Flip between the original radial topology and the Sankey flow view."""
        self._layout_mode = 'sankey' if self._layout_mode == 'radial' else 'radial'
        sankey = (self._layout_mode == 'sankey')
        try:
            self._layout_btn.config(
                text='⇉ SANKEY' if sankey else '◎ RADIAL',
                fg='#f7cc73' if sankey else '#38b8f0',
                highlightbackground='#5a4a1a' if sankey else '#1a3a5a')
        except Exception:
            _exc('_toggle_layout')
        # Reset view so the columns are framed correctly, and clear stale slots
        self._bg = None; self._bg_sig = None; self._ribbon_sig = None
        if sankey:
            self._sankey_order = {}
            self._zoom = 1.0; self._pan_x = 0.5; self._pan_y = 0.5
        try:
            self._apply_view()
        except Exception:
            _exc('_toggle_layout')

    # ── Sankey layout ────────────────────────────────────────────────────────
    @staticmethod
    def _is_internal(ip):
        """RFC1918 / loopback / link-local = 'internal'."""
        try:
            return (ip.startswith(('192.168.', '10.', '127.', '169.254.'))
                    or any(ip.startswith(f'172.{n}.') for n in range(16, 32)))
        except Exception:
            return False

    def _sankey_layout(self, nodes, flows):
        """Assign bipartite column positions IN PLACE on the (copied) node dicts.

        Internal hosts stack in a left column, external servers on the right,
        each ordered by traffic volume so the busiest sit at the top. Slots are
        remembered in self._sankey_order so rows don't jump around between
        frames as byte counts tick over.
        """
        L_X, R_X = 0.185, 0.815
        TOP, BOT = 0.925, 0.075

        internal = [ip for ip in nodes if self._is_internal(ip)]
        external = [ip for ip in nodes if not self._is_internal(ip)]

        def _place(col, x):
            if not col:
                return
            # Busiest first, but keep a stable slot once assigned.
            col.sort(key=lambda ip: (self._sankey_order.get(ip, 9999),
                                     -nodes[ip].get('bytes', 0.0)))
            for i, ip in enumerate(col):
                self._sankey_order[ip] = i
            n = len(col)
            if n == 1:
                ys = [(TOP + BOT) / 2]
            else:
                step = (TOP - BOT) / (n - 1)
                ys = [TOP - i * step for i in range(n)]
            for ip, y in zip(col, ys):
                nodes[ip]['pos'] = (x, y)

        _place(internal, L_X)
        _place(external, R_X)
        # Drop stale slots so the dict can't grow without bound
        if len(self._sankey_order) > self.MAX_NODES * 2:
            live = set(nodes)
            self._sankey_order = {k: v for k, v in self._sankey_order.items()
                                  if k in live}

    @staticmethod
    def _flow_bow(y0, y1, key):
        """Vertical bow for a flow's curve.

        When src and dst sit at (nearly) the same height the cubic's control
        points collapse onto the same y and the 'ribbon' degenerates into a
        flat horizontal slab spanning the canvas. Bowing the control points
        turns those into gentle arcs, and the hash-derived sign fans several
        level flows apart instead of stacking them on top of each other.
        """
        dy = abs(y1 - y0)
        flat = 1.0 - min(1.0, dy / 0.22)      # 1.0 when perfectly level
        if flat <= 0.0:
            return 0.0
        h = hash(key)
        # Bow away from the nearest edge, so an arc near the top of the column
        # can't be pushed off-canvas. Only free-float in the middle band.
        mid = (y0 + y1) / 2.0
        if mid > 0.72:
            sign = -1.0                       # near the top -> arc downward
        elif mid < 0.28:
            sign = 1.0                        # near the bottom -> arc upward
        else:
            sign = 1.0 if (h & 1) else -1.0
        # Vary the MAGNITUDE too, not just the sign — otherwise several level
        # flows all get the same arc and stack right back on top of each other.
        mag = 0.40 + 0.60 * (((h >> 1) & 0x7F) / 127.0)   # 0.40 .. 1.00
        return sign * 0.15 * flat * mag

    @staticmethod
    def _flow_bulge(x0, x1):
        """Horizontal push for flows whose endpoints share a column.

        internal->internal traffic (broadcast, mDNS, ARP) puts BOTH endpoints in
        the left column, so x0 == x1 and the cubic degenerates into a vertical
        line sitting on top of the column — which is what turned its packets into
        that stack of white dots. Pushing the control points sideways bows those
        flows out into a visible lateral arc instead. Same for external<->external
        chatter on the right.
        """
        if abs(x1 - x0) > 0.02:
            return 0.0
        return -0.16 if x0 < 0.5 else 0.16     # arc away from the canvas centre

    @staticmethod
    def _bezier_xy(x0, y0, x1, y1, t, bow=0.0, bulge=0.0):
        """Point(s) on the cubic bezier the ribbons are built from.
        `t` may be scalar or ndarray. `bow` lifts the control points vertically,
        `bulge` pushes them sideways (for same-column flows)."""
        cx = 0.42
        c0x = x0 + (x1 - x0) * cx + bulge
        c1x = x1 - (x1 - x0) * cx + bulge
        c0y = y0 + bow
        c1y = y1 + bow
        mt = 1.0 - t
        bx = (mt**3)*x0 + 3*(mt**2)*t*c0x + 3*mt*(t**2)*c1x + (t**3)*x1
        by = (mt**3)*y0 + 3*(mt**2)*t*c0y + 3*mt*(t**2)*c1y + (t**3)*y1
        return bx, by

    @staticmethod
    def _bezier_tangent(x0, y0, x1, y1, t, bow=0.0, bulge=0.0):
        """Derivative of the same cubic — gives each packet its heading."""
        cx = 0.42
        c0x = x0 + (x1 - x0) * cx + bulge
        c1x = x1 - (x1 - x0) * cx + bulge
        c0y = y0 + bow
        c1y = y1 + bow
        mt = 1.0 - t
        dx = 3*(mt**2)*(c0x-x0) + 6*mt*t*(c1x-c0x) + 3*(t**2)*(x1-c1x)
        dy = 3*(mt**2)*(c0y-y0) + 6*mt*t*(c1y-c0y) + 3*(t**2)*(y1-c1y)
        return dx, dy

    @staticmethod
    def _arrow_polys(xs, ys, dxs, dys, sizes_pt, ax_w_pt, ax_h_pt):
        """Arrowhead triangles pointing along the flow.

        Direction is normalised in PIXEL space (the axes is 0..1 in both dims but
        far wider than tall, so normalising in data space would skew every arrow).
        """
        polys = []
        xs  = np.atleast_1d(np.asarray(xs,  dtype=float))
        ys  = np.atleast_1d(np.asarray(ys,  dtype=float))
        dxs = np.atleast_1d(np.asarray(dxs, dtype=float))
        dys = np.atleast_1d(np.asarray(dys, dtype=float))
        ss  = np.atleast_1d(np.asarray(sizes_pt, dtype=float))
        if ss.size == 1 and xs.size > 1:
            ss = np.repeat(ss, xs.size)
        for x, y, dx, dy, s in zip(xs, ys, dxs, dys, ss):
            x = float(x); y = float(y); dx = float(dx); dy = float(dy); s = float(s)
            px, py = dx * ax_w_pt, dy * ax_h_pt        # heading, in points
            m = (px*px + py*py) ** 0.5
            if m < 1e-9 or s <= 0.3:
                continue
            ux, uy = px/m, py/m                        # unit heading
            nx, ny = -uy, ux                           # unit normal
            L = s * 1.35                               # length, points
            W = s * 0.62                               # half-width, points
            def _d(ax_, ay_):                          # points -> data coords
                return (x + ax_/ax_w_pt, y + ay_/ax_h_pt)
            tip  = _d(ux*L,            uy*L)
            bl   = _d(-ux*L*0.55 + nx*W, -uy*L*0.55 + ny*W)
            br   = _d(-ux*L*0.55 - nx*W, -uy*L*0.55 - ny*W)
            notch= _d(-ux*L*0.18,       -uy*L*0.18)    # concave tail -> reads as an arrow
            polys.append(np.array([tip, bl, notch, br]))
        return polys

    @staticmethod
    def _ribbon_poly(x0, y0, x1, y1, w, n=20, bow=0.0, bulge=0.0):
        """Cubic-bezier ribbon polygon between two points, thickness w.

        Built from _bezier_xy so the ribbon and the packets riding it can never
        drift apart.
        """
        t = np.linspace(0.0, 1.0, n)
        bx, by = EtherApeWindow._bezier_xy(x0, y0, x1, y1, t, bow, bulge)
        half = w / 2.0
        upper = np.column_stack([bx, by + half])
        lower = np.column_stack([bx[::-1], by[::-1] - half])
        # Rounded caps: a semicircle of radius `half` at each end, bulging away
        # from the ribbon, so a flow finishes in a soft dome rather than a blunt
        # chopped edge. Wound to match the polygon order (upper L->R, end cap,
        # lower R->L, start cap) so the outline stays one closed loop.
        k = 9
        a_end = np.linspace(np.pi / 2.0, -np.pi / 2.0, k)
        cap_end = np.column_stack([bx[-1] + half * np.cos(a_end),
                                   by[-1] + half * np.sin(a_end)])
        a_start = np.linspace(-np.pi / 2.0, -3.0 * np.pi / 2.0, k)
        cap_start = np.column_stack([bx[0] + half * np.cos(a_start),
                                     by[0] + half * np.sin(a_start)])
        return np.vstack([upper, cap_end, lower, cap_start])

    def _render_tick_inner(self):
        batch=self._pkt_queue[:5000]; del self._pkt_queue[:5000]  # larger batch = fewer render cycles
        # Cap queue so it can't grow unbounded on very busy networks
        if len(self._pkt_queue) > 10000:
            del self._pkt_queue[:len(self._pkt_queue)-5000]
        fp=self._filter_proto
        for src,dst,protos,length in batch:
            ptag=self._proto_tag(protos)
            if fp!='ALL' and fp.lower() not in protos: continue
            self._total_bytes+=length; self._total_pkts+=1
            for ip in (src,dst):
                # Skip MAC addresses (contain ':' and are not IPv6 with port)
                if ip.count(':') >= 4: continue  # MAC = 5 colons
                if ip not in self._nodes:
                    if len(self._nodes)>=self.MAX_NODES:
                        # Evict the stalest node instead of dropping new ones
                        evict_ip = max(self._nodes, key=lambda k: self._nodes[k].get('age',0))
                        del self._nodes[evict_ip]
                    # Deterministic placement by IP hash — no clustering, consistent positions
                    _h = hash(ip) & 0xFFFFFF
                    angle = (_h % 1000) / 1000.0 * 2 * np.pi
                    r_    = 0.28 + ((_h >> 12) % 200) / 1000.0  # 0.28–0.48
                    self._nodes[ip]={'bytes':0.0,'pkts':0,'pos':(0.5+r_*np.cos(angle),0.5+r_*np.sin(angle)),'proto':ptag,'age':0}
                nd=self._nodes[ip]; nd['bytes']+=length; nd['pkts']+=1; nd['proto']=ptag; nd['age']=0
            key=(src,dst,ptag)
            if key not in self._flows:
                if len(self._flows)>=self.MAX_FLOWS:
                    evict=min(self._flows,key=lambda k:self._flows[k]['bytes']); del self._flows[evict]
                self._flows[key]={'bytes':0.0,'pkts':0,'proto':ptag,'age':0}
            fl=self._flows[key]; fl['bytes']+=length; fl['pkts']+=1; fl['age']=0
        self._tick+=1; self._pulse_t=(self._pulse_t+0.15)%1.0
        # Drive the packet stream off the WALL CLOCK, not the frame counter.
        # A fixed step per frame means every dropped frame lurches the motion;
        # phase-from-time stays smooth however uneven the render rate gets.
        self._flow_phase=(time.time()*0.22)%1.0   # ~4.5s per traversal
        # Repulsion every 10 ticks — push nodes apart so labels don't overlap
        if self._tick % 10 == 0 and len(self._nodes) > 1:
            _items = [(ip, nd['pos']) for ip, nd in self._nodes.items()
                      if not nd.get('pinned', False)]
            for i, (ip1, (x1,y1)) in enumerate(_items):
                fx, fy = 0.0, 0.0
                for ip2, (x2,y2) in _items:
                    if ip1 == ip2: continue
                    dx, dy = x1-x2, y1-y2
                    # Skip early if clearly too far — avoids sqrt for most pairs
                    if abs(dx) > 0.08 or abs(dy) > 0.08: continue
                    dist = (dx*dx + dy*dy)**0.5 or 0.001
                    if dist < 0.08:
                        f = (0.08 - dist) * 0.008
                        fx += dx/dist * f; fy += dy/dist * f
                if fx or fy:
                    nx2 = max(0.03, min(0.97, x1 + fx))
                    ny2 = max(0.03, min(0.97, y1 + fy))
                    self._nodes[ip1]['pos'] = (nx2, ny2)
        hold=getattr(self,'_hold_flows_var',None) and self._hold_flows_var.get()
        if not hold:
            # Increment age each tick — reset to 0 when traffic arrives
            for nd in self._nodes.values(): nd['age']+=1
            for fl in self._flows.values(): fl['age']+=1
            # Remove nodes with no traffic for >5min (6000 ticks) OR bytes fully decayed
            for ip in [ip for ip,nd in self._nodes.items()
                       if nd['age']>6000 or nd['bytes']<0.001]: del self._nodes[ip]
            for nd in self._nodes.values(): nd['bytes']*=self.DECAY
            # Remove flows with no traffic for >2min (2400 ticks) OR bytes fully decayed
            for k in [k for k,fl in self._flows.items()
                      if fl['age']>2400 or fl['bytes']<0.0005]: del self._flows[k]
            for fl in self._flows.values(): fl['bytes']*=self.DECAY
            # Cap dns_cache and geo_cache to prevent unbounded growth
            if len(self._dns_cache) > 3000:
                # Keep most recent 500
                keys = list(self._dns_cache.keys())
                for k in keys[:len(keys)-500]: del self._dns_cache[k]
            if len(self._geo_cache) > 3000:
                keys = list(self._geo_cache.keys())
                for k in keys[:len(keys)-500]: del self._geo_cache[k]
        nodes, flows = self._render_data()
        # ── Attack drill ────────────────────────────────────────────────────
        # Hostiles come from the same server-side drill the web views use, so
        # the desktop Sankey/radial shows exactly the same contacts.
        try:
            _ah = _nm_attack_hosts()
            if _ah:
                nodes = dict(nodes); flows = dict(flows)
                _me = next((k for k in nodes if str(k).startswith(
                    ('192.168.', '10.', '172.'))), 'this-machine')
                for _h in _ah:
                    nodes[_h['ip']] = {
                        'bytes': int(_h['bytes']), 'pkts': _h['pkts'],
                        'proto': _h['proto'], 'first': time.time(),
                        'last': time.time(), 'country': _h['city'],
                        'label': 'SIM ' + _h['city'],
                        'blocked': _h['state'] == 'blocked', 'suspicious': True,
                        'attack': True, 'attack_state': _h['state'],
                        'kind': _h['kind'],
                    }
                    flows[(_h['ip'], _me, _h['proto'])] = {
                        'bytes': int(_h['bytes']), 'pkts': _h['pkts'],
                        'last': time.time(), 'blocked': _h['state'] == 'blocked',
                        'attack': True,
                    }
        except Exception:
            _exc_debug('etherape_attack_sim')
        # Renderer colours threats from these sets, not from the node dict, so a
        # drill host was drawn in ordinary protocol colours. Register them here.
        _atk_ips = {ip for ip, nd in nodes.items() if nd.get('attack')}

        # ── Timeline scrubber: buffer live frames; draw a past one when scrubbed ──
        # Accumulation and ageing above already ran on the live dicts, so pausing
        # here freezes only what is drawn — no capture data is lost.
        if getattr(self, '_replay', None) is None:
            try:
                self._tl_push(nodes, flows)
                if not self._tl_live and self._tl_hist:
                    _tlf = self._tl_hist[min(self._tl_idx, len(self._tl_hist) - 1)]
                    nodes, flows = _tlf[1], _tlf[2]
            except Exception:
                _exc_debug('etherape_timeline')
        # ── Min-bytes threshold filter ────────────────────────────────────────
        _thresh=self._min_bytes_thresh  # init'd in __init__, no need for getattr
        if _thresh>0:
            # Drill hostiles are exempt: they start at a few KB, so any MIN
            # TRAFFIC setting above that silently hid them from the view.
            nodes={ip:nd for ip,nd in nodes.items()
                   if nd.get('bytes',0)>=_thresh or nd.get('attack')}
            _thresh_ips=set(nodes)
            flows={k:v for k,v in flows.items()
                   if (k[0] in _thresh_ips and k[1] in _thresh_ips) or v.get('attack')}
        # ── Country filter ────────────────────────────────────────────────────
        _fc = getattr(self, '_filter_country', '').strip().lower()
        if _fc:
            _geo = getattr(self, '_geo_cache', {})
            # IPs whose resolved country matches the search term
            _match_ips = set(
                ip for ip, g in _geo.items()
                if _fc in (g.get('country','') or '').lower()
                or _fc in (g.get('countryCode','') or '').lower()
            )
            # Also include private IPs if the search is "private" or "local"
            if _fc in ('private','local','lan'):
                for ip in nodes:
                    if ip.startswith(('192.168.','10.','172.','127.')):
                        _match_ips.add(ip)
            # Drill hostiles have no geo entry, so a country filter would drop
            # them entirely — keep them regardless.
            for ip, nd in nodes.items():
                if nd.get('attack'):
                    _match_ips.add(ip)
            # Only keep flows where at least one endpoint is a matching IP
            flows = {k: v for k, v in flows.items()
                     if k[0] in _match_ips or k[1] in _match_ips or v.get('attack')}
            # Only keep nodes involved in remaining flows
            _flow_ips = set()
            for (s,d,_) in flows: _flow_ips.add(s); _flow_ips.add(d)
            nodes = {ip: nd for ip, nd in nodes.items() if ip in _flow_ips}
        # ─────────────────────────────────────────────────────────────────────
        if not nodes:
            self._edge_col.set_segments([]); self._glow_col.set_segments([])
            self._node_sc.set_offsets(np.empty((0,2))); self._node_sc.set_sizes([])
            self._pulse_sc.set_offsets(np.empty((0,2))); self._pulse_sc.set_sizes([])
            # Clear all cached label artists cleanly
            for a in getattr(self,'_label_artists',{}).values():
                try: a.remove()
                except Exception: _exc('_render_tick_inner')
            self._label_artists = {}
            for a in getattr(self,'_blocked_label_artists',[]):
                try: a.remove()
                except Exception: _exc('_render_tick_inner')
            self._blocked_label_artists = []
            for a in getattr(self,'_legend_artists',[]):
                try: a.remove()
                except Exception: _exc('_render_tick_inner')
            self._legend_artists = []
            if not getattr(self,'_placeholder_drawn',False):
                # Remove placeholder if switching from nodes→no-nodes
                _pa = getattr(self,'_placeholder_artist',None)
                if _pa:
                    try: _pa.remove()
                    except Exception: _exc('_render_tick_inner')
                self._placeholder_artist = self._ax.text(
                    0.5,0.5,'No traffic yet\nStart a capture to see the topology',
                    color=self._TICK,fontsize=13,ha='center',va='center',
                    fontfamily='monospace',linespacing=1.8,zorder=20)
                self._placeholder_drawn=True
            self._apply_view(); self._canvas.draw_idle()
            # JPEG tick runs here too so the "No traffic yet" canvas frame is
            # captured and served by the web stream instead of _no_ea_jpeg().
            if not hasattr(self, '_jpeg_tick'): self._jpeg_tick = 0
            self._jpeg_tick += 1
            if self._jpeg_tick % 25 == 0:
                self._jpeg_pending = True
            return
        else:
            # Remove placeholder only — leave cached label/legend artists intact
            if getattr(self,'_placeholder_drawn',False):
                _pa = getattr(self,'_placeholder_artist',None)
                if _pa:
                    try: _pa.remove()
                    except Exception: _exc('_render_tick_inner')
                    self._placeholder_artist = None
                self._placeholder_drawn=False
        max_bytes=max((n['bytes'] for n in nodes.values()),default=1) or 1
        segs,lws,colors_e,segs_glow,lws_glow=[],[],[],[],[]
        # Keyed by the blocked IP itself, not appended per-flow, so several
        # flows sharing one blocked destination don't stack identical
        # "[ BLOCKED ]" markers exactly on top of each other.
        _blocked_segs={}
        pulse_xs,pulse_ys,pulse_ss,pulse_cs=[],[],[],[]
        # ── Sankey mode: bipartite columns. We shallow-copy each node dict so
        #    overwriting 'pos' cannot corrupt the radial layout underneath.
        _sankey = (self._layout_mode == 'sankey')
        # Axes height in points — lets us size packets relative to ribbon
        # thickness instead of guessing, and it rescales with the window.
        _ax_pts = 700.0
        if _sankey:
            try:
                _ax_pts = self._ax.get_window_extent().height * 72.0 / self._fig.dpi
            except Exception:
                _ax_pts = 700.0
        if _sankey and nodes:
            nodes = {ip: dict(nd) for ip, nd in nodes.items()}
            self._sankey_layout(nodes, flows)
        _ribbon_specs=[]; _ribbon_cols=[]; _arrow_pts=[]
        # Keep the total particle count sane. With ~40 flows the old 10-per-flow
        # budget put 400 scatter points on screen every frame: cluttered to look
        # at and slow enough to drop frames.
        _pkt_budget = 180
        _n_flows = max(1, len(flows))
        _pkt_scale = min(1.0, _pkt_budget / (_n_flows * 6.0))

        flow_seg_map=[]
        for (src,dst,proto),fl in flows.items():
            if src not in nodes or dst not in nodes: continue
            if fl['bytes']<0.1: continue
            if fp!='ALL' and fp.lower()!=proto: continue
            x0,y0=nodes[src]['pos']; x1,y1=nodes[dst]['pos']
            # ── Manual reposition: in sankey mode a flow the user has dragged
            #    carries a persistent (dx,dy) offset applied to BOTH endpoints,
            #    so the whole ribbon slides as one. Applied before anything
            #    downstream (ribbon poly, packets, arrows, hit-test) reads them.
            # NOTE: a dragged flow no longer translates its endpoints — they stay
            # tethered to their nodes and the curve bends instead (see below).
            col=self.PROTO_COLORS.get(proto,self.PROTO_COLORS['other'])
            # Flash red for AI-flagged flows
            _susp_key = (src,dst,proto)
            _is_atk   = (src in _atk_ips or dst in _atk_ips)
            _is_susp  = (_susp_key in self._suspicious_flows or
                         (dst,src,proto) in self._suspicious_flows or _is_atk)
            if _is_susp:
                col = '#ff2222' if (self._tick // 6) % 2 == 0 else '#ff8888'
            frac=np.log1p(fl['bytes'])/np.log1p(max_bytes); lw=max(0.5,frac*self._flow_scale)
            if _is_susp: lw = max(lw, self._flow_scale * 0.8)  # always visible
            if _sankey:
                # Ribbon thickness scales with volume (data coords, axes are 0..1)
                _w = max(0.004, frac * 0.055)
                if (src in self._blocked_ips or dst in self._blocked_ips
                        or _is_susp or _is_atk):
                    _rc = '#e03b20' if _is_atk else '#b5484a'   # threat / blocked
                else:
                    _rc = col                # keep protocol colour = legend still true
                # ── Activity fade: a flow that just carried packets burns bright,
                #    one that's gone quiet dims away. age resets to 0 on traffic.
                _act = float(np.exp(-fl.get('age', 0) / 60.0))   # 1.0 live -> 0.0 idle
                _bow = self._flow_bow(y0, y1, (src, dst, proto))
                _bulge = self._flow_bulge(x0, x1)
                # ── Tethered drag: endpoints stay pinned to their nodes and the
                #    CURVE is pulled toward the cursor, so a dragged flow changes
                #    shape (rubber-band) instead of sliding away from the hosts
                #    it connects. A cubic bezier's midpoint only reaches 3/4 of a
                #    control-point offset, so scale by 4/3 to track the cursor ~1:1.
                _foff = self._flow_offsets.get((src, dst, proto))
                if _foff:
                    _bulge += _foff[0] * 1.3333
                    _bow   += _foff[1] * 1.3333
                # Defer the polygon build — geometry rarely changes between
                # frames, so we fingerprint it and rebuild only when it does.
                _ribbon_specs.append((x0, y0, x1, y1, _w, _bow, _bulge))
                _ribbon_cols.append(to_rgba(_rc, 0.14 + 0.62 * _act))
            segs.append([(x0,y0),(x1,y1)]); lws.append(lw); colors_e.append(col)
            segs_glow.append([(x0,y0),(x1,y1)]); lws_glow.append(lw*6); colors_e.append(col)
            flow_seg_map.append((x0,y0,x1,y1,src,dst,proto,
                                 (_bow if _sankey else 0.0),
                                 (_bulge if _sankey else 0.0)))
            # Collect BLOCKED marker positions (drawn after texts clear).
            # This used to sit at the flow's arithmetic midpoint — halfway
            # between the Internal Hosts and External Servers columns, so on
            # a busy canvas it landed in a meaningless spot in mid-air, not
            # next to whichever server was actually blocked. Anchor it at the
            # blocked endpoint itself instead (offset a little below the node,
            # since that node's own name label — if one is shown — sits just
            # above it), so it's unambiguous which server the marker is for.
            if dst in self._blocked_ips:
                _blocked_segs[dst] = (x1, y1 + 0.026)
            elif src in self._blocked_ips:
                _blocked_segs[src] = (x0, y0 + 0.026)
            if _sankey:
                # ── Packet stream: busier ribbons carry more, brighter packets ──
                _n = max(1, int(round((2 + frac * 5) * _pkt_scale)))   # 1..7, budgeted
                _off = (hash((src,dst,proto)) & 0xFF) / 255.0   # de-sync each ribbon
                _ts = (self._flow_phase + _off + np.arange(_n) / _n) % 1.0
                _px, _py = self._bezier_xy(x0, y0, x1, y1, _ts, _bow, _bulge)
                # Fade in/out at the endpoints. A steeper curve keeps packets from
                # bunching into a blob where every ribbon meets its host node.
                _fade = np.sin(np.pi * _ts) ** 1.6
                # Size the packet to the PIPE it travels in, then clamp — on a big
                # canvas an unclamped 60%-of-ribbon dot becomes a 30pt blob.
                _dia = min(11.0, max(2.5, _w * _ax_pts * 0.34))   # diameter, points
                _sz  = (_dia ** 2) * _fade
                _pc  = '#ffd0c0' if (_is_susp or _is_atk or src in self._blocked_ips
                                     or dst in self._blocked_ips) else '#ffffff'
                _pa  = 0.45 + 0.55 * _act                  # quiet flows -> faint packets
                _dx, _dy = self._bezier_tangent(x0, y0, x1, y1, _ts, _bow, _bulge)
                _asz = np.asarray(_dia * 0.5 * (_fade ** 0.6), dtype=float)
                _arrow_pts.append((_px, _py, _dx, _dy, _asz, to_rgba(_pc, _pa)))
            else:
                # Radial: same arrowheads, riding the straight chord src -> dst.
                t=(self._flow_phase+(hash((src,dst,proto))&0xFF)/255.0)%1.0
                px=x0+(x1-x0)*t; py=y0+(y1-y0)*t
                _fd=np.sin(np.pi*t)**0.8
                _sz=max(3.0, min(9.0, 2.5+frac*7.0))
                _arrow_pts.append((np.array([px]), np.array([py]),
                                   np.array([x1-x0]), np.array([y1-y0]),
                                   np.array([_sz*_fd], dtype=float), to_rgba(col, 0.95)))
        self._flow_seg_map=flow_seg_map
        # Sankey chrome on/off. flow_seg_map is still populated either way, so
        # click-to-inspect on flows keeps working in both modes.
        self._ribbon_col.set_visible(_sankey)
        self._grid_sc.set_visible(_sankey)
        for _h in self._col_hdrs: _h.set_visible(_sankey)
        if _sankey and _ribbon_specs:
            # Ribbon shape only changes when nodes move or flow volumes shift.
            # Rebuilding ~40 bezier polygons and re-pathing them EVERY frame was
            # the main cost, and dropped frames are what made the motion stutter.
            # Fingerprint the geometry (quantised, so byte-counts ticking over
            # don't invalidate it) and reuse the cached polys when it's unchanged.
            _sig = tuple((round(a,3), round(b,3), round(c,3), round(d,3),
                          round(e,3), round(f,3), round(g,3))
                         for (a,b,c,d,e,f,g) in _ribbon_specs)
            if _sig != self._ribbon_sig:
                self._ribbon_cache = [self._ribbon_poly(a,b,c,d,e,bow=f,bulge=g)
                                      for (a,b,c,d,e,f,g) in _ribbon_specs]
                self._ribbon_sig = _sig
                self._ribbon_col.set_verts(self._ribbon_cache)
            # Colours DO change every frame (the activity fade) — but that's cheap.
            self._ribbon_col.set_facecolors(_ribbon_cols)
            self._ribbon_col.set_alpha(None)   # per-face RGBA carries the fade
        else:
            self._ribbon_col.set_verts([])
            self._ribbon_sig = None
        # Packets must sit ON TOP of their ribbon at full strength, or the
        # ribbon's own colour swallows them.
        self._pulse_sc.set_alpha(None if _sankey else 0.75)
        self._pulse_sc.set_zorder(10 if _sankey else 9)

        if segs and not _sankey:
            self._edge_col.set_segments(segs); self._edge_col.set_linewidth(lws)
            self._edge_col.set_colors(colors_e[:len(segs)]); self._edge_col.set_alpha(0.75)
            self._glow_col.set_segments(segs_glow); self._glow_col.set_linewidth(lws_glow)
            self._glow_col.set_colors(colors_e[:len(segs)]); self._glow_col.set_alpha(0.10)
        else:
            # Ribbons carry the visual in sankey mode — hide the line layers.
            self._edge_col.set_segments([]); self._glow_col.set_segments([])
        if _arrow_pts:
            try:
                _bb = self._ax.get_window_extent()
                _awp = _bb.width  * 72.0 / self._fig.dpi
                _ahp = _bb.height * 72.0 / self._fig.dpi
            except Exception:
                _awp = _ahp = 700.0
            _apolys=[]; _acols=[]
            for (_px,_py,_dx,_dy,_ss,_col) in _arrow_pts:
                _pp=self._arrow_polys(_px,_py,_dx,_dy,_ss,_awp,_ahp)
                _apolys.extend(_pp); _acols.extend([_col]*len(_pp))
            self._pkt_arrows.set_verts(_apolys)
            self._pkt_arrows.set_facecolors(_acols)
            self._pkt_arrows.set_alpha(None)
            self._pkt_arrows.set_visible(True)
            self._pulse_sc.set_offsets(np.empty((0,2))); self._pulse_sc.set_sizes([])
        else:
            self._pkt_arrows.set_visible(False); self._pkt_arrows.set_verts([])
            self._pulse_sc.set_offsets(np.empty((0,2))); self._pulse_sc.set_sizes([])
        # ── Animated directional arrows — chevrons via persistent LineCollection ──
        arr_segs=[]; arr_cols=[]
        if segs and not _sankey:   # chevrons are chord-aligned; ribbons carry direction
            for idx2,((x0,y0),(x1,y1)) in enumerate(segs):
                col=colors_e[idx2]
                dx2=x1-x0; dy2=y1-y0; seg_len=(dx2**2+dy2**2)**0.5
                if seg_len<0.02: continue
                nx=dx2/seg_len; ny=dy2/seg_len
                # Perpendicular
                px2=-ny*0.005; py2=nx*0.005
                head=0.010
                t_off=(self._pulse_t+idx2*0.31)%1.0
                for t_frac in [t_off,(t_off+0.5)%1.0]:
                    t_frac=max(0.05,min(0.92,t_frac))
                    tx=x0+t_frac*dx2; ty=y0+t_frac*dy2
                    tip_x=tx+nx*head; tip_y=ty+ny*head
                    # Left and right chevron lines to tip
                    arr_segs.append([(tx-nx*head*0.5+px2,ty-ny*head*0.5+py2),(tip_x,tip_y)])
                    arr_segs.append([(tx-nx*head*0.5-px2,ty-ny*head*0.5-py2),(tip_x,tip_y)])
                    arr_cols.extend([col,col])
        self._arrow_lc.set_segments(arr_segs)
        if arr_cols: self._arrow_lc.set_colors(arr_cols)

        node_xs,node_ys,node_ss,node_cs=[],[],[],[]
        for ip,nd in nodes.items():
            x,y=nd['pos']; col=self.PROTO_COLORS.get(nd['proto'],self.PROTO_COLORS['other'])
            if nd.get('attack'):
                # Hostile: pulses red, brighter once the rule is written.
                col = ('#ff3020' if nd.get('attack_state') == 'blocked'
                       else ('#ff5a2a' if (self._tick // 4) % 2 == 0 else '#ff9a5a'))
            frac=nd['bytes']/max_bytes; sz=max(40,min(1400,frac*1200+40))
            if nd.get('attack'): sz=max(sz,260)
            node_xs.append(x); node_ys.append(y); node_ss.append(sz); node_cs.append(col)
        if node_xs:
            pts=np.column_stack([node_xs,node_ys])
            self._node_sc.set_offsets(pts); self._node_sc.set_sizes(node_ss); self._node_sc.set_facecolors(node_cs)
        else:
            self._node_sc.set_offsets(np.empty((0,2))); self._node_sc.set_sizes([])
        # IDS red rings around suspicious nodes
        if not hasattr(self,'_ids_ring_sc'):
            self._ids_ring_sc=self._ax.scatter([],[],s=[],facecolors='none',
                                                edgecolors='#ff4444',linewidths=2,zorder=10,alpha=0.9)
        susp=getattr(self,'_ids_suspicious',set())
        ring_xs=[]; ring_ys=[]; ring_ss=[]
        for ip,nd in nodes.items():
            if ip in susp:
                x2,y2=nd['pos']; frac2=nd['bytes']/max_bytes
                ring_xs.append(x2); ring_ys.append(y2)
                ring_ss.append(max(80,min(1600,frac2*1400+80)))
        if ring_xs:
            self._ids_ring_sc.set_offsets(np.column_stack([ring_xs,ring_ys]))
            self._ids_ring_sc.set_sizes(ring_ss)
        else:
            self._ids_ring_sc.set_offsets(np.empty((0,2))); self._ids_ring_sc.set_sizes([])
        # Labels — use persistent Text artists, only recreate when content changes
        if not hasattr(self,'_label_artists'): self._label_artists = {}
        # Collect what labels we want this frame
        wanted = {}  # ip → (x, y, text, color, blk)
        _flow_ips = set()
        for (_fs,_fd,_fp) in flows.keys(): _flow_ips.add(_fs); _flow_ips.add(_fd)
        if self._show_labels:
            # Collect label candidates, then place them most-important-first and
            # skip any that would overlap one already placed in the same column.
            # This declutters the crowded External Servers column — every node
            # still shows its dot, but only non-overlapping labels get text.
            _cands = []
            for ip,nd in nodes.items():
                if ip not in _flow_ips: continue
                x,y=nd['pos']; col=self.PROTO_COLORS.get(nd['proto'],self.PROTO_COLORS['other'])
                disp=self._resolve(ip); frac=nd['bytes']/max_bytes
                r_px=max(0.012,min(0.065,0.012+frac*0.053))
                _geo_n = self._geo_cache.get(ip,{})
                _blk   = ip in self._blocked_ips
                _atk_n = nd.get('attack')
                _cntry = _geo_n.get('country','')
                _cc    = _cntry[:2].upper() if _cntry else ''
                _prefix = '[' + _cc + '] ' if _cc else ''
                _suffix = ' BLOCKED' if _blk else ''
                if _atk_n:
                    # Name the threat plainly: nothing else in the view is red
                    # with a skull, so a drill is unmistakable.
                    _prefix = '\u2620 SIM '
                    disp = (nd.get('country') or ip)
                    _suffix = (' \u2014 BLOCKED' if nd.get('attack_state') == 'blocked'
                               else ' \u2014 ' + str(nd.get('kind', 'hostile')))
                _lbl   = _prefix + disp + _suffix
                _lcol  = '#ff5030' if _atk_n else ('#ff4444' if _blk else col)
                _cands.append((nd['bytes'], _blk, ip, x, y-r_px-0.022, _lbl, _lcol))
            # Blocked first (security-relevant), then by volume.
            # Hostiles first, then blocked, then by volume.
            _cands.sort(key=lambda c: (not c[1], -c[0]))
            _placed_l, _placed_r = [], []
            _min_gap = 0.028
            for _by, _blk, ip, x, ly, _lbl, _lcol in _cands:
                _col = _placed_l if x < 0.5 else _placed_r
                if any(abs(ly - py) < _min_gap for py in _col):
                    continue                 # would overlap a placed label → skip
                _col.append(ly)
                wanted[ip] = (x, ly, _lbl, _lcol, _blk)
        # Remove artists for IPs no longer wanted
        for ip in list(self._label_artists):
            if ip not in wanted:
                try: self._label_artists[ip].remove()
                except Exception: _exc('_render_tick_inner')
                del self._label_artists[ip]
        # Update or create artists
        for ip,(x,y,txt,col,blk) in wanted.items():
            if ip in self._label_artists:
                a = self._label_artists[ip]
                a.set_position((x,y)); a.set_text(txt); a.set_color(col)
            else:
                _bbox_ec = '#ff4444' if blk else 'none'
                a = self._ax.text(x,y,txt,color=col,
                          fontsize=self._label_fontsize,
                          ha='center',va='top',fontfamily=self._label_fontfamily,
                          fontweight='bold',zorder=11,
                          bbox=dict(boxstyle='round,pad=0.08',
                                    facecolor='#1a0000' if blk else '#020810',
                                    edgecolor=_bbox_ec,alpha=0.85 if blk else 0.60))
                self._label_artists[ip] = a
        # BLOCKED markers, one per blocked host (small set, ok to recreate)
        if not hasattr(self,'_blocked_label_artists'): self._blocked_label_artists=[]
        for a in self._blocked_label_artists:
            try: a.remove()
            except Exception: _exc('_render_tick_inner')
        self._blocked_label_artists=[]
        if _blocked_segs and self._show_labels:
            for _bx,_by in _blocked_segs.values():
                a=self._ax.text(_bx,_by,'[ BLOCKED ]',color='#ff4444',
                              fontsize=7,ha='center',va='center',zorder=13,
                              fontfamily=self._label_fontfamily,fontweight='bold',
                              bbox=dict(boxstyle='round,pad=0.1',facecolor='#1a0000',
                                        edgecolor='#ff4444',alpha=0.85))
                self._blocked_label_artists.append(a)
        if self._show_legend:
            protos_seen=set(nd['proto'] for nd in nodes.values())
            # Clear old legend artists and redraw (legend is small, cheap to redo)
            for a in getattr(self,'_legend_artists',[]):
                try: a.remove()
                except Exception: _exc('_render_tick_inner')
            self._legend_artists=[]
            lx,ly=0.01,0.99
            for proto in self.PROTO_PRIORITY+['other']:
                if proto not in protos_seen: continue
                col=self.PROTO_COLORS.get(proto,self.PROTO_COLORS['other'])
                a=self._ax.text(lx+0.028,ly-0.004,f'* {proto.upper()}',color=col,
                              fontsize=self._label_fontsize,va='center',
                              fontfamily=self._label_fontfamily,fontweight='bold',zorder=12)
                self._legend_artists.append(a)
                ly-=0.036
        else:
            for a in getattr(self,'_legend_artists',[]):
                try: a.remove()
                except Exception: _exc('_render_tick_inner')
            self._legend_artists=[]
        tb=self._total_bytes
        unit='KB' if tb<1e6 else 'MB' if tb<1e9 else 'GB'
        div=1e3 if tb<1e6 else 1e6 if tb<1e9 else 1e9
        self._total_var.set(f'{len(nodes)} hosts  |  {len(flows)} flows  |  {self._total_pkts:,} pkts  |  {tb/div:.1f} {unit}')
        self._pkt_var.set(f'{self._total_pkts:,} pkts')
        self._apply_view()
        if _sankey:
            self._blit_frame()      # cheap: only the packets get repainted
        else:
            self._canvas.draw_idle()
        # JPEG for web stream: set flag — draw_event hook captures pixels safely.
        if not hasattr(self, '_jpeg_tick'): self._jpeg_tick = 0
        self._jpeg_tick += 1
        if self._jpeg_tick % 25 == 0:
            self._jpeg_pending = True

    def _table_tick(self):
        if self._closed: return
        try: self._table_tick_inner()
        except Exception: _exc('_table_tick')
        # Auto-block any new IPs from persistently blocked countries
        try: self._auto_block_country_ips()
        except Exception: _exc('_table_tick')
        try: self._persist_flows()
        except Exception: _exc('_persist_flows')
        self._schedule_table_update()

    # ── Flow persistence ─────────────────────────────────────────────────────
    #  self._flows holds CUMULATIVE byte counts for the life of the capture, so
    #  writing them straight to the DB every minute would double-count massively.
    #  Persist the DELTA since the last flush instead — that gives a real time
    #  series you can ask "what used my bandwidth at 3am" of.

    _FLUSH_SECS = 60

    def _persist_flows(self):
        now = time.time()
        last = getattr(self, '_last_flow_flush', 0)
        if now - last < self._FLUSH_SECS:
            return
        self._last_flow_flush = now

        db = None
        for m in _monitor_instances:
            db = getattr(m, '_db', None)
            if db is not None:
                break
        if db is None:
            return

        prev = getattr(self, '_flow_prev', None)
        if prev is None:
            prev = self._flow_prev = {}

        snap = dict(self._flows)
        rows = []
        for (src, dst, proto), fl in snap.items():
            cb, cp = float(fl.get('bytes') or 0), int(fl.get('pkts') or 0)
            pb, pp = prev.get((src, dst, proto), (0.0, 0))
            db_, dp = cb - pb, cp - pp
            if db_ <= 0 and dp <= 0:
                continue                       # nothing moved this minute
            geo = self._geo_cache.get(dst) or {}
            rows.append({'src': src, 'dst': dst, 'proto': proto,
                         'port': None, 'cc': geo.get('countryCode') or None,
                         'bytes': int(max(0, db_)), 'pkts': int(max(0, dp))})
        self._flow_prev = {k: (float(v.get('bytes') or 0), int(v.get('pkts') or 0))
                           for k, v in snap.items()}

        if not rows:
            return
        ts = datetime.now().isoformat()
        try:
            n = db.insert_flows(ts, rows)
            if n:
                log.debug(f'[flows] persisted {n} rows')
        except Exception:
            _exc('_persist_flows.insert')

        # Housekeeping: don't let the table grow forever.
        if not getattr(self, '_flows_purged', False):
            self._flows_purged = True
            try:
                db.purge_flows(keep_days=30)
            except Exception:
                _exc('_persist_flows.purge')

    def _table_tick_inner(self):
        if self._closed: return
        try:
            nodes=dict(self._nodes); flows=dict(self._flows)
            # Build new host rows
            host_rows = []
            for ip,nd in sorted(nodes.items(),key=lambda x:x[1]['bytes'],reverse=True)[:60]:
                b=nd['bytes']; unit='KB' if b<1e6 else 'MB'; div=1e3 if b<1e6 else 1e6
                name=self._dns_cache.get(ip,'')
                host_rows.append((ip, (ip,name,f"{nd['pkts']:,}",f"{b/div:.1f}{unit}",nd['proto'].upper()), nd['proto']))
            # Efficient update: delete only if count changed significantly, else update in-place
            existing = self._host_tree.get_children()
            if len(existing) != len(host_rows):
                self._host_tree.delete(*existing) if existing else None
                for ip,vals,proto in host_rows:
                    self._host_tree.insert('','end',values=vals,tags=(proto,))
            else:
                for iid,(ip,vals,proto) in zip(existing, host_rows):
                    self._host_tree.item(iid, values=vals, tags=(proto,))
            # Flow tree - always rebuild (flow keys change)
            existing_f = self._flow_tree.get_children()
            if existing_f: self._flow_tree.delete(*existing_f)
            for (src,dst,proto),fl in sorted(flows.items(),key=lambda x:x[1]['bytes'],reverse=True)[:80]:
                b=fl['bytes']; unit='KB' if b<1e6 else 'MB'; div=1e3 if b<1e6 else 1e6
                self._flow_tree.insert('','end',
                    values=(src[:22],dst[:22],proto.upper(),f"{fl['pkts']:,}",f"{b/div:.1f}{unit}"),tags=(proto,))
        except Exception: _exc('_table_tick_inner')

    def _apply_view(self):
        half=0.5/self._zoom
        self._ax.set_xlim(self._pan_x-half,self._pan_x+half)
        self._ax.set_ylim(self._pan_y-half,self._pan_y+half)
        try: self._zoom_lbl.config(text=f'{int(self._zoom*100)}%')
        except Exception: _exc('_apply_view')

    def _apply_country_filter(self):
        """Filter topology to show only flows involving nodes from the given country."""
        term = getattr(self,'_country_var',None)
        if term is None: return
        q = term.get().strip()
        self._filter_country = q.lower()
        try:
            if q:
                self._country_lbl.config(text=f'  ◈ {q.upper()}')
            else:
                self._country_lbl.config(text='')
        except Exception: _exc('_apply_country_filter')

    # ── Persistent country blocking ───────────────────────────────────────────

    def _load_blocked_countries(self):
        """Load persistently blocked country codes from disk."""
        try:
            p = Path(self._BLOCKED_CC_FILE)
            if p.exists():
                data = json.loads(p.read_text(encoding='utf-8'))
                self._blocked_countries = set(c.upper() for c in data if c)
                print(f'[NM] Loaded {len(self._blocked_countries)} blocked countries from {p}')
            else:
                print(f'[NM] No blocked_countries.json found at {p}')
        except Exception as e:
            print(f'[NM] Failed to load blocked_countries.json: {e}')

    def _save_blocked_countries(self):
        """Save persistently blocked country codes to disk."""
        try:
            p = Path(self._BLOCKED_CC_FILE)
            p.write_text(
                json.dumps(sorted(self._blocked_countries), indent=2),
                encoding='utf-8')
            print(f'[NM] Saved {len(self._blocked_countries)} blocked countries to {p}')
        except Exception as e:
            print(f'[NM] Failed to save blocked_countries.json: {e}')

    def _block_country(self):
        """Block country: add to persistent list, block current IPs, remember for future."""
        log.info(f"block_country: called")
        cc = getattr(self,'_block_cc_var',None)
        if cc is None: return
        code = cc.get().strip().upper()
        if not code:
            return
        # Add to persistent blocked set immediately
        self._blocked_countries.add(code)
        self._save_blocked_countries()
        # Collect IPs to block right now
        geo = dict(getattr(self,'_geo_cache',{}))
        def _cc_match(g):
            cc = (g.get('countryCode','') or '').upper()
            if not cc:
                cc = (g.get('country','') or '')[:2].upper()
            return cc == code
        targets = [ip for ip,g in geo.items() if _cc_match(g)]
        for ip in list(self._nodes.keys()):
            g = geo.get(ip,{})
            if _cc_match(g) and ip not in targets:
                targets.append(ip)

        lbl_msg = f'⛔ {code} blocked (0 IPs so far)' if not targets else f'Blocking {len(targets)} IPs...'
        try:
            self._block_cc_btn.config(state='disabled', text='Blocking...')
            self._block_cc_lbl.config(text=lbl_msg)
        except Exception: _exc('_cc_match')

        def _do():
            import re as _re
            blocked_count = 0
            skipped = 0
            flags = subprocess.CREATE_NO_WINDOW if sys.platform == 'win32' else 0
            for ip in targets:
                if not _re.match(r'^[\d.]+$', ip):
                    skipped += 1; continue
                rule = f'NM_BLOCK_{ip.replace(".","_")}'
                try:
                    # Check firewall first — don't add if rule already exists
                    _chk_exists = _nm_fw_rule_exists(rule)
                    if _chk_exists:
                        self._blocked_ips.add(ip)
                        blocked_count += 1
                        self._refresh_blocked_count()
                        continue  # already blocked — skip
                    if ip in self._blocked_ips:
                        blocked_count += 1; continue
                    _ok, _err = _nm_fw_add_block(rule, ip)
                    if not _ok:
                        log.warning('[fw] block of %s failed: %s', ip, _err)
                        continue
                    self._blocked_ips.add(ip)
                    blocked_count += 1
                    self._refresh_blocked_count()
                except Exception:
                    skipped += 1
            def _done():
                try:
                    self._block_cc_btn.config(state='normal', text='⛔ BLOCK')
                    msg = f'⛔ {code} active — {blocked_count} IP(s) blocked'
                    if skipped: msg += f', {skipped} skipped'
                    self._block_cc_lbl.config(text=msg)
                except Exception: _exc('_done')
            try: self.root.after(0, _done)
            except Exception: _exc('_done')
        threading.Thread(target=_do, daemon=True).start()

    def _auto_block_country_ips(self):
        """Called every TABLE_MS: block new IPs from persistently blocked countries.
        Dispatches to a background thread so it never stalls the Tk main loop."""
        if not self._blocked_countries:
            return
        if sys.platform != 'win32':
            return
        # Guard: don't start another thread if one is already running
        if getattr(self, '_auto_block_running', False):
            return
        import re as _re
        geo = dict(self._geo_cache)
        # Collect IPs that need blocking (not yet in _blocked_ips)
        to_block = []
        for ip, g in geo.items():
            # Match on countryCode OR first two letters of country name
            cc = (g.get('countryCode','') or '').upper()
            if not cc:
                cc = (g.get('country','') or '')[:2].upper()
            if cc not in self._blocked_countries:
                continue
            if ip in self._blocked_ips:
                continue
            if not _re.match(r'^[\d.:a-fA-F]+$', ip):
                continue
            to_block.append(ip)
        if not to_block:
            return
        def _do():
            flags = _nm_flags()
            import re as _re2
            # One query for every NM_BLOCK_ rule, instead of one per IP
            try:
                # one query for all our rules, whichever backend is active
                existing_rules = set(_nm_fw_list_rules('NM_BLOCK_'))
            except Exception:
                existing_rules = set()
            for ip in to_block:
                if not _re2.match(r'^[\d.]+$', ip): continue
                rule = f'NM_BLOCK_{ip.replace(".","_")}'
                try:
                    if rule in existing_rules:
                        self._blocked_ips.add(ip)
                        continue  # already exists — don't duplicate
                    _ok, _err = _nm_fw_add_block(rule, ip)
                    if not _ok:
                        log.warning('[fw] auto-block of %s failed: %s', ip, _err)
                        continue
                    self._blocked_ips.add(ip)
                except Exception:
                    _exc('_do')
            self._auto_block_running = False
        self._auto_block_running = True
        threading.Thread(target=_do, daemon=True).start()

    def _open_blocked_countries_window(self):
        """Show a window listing blocked countries with unblock buttons."""
        import tkinter as tk
        win = tk.Toplevel()
        win.title('Blocked Countries')
        win.configure(bg='#050d1a')
        win.geometry('460x420')
        win.minsize(340, 200)

        BG='#050d1a'; PNL='#06101e'; ACC='#ff4444'; TICK='#6a9ab8'; GRN='#2ea043'
        TXT='#c8dff0'

        tk.Label(win, text='⛔  BLOCKED COUNTRIES',
                 bg=BG, fg=ACC, font=(_NM_MONO, 11,'bold')).pack(pady=(14,4))
        tk.Label(win, text='IPs from these countries are blocked automatically.',
                 bg=BG, fg=TICK, font=(_NM_MONO, 8)).pack(pady=(0,10))

        frame = tk.Frame(win, bg=BG)
        frame.pack(fill='both', expand=True, padx=16, pady=4)

        def _refresh():
            for w in frame.winfo_children():
                w.destroy()
            ccs = sorted(self._blocked_countries)
            if not ccs:
                tk.Label(frame, text='No countries are currently blocked.',
                         bg=BG, fg=TICK, font=(_NM_MONO, 9)).pack(pady=20)
                return
            for cc in ccs:
                # Count how many IPs are blocked for this CC
                geo = dict(self._geo_cache)
                def _match(g, c=cc):
                    x = (g.get('countryCode','') or '').upper()
                    if not x: x = (g.get('country','') or '')[:2].upper()
                    return x == c
                n_ips = sum(1 for ip in self._blocked_ips if _match(geo.get(ip,{})))
                country_name = next(
                    (g.get('country','') for g in geo.values()
                     if (g.get('countryCode','') or (g.get('country','') or '')[:2]).upper() == cc), '')
                row = tk.Frame(frame, bg=PNL, relief='flat', bd=0)
                row.pack(fill='x', pady=2, ipady=4)
                tk.Label(row, text=f'  {cc}', bg=PNL, fg=ACC,
                         font=(_NM_MONO, 11,'bold'), width=6, anchor='w').pack(side='left')
                lbl = f'{country_name}' if country_name else cc
                tk.Label(row, text=f'{lbl}   ({n_ips} IP(s) blocked)',
                         bg=PNL, fg=TXT, font=(_NM_MONO, 9), anchor='w').pack(side='left', fill='x', expand=True)
                def _unblock(c=cc):
                    self._unblock_country(c)
                    _refresh()
                tk.Button(row, text='Unblock', bg='#0a1828', fg=GRN,
                          relief='flat', font=(_NM_MONO, 8,'bold'),
                          cursor='hand2', padx=8, pady=2,
                          activebackground=GRN, activeforeground='white',
                          command=_unblock).pack(side='right', padx=8)

        _refresh()

        # Add new CC at bottom
        add_frame = tk.Frame(win, bg=BG)
        add_frame.pack(fill='x', padx=16, pady=(8,14))
        tk.Label(add_frame, text='Block country code:',
                 bg=BG, fg=TICK, font=(_NM_MONO, 8)).pack(side='left')
        add_var = tk.StringVar()
        add_ent = tk.Entry(add_frame, textvariable=add_var, width=6,
                           bg='#0a1220', fg=ACC, insertbackground=ACC,
                           relief='flat', font=(_NM_MONO, 9,'bold'),
                           highlightthickness=1, highlightcolor=ACC,
                           highlightbackground='#1a3a5a')
        add_ent.pack(side='left', padx=8, ipady=3)
        def _add():
            c = add_var.get().strip().upper()
            if not c: return
            self._blocked_countries.add(c)
            self._save_blocked_countries()
            add_var.set('')
            _refresh()
            # Trigger immediate block of known IPs
            self._block_cc_var.set(c) if hasattr(self,'_block_cc_var') else None
            threading.Thread(target=lambda: self._auto_block_country_ips(), daemon=True).start()
        add_ent.bind('<Return>', lambda e: _add())
        tk.Button(add_frame, text='+ Block', bg='#0a1220', fg=ACC,
                  relief='flat', font=(_NM_MONO, 8,'bold'), cursor='hand2',
                  padx=8, pady=3, activebackground=ACC, activeforeground='white',
                  command=_add).pack(side='left')

    def _unblock_country(self, code):
        """Remove country from blocked list and remove all its firewall rules."""
        code = code.upper()
        self._blocked_countries.discard(code)
        self._save_blocked_countries()
        # Remove firewall rules for all IPs of this country
        geo = dict(self._geo_cache)
        def _cc_match(g):
            cc2 = (g.get('countryCode','') or '').upper()
            if not cc2: cc2 = (g.get('country','') or '')[:2].upper()
            return cc2 == code
        targets = [ip for ip,g in geo.items() if _cc_match(g)]

        def _do():
            flags = subprocess.CREATE_NO_WINDOW if sys.platform == 'win32' else 0
            for ip in targets:
                rule = f'NM_BLOCK_{ip.replace(".","_").replace(":","_")}'
                try:
                    _nm_fw_delete_rule(rule)
                    self._blocked_ips.discard(ip)
                except Exception:
                    _exc('_do')
        threading.Thread(target=_do, daemon=True).start()

    def _zoom_reset(self):
        self._zoom=1.0; self._pan_x=0.5; self._pan_y=0.5
        self._apply_view(); self._canvas.draw_idle()

    def _on_scroll(self,event):
        if self._closed or event.xdata is None or event.ydata is None: return
        factor=1.15 if event.button=='up' else (1/1.15)
        new_zoom=max(0.2,min(20.0,self._zoom*factor))
        cx,cy=event.xdata,event.ydata
        self._pan_x=cx+(self._pan_x-cx)*(self._zoom/new_zoom)
        self._pan_y=cy+(self._pan_y-cy)*(self._zoom/new_zoom)
        self._zoom=new_zoom; self._apply_view(); self._canvas.draw_idle()

    def _on_pan_start(self,event):
        if self._closed: return
        if event.button in (2,3) and event.xdata is not None and event.ydata is not None:
            self._drag_node=None  # cancel any node drag on right/middle click
            self._pan_dragging=True; self._pan_last=(event.xdata,event.ydata)

    def _on_canvas_resize(self,event):
        """Spread existing nodes across the new visible area when window is resized."""
        if self._closed or not self._nodes: return
        # Get current view bounds
        half = 0.5 / self._zoom
        xmin = self._pan_x - half; xmax = self._pan_x + half
        ymin = self._pan_y - half; ymax = self._pan_y + half
        # Find current node bounds
        xs = [nd['pos'][0] for nd in self._nodes.values()]
        ys = [nd['pos'][1] for nd in self._nodes.values()]
        if not xs: return
        nxmin,nxmax = min(xs),max(xs)
        nymin,nymax = min(ys),max(ys)
        nxr = nxmax-nxmin or 1; nyr = nymax-nymin or 1
        # Target: fill 80% of the view
        txmin = xmin+0.1*(xmax-xmin); txmax = xmax-0.1*(xmax-xmin)
        tymin = ymin+0.1*(ymax-ymin); tymax = ymax-0.1*(ymax-ymin)
        # Rescale node positions (skip pinned nodes)
        for nd in self._nodes.values():
            if nd.get('pinned'): continue
            nx,ny = nd['pos']
            fx = (nx-nxmin)/nxr; fy = (ny-nymin)/nyr
            nd['pos'] = (txmin+fx*(txmax-txmin), tymin+fy*(tymax-tymin))
        self._canvas.draw_idle()

    def _on_pan_move(self,event):
        if self._closed: return
        if event.xdata is None or event.ydata is None: return
        # Flow drag (sankey) takes top priority: slide the grabbed ribbon,
        # storing a persistent offset so it holds its new spot every frame.
        if self._drag_flow is not None:
            cx,cy=event.xdata,event.ydata
            sx,sy=self._drag_flow_start; ox,oy=self._drag_flow_orig
            dx=ox+(cx-sx); dy=oy+(cy-sy)
            dx=max(-0.85,min(0.85,dx)); dy=max(-0.85,min(0.85,dy))
            self._flow_offsets[self._drag_flow]=(dx,dy)
            self._drag_flow_moved=True
            self._canvas.draw_idle()
            return
        # Node drag takes priority
        if self._drag_node and self._drag_node in self._nodes:
            ox,oy=self._drag_offset
            self._nodes[self._drag_node]['pos']=(event.xdata-ox, event.ydata-oy)
            self._canvas.draw_idle()
            return
        if not self._pan_dragging: return
        dx=event.xdata-self._pan_last[0]; dy=event.ydata-self._pan_last[1]
        self._pan_x-=dx; self._pan_y-=dy; self._apply_view(); self._canvas.draw_idle()

    def _on_pan_end(self,event):
        if event.button==1 and self._drag_flow is not None:
            self._drag_flow=None  # release the dragged ribbon
        if event.button==1 and self._drag_node:
            self._drag_node=None  # release
        if event.button in (2,3): self._pan_dragging=False

    def _on_canvas_click(self,event):
        if self._closed: return
        try:
            if event.xdata is None or event.ydata is None: return
            cx,cy=event.xdata,event.ydata
            # Left-click: check if clicking a node (start drag)
            if event.button==1:
                best_node=None; best_nd=1e9
                for ip,nd in self._nodes.items():
                    nx,ny=nd['pos']
                    d=((cx-nx)**2+(cy-ny)**2)**0.5
                    if d<best_nd and d<0.05: best_nd=d; best_node=ip
                if best_node:
                    nx,ny=self._nodes[best_node]['pos']
                    import time as _t
                    now_t=_t.time()
                    is_dbl=(best_node==self._last_click_node and
                            now_t-self._last_click_time < 0.4)
                    self._last_click_node=best_node
                    self._last_click_time=now_t
                    if is_dbl:
                        self._drag_node=None  # cancel drag on double-click
                        self._show_node_popup(best_node)
                        return
                    self._drag_node=best_node
                    self._drag_offset=(cx-nx,cy-ny)
                    self._nodes[best_node]['pinned']=True
                    self._show_node_detail(best_node)
                    return
            # Left-click (no node hit) or other button: flow selection
            best_dist=0.04; best_flow=None
            for _seg in self._flow_seg_map:
                x0,y0,x1,y1,src,dst,proto = _seg[:7]
                _sbow  = _seg[7] if len(_seg) > 7 else 0.0
                _sbulge= _seg[8] if len(_seg) > 8 else 0.0
                if _sbow or _sbulge:
                    # Curved (sankey) ribbon — measure against the actual bezier
                    # so a dragged, bent flow is still grabbed where it's drawn.
                    _tt = np.linspace(0.0, 1.0, 13)
                    _px, _py = self._bezier_xy(x0, y0, x1, y1, _tt, _sbow, _sbulge)
                    dist = float(np.min(np.hypot(_px - cx, _py - cy)))
                else:
                    dx,dy=x1-x0,y1-y0; seg_len2=dx*dx+dy*dy
                    if seg_len2==0: dist=((cx-x0)**2+(cy-y0)**2)**0.5
                    else:
                        t=max(0.0,min(1.0,((cx-x0)*dx+(cy-y0)*dy)/seg_len2))
                        px,py=x0+t*dx,y0+t*dy; dist=((cx-px)**2+(cy-py)**2)**0.5
                if dist<best_dist: best_dist=dist; best_flow=(src,dst,proto)
            if best_flow:
                src,dst,proto=best_flow; self._show_flow_detail(src,dst,proto)
                iid=f'{src}|{dst}|{proto}'
                try:
                    if self._flow_tree.exists(iid): self._flow_tree.selection_set(iid); self._flow_tree.see(iid)
                except Exception: _exc('_on_canvas_click')
                # ── Sankey: grab this flow so it can be dragged to reposition.
                #    A left-drag slides the ribbon; a double-click on a flow
                #    snaps it back to its automatic slot position.
                if self._layout_mode=='sankey' and event.button==1:
                    import time as _t
                    now_t=_t.time()
                    is_dbl=(best_flow==self._last_click_flow and
                            now_t-self._last_click_ftime < 0.4)
                    self._last_click_flow=best_flow; self._last_click_ftime=now_t
                    if is_dbl:
                        self._flow_offsets.pop(best_flow, None)
                        self._drag_flow=None
                        self._canvas.draw_idle()
                    else:
                        self._drag_flow=best_flow
                        self._drag_flow_start=(cx,cy)
                        self._drag_flow_orig=self._flow_offsets.get(best_flow,(0.0,0.0))
                        self._drag_flow_moved=False
        except Exception: _exc('_on_canvas_click')

    def _show_flow_detail(self,src,dst,proto):
        try:
            fl=self._flows.get((src,dst,proto))
            txt=self._flow_detail; txt.config(state='normal'); txt.delete('1.0','end')
            txt.insert('end','  Flow Detail\n','hdr'); txt.insert('end','\u2500'*36+'\n','label')
            def row(label,value,vtag='val'):
                txt.insert('end',f'  {label:<16}','label'); txt.insert('end',f'{value}\n',vtag)
            row('Protocol',proto.upper(),f'p_{proto}'); txt.insert('end','\n')
            row('Source IP',src)
            src_name=self._dns_cache.get(src,'')
            if src_name and src_name!=src: row('  \u2192 hostname',src_name)
            row('Destination',dst)
            dst_name=self._dns_cache.get(dst,'')
            if dst_name and dst_name!=dst: row('  \u2192 hostname',dst_name)
            txt.insert('end','\n')
            if fl:
                b=fl['bytes']; pkts=fl['pkts']
                if b<1e3: b_str=f'{b:.0f} B'
                elif b<1e6: b_str=f'{b/1e3:.1f} KB'
                elif b<1e9: b_str=f'{b/1e6:.1f} MB'
                else: b_str=f'{b/1e9:.2f} GB'
                row('Packets',f'{pkts:,}'); row('Data (approx)',b_str)
                if pkts>0: row('Avg pkt size',f'{b/pkts:.0f} B')
            else: txt.insert('end','  (flow data expired)\n','label')
            txt.insert('end','\n'); txt.insert('end','\u2500'*36+'\n','label')
            txt.config(state='disabled')
            # Store context for AI
            nd_src=self._nodes.get(src,{}); nd_dst=self._nodes.get(dst,{})
            self._current_flow_ctx={
                'src':src,'dst':dst,'proto':proto,
                'src_name':self._dns_cache.get(src,src),
                'dst_name':self._dns_cache.get(dst,dst),
                'bytes':fl['bytes'] if fl else 0,
                'pkts':fl['pkts'] if fl else 0,
                'src_bytes':nd_src.get('bytes',0),
                'dst_bytes':nd_dst.get('bytes',0),
            }
            # Reset AI response
            try:
                self._flow_ai_resp.config(state='normal')
                self._flow_ai_resp.delete('1.0','end')
                self._flow_ai_resp.config(state='disabled')
            except Exception: _exc('row')
        except Exception:
            try: self._flow_detail.config(state='disabled')
            except Exception: _exc('row')

    def _show_node_detail(self, ip):
        """Populate the flow detail panel with all flows involving this node."""
        try:
            nd = self._nodes.get(ip, {})
            txt = self._flow_detail
            txt.config(state='normal'); txt.delete('1.0', 'end')

            def fmt_b(b):
                if b < 1e3:  return f'{b:.0f} B'
                if b < 1e6:  return f'{b/1e3:.1f} KB'
                if b < 1e9:  return f'{b/1e6:.1f} MB'
                return f'{b/1e9:.2f} GB'

            def row(label, value, vtag='val'):
                txt.insert('end', f'  {label:<18}', 'label')
                txt.insert('end', value + '\n', vtag)

            hostname = self._dns_cache.get(ip, '')
            fullname = self._dns_raw.get(ip, '')
            txt.insert('end', '  Node: ' + ip + '\n', 'hdr')
            txt.insert('end', '\u2500'*36 + '\n', 'label')
            if hostname and hostname != ip:
                row('Hostname', hostname)
            # The friendly label is for the graph; show the real record here.
            if fullname and fullname.lower() != hostname.lower():
                row('DNS record', fullname)
                row('Source', 'forward DNS' if self._dns_src.get(ip)=='dns' else 'reverse DNS (PTR)')
            row('Total bytes',   fmt_b(nd.get('bytes', 0)))
            row('Total packets', f'{nd.get("pkts", 0):,}')
            row('Protocol',      nd.get('proto', '?').upper())
            txt.insert('end', '\n')

            _flows_snap = dict(self._flows)  # snapshot to avoid race
            outbound = [(k, v) for k, v in _flows_snap.items() if k[0] == ip]
            inbound  = [(k, v) for k, v in _flows_snap.items() if k[1] == ip]

            def flow_section(title, flow_list):
                if not flow_list: return
                txt.insert('end', '  ' + title + '\n', 'hdr')
                txt.insert('end', '\u2500'*36 + '\n', 'label')
                for (fsrc, fdst, fproto), fl in sorted(
                        flow_list, key=lambda x: x[1].get('bytes', 0), reverse=True)[:15]:
                    peer = fdst if fsrc == ip else fsrc
                    peer_disp = self._dns_cache.get(peer, peer)
                    if peer_disp == peer or len(peer_disp) > 20: peer_disp = peer
                    b    = fl.get('bytes', 0)
                    pkts = fl.get('pkts',  0)
                    txt.insert('end', f'  {fproto.upper():<6}', f'p_{fproto}')
                    txt.insert('end', f'{peer_disp:<22}', 'val')
                    txt.insert('end', f'{fmt_b(b):>9}  {pkts:>6,} pkts\n', 'label')

            flow_section(f'\u2192 Outbound ({len(outbound)})', outbound)
            if outbound and inbound: txt.insert('end', '\n')
            flow_section(f'\u2190 Inbound  ({len(inbound)})', inbound)
            txt.insert('end', '\n')
            txt.insert('end', '\u2500'*36 + '\n', 'label')
            txt.config(state='disabled')

            # AI context
            all_flows = outbound + inbound
            total_b   = sum(v.get('bytes', 0) for _, v in all_flows)
            protos    = set(k[2] for k, _ in all_flows)
            peers     = set(k[1] if k[0]==ip else k[0] for k, _ in all_flows)
            self._current_flow_ctx = {
                'src': ip, 'dst': ', '.join(list(peers)[:5]),
                'src_name': hostname or ip,
                'dst_name': f'{len(peers)} peers',
                'proto': ', '.join(protos),
                'bytes': total_b, 'pkts': nd.get('pkts', 0),
                'src_bytes': nd.get('bytes', 0), 'dst_bytes': 0,
            }
            try:
                self._flow_ai_resp.config(state='normal')
                self._flow_ai_resp.delete('1.0', 'end')
                self._flow_ai_resp.config(state='disabled')
            except Exception: _exc('flow_section')
        except Exception:
            try: self._flow_detail.config(state='disabled')
            except Exception: _exc('flow_section')

    # EtherApe security analysis methods — paste into EtherApeWindow class

    # ── Shared analysis results window ───────────────────────────────────────────
    def _show_analysis_window(self, title, sections, accent='#ff6b6b'):
        """Display a scrollable analysis results window."""
        tk = self._tk; ttk = self._ttk
        win = tk.Toplevel(self.root)
        win.title(title)
        win.configure(bg=self._BG)
        win.geometry('860x620')
        win.minsize(640, 400)

        hdr = tk.Frame(win, bg='#120308', height=44)
        hdr.pack(fill='x'); hdr.pack_propagate(False)
        tk.Label(hdr, text=f'  {title}', bg='#120308', fg=accent,
                 font=(_NM_MONO, 11, 'bold')).pack(side='left', padx=14, pady=8)
        self._ids_running_var = getattr(self, '_ids_running_var', None)
        ts_var = tk.StringVar(value='')
        tk.Label(hdr, textvariable=ts_var, bg='#120308', fg='#4a6070',
                 font=(_NM_MONO, 8)).pack(side='right', padx=14)
        from datetime import datetime
        ts_var.set(datetime.now().strftime('Analysed: %H:%M:%S'))
        tk.Frame(win, bg=accent, height=2).pack(fill='x')

        # Toolbar
        tf = tk.Frame(win, bg='#0a1020', pady=4)
        tf.pack(fill='x')
        total_findings = sum(len(v) for _, v in sections)
        count_col = '#ff6b6b' if total_findings > 0 else '#38f0a8'
        label = f'  {total_findings} finding{"s" if total_findings != 1 else ""}  across {len(sections)} categor{"ies" if len(sections) != 1 else "y"}'
        tk.Label(tf, text=label, bg='#0a1020', fg=count_col,
                 font=(_NM_MONO, 9, 'bold')).pack(side='left', padx=10)
        tk.Button(tf, text='Export TXT', bg='#0d2235', fg='#38b8f0', relief='flat',
                  font=(_NM_MONO, 8), cursor='hand2', padx=8,
                  command=lambda: self._export_analysis(title, sections, win)
                  ).pack(side='right', padx=8)

        # Scrollable text
        fc = tk.Frame(win, bg=self._PANEL)
        fc.pack(fill='both', expand=True, padx=6, pady=6)
        txt = tk.Text(fc, bg='#04080e', fg=self._TEXT, font=(_NM_MONO, 9),
                      relief='flat', wrap='word', state='normal',
                      selectbackground='#0a3060', padx=12, pady=10)
        vsb = ttk.Scrollbar(fc, orient='vertical', command=txt.yview)
        txt.configure(yscrollcommand=vsb.set)
        vsb.pack(side='right', fill='y')
        txt.pack(fill='both', expand=True)

        txt.tag_configure('section', foreground=accent,
                          font=(_NM_MONO, 10, 'bold'))
        txt.tag_configure('ok',      foreground='#38f0a8',
                          font=(_NM_MONO, 9, 'bold'))
        txt.tag_configure('warn',    foreground='#ffd93d',
                          font=(_NM_MONO, 9, 'bold'))
        txt.tag_configure('crit',    foreground='#ff6b6b',
                          font=(_NM_MONO, 9, 'bold'))
        txt.tag_configure('ip',      foreground='#38b8f0')
        txt.tag_configure('label',   foreground='#6a9ab8')
        txt.tag_configure('dim',     foreground='#2a4a6a')

        for sec_title, findings in sections:
            txt.insert('end', f'\n  {sec_title}\n', 'section')
            txt.insert('end', '  ' + '─'*60 + '\n', 'dim')
            if not findings:
                txt.insert('end', '  ✓  No issues detected\n', 'ok')
            else:
                for sev, ip, msg in findings:
                    tag = 'crit' if sev == 'CRIT' else 'warn' if sev == 'WARN' else 'ok'
                    txt.insert('end', f'  [{sev}]  ', tag)
                    txt.insert('end', f'{ip:<20}  ', 'ip')
                    txt.insert('end', msg + '\n', 'label')
            txt.insert('end', '\n')

        txt.config(state='disabled')
        return win

    def _export_analysis(self, title, sections, parent):
        from tkinter import filedialog
        from datetime import datetime
        path = filedialog.asksaveasfilename(
            parent=parent, title='Export Analysis',
            defaultextension='.txt',
            initialfile=f'nm_analysis_{datetime.now().strftime("%Y%m%d_%H%M%S")}.txt',
            filetypes=[('Text', '*.txt'), ('All files', '*.*')])
        if not path: return
        lines = [f'{title}', f'Generated: {datetime.now()}', '='*70, '']
        for sec_title, findings in sections:
            lines.append(f'\n{sec_title}')
            lines.append('─'*60)
            if not findings:
                lines.append('  No issues detected')
            else:
                for sev, ip, msg in findings:
                    lines.append(f'  [{sev}]  {ip:<20}  {msg}')
            lines.append('')
        open(path, 'w').write('\n'.join(lines))

    # ── Behavioral Anomaly Detection ─────────────────────────────────────────────
    def _analyze_behavioral(self):
        """Detect per-host behavioral anomalies from current flow data."""
        import threading
        def _run():
            nodes = dict(self._nodes)
            flows = dict(self._flows)
            if not nodes:
                self.root.after(0, lambda: self._show_analysis_window(
                    '⚠ Behavioral Anomaly Detection',
                    [('Status', [('INFO', '—', 'No traffic data. Start a capture first.')])],
                    '#ffd93d'))
                return

            findings_fanout  = []
            findings_volume  = []
            findings_ratio   = []
            findings_proto   = []
            findings_scan    = []

            # Per-host metrics
            for ip, nd in nodes.items():
                out_flows = [(k, v) for k, v in flows.items() if k[0] == ip]
                in_flows  = [(k, v) for k, v in flows.items() if k[1] == ip]
                out_peers = set(k[1] for k, _ in out_flows)
                in_peers  = set(k[0] for k, _ in in_flows)
                out_bytes = sum(v.get('bytes', 0) for _, v in out_flows)
                in_bytes  = sum(v.get('bytes', 0) for _, v in in_flows)
                out_pkts  = sum(v.get('pkts',  0) for _, v in out_flows)
                in_pkts   = sum(v.get('pkts',  0) for _, v in in_flows)
                all_protos= set(k[2] for k, _ in out_flows + in_flows)
                total_b   = nd.get('bytes', 0)
                total_p   = nd.get('pkts', 0)
                avg_pkt   = (total_b / total_p) if total_p > 0 else 0
                name = self._dns_cache.get(ip, ip)

                # Fan-out: too many unique destinations
                if len(out_peers) >= 20:
                    sev = 'CRIT' if len(out_peers) >= 40 else 'WARN'
                    findings_fanout.append((sev, name,
                        f'{len(out_peers)} unique destinations — possible port scan / lateral movement'))
                elif len(out_peers) >= 10:
                    findings_fanout.append(('INFO', name,
                        f'{len(out_peers)} unique destinations — elevated fan-out'))

                # Volume spike
                if total_b > 100e6:
                    findings_volume.append(('CRIT', name,
                        f'{total_b/1e6:.1f} MB transferred — high volume'))
                elif total_b > 10e6:
                    findings_volume.append(('WARN', name,
                        f'{total_b/1e6:.1f} MB transferred'))

                # Inbound/outbound byte ratio
                if out_bytes > 0 and in_bytes > 0:
                    ratio = out_bytes / max(in_bytes, 1)
                    if ratio > 10:
                        findings_ratio.append(('WARN', name,
                            f'Outbound {out_bytes/1e3:.1f}KB vs inbound {in_bytes/1e3:.1f}KB '
                            f'(ratio {ratio:.1f}x) — possible data exfiltration'))
                    elif ratio < 0.05 and in_bytes > 1e6:
                        findings_ratio.append(('WARN', name,
                            f'High inbound {in_bytes/1e6:.1f}MB vs tiny outbound — possible C2 receiver'))

                # Tiny avg packet size (scan traffic)
                if total_p > 50 and avg_pkt < 80:
                    findings_scan.append(('WARN', name,
                        f'Avg packet {avg_pkt:.0f}B over {total_p:,} pkts — '
                        f'small packets consistent with scanning'))

                # Protocol diversity
                if len(all_protos) >= 6:
                    findings_proto.append(('WARN', name,
                        f'{len(all_protos)} protocols used: {", ".join(sorted(all_protos)).upper()}'))

            sections = [
                ('Fan-out / Scanning',          findings_fanout),
                ('High-Volume Transfers',        findings_volume),
                ('TX/RX Ratio Anomalies',        findings_ratio),
                ('Tiny Packet Patterns (Scans)', findings_scan),
                ('Protocol Diversity',           findings_proto),
            ]
            self.root.after(0, lambda: self._show_analysis_window(
                '⚠ Behavioral Anomaly Detection', sections, '#ffd93d'))

        threading.Thread(target=_run, daemon=True).start()

    # ── Traffic Anomaly Detection ─────────────────────────────────────────────────
    def _analyze_traffic(self):
        """Detect network-level traffic anomalies and threat indicators."""
        import threading, re as _re
        def _run():
            nodes = dict(self._nodes)
            flows = dict(self._flows)
            if not nodes:
                self.root.after(0, lambda: self._show_analysis_window(
                    '◎ Traffic Anomaly & Threat Visibility',
                    [('Status', [('INFO', '—', 'No traffic data. Start a capture first.')])],
                    '#a371f7'))
                return

            findings_ports   = []
            findings_dns     = []
            findings_bcast   = []
            findings_beacon  = []
            findings_vol     = []
            findings_internal = []

            # Known suspicious ports (in proto strings from tshark)
            SUSP_PORTS = {
                '4444': 'Metasploit default listener',
                '31337': 'Back Orifice / elite',
                '12345': 'NetBus trojan',
                '1234':  'Common backdoor',
                '6666':  'IRC / botnet',
                '6667':  'IRC / botnet',
                '6668':  'IRC / botnet',
                '6669':  'IRC / botnet',
                '1080':  'SOCKS proxy',
                '4899':  'Radmin remote admin',
                '5900':  'VNC (unencrypted)',
                '23':    'Telnet (cleartext)',
                '21':    'FTP (cleartext)',
                '69':    'TFTP',
                '161':   'SNMP (may expose device info)',
            }

            # Private IP ranges
            def _is_private(ip):
                return (ip.startswith('192.168.') or ip.startswith('10.') or
                        ip.startswith('172.') or ip.startswith('127.') or
                        ip.startswith('169.254.'))

            # Check flow protocols for suspicious port numbers
            for (src, dst, proto), fl in flows.items():
                for port, desc in SUSP_PORTS.items():
                    if port in proto:
                        sev = 'CRIT' if port in ('4444','31337','12345') else 'WARN'
                        name = self._dns_cache.get(src, src)
                        findings_ports.append((sev, name,
                            f'→ {dst}  port {port} ({desc})  '
                            f'{fl.get("bytes",0)/1e3:.1f}KB  {fl.get("pkts",0)} pkts'))

            # DNS anomalies — high DNS count from single host
            dns_by_host = {}
            for (src, dst, proto), fl in flows.items():
                if 'dns' in proto:
                    dns_by_host[src] = dns_by_host.get(src, 0) + fl.get('pkts', 0)
            for ip, count in dns_by_host.items():
                if count > 500:
                    name = self._dns_cache.get(ip, ip)
                    findings_dns.append(('CRIT', name,
                        f'{count:,} DNS packets — possible DNS tunneling or flood'))
                elif count > 100:
                    name = self._dns_cache.get(ip, ip)
                    findings_dns.append(('WARN', name,
                        f'{count:,} DNS packets — elevated DNS query rate'))

            # Broadcast / multicast storms
            bcast_hosts = {}
            for (src, dst, proto), fl in flows.items():
                if dst in ('255.255.255.255', 'ff:ff:ff:ff:ff:ff', '224.0.0.251',
                           '239.255.255.250') or dst.startswith('ff:'):
                    bcast_hosts[src] = bcast_hosts.get(src, 0) + fl.get('pkts', 0)
            for ip, count in bcast_hosts.items():
                if count > 200:
                    name = self._dns_cache.get(ip, ip)
                    findings_bcast.append(('WARN', name,
                        f'{count:,} broadcast/multicast packets'))

            # Beaconing — same src→dst pair with high packet count but low bytes (C2)
            for (src, dst, proto), fl in flows.items():
                pkts = fl.get('pkts', 0); byts = fl.get('bytes', 0)
                if pkts > 200 and byts > 0 and byts / pkts < 100:
                    if not _is_private(dst):
                        name = self._dns_cache.get(src, src)
                        dst_name = self._dns_cache.get(dst, dst)
                        findings_beacon.append(('WARN', name,
                            f'→ {dst_name}  {pkts:,} pkts  avg {byts/pkts:.0f}B/pkt  '
                            f'({proto.upper()}) — regular small packets, possible beacon'))

            # Large external transfers
            for (src, dst, proto), fl in flows.items():
                byts = fl.get('bytes', 0)
                if byts > 50e6 and not _is_private(dst):
                    name = self._dns_cache.get(src, src)
                    dst_name = self._dns_cache.get(dst, dst)
                    findings_vol.append(('CRIT', name,
                        f'→ {dst_name}  {byts/1e6:.1f}MB externally  ({proto.upper()})'))
                elif byts > 5e6 and not _is_private(dst):
                    name = self._dns_cache.get(src, src)
                    dst_name = self._dns_cache.get(dst, dst)
                    findings_vol.append(('WARN', name,
                        f'→ {dst_name}  {byts/1e6:.1f}MB external'))

            # Internal→internal large flows (lateral movement)
            for (src, dst, proto), fl in flows.items():
                byts = fl.get('bytes', 0)
                if byts > 20e6 and _is_private(src) and _is_private(dst):
                    name = self._dns_cache.get(src, src)
                    dst_name = self._dns_cache.get(dst, dst)
                    findings_internal.append(('WARN', name,
                        f'→ {dst_name}  {byts/1e6:.1f}MB internal  ({proto.upper()})'))

            sections = [
                ('Suspicious Ports / Services',       findings_ports),
                ('DNS Anomalies',                      findings_dns),
                ('Broadcast / Multicast Storm',        findings_bcast),
                ('Beaconing / C2 Indicators',          findings_beacon),
                ('Large External Transfers',           findings_vol),
                ('Large Internal Flows (Lateral Mvt)', findings_internal),
            ]
            self.root.after(0, lambda: self._show_analysis_window(
                '◎ Traffic Anomaly & Threat Visibility', sections, '#a371f7'))

        threading.Thread(target=_run, daemon=True).start()

    # ── Built-in IDS ──────────────────────────────────────────────────────────────
    def _run_ids(self):
        """IDS - runs rules, builds rich HTML dashboard, opens in browser."""
        import threading, json as _json, tempfile, webbrowser
        from datetime import datetime

        def _is_private(ip):
            return ip.startswith(('192.168.','10.','172.','127.','169.254.',
                                   '224.','239.','ff:','fe80','::1'))

        def _run():
            print('[IDS] Starting analysis...')
            try: self._pkt_var.set('IDS running...')
            except Exception: _exc('_run')
            _server_url = 'http://localhost:8765'
            nodes = dict(self._nodes)
            flows = dict(self._flows)
            now   = datetime.now()
            alerts = []
            print(f'[IDS] {len(nodes)} nodes, {len(flows)} flows')

            MALWARE_PORTS = {
                '4444':'Metasploit listener','31337':'BackOrifice',
                '12345':'NetBus','6667':'IRC botnet C2','6666':'IRC botnet',
                '1080':'SOCKS proxy','9001':'Tor relay','9030':'Tor directory',
                '4899':'Radmin','8080':'Alt-HTTP C2','8443':'Alt-HTTPS C2',
                '23':'Telnet','21':'FTP cleartext','69':'TFTP',
                '161':'SNMP','5900':'VNC unencrypted',
            }
            # BitTorrent / P2P ports — suppress false positives
            TORRENT_PORTS = {
                '6881','6882','6883','6884','6885','6886','6887','6888','6889',
                '6969','51413','51414','6771','4444',  # uTorrent/qBit DHT
            }
            TORRENT_PROTOS = ('bittorrent','bt-dht','bt-tracker','utp',
                              'bt','torrent')
            def _is_torrent(proto):
                return (any(p in proto.lower() for p in TORRENT_PROTOS) or
                        any(port in proto for port in TORRENT_PORTS))
            SMB_P = ('smb','msrpc','nbss','nbns','dcerpc','rdp','netbios')

            # Per-host stats
            hs_map = {}
            for ip in nodes:
                out_f = [(k,v) for k,v in flows.items() if k[0]==ip]
                in_f  = [(k,v) for k,v in flows.items() if k[1]==ip]
                hs_map[ip] = {
                    'out_peers': set(k[1] for k,_ in out_f),
                    'out_bytes': sum(v.get('bytes',0) for _,v in out_f),
                    'in_bytes':  sum(v.get('bytes',0) for _,v in in_f),
                    'dns_pkts':  sum(v.get('pkts',0) for (s,d,p),v in flows.items()
                                     if s==ip and 'dns' in p),
                    'arp_pkts':  sum(v.get('pkts',0) for (s,d,p),v in flows.items()
                                     if s==ip and 'arp' in p),
                    'smb_dsts':  set(k[1] for k,_ in out_f
                                     if any(p in k[2] for p in SMB_P)),
                    'ext_bytes': sum(v.get('bytes',0) for (s,d,p),v in flows.items()
                                     if s==ip and not _is_private(d)),
                    'protos':    set(k[2] for k,_ in out_f+in_f),
                }

            # Protocol counters
            proto_counts = {}
            tls_ver = {}
            for (s2,d2,pr2),fl2 in flows.items():
                p = pr2.split(':')[-1].upper() if pr2 else 'OTHER'
                proto_counts[p] = proto_counts.get(p,0) + fl2.get('pkts',0)
                if 'tls' in pr2 or 'ssl' in pr2:
                    k2 = ('TLS 1.3' if 'tls13' in pr2 else
                          'TLS 1.2' if 'tls12' in pr2 else
                          'TLS 1.1' if 'tls11' in pr2 else 'TLS other')
                    tls_ver[k2] = tls_ver.get(k2,0) + fl2.get('pkts',0)

            # Rules
            for ip, hs in hs_map.items():
                name = self._dns_cache.get(ip, ip)

                if len(hs['out_peers']) >= 15:
                    sev = 'critical' if len(hs['out_peers'])>=30 else 'high'
                    alerts.append({'sev':sev,'ip':ip,'name':name,'rule':'PORT_SCAN',
                        'category':'Scanning','proto':'TCP/UDP','dst':'multiple',
                        'detail':str(len(hs['out_peers']))+' unique dests — horizontal scan',
                        'count':len(hs['out_peers'])})

                if hs['arp_pkts'] > 50:
                    sev = 'critical' if hs['arp_pkts']>200 else 'high'
                    alerts.append({'sev':sev,'ip':ip,'name':name,'rule':'ARP_FLOOD',
                        'category':'ARP Anomaly','proto':'ARP','dst':'broadcast',
                        'detail':str(hs['arp_pkts'])+' ARP pkts — possible poisoning',
                        'count':hs['arp_pkts']})

                if hs['dns_pkts'] > 300:
                    sev = 'critical' if hs['dns_pkts']>800 else 'high'
                    alerts.append({'sev':sev,'ip':ip,'name':name,'rule':'DNS_FLOOD',
                        'category':'DNS Anomaly','proto':'DNS','dst':'resolver',
                        'detail':str(hs['dns_pkts'])+' DNS queries — flood / tunnel',
                        'count':hs['dns_pkts']})

                for (s2,d2,pr2),fl2 in flows.items():
                    if s2 != ip: continue
                    avg2 = fl2.get('bytes',0)/max(fl2.get('pkts',1),1)
                    if 'dns' in pr2 and avg2 > 350:
                        alerts.append({'sev':'critical','ip':ip,'name':name,
                            'rule':'DNS_TUNNEL','category':'DNS Tunneling',
                            'proto':'DNS','dst':d2,'count':fl2.get('pkts',0),
                            'detail':'Avg DNS pkt '+str(int(avg2))+'B (>350B) — DNS tunneling'})
                    if not _is_private(d2) and not _is_torrent(pr2):
                        for port,desc in MALWARE_PORTS.items():
                            if port in pr2:
                                alerts.append({'sev':'critical','ip':ip,'name':name,
                                    'rule':'MALWARE_C2','category':'Malware/C2',
                                    'proto':pr2.upper(),'dst':d2,
                                    'count':fl2.get('pkts',0),
                                    'detail':'port '+port+' ('+desc+') -> '+d2})
                    if not _is_private(d2) and not _is_torrent(pr2):
                        p2=fl2.get('pkts',0); b2=fl2.get('bytes',0)
                        if p2>150 and b2>0 and b2/p2<120:
                            alerts.append({'sev':'high','ip':ip,'name':name,
                                'rule':'BEACONING','category':'C2 Beaconing',
                                'proto':pr2.upper(),'dst':d2,'count':p2,
                                'detail':str(p2)+' pkts avg '+str(int(b2/p2))+'B/pkt to '+d2})
                    if 'icmp' in pr2 and fl2.get('pkts',0)>300:
                        alerts.append({'sev':'high','ip':ip,'name':name,
                            'rule':'ICMP_FLOOD','category':'DDoS/Flood',
                            'proto':'ICMP','dst':d2,'count':fl2['pkts'],
                            'detail':str(fl2['pkts'])+' ICMP pkts -> '+d2})
                    if ('telnet' in pr2 or ('ftp' in pr2 and 'ftps' not in pr2)):
                        lbl = 'Telnet' if 'telnet' in pr2 else 'FTP'
                        alerts.append({'sev':'medium','ip':ip,'name':name,
                            'rule':'CLEARTEXT','category':'Cleartext Protocol',
                            'proto':lbl,'dst':d2,'count':fl2.get('pkts',0),
                            'detail':lbl+' to '+d2+' — credentials in cleartext'})

                if len(hs['smb_dsts']) >= 4:
                    alerts.append({'sev':'critical','ip':ip,'name':name,
                        'rule':'SMB_LATERAL','category':'Lateral Movement',
                        'proto':'SMB/RDP','dst':'internal','count':len(hs['smb_dsts']),
                        'detail':'SMB/RDP to '+str(len(hs['smb_dsts']))+' internal hosts'})

                if hs['ext_bytes'] > 50e6:
                    sev = 'critical' if hs['ext_bytes']>200e6 else 'high'
                    alerts.append({'sev':sev,'ip':ip,'name':name,
                        'rule':'EXFILTRATION','category':'Data Exfiltration',
                        'proto':'TCP','dst':'external','count':int(hs['ext_bytes']//1024),
                        'detail':str(round(hs['ext_bytes']/1e6,1))+'MB sent externally'})

                if len(hs['protos']) >= 7:
                    alerts.append({'sev':'medium','ip':ip,'name':name,
                        'rule':'PROTO_DIVERSITY','category':'Protocol Anomaly',
                        'proto':'multiple','dst':'multiple','count':len(hs['protos']),
                        'detail':str(len(hs['protos']))+' protocols: '+', '.join(sorted(hs['protos'])).upper()})

            # Deduplicate exact-same rule+ip
            seen = set()
            dedup = []
            for a in alerts:
                key = (a['ip'], a['rule'], a.get('dst',''))
                if key not in seen: seen.add(key); dedup.append(a)
            alerts = dedup

            self._ids_suspicious = set(a['ip'] for a in alerts
                                        if a['sev'] in ('critical','high'))

            n_crit = sum(1 for a in alerts if a['sev']=='critical')
            n_high = sum(1 for a in alerts if a['sev']=='high')
            n_med  = sum(1 for a in alerts if a['sev']=='medium')
            status = 'THREATS DETECTED' if n_crit+n_high > 0 else 'CLEAN'
            sc = '#ff4444' if n_crit>0 else '#ff9f43' if n_high>0 else '#38f0a8'

            total_b = sum(nd.get('bytes',0) for nd in nodes.values())
            total_p = sum(nd.get('pkts',0)  for nd in nodes.values())
            bstr = ('%.1fMB'%(total_b/1e6)) if total_b>=1e6 else ('%.1fKB'%(total_b/1e3))

            # Build HTML
            sev_col = {'critical':'#ff4444','high':'#ff9f43','medium':'#ffd93d','low':'#38b8f0'}
            def badge(sev):
                c=sev_col.get(sev,'#c8dff0')
                return ('<span style="background:'+c+'22;color:'+c+';border:1px solid '+c+'55;'
                        'display:inline-block;padding:2px 8px;border-radius:4px;'
                        'font-size:10px;font-weight:bold">'+sev.upper()+'</span>')

            alert_rows = ''
            for a in sorted(alerts, key=lambda x:{'critical':0,'high':1,'medium':2}.get(x['sev'],3)):
                alert_rows += ('<tr>'
                    +'<td>'+badge(a['sev'])+'</td>'
                    +'<td class="mono" style="color:#38b8f0">'+a['name']+'</td>'
                    +'<td><span style="background:#0a1828;border:1px solid #1a3050;border-radius:3px;padding:1px 7px;font-size:10px;color:#6a9ab8">'+a['rule']+'</span></td>'
                    +'<td style="color:#a0b8cc">'+a['category']+'</td>'
                    +'<td style="color:#c8dff0;font-size:.8rem">'+a['detail']+'</td>'
                    +'<td class="mono" style="color:#6a9ab8;text-align:right">'+str(a['count'])+'</td>'
                    +'<td class="mono" style="color:#6a9ab8">'+a['proto']+'</td>'
                    +'</tr>')

            # Category summary
            by_cat = {}
            for a in alerts:
                by_cat.setdefault(a['category'],{'c':0,'h':0,'m':0,'t':0})
                by_cat[a['category']][a['sev'][0]] = by_cat[a['category']].get(a['sev'][0],0)+1
                by_cat[a['category']]['t'] += 1
            cat_rows = ''
            for cat,cnt in sorted(by_cat.items(),key=lambda x:-x[1]['t']):
                col2 = '#ff4444' if cnt.get('c') else '#ff9f43' if cnt.get('h') else '#ffd93d'
                cat_rows += ('<tr><td style="color:'+col2+'">'+cat+'</td>'
                             +'<td style="color:#ff4444;text-align:center">'+str(cnt.get('c',0) or '')+'</td>'
                             +'<td style="color:#ff9f43;text-align:center">'+str(cnt.get('h',0) or '')+'</td>'
                             +'<td style="color:#ffd93d;text-align:center">'+str(cnt.get('m',0) or '')+'</td>'
                             +'<td style="color:#6a9ab8;text-align:center">'+str(cnt['t'])+'</td></tr>')

            # Top talkers
            talker_rows = ''
            for ip2,nd2 in sorted(nodes.items(),key=lambda x:-x[1].get('bytes',0))[:15]:
                n2 = self._dns_cache.get(ip2,ip2)
                b2 = nd2.get('bytes',0); p2 = nd2.get('pkts',0)
                bstr2 = ('%.1fMB'%(b2/1e6)) if b2>=1e6 else ('%.1fKB'%(b2/1e3))
                susp = ip2 in self._ids_suspicious
                col2 = '#ff4444' if susp else '#38b8f0'
                flag = '  \u26a0' if susp else ''
                talker_rows += ('<tr><td style="color:'+col2+'" class="mono">'+n2+flag+'</td>'
                               +'<td style="text-align:right;color:#c8dff0">'+bstr2+'</td>'
                               +'<td style="text-align:right;color:#6a9ab8">'+str(p2)+'</td></tr>')

            flagged_html = ''
            for fip in self._ids_suspicious:
                fn = self._dns_cache.get(fip,fip)
                flagged_html += '<div style="padding:5px 0;border-bottom:1px solid #0d2030;color:#ff4444">'+fn+'</div>'
            flagged_html = flagged_html or '<div style="padding:12px;color:#2a4060">No hosts flagged</div>'

            # Chart data
            top_p = sorted(proto_counts.items(),key=lambda x:-x[1])[:8]
            pl = _json.dumps([p for p,_ in top_p])
            pd_ = _json.dumps([c for _,c in top_p])
            pc = _json.dumps(['#38b8f0','#a371f7','#ff9f43','#38f0a8','#ffd93d','#ff6b6b','#00d4aa','#c8dff0'])
            tl = _json.dumps(list(tls_ver.keys()) or ['No TLS data'])
            td_ = _json.dumps(list(tls_ver.values()) or [1])
            tc = _json.dumps(['#38f0a8','#38b8f0','#a371f7','#6a9ab8'])

            ts_str = now.strftime('%Y-%m-%d %H:%M:%S')
            no_data_row = '<tr><td colspan="7" style="text-align:center;color:#2a4060;padding:20px">No alerts detected - traffic looks clean</td></tr>'
            body_content = alert_rows if alert_rows else no_data_row

            css = ('*{box-sizing:border-box;margin:0;padding:0}'
                  'body{background:#050d1a;color:#c8dff0;font-family:Consolas,DejaVu Sans Mono,Liberation Mono,Menlo,Courier New,monospace;font-size:13px}'
                  '.topbar{background:#020810;padding:10px 20px;display:flex;align-items:center;gap:20px;border-bottom:2px solid '+sc+'}'
                  '.topbar h1{font-size:13px;letter-spacing:.12em;color:'+sc+'}'
                  '.status-pill{padding:3px 12px;border-radius:20px;font-size:10px;font-weight:bold;background:'+sc+'22;color:'+sc+';border:1px solid '+sc+'55}'
                  '.ts{color:#2a4060;font-size:11px;margin-left:auto}'
                  '.grid-4{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;padding:12px 16px}'
                  '.stat-card{background:#060f1c;border-radius:8px;border:1px solid #0d2030;padding:12px 16px}'
                  '.sv{font-size:26px;font-weight:bold;line-height:1}'
                  '.sl{font-size:9px;color:#6a9ab8;text-transform:uppercase;letter-spacing:.1em;margin-top:4px}'
                  '.charts-row{display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px;padding:0 16px 12px}'
                  '.chart-card{background:#060f1c;border-radius:8px;border:1px solid #0d2030;padding:12px}'
                  '.chart-card h3{font-size:9px;text-transform:uppercase;letter-spacing:.1em;color:#6a9ab8;margin-bottom:8px}'
                  '.chart-card canvas{max-height:150px}'
                  '.section{padding:0 16px 16px}'
                  '.shdr{display:flex;align-items:center;padding:8px 0 6px;border-bottom:1px solid #0d2030;margin-bottom:8px}'
                  '.shdr h2{font-size:10px;text-transform:uppercase;letter-spacing:.12em;color:#6a9ab8}'
                  'table{width:100%;border-collapse:collapse;font-size:12px}'
                  'th{color:#2a4a6a;font-weight:normal;text-align:left;padding:5px 10px;border-bottom:1px solid #0d2030;font-size:9px;text-transform:uppercase;letter-spacing:.08em}'
                  'td{padding:6px 10px;border-bottom:1px solid #080e20}'
                  'tr:hover td{background:#060f1c}'
                  '.mono{font-family:Consolas,DejaVu Sans Mono,Liberation Mono,Menlo,Courier New,monospace}')

            html = ('<!DOCTYPE html><html lang="en"><head>'
                    '<meta charset="UTF-8"><title>IDS Report</title>'
                    '<script src="https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.min.js"></script>'
                    '<style>'+css+'</style></head><body>'
                    '<div class="topbar">'
                    '<h1>◼ NETWORK INTRUSION DETECTION SYSTEM</h1>'
                    '<div class="status-pill">'+status+'</div>'
                    '<span style="color:#6a9ab8;font-size:11px">'+str(n_crit)+' critical &nbsp;|&nbsp; '+str(n_high)+' high &nbsp;|&nbsp; '+str(n_med)+' medium</span>'
                    '<span class="ts">'+ts_str+'</span></div>'
                    '<div class="grid-4">'
                    '<div class="stat-card"><div class="sv" style="color:'+sc+'">'+str(len(alerts))+'</div><div class="sl">Total Alerts</div></div>'
                    '<div class="stat-card"><div class="sv" style="color:#ff4444">'+str(n_crit)+'</div><div class="sl">Critical</div></div>'
                    '<div class="stat-card"><div class="sv" style="color:#ffd93d">'+str(n_high)+'</div><div class="sl">High</div></div>'
                    '<div class="stat-card"><div class="sv" style="color:#38b8f0">'+str(len(nodes))+'</div><div class="sl">Hosts</div></div>'
                    '<div class="stat-card"><div class="sv" style="color:#a371f7">'+str(len(flows))+'</div><div class="sl">Active Flows</div></div>'
                    '<div class="stat-card"><div class="sv" style="color:#38f0a8">'+str(total_p)+'</div><div class="sl">Total Packets</div></div>'
                    '<div class="stat-card"><div class="sv" style="color:#ff9f43">'+bstr+'</div><div class="sl">Total Volume</div></div>'
                    '<div class="stat-card"><div class="sv" style="color:#ff4444">'+str(len(self._ids_suspicious))+'</div><div class="sl">Flagged Hosts</div></div>'
                    '</div>'
                    '<div class="charts-row">'
                    '<div class="chart-card" style="grid-column:span 2">'
                    '<h3>Alert Categories</h3>'
                    +'<table><thead><tr><th>Category</th><th>Crit</th><th>High</th><th>Med</th><th>Total</th></tr></thead><tbody>'
                    +(cat_rows or '<tr><td colspan="5" style="text-align:center;color:#2a4060">No alerts</td></tr>')
                    +'</tbody></table></div>'
                    '<div class="chart-card"><h3>Protocol Distribution</h3><canvas id="pc"></canvas></div>'
                    '</div>'
                    '<div class="charts-row">'
                    '<div class="chart-card"><h3>TLS Versions</h3><canvas id="tc"></canvas></div>'
                    '<div class="chart-card"><h3>Top Talkers</h3><table><thead><tr><th>Host</th><th>Bytes</th><th>Pkts</th></tr></thead><tbody>'+talker_rows+'</tbody></table></div>'
                    '<div class="chart-card"><h3>Flagged Hosts ('+str(len(self._ids_suspicious))+')</h3>'+flagged_html+'</div>'
                    '</div>'
                    '<div class="section"><div class="shdr"><h2>Alert Details ('+str(len(alerts))+')</h2></div>'
                    '<table><thead><tr><th>Sev</th><th>Source</th><th>Rule</th><th>Category</th><th>Detail</th><th>Count</th><th>Proto</th></tr></thead><tbody>'
                    +body_content
                    +'</tbody></table></div>'
                    +'<div style="padding:12px 16px 16px">'
                    +'<div style="font-size:10px;text-transform:uppercase;letter-spacing:.12em;color:#6a9ab8;padding-bottom:8px;border-bottom:1px solid #0d2030;margin-bottom:12px">\u2726 AI Threat Advisor</div>'
                    +'<div style="margin-bottom:12px">'
                    +'<div style="display:flex;align-items:center;gap:10px;margin-bottom:8px">'
                    +'<button id="ai-btn" style="background:#0a1a2e;color:#c084fc;border:1px solid #a371f7;border-radius:6px;'
                    +'padding:8px 20px;font-family:Consolas,DejaVu Sans Mono,Liberation Mono,Menlo,Courier New,monospace;font-size:11px;cursor:pointer;font-weight:bold;flex-shrink:0">\u2726 Ask AI</button>'
                    +'<input id="ai-query" type="text" '
                    +'style="flex:1;background:#040c18;color:#e0c0ff;border:1px solid #2a1050;border-radius:6px;'
                    +'padding:7px 12px;font-family:Consolas,DejaVu Sans Mono,Liberation Mono,Menlo,Courier New,monospace;font-size:11px;outline:none" '
                    +'placeholder="Ask anything about this capture... or leave blank for full threat analysis">'
                    +'</div>'
                    +'<span id="ai-status" style="font-size:11px;color:#6a9ab8">Local AI via Ollama \u2014 server: '+_server_url+'</span>'
                    +'</div>'
                    +'<div id="ai-resp" style="display:none;background:#06020f;border:1px solid #2a1050;border-radius:8px;'
                    +'padding:16px;font-size:12px;line-height:1.8;color:#e0c0ff;white-space:pre-wrap;min-height:120px"></div>'
                    +'</div>'
                    +'<script>'
                    +'var _SRV="'+_server_url+'";'
                    +'var _SUM='+_json.dumps({
                        'total_alerts': len(alerts), 'critical': n_crit,
                        'high': n_high, 'medium': n_med,
                        'flagged_hosts': list(self._ids_suspicious),
                        'alerts': [{'rule':a['rule'],'sev':a['sev'],'host':a['name'],
                                    'detail':a['detail'],'proto':a['proto']} for a in alerts[:30]],
                        'hosts': len(nodes), 'flows': len(flows),
                        'top_protocols': [p for p,_ in sorted(
                            proto_counts.items(),key=lambda x:-x[1])[:8]],
                    })+';'
                    +'document.getElementById("ai-btn").addEventListener("click",function(){'
                    +'  var btn=this,resp=document.getElementById("ai-resp"),'
                    +'      stat=document.getElementById("ai-status");'
                    +'  btn.disabled=true;btn.textContent="Analysing...";'
                    +'  resp.style.display="block";resp.style.color="#7c5cbf";'
                    +'  resp.textContent="Sending IDS findings to AI...";'
                    +'  stat.textContent="Working...";'
                    +'  var q=document.getElementById("ai-query").value.trim();'
                    +'  var def_q="You are a network security expert. The user runs BitTorrent/P2P software regularly so torrent traffic is expected and has been filtered. Analyse these IDS findings: 1) Threat severity executive summary. 2) Each alert explained in plain English. 3) Most dangerous first. 4) Specific remediation steps. 5) Patterns suggesting coordinated attack.";'
                    +'  var _prompt=(q||def_q)+" | IDS findings (JSON): "+JSON.stringify(_SUM);'
                    +'  fetch(_SRV+"/api/ai_analyze",{method:"POST",'
                    +'    headers:{"Content-Type":"application/json"},'
                    +'    body:JSON.stringify({prompt:_prompt})})'
                    +'.then(function(r){if(!r.ok)throw new Error("HTTP "+r.status+" - is desktop app running?");return r.json();})'
                    +'.then(function(d){resp.textContent=d.text||(d.error?("AI unavailable: "+d.error):"No response");resp.style.color=d.text?"#e0c0ff":"#ff9f43";stat.textContent="Analysis complete";btn.disabled=false;btn.textContent="\u2726 Analyse Threats with AI";})'
                    +'.catch(function(e){resp.textContent="Error: "+e.message;resp.style.color="#ff6b6b";stat.textContent="Failed";btn.disabled=false;btn.textContent="\u2726 Analyse Threats with AI";})'
                    +'});'
                    +'const T="#6a9ab8";'
                    +'function mk(id,t,lbl,dat,col){var el=document.getElementById(id);if(!el)return;'
                    +'new Chart(el.getContext("2d"),{type:t,data:{labels:lbl,datasets:[{data:dat,backgroundColor:col,borderWidth:1,borderColor:"#060f1c"}]},'
                    +'options:{responsive:true,animation:false,plugins:{legend:{position:"right",labels:{color:T,font:{size:9},boxWidth:10}}},scales:{}}})'
                    +'}'
                    +'mk("pc","doughnut",'+pl+','+pd_+','+pc+');'
                    +'mk("tc","doughnut",'+tl+','+td_+','+tc+');'
                    +'</script></body></html>')

            import tempfile, webbrowser
            tmp = tempfile.NamedTemporaryFile(delete=False, suffix='.html',
                    prefix='nm_ids_', mode='w', encoding='utf-8')
            tmp.write(html); tmp.close()
            _nm_open_path('file:///'+tmp.name.replace('\\', '/'))
            print('[IDS] Report opened in browser:', tmp.name)
            try: self.root.after(0, lambda: self._pkt_var.set('IDS done'))
            except Exception: _exc('badge')

        def _safe_run():
            try:
                _run()
            except Exception as _e:
                import traceback as _tb
                _msg = _tb.format_exc()
                _emsg = str(_e)
                print('[IDS ERROR]', _msg)
                def _show_ids_err(m=_emsg, t=_msg):
                    import tkinter.messagebox as _tmb
                    _tmb.showerror('IDS Error', m+'\n\n'+t[-600:],
                                  parent=self.root)
                self.root.after(0, _show_ids_err)
        threading.Thread(target=_safe_run, daemon=True).start()

    def _show_node_popup(self, ip):
        """Double-click popup: geo location + firewall block/unblock."""
        import threading, sys, subprocess
        tk = self._tk; ttk = self._ttk

        def _is_private(addr):
            return addr.startswith(('192.168.','10.','172.','127.','169.254.',
                                    '::1','fe80','fc','fd','224.','239.'))

        # ── Window ─────────────────────────────────────────────────────────
        win = tk.Toplevel(self.root)
        win.title('Node: ' + ip)
        win.configure(bg='#050d1a')
        win.geometry('520x560')
        win.resizable(False, False)
        win.lift(); win.focus_force()

        ACC = '#38b8f0'; RED = '#ff4444'; GRN = '#38f0a8'
        BG = '#050d1a'; PNL = '#060f1c'; TICK = '#6a9ab8'; TEXT = '#c8dff0'

        # Header
        hdr = tk.Frame(win, bg='#020810', height=48)
        hdr.pack(fill='x'); hdr.pack_propagate(False)
        tk.Frame(win, bg=ACC, height=2).pack(fill='x')
        hostname = self._dns_cache.get(ip, '')
        title = hostname if hostname and hostname != ip else ip
        tk.Label(hdr, text='  ⊙  ' + title, bg='#020810', fg=ACC,
                 font=(_NM_MONO, 11, 'bold')).pack(side='left', padx=14, pady=12)
        if hostname and hostname != ip:
            tk.Label(hdr, text=ip, bg='#020810', fg=TICK,
                     font=(_NM_MONO, 9)).pack(side='left', pady=14)

        # ── Firewall section ───────────────────────────────────────────────
        fw_frame = tk.Frame(win, bg=PNL, padx=14, pady=12)
        fw_frame.pack(fill='x', padx=10, pady=(10, 0))
        tk.Label(fw_frame, text='FIREWALL', bg=PNL, fg=TICK,
                 font=(_NM_MONO, 8, 'bold')).pack(anchor='w', pady=(0, 8))

        # Validate IP before using in netsh command
        import re as _re
        if not _re.match(r'^[\d.:a-fA-F]+$', ip):
            return  # reject anything that isn't an IP address
        rule_name = f'NM_BLOCK_{ip.replace(".", "_").replace(":", "_")}'
        status_var = tk.StringVar(value='Checking...')
        blocked_var = [False]

        def _check_blocked():
            if not _nm_fw_backend():
                status_var.set('Firewall control unavailable'
                               + ('' if _NM_IS_WIN else ' — install nftables'))
                block_btn.config(state='disabled')
                return
            try:
                blocked = _nm_fw_rule_exists(rule_name)
                blocked_var[0] = blocked
                col = RED if blocked else GRN
                label = f'BLOCKED — rule "{rule_name}"' if blocked else 'NOT BLOCKED — traffic allowed'
                win.after(0, lambda: status_var.set(label))
                win.after(0, lambda: status_lbl.config(fg=col))
                win.after(0, lambda: block_btn.config(
                    text='⬛ Unblock' if blocked else '⛔ Block',
                    fg=GRN if blocked else RED,
                    highlightbackground=GRN if blocked else RED))
            except Exception as e:
                _m = str(e)
                win.after(0, lambda m=_m: status_var.set(f'Error: {m}'))

        def _toggle_firewall():
            if sys.platform != 'win32':
                return
            block_btn.config(state='disabled', text='Working...')
            def _do():
                try:
                    flags = _nm_flags()
                    if blocked_var[0]:
                        # Unblock
                        _nm_fw_delete_rule(rule_name)
                    else:
                        # Block inbound + outbound
                        _ok, _err = _nm_fw_add_block(rule_name, ip)
                        if not _ok:
                            _m = _err or 'the firewall refused the rule'
                            win.after(0, lambda mm=_m: self._show_error_dialog(
                                'Block failed',
                                'No firewall rule was created for %s.\n\n%s\n\n'
                                '%s' % (ip, mm,
                                        'Run the app as Administrator and try again.'
                                        if _NM_IS_WIN else
                                        'Firewall changes need root: run with sudo, '
                                        'and make sure nftables is installed.')))
                            win.after(0, lambda: block_btn.config(state='normal'))
                            return
                    # Update _blocked_ips directly — no need to wait for refresh
                    if blocked_var[0]:
                        self._blocked_ips.discard(ip)
                    else:
                        self._blocked_ips.add(ip)
                    win.after(0, lambda: block_btn.config(state='normal'))
                    win.after(0, _check_blocked)
                except Exception as e:
                    _m = str(e)
                    win.after(0, lambda m=_m: status_var.set(f'Error: {m}'))
                    win.after(0, lambda: block_btn.config(state='normal'))
            threading.Thread(target=_do, daemon=True).start()

        status_lbl = tk.Label(fw_frame, textvariable=status_var,
                               bg=PNL, fg=TICK, font=(_NM_MONO, 9))
        status_lbl.pack(anchor='w', pady=(0, 8))

        if _is_private(ip):
            status_var.set('Private/local IP — firewall blocking not recommended')
            block_btn = tk.Button(fw_frame, text='⛔ Block', state='disabled',
                                   bg='#0a1828', fg='#2a4060',
                                   relief='flat', font=(_NM_MONO, 9, 'bold'),
                                   padx=16, pady=6, bd=0,
                                   highlightthickness=1, highlightbackground='#1a3050')
        else:
            block_btn = tk.Button(fw_frame, text='⛔ Block', command=_toggle_firewall,
                                   bg='#0a1828', fg=RED,
                                   activebackground=RED, activeforeground='#000',
                                   relief='flat', font=(_NM_MONO, 9, 'bold'),
                                   cursor='hand2', padx=16, pady=6, bd=0,
                                   highlightthickness=1, highlightbackground=RED)
            threading.Thread(target=_check_blocked, daemon=True).start()

        block_btn.pack(anchor='w')
        tk.Label(fw_frame, text='Requires administrator privileges on Windows',
                 bg=PNL, fg='#1a3050', font=(_NM_MONO, 7)).pack(anchor='w', pady=(6, 0))

        # ── Geographic section ─────────────────────────────────────────────
        geo_frame = tk.Frame(win, bg=PNL, padx=14, pady=12)
        geo_frame.pack(fill='x', padx=10, pady=(8, 0))
        tk.Label(geo_frame, text='GEOGRAPHIC LOCATION', bg=PNL, fg=TICK,
                 font=(_NM_MONO, 8, 'bold')).pack(anchor='w', pady=(0, 8))

        if _is_private(ip):
            tk.Label(geo_frame, text='Private/local IP — no geolocation available',
                     bg=PNL, fg=TICK, font=(_NM_MONO, 9)).pack(anchor='w')
        else:
            geo_rows = {}
            for field in ('Country', 'Region', 'City', 'ISP', 'Org',
                          'Lat/Lon', 'Timezone', 'AS'):
                rf = tk.Frame(geo_frame, bg=PNL)
                rf.pack(fill='x', pady=1)
                tk.Label(rf, text=f'{field:<12}', bg=PNL, fg=TICK,
                         font=(_NM_MONO, 9), width=14, anchor='w').pack(side='left')
                v = tk.StringVar(value='…')
                tk.Label(rf, textvariable=v, bg=PNL, fg=TEXT,
                         font=(_NM_MONO, 9), anchor='w').pack(side='left')
                geo_rows[field] = v

            # Flag + map link row
            flag_var = tk.StringVar(value='')
            flag_lbl = tk.Label(geo_frame, textvariable=flag_var, bg=PNL,
                                 fg=ACC, font=(_NM_MONO, 10))
            flag_lbl.pack(anchor='w', pady=(6, 0))

            def _fetch_geo():
                try:
                    import urllib.request, json as _j
                    with urllib.request.urlopen(
                            f'http://ip-api.com/json/{ip}?fields=status,country,countryCode,'
                            f'regionName,city,isp,org,lat,lon,timezone,as,query',
                            timeout=8) as r:
                        d = _j.loads(r.read().decode())
                    if d.get('status') != 'success':
                        win.after(0, lambda: geo_rows['Country'].set('Lookup failed'))
                        return
                    updates = {
                        'Country':  d.get('country','—') + f' ({d.get("countryCode","?")})',
                        'Region':   d.get('regionName','—'),
                        'City':     d.get('city','—'),
                        'ISP':      d.get('isp','—'),
                        'Org':      d.get('org','—'),
                        'Lat/Lon':  f'{d.get("lat","?")}°, {d.get("lon","?")}°',
                        'Timezone': d.get('timezone','—'),
                        'AS':       d.get('as','—'),
                    }
                    cc = d.get('countryCode','')
                    # Unicode flag from country code
                    flag = ''.join(chr(0x1F1E6 + ord(c) - ord('A')) for c in cc.upper()) if len(cc)==2 else ''
                    for field, val in updates.items():
                        v2 = val
                        win.after(0, lambda f=field, v=v2: geo_rows[f].set(v))
                    map_url = f'https://www.openstreetmap.org/?mlat={d.get("lat")}&mlon={d.get("lon")}&zoom=10'
                    def _add_map_btn():
                        flag_lbl.config(text=f'{flag}  {d.get("city","")}, {d.get("country","")}')
                        tk.Button(geo_frame,
                                  text='  Open in Map  ',
                                  command=lambda u=map_url: __import__('webbrowser').open(u),
                                  bg='#062040', fg=ACC,
                                  activebackground=ACC, activeforeground='#000',
                                  relief='flat', font=(_NM_MONO, 8, 'bold'),
                                  cursor='hand2', padx=10, pady=4,
                                  highlightthickness=1, highlightbackground=ACC
                                  ).pack(anchor='w', pady=(4, 0))
                    win.after(0, _add_map_btn)
                except Exception as e:
                    _m = str(e)
                    win.after(0, lambda m=_m: geo_rows['Country'].set(f'Error: {m}'))

            threading.Thread(target=_fetch_geo, daemon=True).start()

        # ── Node stats ─────────────────────────────────────────────────────
        nd = self._nodes.get(ip, {})
        stats_frame = tk.Frame(win, bg=PNL, padx=14, pady=12)
        stats_frame.pack(fill='x', padx=10, pady=(8, 0))
        tk.Label(stats_frame, text='NODE STATS', bg=PNL, fg=TICK,
                 font=(_NM_MONO, 8, 'bold')).pack(anchor='w', pady=(0, 8))
        b = nd.get('bytes', 0)
        bstr = f'{b/1e6:.2f} MB' if b>=1e6 else f'{b/1e3:.1f} KB' if b>=1e3 else f'{b} B'
        out_flows = [(k,v) for k,v in self._flows.items() if k[0]==ip]
        in_flows  = [(k,v) for k,v in self._flows.items() if k[1]==ip]
        for label, val in [
            ('Total bytes',  bstr),
            ('Packets',      f'{nd.get("pkts",0):,}'),
            ('Protocol',     nd.get('proto','?').upper()),
            ('Outbound flows', str(len(out_flows))),
            ('Inbound flows',  str(len(in_flows))),
            ('IDS flagged',  'YES ⚠' if ip in getattr(self,'_ids_suspicious',set()) else 'No'),
        ]:
            rf2 = tk.Frame(stats_frame, bg=PNL); rf2.pack(fill='x', pady=1)
            tk.Label(rf2, text=f'{label:<18}', bg=PNL, fg=TICK,
                     font=(_NM_MONO, 9), width=20, anchor='w').pack(side='left')
            col3 = RED if label=='IDS flagged' and 'YES' in val else TEXT
            tk.Label(rf2, text=val, bg=PNL, fg=col3,
                     font=(_NM_MONO, 9, 'bold')).pack(side='left')

        # Close button
        tk.Button(win, text='  Close  ', command=win.destroy,
                  bg='#0a1828', fg=TICK, relief='flat',
                  font=(_NM_MONO, 9), cursor='hand2',
                  padx=12, pady=6).pack(pady=10)


    # ── Geo Map state ─────────────────────────────────────────────────────────────
    _geo_cache  = {}   # ip → {lat,lon,country,city,isp,flag}
    _geo_window = None

    def _open_geo_window(self):
        if (self._geo_window and
                hasattr(self._geo_window, 'root') and
                self._geo_window.root.winfo_exists()):
            self._geo_window.root.lift()
            self._geo_window.root.focus_force()
            return
        self._geo_window = _EtherApeGeoWindow(self)

    # ── LAN Scan state ────────────────────────────────────────────────────────────
    _scan_window = None

    def _open_lan_scan_window(self):
        if (self._scan_window and
                hasattr(self._scan_window, 'root') and
                self._scan_window.root.winfo_exists()):
            self._scan_window.root.lift()
            self._scan_window.root.focus_force()
            return
        self._scan_window = _EtherApeScanWindow(self)

    def _refresh_blocked_count(self):
        """Keep the toolbar counter in step with the real firewall."""
        try:
            n = len(self._blocked_ips)
            if hasattr(self, '_blocked_var'):
                self._blocked_var.set('\u26d4 %d blocked' % n if n else '')
        except Exception:
            _exc_debug('_refresh_blocked_count')

    def _open_honeypot_window(self):
        """Start/stop a low-interaction honeypot and watch who connects.

        Binds decoy ports on this machine only. Nothing spoofs or claims an
        address the host does not own, so it is safe on any network. A hit is
        always a scan or an attack - no real service lives on these ports.
        """
        tk = self._tk
        win = tk.Toplevel(self.root)
        win.title('Honeypot')
        win.configure(bg='#050d1a')
        win.geometry('760x560')

        hdr = tk.Frame(win, bg='#0a1828', height=42); hdr.pack(fill='x')
        hdr.pack_propagate(False)
        tk.Label(hdr, text='  \U0001f36f  HONEYPOT', bg='#0a1828', fg='#38f0a8',
                 font=(_NM_MONO, 11, 'bold')).pack(side='left', padx=8, pady=8)
        state = tk.StringVar(value='stopped')
        tk.Label(hdr, textvariable=state, bg='#0a1828', fg='#6a9ab8',
                 font=(_NM_MONO, 9)).pack(side='left', padx=8)
        tk.Frame(win, bg='#38f0a8', height=2).pack(fill='x')

        opts = tk.Frame(win, bg='#050d1a'); opts.pack(fill='x', padx=10, pady=8)
        autoblock = tk.BooleanVar(value=False)
        tk.Checkbutton(opts, text='Auto-block after 2 hits',
                       variable=autoblock, bg='#050d1a', fg='#ff9f43',
                       selectcolor='#0a1828', activebackground='#050d1a',
                       activeforeground='white', font=(_NM_MONO, 8),
                       bd=0, highlightthickness=0).pack(side='left')
        tarpit_var = tk.BooleanVar(value=_NM_HP_TARPIT['on'])

        def _toggle_tarpit():
            _NM_HP_TARPIT['on'] = bool(tarpit_var.get())
            hp = _nm_honeypot()
            if hp is not None:
                hp._tarpit_enabled = _NM_HP_TARPIT['on']
        tk.Checkbutton(opts, text='Tarpit (stall connections)',
                       variable=tarpit_var, command=_toggle_tarpit,
                       bg='#050d1a', fg='#38f0a8',
                       selectcolor='#0a1828', activebackground='#050d1a',
                       activeforeground='white', font=(_NM_MONO, 8),
                       bd=0, highlightthickness=0).pack(side='left', padx=(14, 0))
        # Show what is actually bound, both protocols, with the service names -
        # a truncated list of bare TCP numbers hid the UDP decoys entirely.
        _ports_lbl = tk.Label(opts, text='', bg='#050d1a', fg='#6a9ab8',
                              font=(_NM_MONO, 8), justify='left', anchor='w')
        _ports_lbl.pack(side='left', padx=12, fill='x', expand=True)

        def _fmt_ports():
            _t = ', '.join('%d %s' % (p, _NM_HONEYPOT_PORTS[p])
                           for p in sorted(_NM_HONEYPOT_PORTS))
            _u = ', '.join('%d %s' % (p, _NM_HONEYPOT_UDP_PORTS[p])
                           for p in sorted(_NM_HONEYPOT_UDP_PORTS))
            return ('TCP (%d): %s\nUDP (%d): %s'
                    % (len(_NM_HONEYPOT_PORTS), _t,
                       len(_NM_HONEYPOT_UDP_PORTS), _u))
        _ports_lbl.config(text=_fmt_ports())

        # Table on the left, threat radar on the right (toggleable).
        mid = tk.Frame(win, bg='#050d1a')
        mid.pack(fill='both', expand=True)

        cols = ('time', 'ip', 'kind', 'port', 'service', 'tool', 'hits', 'sample')
        tree = self._ttk.Treeview(mid, columns=cols, show='headings', height=17,
                                  style='EA.Treeview')
        for c, t, w in (('time', 'Time', 70), ('ip', 'Source', 120),
                        ('kind', 'Origin', 74),
                        ('port', 'Port', 62), ('service', 'Service', 86),
                        ('tool', 'Looks like', 150),
                        ('hits', 'Hits', 40), ('sample', 'First bytes', 190)):
            tree.heading(c, text=t); tree.column(c, width=w, anchor='w')
        tree.pack(side='left', fill='both', expand=True, padx=(10, 6), pady=(0, 6))

        radar = tk.Canvas(mid, bg='#040c18', width=360, highlightthickness=1,
                          highlightbackground='#12283e')
        # packed only when toggled on, so the table keeps the full width by default

        info = tk.Label(win, text='', bg='#050d1a', fg='#6a9ab8', anchor='w',
                        font=(_NM_MONO, 8))
        info.pack(fill='x', padx=10)

        # AI assessment pane (collapsed until used)
        ai_frame = tk.Frame(win, bg='#0a1828', highlightthickness=1,
                            highlightbackground='#1f4a6a')
        ai_head = tk.Frame(ai_frame, bg='#0a1828'); ai_head.pack(fill='x')
        tk.Label(ai_head, text='\u2726 AI ASSESSMENT', bg='#0a1828', fg='#b388ff',
                 font=(_NM_MONO, 8, 'bold')).pack(side='left', padx=8, pady=3)
        ai_txt = tk.Text(ai_frame, bg='#0a1828', fg='#c8dff0', font=(_NM_MONO, 8),
                         relief='flat', wrap='word', height=7, padx=8, pady=6,
                         highlightthickness=0)
        ai_txt.pack(fill='both', expand=True)
        ai_txt.configure(state='disabled')

        def show_ai(msg, colour='#c8dff0'):
            ai_frame.pack(fill='x', padx=10, pady=(6, 0))
            ai_txt.configure(state='normal', fg=colour)
            ai_txt.delete('1.0', 'end'); ai_txt.insert('1.0', msg)
            ai_txt.configure(state='disabled')

        def run_ai():
            hp = _nm_honeypot()
            if not (hp and hp.hits(1)):
                show_ai('No hits to analyse yet. Start the honeypot (and press '
                        'TEST, or wait for real probes) first.', '#ff9f43')
                return
            show_ai('Analysing %d hit(s)\u2026 this uses your configured AI '
                    'provider (local Ollama by default).' % hp.summary()['total'],
                    '#6a9ab8')
            # The worker thread must not touch Tk directly (after() from a
            # non-main thread is unreliable). It drops the result into a holder
            # that the periodic tick() renders on the GUI thread.
            self._hp_ai_pending = None
            def work():
                text, err = _nm_honeypot_analyse()
                self._hp_ai_pending = (text, err)
            import threading as _th
            _th.Thread(target=work, daemon=True).start()

        def on_hit(rec, count):
            if autoblock.get() and count >= 2:
                ok, err = _nm_firewall_block(rec['ip'])
                if ok:
                    log.info('[honeypot] auto-blocked %s after %d hits',
                             rec['ip'], count)
                    try:
                        self._blocked_ips.add(rec['ip'])
                        self._refresh_blocked_count()
                    except Exception:
                        pass

        def refresh():
            global _NM_HONEYPOT
            hp = _nm_honeypot()
            for i in tree.get_children():
                tree.delete(i)
            if hp is None:
                state.set('stopped'); info.config(text=''); return
            import time as _t
            counts = dict(hp._hit_counts)
            for h in reversed(hp.hits(200)):
                tree.insert('', 'end', values=(
                    _t.strftime('%H:%M:%S', _t.localtime(h['time'])),
                    h['ip'],
                    'known LAN' if h.get('known') else 'external',
                    '%s/%s' % (h['port'], h.get('proto', 'tcp')),
                    h['service'],
                    h.get('tool', ''),
                    counts.get(h['ip'], 1),
                    h['sample'][:40]))
            sm = hp.summary()
            import time as _t2
            _stuck = (' \u00b7 %d stuck now' % sm['tarpit_active']
                      if sm.get('tarpit_active') else '')
            if sm['total'] == 0 and sm.get('started'):
                _mins = int((_t2.time() - sm['started']) / 60)
                state.set('running \u00b7 %d ports bound \u00b7 no hits yet '
                          '(%dm) \u2014 quiet is normal on a clean network%s'
                          % (sm.get('bound', 0), _mins, _stuck))
            else:
                _ago = ''
                if sm.get('last_hit'):
                    _s = int(_t2.time() - sm['last_hit'])
                    _ago = ' \u00b7 last %s ago' % ('%ds' % _s if _s < 90
                            else '%dm' % (_s // 60))
                state.set('running \u00b7 %d hits from %d source(s)%s%s'
                          % (sm['total'], sm['unique_ips'], _ago, _stuck))

        def start():
            global _NM_HONEYPOT
            if _nm_honeypot() and _nm_honeypot()._running:
                return
            excl = set()
            _ea = _active_ea()          # never trap our own hosts
            try:
                if _ea is not None:
                    excl = {ip for ip in getattr(_ea, '_nodes', {})
                            if _nm_is_private_ip(ip)}
            except Exception:
                pass
            # EtherApeWindow has no _monitor; fall back through what exists.
            _db = getattr(self, '_db', None)
            if _db is None:
                _mon = getattr(self, '_monitor', None)
                _db = getattr(_mon, '_db', None) if _mon else None
            if _db is None:
                _db = _nm_store()
            _NM_HONEYPOT = _NMHoneypot(on_hit=on_hit, exclude_ips=excl, db=_db,
                                       tarpit=_NM_HP_TARPIT['on'])
            bound = _NM_HONEYPOT.start()
            if bound == 0:
                self._show_error_dialog(
                    'Honeypot could not start',
                    'No decoy ports could be bound. On Windows some ports may '
                    'be in use; on Linux ports below 1024 need root.\n\n'
                    'Run elevated, or the honeypot will use only the high ports '
                    'it can bind.')
            state.set('running')
            refresh()

        def stop():
            global _NM_HONEYPOT
            hp = _nm_honeypot()
            if hp:
                hp.stop()
            state.set('stopped')

        # ── Threat radar ────────────────────────────────────────────────
        # Only honeypot sources appear here: hosts that actually probed a
        # decoy port. Positions come from the geo cache, using the same
        # equirectangular projection the sonar radar uses.
        self._hp_radar_on = False
        self._hp_radar_blips = []

        def _geo_xy(lat, lon, cx, cy, R):
            x = cx + (lon / 180.0) * R
            y = cy - (lat / 90.0) * R
            dx, dy = x - cx, y - cy
            d = (dx * dx + dy * dy) ** 0.5
            lim = R * 0.94
            if d > lim:
                x = cx + dx / d * lim
                y = cy + dy / d * lim
            return x, y

        # Layered drawing: the map/rings never change, blips change on the data
        # timer, and only the sweep is redrawn per frame. Redrawing everything
        # (and re-running the threat feed) every frame made it crawl at ~8fps.
        self._hp_radar_geom = None
        self._hp_radar_mapimg = None

        def _radar_geom():
            W = radar.winfo_width()
            H = radar.winfo_height()
            if W < 60 or H < 60:
                return None
            return (W / 2.0, H / 2.0, max(40, min(W, H) * 0.44))

        def _radar_static(cx, cy, R):
            import math as _m
            c = radar
            c.delete('static')
            G = '#00cc44'
            # world map, masked to the scope circle so lat/lon blips land on it
            try:
                from PIL import Image as _PI, ImageDraw as _PD, ImageTk as _PT
                import base64 as _b64, io as _io
                side = int(R * 2)
                raw = _PI.open(_io.BytesIO(_b64.b64decode(_RADAR_MAP_B64)))
                raw = raw.convert('RGBA').resize((side, side), _PI.BILINEAR)
                mask = _PI.new('L', (side, side), 0)
                _PD.Draw(mask).ellipse([0, 0, side - 1, side - 1], fill=255)
                base = _PI.new('RGBA', (side, side), (4, 12, 24, 255))
                base.paste(raw, (0, 0), mask)
                self._hp_radar_mapimg = _PT.PhotoImage(base)
                c.create_image(cx, cy, image=self._hp_radar_mapimg, tags='static')
            except Exception:
                _exc_debug('radar map')
            for i in range(1, 5):
                r = R * i / 4.0
                c.create_oval(cx - r, cy - r, cx + r, cy + r,
                              outline='#0a5a28', tags='static')
            c.create_line(cx - R, cy, cx + R, cy, fill='#0a5a28', tags='static')
            c.create_line(cx, cy - R, cx, cy + R, fill='#0a5a28', tags='static')
            c.create_oval(cx - R - 4, cy - R - 4, cx + R + 4, cy + R + 4,
                          outline=G, tags='static')
            for deg in range(0, 360, 30):
                a = _m.radians(deg) - _m.pi / 2
                c.create_line(cx + _m.cos(a) * (R + 4), cy + _m.sin(a) * (R + 4),
                              cx + _m.cos(a) * (R + 12), cy + _m.sin(a) * (R + 12),
                              fill=G, tags='static')
            c.create_oval(cx - 4, cy - 4, cx + 4, cy + 4,
                          fill='#38b8f0', outline='', tags='static')
            c.create_oval(cx - 9, cy - 9, cx + 9, cy + 9,
                          outline='#1c5f80', tags='static')

        def _radar_blips(cx, cy, R):
            import math as _m
            c = radar
            c.delete('blip')
            self._hp_radar_blips = []
            feed = _nm_threat_feed(limit=80)
            nolocated = 0
            for t in feed.get('threats', []):
                lat, lon = t.get('lat'), t.get('lon')
                if isinstance(lat, (int, float)) and isinstance(lon, (int, float)):
                    bx, by = _geo_xy(lat, lon, cx, cy, R)
                else:
                    nolocated += 1
                    h = sum(ord(ch) for ch in t['ip'])
                    a = (h % 360) * _m.pi / 180.0
                    bx = cx + _m.cos(a) * R * 0.12
                    by = cy + _m.sin(a) * R * 0.12
                col = '#ff3020' if t['sev'] == 'critical' else '#ff9f43'
                sz = max(4, min(11, 3 + (t.get('count', 1) ** 0.5) * 2.2))
                c.create_oval(bx - sz - 3, by - sz - 3, bx + sz + 3, by + sz + 3,
                              outline=col, tags='blip')
                c.create_oval(bx - sz / 2, by - sz / 2, bx + sz / 2, by + sz / 2,
                              fill=col, outline='', tags='blip')
                self._hp_radar_blips.append((bx, by, sz + 4, t))
            c.create_text(8, 10, anchor='w', fill='#6a9ab8', font=(_NM_MONO, 8),
                          text='honeypot sources: %d' % feed.get('total', 0),
                          tags='blip')
            if nolocated:
                c.create_text(8, 24, anchor='w', fill='#6a9ab8', font=(_NM_MONO, 8),
                              text='%d awaiting geo' % nolocated, tags='blip')

        def _radar_sweep(cx, cy, R):
            import math as _m, time as _t3
            c = radar
            c.delete('sweep')
            ang = (_t3.time() * 0.9) % (2 * _m.pi)
            _bg = (4, 12, 24)
            for k in range(12, -1, -1):
                aa = ang - (k / 12.0) * _m.pi * 0.45
                f = 1.0 - k / 12.0
                shade = '#%02x%02x%02x' % (
                    int(_bg[0] * (1 - f)),
                    int(_bg[1] + (255 - _bg[1]) * f * 0.5),
                    int(_bg[2] + (80 - _bg[2]) * f * 0.5))
                c.create_line(cx, cy, cx + _m.cos(aa) * (R + 4),
                              cy + _m.sin(aa) * (R + 4), fill=shade, tags='sweep')
            c.create_line(cx, cy, cx + _m.cos(ang) * (R + 4),
                          cy + _m.sin(ang) * (R + 4),
                          fill='#00ff50', width=2, tags='sweep')
            c.tag_raise('blip')

        def draw_radar():
            """Frame tick: only the sweep is redrawn here (~30fps)."""
            if not win.winfo_exists() or not self._hp_radar_on:
                return
            g = _radar_geom()
            if g is None:
                win.after(80, draw_radar)
                return
            cx, cy, R = g
            if self._hp_radar_geom != g:
                self._hp_radar_geom = g
                _radar_static(cx, cy, R)
                _radar_blips(cx, cy, R)
            _radar_sweep(cx, cy, R)
            win.after(33, draw_radar)

        def refresh_radar_data():
            """Slow tick: re-run the threat feed and repaint blips only."""
            if not win.winfo_exists() or not self._hp_radar_on:
                return
            g = _radar_geom()
            if g is not None:
                _radar_blips(*g)
            win.after(2500, refresh_radar_data)

        def _radar_hover(ev):
            for bx, by, rr, t in self._hp_radar_blips:
                if abs(ev.x - bx) <= rr and abs(ev.y - by) <= rr:
                    loc = ', '.join(x for x in (t.get('city'), t.get('country')) if x)
                    state.set('%s  %s  \u00b7  %s' % (t['ip'], loc or '(locating\u2026)',
                                                     t.get('detail', '')))
                    return
        radar.bind('<Motion>', _radar_hover)

        def toggle_radar():
            self._hp_radar_on = not self._hp_radar_on
            if self._hp_radar_on:
                # Pack order decides who gets the space. The table is packed
                # with expand=True, so if it goes in first it claims the whole
                # cavity and the canvas ends up 1px wide and never mapped.
                # Re-pack so the radar reserves its width first.
                tree.pack_forget()
                radar.pack(side='right', fill='both', padx=(0, 10), pady=(0, 6))
                tree.pack(side='left', fill='both', expand=True,
                          padx=(10, 6), pady=(0, 6))
                # The table alone needs ~800px; widen the window so both fit.
                try:
                    _w = max(win.winfo_width(), 1)
                    if _w < 1180:
                        win.geometry('%dx%d' % (1180, max(560, win.winfo_height())))
                except Exception:
                    _exc_debug('radar resize')
                win.after(60, draw_radar)
                win.after(300, refresh_radar_data)
            else:
                radar.pack_forget()

        def run_test():
            """Fire real connections at the running honeypot from this machine.

            Uses the actual listeners and the actual record path - a genuine
            end-to-end check, not a fake injected row - so if the display,
            counts or auto-block are broken the test surfaces it.
            """
            import socket as _sk, threading as _th, time as _tm
            hp = _nm_honeypot()
            if not (hp and hp._running):
                self._show_error_dialog(
                    'Start the honeypot first',
                    'Press START, then TEST - the test connects to the real '
                    'decoy ports, so they have to be listening.')
                return
            # Find our own outbound IP; connecting from loopback is ignored by
            # the safety guard, so the test would (correctly) record nothing.
            try:
                _s = _sk.socket(_sk.AF_INET, _sk.SOCK_DGRAM)
                _s.connect(('8.8.8.8', 80)); myip = _s.getsockname()[0]; _s.close()
            except Exception:
                myip = ''
            if not myip or myip.startswith('127.'):
                self._show_error_dialog(
                    'No routable address',
                    'Could not find a non-loopback address to test from. The '
                    'honeypot ignores loopback by design, so a local-only '
                    'machine cannot self-test.')
                return
            ports = [p for p in sorted(_NM_HONEYPOT_PORTS) if p in
                     [s.getsockname()[1] for s in hp._servers]]
            probe = ports[:4] or sorted(_NM_HONEYPOT_PORTS)[:4]
            samples = [b'SSH-2.0-scanner\r\n', b'\x00\x00SMBprobe',
                       b'root:admin\n', b'GET / HTTP/1.0\r\n']

            # Our own address is in the exclude set (it is a live host), so the
            # honeypot would normally drop these self-test connections. Flag the
            # next few hits as forced so they are recorded.
            hp._force_next = True
            def fire():
                for i, port in enumerate(probe):
                    try:
                        c = _sk.socket(); c.settimeout(2)
                        c.bind((myip, 0)); c.connect((myip, port))
                        # send first - most decoy ports send no banner, so
                        # waiting to recv here would just stall until timeout
                        c.sendall(samples[i % len(samples)])
                        try: c.recv(64)
                        except Exception: pass
                        _tm.sleep(0.1); c.close()
                    except Exception:
                        pass
                    _tm.sleep(0.2)
                hp._force_next = False
                # Do NOT call Tk from this worker thread - after() from a
                # non-main thread raises RuntimeError. The periodic tick()
                # refreshes within 2.5s; nudge the state text (a StringVar,
                # which is thread-safe to set) so the user sees progress.
                try: state.set('test complete \u2014 refreshing\u2026')
                except Exception: pass
            _th.Thread(target=fire, daemon=True).start()
            state.set('test: probing %d port(s) from %s\u2026'
                      % (len(probe), myip))

        def block_sel():
            for i in tree.selection():
                v = tree.item(i, 'values')
                if v and v[1]:
                    ok, err = _nm_firewall_block(v[1])
                    if ok:
                        try:
                            self._blocked_ips.add(v[1]); self._refresh_blocked_count()
                        except Exception:
                            pass

        bar = tk.Frame(win, bg='#050d1a'); bar.pack(fill='x', padx=8, pady=8)
        for txt, cmd, col in (('\u25b6  START', start, '#38f0a8'),
                              ('\u25a0  STOP', stop, '#ff9f43'),
                              ('\U0001f9ea TEST', run_test, '#ff6bff'),
                              ('\u27f3  REFRESH', refresh, '#38b8f0'),
                              ('\u26d4  BLOCK SELECTED', block_sel, '#ff4444'),
                              ('\u25c9  RADAR', toggle_radar, '#38b8f0'),
                              ('\u2726  AI ANALYSIS', run_ai, '#b388ff'),
                              ('\u2715  CLOSE', win.destroy, '#6a9ab8')):
            tk.Button(bar, text=txt, command=cmd, bg='#0a1828', fg=col,
                      activebackground='#16324a', activeforeground='white',
                      relief='flat', font=(_NM_MONO, 8, 'bold'), cursor='hand2',
                      bd=0, highlightthickness=1, highlightbackground=col,
                      padx=9, pady=4).pack(side='left', padx=(0, 6))

        # live refresh while the window is open
        def tick():
            if not win.winfo_exists():
                return
            pend = getattr(self, '_hp_ai_pending', None)
            if pend is not None:
                self._hp_ai_pending = None
                _txt, _err = pend
                show_ai(_txt if _txt else (_err or 'AI analysis failed.'),
                        '#c8dff0' if _txt else '#ff9f43')
            refresh()
            win.after(2500, tick)
        win.after(2500, tick)
        refresh()

    def _open_firewall_window(self):
        """List the firewall rules this app has written.

        Reads the firewall itself rather than the in-memory set, so it shows
        what is actually in place - including nothing at all, if the rules
        failed to write because the app is not elevated.
        """
        tk = self._tk
        win = tk.Toplevel(self.root)
        win.title('Firewall rules')
        win.configure(bg='#050d1a')
        win.geometry('720x520')

        hdr = tk.Frame(win, bg='#0a1828', height=42); hdr.pack(fill='x')
        hdr.pack_propagate(False)
        tk.Label(hdr, text='  \u26d4  FIREWALL RULES', bg='#0a1828', fg='#ff9f43',
                 font=(_NM_MONO, 11, 'bold')).pack(side='left', padx=8, pady=8)
        sub = tk.StringVar(value='reading\u2026')
        tk.Label(hdr, textvariable=sub, bg='#0a1828', fg='#6a9ab8',
                 font=(_NM_MONO, 8)).pack(side='left', padx=8)
        tk.Frame(win, bg='#ff9f43', height=2).pack(fill='x')

        search_bar = tk.Frame(win, bg='#050d1a'); search_bar.pack(fill='x', padx=8, pady=(8, 0))
        tk.Label(search_bar, text='\U0001f50d', bg='#050d1a', fg='#6a9ab8',
                 font=(_NM_MONO, 9)).pack(side='left', padx=(0, 4))
        search_var = tk.StringVar(value='')
        search_entry = tk.Entry(search_bar, textvariable=search_var, bg='#0a1828',
                                 fg='#c8dff0', insertbackground='#c8dff0', relief='flat',
                                 font=(_NM_MONO, 9))
        search_entry.pack(side='left', fill='x', expand=True, ipady=3)
        match_var = tk.StringVar(value='')
        tk.Label(search_bar, textvariable=match_var, bg='#050d1a', fg='#6a9ab8',
                 font=(_NM_MONO, 8)).pack(side='left', padx=(6, 0))

        body = tk.Frame(win, bg='#050d1a'); body.pack(fill='both', expand=True)
        cols = ('ip', 'name', 'rule', 'state')
        tree = self._ttk.Treeview(body, columns=cols, show='headings', height=16,
                                  style='EA.Treeview') \
            if hasattr(self, '_ttk') else None
        if tree is None:
            from tkinter import ttk as _ttk2
            tree = _ttk2.Treeview(body, columns=cols, show='headings', height=16,
                                  style='EA.Treeview')
        for c, t, w in (('ip', 'Blocked address', 200), ('name', 'Name', 160),
                        ('rule', 'Rule name', 260), ('state', 'State', 100)):
            tree.heading(c, text=t); tree.column(c, width=w, anchor='w')
        sb = self._ttk.Scrollbar(body, orient='vertical', command=tree.yview)
        tree.configure(yscrollcommand=sb.set)
        sb.pack(side='right', fill='y'); tree.pack(fill='both', expand=True, padx=8, pady=8)

        info = tk.Label(win, text='', bg='#050d1a', fg='#6a9ab8', anchor='w',
                        justify='left', font=(_NM_MONO, 8), wraplength=690)
        info.pack(fill='x', padx=10, pady=(0, 6))

        # All rows fetched from the firewall live here; the search box only
        # ever re-renders from this list, it never re-queries the firewall
        # (netsh/nft calls are subprocess round-trips - too slow per keystroke).
        rows_cache = []

        def render(rows):
            for i in tree.get_children():
                tree.delete(i)
            for ip, name, rule, state in rows:
                tree.insert('', 'end', values=(ip, name or '\u2014', rule, state))

        def apply_filter(*_a):
            q = search_var.get().strip().lower()
            if not q:
                match_var.set('')
                render(rows_cache)
                return
            shown = [r for r in rows_cache
                     if q in r[0].lower() or q in (r[1] or '').lower()
                     or q in r[2].lower()]
            match_var.set('%d of %d shown' % (len(shown), len(rows_cache)))
            render(shown)

        search_var.trace_add('write', apply_filter)

        def load():
            try:
                backend = _nm_fw_backend()
                ips = _nm_list_blocked()
                rules = _nm_fw_list_rules('NM_')
                elevated = _nm_is_admin()
                ks = _nm_killswitch_active()
            except Exception as e:
                sub.set('error: %s' % e); return
            sub.set('%s  \u00b7  %d blocked  \u00b7  kill switch %s'
                    % (backend or 'no backend', len(ips), 'ON' if ks else 'off'))
            # Best-effort names: user label, LAN vendor, or a cached PTR lookup.
            # A PTR that hasn't resolved yet just shows blank for now \u2014 it's
            # cached in the background and appears next time this refreshes.
            try:
                _db = None
                if _monitor_instances:
                    _db = getattr(_monitor_instances[-1], '_db', None)
                names = _nm_fw_names(ips, db=_db)
            except Exception:
                _exc_debug('_open_firewall_window.names'); names = {}
            rows_cache.clear()
            for ip in ips:
                rows_cache.append((ip, names.get(ip, ''),
                                   'NM_BLOCK_%s' % ip.replace('.', '_'), 'blocked'))
            for r in rules:
                if not r.startswith('NM_BLOCK_'):
                    rows_cache.append(('\u2014', '', r, 'active'))
            apply_filter()
            msgs = []
            if not backend:
                msgs.append('No firewall backend available.'
                            if _NM_IS_WIN else
                            'nftables is not installed - sudo apt install nftables')
            elif not elevated:
                msgs.append('NOT RUNNING ELEVATED - new blocks will fail. '
                            + ('Restart as Administrator.' if _NM_IS_WIN
                               else 'Restart with sudo.'))
            if not ips and not rules:
                msgs.append('This app has not written any firewall rules.')
            info.config(text='\n'.join(msgs), fg='#ff9f43' if msgs else '#6a9ab8')
            # keep the toolbar counter honest with what the firewall reports
            try:
                self._blocked_ips = set(ips)
                self._refresh_blocked_count()
            except Exception:
                _exc_debug('_open_firewall_window')

        def unblock():
            sel = tree.selection()
            if not sel:
                return
            for i in sel:
                vals = tree.item(i, 'values')
                if vals and vals[0] and vals[0] != '\u2014':
                    _nm_firewall_unblock(vals[0])
            load()

        bar = tk.Frame(win, bg='#050d1a'); bar.pack(fill='x', padx=8, pady=(0, 10))
        for txt, cmd, col in (('\u27f3  REFRESH', load, '#38b8f0'),
                              ('\u2717  UNBLOCK SELECTED', unblock, '#ff4444'),
                              ('\u2715  CLOSE', win.destroy, '#6a9ab8')):
            tk.Button(bar, text=txt, command=cmd, bg='#0a1828', fg=col,
                      activebackground='#16324a', activeforeground='white',
                      relief='flat', font=(_NM_MONO, 8, 'bold'), cursor='hand2',
                      bd=0, highlightthickness=1, highlightbackground=col,
                      padx=10, pady=4).pack(side='left', padx=(0, 6))
        load()

    def _open_3d_view(self):
        port = 8765
        try:
            port = int(getattr(self, '_monitor', None)
                       and self._monitor.config.get('web_port', 8765) or 8765)
        except Exception:
            _exc_debug('_open_3d_view')
        url = 'http://localhost:%d/3d' % port
        # Check the server is actually up before blaming the browser, and never
        # fail silently - a button that does nothing is the worst outcome.
        import socket as _sk
        try:
            _s = _sk.create_connection(('127.0.0.1', port), timeout=1.5)
            _s.close()
        except Exception:
            self._show_error_dialog(
                '3D view unavailable',
                'Nothing is listening on port %d.\n\n'
                'The built-in web server starts with the main window - make sure '
                'the app is fully started, or check the web port in Settings.' % port)
