    def _geo_fetch_new(self):
        # Guard against concurrent calls
        if getattr(self, '_geo_fetching', False): return
        import time as _time
        # Minimum 10s between any fetch — prevents thread explosion from rapid callers
        _last_fetch = getattr(self, '_geo_fetch_last_time', 0)
        if _time.time() - _last_fetch < 30:  # geo data doesn't change faster than 30s
            return
        # Backoff: if last fetch failed (timeout), wait 60s before retrying
        _last_fail = getattr(self, '_geo_fetch_last_fail', 0)
        if _last_fail and (_time.time() - _last_fail) < 60:
            return
        import re as _re
        _ipv4 = _re.compile(r'^(\d{1,3}\.){3}\d{1,3}$')
        def _is_private(ip):
            return ip.startswith(('192.168.','10.','172.','127.','169.254.',
                                  '::1','fe80','fc00','fd','224.','239.'))
        # Accumulate all IPs ever seen — nodes decay quickly so we must remember them
        if not hasattr(self, '_seen_ips'): self._seen_ips = set()
        self._seen_ips.update(self._nodes.keys())
        # Cap to prevent unbounded growth
        if len(self._seen_ips) > 5000:
            self._seen_ips = set(list(self._seen_ips)[-3000:])
        needed = [ip for ip in self._seen_ips
                  if ip not in self._geo_cache
                  and not _is_private(ip)
                  and _ipv4.match(ip)]
        if not needed:
            return
        self._geo_fetching = True
        self._geo_fetch_last_time = _time.time()
        log.debug(f"geo_fetch_new: fetching {len(needed)} IPs")
        import threading
        def _fetch():
            import urllib.request, json as _j
            for i in range(0, len(needed), 100):
                chunk = needed[i:i+100]
                payload = _j.dumps([{'query': ip} for ip in chunk]).encode()
                try:
                    req = urllib.request.Request(
                        'http://ip-api.com/batch?fields=query,status,lat,lon,'
                        'country,countryCode,city,isp,org,as',
                        data=payload, headers={'Content-Type':'application/json'}, method='POST')
                    with urllib.request.urlopen(req, timeout=8) as r:
                        results = _j.loads(r.read().decode())
                    for res in results:
                        ip2 = res.get('query','')
                        if res.get('status') == 'success' and ip2:
                            cc = res.get('countryCode','')
                            flag = ''.join(chr(0x1F1E6+ord(c)-ord('A')) for c in cc.upper()) if len(cc)==2 else ''
                            self._geo_cache[ip2] = {
                                'lat': float(res.get('lat',0)),
                                'lon': float(res.get('lon',0)),
                                'country':     res.get('country',''),
                                'countryCode': cc,
                                'city':        res.get('city',''),
                                'isp':         res.get('isp',''),
                                'flag':        flag,
                                'org':         res.get('org',''),
                            }
                    self._geo_fetch_last_fail = 0
                except Exception:
                    self._geo_fetch_last_fail = _time.time()
                    _exc('_geo_fetch')
        def _fetch_and_clear():
            try: _fetch()
            finally: self._geo_fetching = False
        threading.Thread(target=_fetch_and_clear, daemon=True).start()


