    def _ai_watch_loop(self):
        import time
        while self._ai_watch_active and not self._closed:
            try:
                self._run_ai_flow_analysis()
            except Exception:
                _exc('_ai_watch_loop')
            for _ in range(300):
                if not self._ai_watch_active or self._closed:
                    return
                time.sleep(0.1)

    def _ml_anomaly_scan(self, flows, geo, _priv):
        """Unsupervised outlier detection over the current flow snapshot with
        scikit-learn's IsolationForest — fully local, no key, no cloud. Returns
        hit dicts shaped like the rule engine's. If scikit-learn/numpy aren't
        installed, or there are too few flows for a stable fit, returns []."""
        try:
            import numpy as _np
            from sklearn.ensemble import IsolationForest
        except Exception:
            return []      # optional dependency absent -> silently skip
        items, feats = [], []
        for (s, d, p), fl in flows.items():
            b = float(fl.get('bytes', 0.0)); pk = float(fl.get('pkts', 0.0))
            if b < 200:
                continue
            ext = d if _priv(s) else s
            port = 0
            if ':' in p:
                try: port = int(p.split(':')[1])
                except Exception: port = 0
            up = 1.0 if not _priv(d) else 0.0
            feats.append([_np.log1p(b), _np.log1p(pk),
                          b / (pk + 1.0), float(port), up])
            items.append((s, d, p, ext))
        if len(feats) < 8:
            return []      # too few points to trust the model
        try:
            X = _np.asarray(feats, dtype=float)
            model = IsolationForest(n_estimators=100, contamination=0.1,
                                    random_state=0)
            pred = model.fit_predict(X)
        except Exception:
            return []
        hits = []
        for (s, d, p, ext), flag in zip(items, pred):
            if flag == -1:
                g = geo.get(ext, {})
                hits.append({'src': s, 'dst': d, 'proto': p,
                             'reason': 'ML anomaly (unusual traffic profile)',
                             'country': g.get('country', ''),
                             'city': g.get('city', ''),
                             'flag': g.get('flag', '')})
        return hits

    def _beacon_scan(self, flows, geo, _priv):
        """Flag external destinations contacted at suspiciously regular
        intervals — a hallmark of C2 beaconing. Keeps a short rolling history of
        observation timestamps per (src,dst) across watch-loop passes and looks
        for low-variance inter-arrival times. Local, keyless, deterministic.

        NOTE: sampling is bounded by the watch-loop cadence, so this only catches
        beacons whose period is comfortably longer than the scan interval, and
        steady legitimate traffic (NTP, telemetry, keep-alives) can look periodic
        — treat hits as leads to investigate, not verdicts.
        """
        import time as _t
        now = _t.time()
        hist = getattr(self, '_beacon_hist', None)
        if hist is None:
            hist = {}; self._beacon_hist = hist
        for (s, d, p), fl in flows.items():
            if _priv(d):
                continue
            if float(fl.get('bytes', 0.0)) < 200:
                continue
            if float(fl.get('age', 0.0)) <= 5.0:        # flow is currently live
                lst = hist.setdefault((s, d), [])
                if not lst or (now - lst[-1]) >= 5.0:   # de-dupe rapid repeats
                    lst.append(now)
                    if len(lst) > 12:
                        del lst[:-12]
        for key in list(hist.keys()):                   # forget stale pairs
            if hist[key] and (now - hist[key][-1]) > 3600:
                del hist[key]
        hits = []
        for (s, d), ts in hist.items():
            if len(ts) < 5:
                continue
            intervals = [ts[i + 1] - ts[i] for i in range(len(ts) - 1)]
            mean = sum(intervals) / len(intervals) if intervals else 0.0
            if mean < 20:               # too fast to separate from steady traffic
                continue
            var = sum((x - mean) ** 2 for x in intervals) / len(intervals)
            cv = (var ** 0.5) / mean if mean else 1.0
            if cv < 0.25:               # very regular cadence -> beacon-like
                g = geo.get(d, {})
                hits.append({'src': s, 'dst': d, 'proto': '',
                             'reason': 'periodic contact ~%ds (possible beacon)' % int(mean),
                             'country': g.get('country', ''),
                             'city': g.get('city', ''),
                             'flag': g.get('flag', '')})
        return hits

    def _run_ai_flow_analysis(self):
        if not self._ai_watch_lock.acquire(blocking=False):
            return
        try:
            import json as _j, re as _re

            flows = dict(self._flows)
            nodes = dict(self._nodes)
            geo   = dict(getattr(self, '_geo_cache', {}))

            # Skip analysis if there's nothing meaningful to analyse
            if not flows:
                return

            def _priv(ip):
                return ip.startswith(('192.168.','10.','172.','127.','169.254.'))

            # ── Rule-based pre-screening ────────────────────────────────
            SUSP_PORTS = {
                4444,6667,1337,31337,9001,9030,5555,8443,3128,1080,
                23,2323,4899,5900,5901,6881,20034,65535,54321,
            }
            RISK_COUNTRIES = {
                'Russia','North Korea','Iran','China',
            }

            rule_hits = []
            for (src2, dst2, proto2), fl in flows.items():
                if fl['bytes'] < 500:
                    continue
                port = None
                if ':' in proto2:
                    try: port = int(proto2.split(':')[1])
                    except Exception: _exc('_priv')
                reasons = []
                if port and port in SUSP_PORTS:
                    reasons.append('port %d' % port)
                ext_ip  = dst2 if _priv(src2) else src2
                g       = geo.get(ext_ip, {})
                country = g.get('country', '')
                if country in RISK_COUNTRIES:
                    reasons.append('from ' + country)
                if not _priv(dst2) and fl['bytes'] > 5_000_000:
                    reasons.append('upload %dKB' % (fl['bytes']//1024))
                if reasons:
                    rule_hits.append({
                        'src': src2, 'dst': dst2, 'proto': proto2,
                        'reason': ', '.join(reasons),
                        'country': country,
                        'city':    g.get('city', ''),
                        'flag':    g.get('flag', ''),
                    })

            # ── Strengthen the keyless scan with local anomaly detection ──
            try:
                _seen_hits = {(h['src'], h['dst'], h.get('proto', ''))
                              for h in rule_hits}
                for _extra in (self._ml_anomaly_scan(flows, geo, _priv),
                               self._beacon_scan(flows, geo, _priv)):
                    for _h in _extra:
                        _k = (_h['src'], _h['dst'], _h.get('proto', ''))
                        if _k not in _seen_hits:
                            _seen_hits.add(_k); rule_hits.append(_h)
            except Exception:
                _exc('_local_anomaly')

            # ── AI confirmation (provider-agnostic; keyless by default) ──
            _rule_fallback = [{'src':h['src'],'dst':h['dst'],'proto':h['proto'],
                               'severity':'medium','reason':h['reason'],
                               'country':h['country']} for h in rule_hits]
            ai_hits = []
            if flows:
                lines_ctx = []
                for (s2, d2, p2), fl in list(flows.items())[:40]:
                    ext2 = d2 if _priv(s2) else s2
                    g2   = geo.get(ext2, {})
                    lines_ctx.append(
                        '%s->%s proto=%s bytes=%d pkts=%d '
                        'country=%s city=%s' % (
                            s2, d2, p2, fl['bytes'], fl['pkts'],
                            g2.get('country','?'), g2.get('city','?')))
                ctx_txt = ('Network flows (%d active):\n' % len(flows)) + '\n'.join(lines_ctx)
                if rule_hits:
                    ctx_txt += '\n\nRule flags:\n' + '\n'.join(
                        '  %s->%s: %s' % (h['src'],h['dst'],h['reason'])
                        for h in rule_hits)
                prompt = (
                    'You are a network security analyst. '
                    'Analyse these live flows for C2 beaconing, data exfiltration, '
                    'port scanning, unusual protocols, Tor/proxy usage, or lateral movement.\n\n'
                    + ctx_txt +
                    '\n\nReply ONLY as JSON: {"threats":[{"src":"ip","dst":"ip",'
                    '"proto":"p","severity":"high|medium","reason":"brief","country":"c"}],'
                    '"clean":true}. Only list genuine threats.'
                )
                text = self._ai_complete(prompt, want_json=True, timeout=25)
                if text:
                    try:
                        try:
                            data = _j.loads(text)            # Ollama format=json: clean
                        except Exception:
                            m = _re.search(r'\{.*\}', text, _re.DOTALL)
                            data = _j.loads(m.group()) if m else {}
                        for t in data.get('threats', []):
                            if t.get('severity') in ('high', 'medium'):
                                ai_hits.append(t)
                    except Exception:
                        ai_hits = list(_rule_fallback)
                else:
                    ai_hits = list(_rule_fallback)   # engine offline -> rules
            else:
                ai_hits = list(_rule_fallback)

            # ── Apply results ───────────────────────────────────────────
            new_flows  = set()
            new_alerts = []
            for t in ai_hits:
                new_flows.add((t['src'], t['dst'], t.get('proto','')))
                self._ids_suspicious.add(t['src'])
                ext3    = t['dst'] if not _priv(t['dst']) else t['src']
                g3      = geo.get(ext3, {})
                flag3   = g3.get('flag', '')
                country3= t.get('country', '') or g3.get('country','')
                new_alerts.append(
                    '%s %s -> %s  [%s]  %s  %s' % (
                        flag3, t['src'], t['dst'],
                        t.get('severity','?').upper(),
                        t.get('reason',''),
                        ('(' + country3 + ')') if country3 else ''))

            def _upd():
                self._suspicious_flows = new_flows
                self._ai_watch_results = new_alerts
                if hasattr(self, '_alert_var'):
                    if new_alerts:
                        msg = '⚠  ' + '   |   '.join(new_alerts[:4])
                        if len(new_alerts) > 4:
                            msg += '   (+%d more)' % (len(new_alerts)-4)
                    else:
                        msg = '✓  No threats detected — next check in 30s'
                    self._alert_var.set(msg)
            try:
                self.root.after(0, _upd)
            except Exception:
                _exc('_upd')
        finally:
            self._ai_watch_lock.release()

    def _flow_ctx_menu(self, event):
        import tkinter as tk, re as _re
        try:
            iid = self._flow_tree.identify_row(event.y)
            if not iid:
                return
            self._flow_tree.selection_set(iid)
            vals = self._flow_tree.item(iid, 'values')
        except Exception:
            return
        if not vals:
            return
        cand = []
        for x in ((vals[0] if len(vals) > 0 else ''), (vals[1] if len(vals) > 1 else '')):
            x = (x or '').strip()
            if _re.match(r'^\d{1,3}(\.\d{1,3}){3}$', x) and x not in cand:
                cand.append(x)
        if not cand:
            return
        m = tk.Menu(self._flow_tree, tearoff=0)
        for ip in cand:
            m.add_command(label='WHOIS  ' + ip, command=lambda i=ip: self._show_whois_dialog(i))
        m.add_separator()
        for ip in cand:
            if ip in self._blocked_ips:
                m.add_command(label='Unblock  ' + ip, command=lambda i=ip: self._host_block_toggle(i, False))
            else:
                m.add_command(label='Block  ' + ip, command=lambda i=ip: self._host_block_toggle(i, True))
        try:
            m.tk_popup(event.x_root, event.y_root)
        finally:
            m.grab_release()

    def _enable_fw_logging(self):
        """Turn on Windows Firewall dropped-packet logging (needs admin)."""
        ok, err = _nm_firewall_enable_logging()
        _NM_FW_HITS_CACHE['t'] = 0.0          # force a re-read next time
        try:
            from tkinter import messagebox
            if ok:
                messagebox.showinfo('Firewall logging',
                                    'Dropped-packet logging enabled.\n\n'
                                    'Attempts will start being counted from now on.',
                                    parent=self._host_tree)
            else:
                messagebox.showerror('Firewall logging',
                                     'Could not enable logging:\n%s\n\n'
                                     'Run the app as Administrator and try again.' % err,
                                     parent=self._host_tree)
        except Exception:
            _exc_debug('_enable_fw_logging')

    def _host_ip_at(self, event):
        try:
            iid = self._host_tree.identify_row(event.y)
            if not iid:
                return None
            vals = self._host_tree.item(iid, 'values')
            ip = (vals[0] if vals else '').strip()
            return ip or None
        except Exception:
            return None

    def _host_dbl_whois(self, event):
        ip = self._host_ip_at(event)
        if ip:
            self._show_whois_dialog(ip)

    def _host_ctx_menu(self, event):
        import tkinter as tk
        ip = self._host_ip_at(event)
        if not ip:
            return
        try:
            iid = self._host_tree.identify_row(event.y)
            if iid:
                self._host_tree.selection_set(iid)
        except Exception:
            _exc_debug('_host_ctx_menu')
        m = tk.Menu(self._host_tree, tearoff=0)
        _lines, _offer = _nm_fw_menu_lines(ip)
        for _ln in _lines:
            m.add_command(label=_ln, state='disabled')
        if _offer:
            m.add_command(label='\u2699  Enable firewall drop logging (admin)',
                          command=lambda: self._enable_fw_logging())
        m.add_separator()
        m.add_command(label='WHOIS  ' + ip, command=lambda: self._show_whois_dialog(ip))
        if ip in self._blocked_ips:
            m.add_command(label='Unblock  ' + ip, command=lambda: self._host_block_toggle(ip, False))
        else:
            m.add_command(label='Block  ' + ip, command=lambda: self._host_block_toggle(ip, True))
        m.add_separator()
        m.add_command(label='Copy IP',
                      command=lambda: (self._host_tree.clipboard_clear(),
                                       self._host_tree.clipboard_append(ip)))
        try:
            m.tk_popup(event.x_root, event.y_root)
        finally:
            m.grab_release()

    def _show_whois_dialog(self, ip):
        import threading
        import tkinter as tk
        from tkinter import ttk
        win = tk.Toplevel(self._host_tree)
        win.title('WHOIS ' + ip)
        win.configure(bg=self._PANEL)
        win.geometry('580x480')
        txt = tk.Text(win, bg='#04101a', fg='#c8dff0', font=(_NM_MONO, 9),
                      wrap='word', borderwidth=0, insertbackground='#c8dff0')
        vsb = ttk.Scrollbar(win, orient='vertical', command=txt.yview)
        txt.configure(yscrollcommand=vsb.set)
        vsb.pack(side='right', fill='y')
        txt.pack(side='left', fill='both', expand=True, padx=(8, 0), pady=8)
        txt.insert('1.0', 'Looking up %s ...\n' % ip)
        txt.config(state='disabled')

        def _work():
            try:
                summary, raw = _nm_whois(ip)
            except Exception as e:
                summary, raw = {'error': str(e)}, ''

            def _fill():
                try:
                    if not win.winfo_exists():
                        return
                    txt.config(state='normal')
                    txt.delete('1.0', 'end')
                    if summary.get('note'):
                        txt.insert('end', summary['note'] + '\n')
                    elif summary.get('error'):
                        txt.insert('end', 'Error: ' + summary['error'] + '\n')
                    else:
                        for k in ('org', 'netname', 'range', 'cidr', 'country', 'descr'):
                            if summary.get(k):
                                txt.insert('end', '%-9s %s\n' % (k + ':', summary[k]))
                        txt.insert('end', '\n' + '-' * 54 + '\n' + (raw or ''))
                    txt.config(state='disabled')
                except Exception:
                    _exc('_show_whois_dialog fill')
            try:
                win.after(0, _fill)
            except Exception:
                _exc_debug('_work')
        threading.Thread(target=_work, daemon=True).start()

    def _host_block_toggle(self, ip, block):
        import threading

        def _work():
            try:
                if block:
                    ok, err = _nm_firewall_block(ip)
                    if ok:
                        self._blocked_ips.add(ip)
                else:
                    ok, err = _nm_firewall_unblock(ip)
                    if ok:
                        self._blocked_ips.discard(ip)
            except Exception as e:
                ok, err = False, str(e)

            def _ui():
                try:
                    from tkinter import messagebox
                    if ok:
                        messagebox.showinfo('Firewall',
                                            ('Blocked ' if block else 'Unblocked ') + ip,
                                            parent=self._host_tree)
                    else:
                        messagebox.showerror('Firewall',
                                             ('Block' if block else 'Unblock') +
                                             ' failed: ' + (err or 'unknown'),
                                             parent=self._host_tree)
                except Exception:
                    _exc('_host_block_toggle ui')
            try:
                self._host_tree.after(0, _ui)
            except Exception:
                _exc_debug('_work')
        threading.Thread(target=_work, daemon=True).start()

    def _block_ip_range(self):
        """Block a CIDR range: enumerate IPs, add individual firewall rules."""
        import ipaddress, re as _re
        raw = getattr(self,'_block_range_var',None)
        if raw is None: return
        cidr = raw.get().strip()
        if not cidr or cidr.startswith('e.g'): return
        # Support plain IP (auto /32) or CIDR
        if '/' not in cidr:
            cidr += '/32'
        try:
            network = ipaddress.ip_network(cidr, strict=False)
        except ValueError:
            try:
                self._block_range_lbl.config(text='Invalid CIDR')
            except Exception: _exc_debug('_block_ip_range')
            return
        targets = [str(ip) for ip in network.hosts()] or [str(network.network_address)]
        try:
            self._block_range_btn.config(state='disabled', text='Blocking...')
            self._block_range_lbl.config(text=f'Blocking {len(targets)} IPs...')
        except Exception: _exc('_block_ip_range_ui')
        def _do():
            import subprocess as _sp
            flags = subprocess.CREATE_NO_WINDOW if sys.platform == 'win32' else 0
            blocked_count = 0
            for ip in targets:
                if not _re.match(r'^[\d.]+$', ip): continue
                rule = f'NM_BLOCK_{ip.replace(".","_")}'
                if ip in self._blocked_ips:
                    blocked_count += 1; continue
                try:
                    # Only count it if the rule was actually written.
                    _ok, _err = _nm_fw_add_block(rule, ip)
                    if not _ok:
                        log.warning('[fw] range block of %s failed: %s', ip, _err)
                        continue
                    self._blocked_ips.add(ip)
                    blocked_count += 1
                    self._refresh_blocked_count()
                except Exception: _exc('_block_ip_range_do')
            def _upd():
                try:
                    self._block_range_btn.config(state='normal', text='⛔ BLOCK')
                    self._block_range_lbl.config(text=f'⛔ Blocked {blocked_count} IPs')
                except Exception: _exc_debug('_upd')
            try: self.root.after(0, _upd)
            except Exception: _exc('_block_ip_range_upd')
        import threading as _thr
        _thr.Thread(target=_do, daemon=True).start()

