    def _schedule_blocked_refresh(self):
        """Refresh blocked IPs from firewall every 10 s."""
        if self._closed: return
        import threading as _thr
        _thr.Thread(target=self._refresh_blocked_ips, daemon=True).start()
        try: self.root.after(30000, self._schedule_blocked_refresh)
        except Exception: _exc('_schedule_blocked_refresh')

    def _rule_exists(self, ip):
        """Return True if NM_BLOCK_ rules already exist for this IP in Windows Firewall."""
        import re as _re
        if not _re.match(r'^[\d.]+$', ip): return False
        # Backend-agnostic: netsh on Windows, nftables on Linux.
        return _nm_fw_rule_exists('NM_BLOCK_%s' % ip.replace('.', '_'))

    def _refresh_blocked_ips(self):
        """Rebuild _blocked_ips by querying the actual Windows Firewall in one call."""
        if not _nm_fw_backend(): return
        try:
            # One query for all of our rules, whichever backend is in use
            existing_rules = set(nm[len('NM_BLOCK_'):]
                                 for nm in _nm_fw_list_rules('NM_BLOCK_'))
            # Build _blocked_ips from matched rule names
            blocked = set()
            for rule_suffix in existing_rules:
                ip = rule_suffix.replace('_', '.')
                blocked.add(ip)
            self._blocked_ips = blocked
            log.debug(f'_refresh_blocked_ips: {len(blocked)} IPs blocked')
        except Exception:
            _exc('_refresh_blocked_ips')

    def _spread_nodes(self):
        """Redistribute nodes into a clean, evenly spaced radial layout."""
        import math as _math
        if not self._nodes:
            return
        nodes = list(self._nodes.keys())
        n = len(nodes)

        # Hub = highest bytes node → stays at centre
        hub = max(self._nodes, key=lambda ip: self._nodes[ip].get('bytes', 0))
        self._nodes[hub]['pos'] = (0.50, 0.50)
        self._nodes[hub]['pinned'] = True

        others = sorted([ip for ip in nodes if ip != hub],
                        key=lambda ip: self._nodes[ip].get('bytes', 0),
                        reverse=True)
        if not others:
            self._canvas.draw_idle(); return

        # Fill rings outward — enough spacing so labels don't overlap
        # Label width ≈ 0.12 canvas units → min arc spacing ≈ 0.14
        ring_configs = [(6, 0.20), (10, 0.30), (16, 0.38), (24, 0.44), (32, 0.48)]
        idx = 0
        for ring_n, radius in ring_configs:
            count = min(ring_n, len(others) - idx)
            if count <= 0: break
            # Stagger angle per ring
            offset = _math.pi / ring_n
            for i in range(count):
                angle = offset + i * 2 * _math.pi / count
                x = max(0.03, min(0.97, 0.50 + radius * _math.cos(angle)))
                y = max(0.03, min(0.97, 0.50 + radius * _math.sin(angle)))
                self._nodes[others[idx]]['pos'] = (x, y)
                self._nodes[others[idx]]['pinned'] = True
                idx += 1
            if idx >= len(others): break

        # Any remaining nodes that didn't fit — outer ring
        if idx < len(others):
            remaining = len(others) - idx
            for i, ip in enumerate(others[idx:]):
                angle = i * 2 * _math.pi / remaining
                x = max(0.03, min(0.97, 0.50 + 0.47 * _math.cos(angle)))
                y = max(0.03, min(0.97, 0.50 + 0.47 * _math.sin(angle)))
                self._nodes[ip]['pos'] = (x, y)
                self._nodes[ip]['pinned'] = True

        self._canvas.draw_idle()

    def _ai_complete(self, prompt, want_json=False, timeout=30):
        """Provider-agnostic single-shot AI completion — the one seam every AI
        feature goes through. Delegates to the module-level _nm_ai_complete so
        there is a single implementation to fix/maintain; the failure reason is
        left in self._ai_last_error so callers can surface it. No API key is
        needed for the default 'ollama' provider; nothing leaves the box.
        """
        text, err = _nm_ai_complete(prompt, want_json=want_json, timeout=timeout)
        if err and 'has no model' in err:
            # Enrich with the list of models this Ollama actually has.
            try:
                from pathlib import Path as _P
                uf = _P.home() / '.nm_ai_url'
                base = ((uf.read_text().strip() if uf.exists() else '')
                        or 'http://localhost:11434').rstrip('/')
                err += self._ollama_models_hint(base)
            except Exception:
                _exc_debug('_ai_complete')
        self._ai_last_error = err or ''
        return text

    def _ollama_models_hint(self, base):
        """Best-effort list of locally-installed Ollama models, for error text."""
        try:
            import json as _j, urllib.request
            with urllib.request.urlopen(base.rstrip('/') + '/api/tags',
                                        timeout=5) as r:
                tags = _j.loads(r.read().decode()).get('models', [])
            names = [m.get('name', '') for m in tags if m.get('name')]
            if names:
                return ' Installed: ' + ', '.join(names[:8]) + '.'
        except Exception:
            _exc_debug('_ollama_models_hint')
        return ''



    def _ask_flow_ai(self):
        import threading
        ctx=getattr(self,'_current_flow_ctx',None)
        if not ctx:
            self._flow_ai_set('Select a flow first.'); return
        q=self._flow_ai_entry.get().strip()
        if not q or q=='Ask about this flow...':
            self._flow_ai_set('Enter a question first.'); return
        import pathlib as _pl, stat as _stat
        provider=(getattr(self,'_flow_ai_provider_var',None).get()
                  if getattr(self,'_flow_ai_provider_var',None) else 'ollama')
        if provider=='anthropic':
            key=self._flow_ai_key_entry.get().strip()
            if not key or key=='sk-ant-... API key':
                self._flow_ai_set('Enter your Anthropic API key, or switch the '
                                  'provider to Ollama (local, no key needed).'); return
            try:
                _kf=_pl.Path.home()/'.nm_anthropic_key'
                _kf.write_text(key); _kf.chmod(_stat.S_IRUSR | _stat.S_IWUSR)
            except Exception: _exc('_ask_flow_ai')
        else:
            # Persist the chosen local model so the watch loop uses it too.
            try:
                _mdl=self._flow_ai_model_entry.get().strip()
                if _mdl: (_pl.Path.home()/'.nm_ai_model').write_text(_mdl)
            except Exception: _exc('_ask_flow_ai')
        self._flow_ai_set('Analysing flow\u2026')
        def _worker():
            try:
                b=ctx['bytes']; p=ctx['pkts']
                if b<1e3: bs=f'{b:.0f} B'
                elif b<1e6: bs=f'{b/1e3:.1f} KB'
                else: bs=f'{b/1e6:.1f} MB'
                context=(
                    f"Flow: {ctx['src']} ({ctx['src_name']}) -> {ctx['dst']} ({ctx['dst_name']})\n"
                    f"Protocol: {ctx['proto'].upper()}\n"
                    f"Packets: {p:,}\n"
                    f"Data: {bs}\n"
                    f"Avg packet size: {b/p:.0f} B" if p else 'Avg packet size: N/A'
                )
                prompt=('You are a network security analyst. Answer concisely about '
                        'the network flow below. Use plain text, no markdown.\n\n'
                        f'Flow data:\n{context}\n\nQuestion: {q}')
                ans=self._ai_complete(prompt, want_json=False, timeout=120)
                if not ans:
                    _err=getattr(self,'_ai_last_error','') or ''
                    ans=('No response from the AI engine.\n\n'
                         + (_err + '\n\n' if _err else '')
                         + 'Ollama (default, no key): make sure `ollama serve` is '
                           'running and the model is pulled (e.g. `ollama pull '
                           'llama3.2`). The model box must match a name from '
                           '`ollama list`. Or switch the provider to Anthropic.')
                self.root.after(0,lambda a=ans:self._flow_ai_set(a))
            except Exception as e:
                self.root.after(0,lambda m=str(e):self._flow_ai_set(m))
        threading.Thread(target=_worker,daemon=True).start()

    def _flow_ai_set(self,text):
        try:
            self._flow_ai_resp.config(state='normal')
            self._flow_ai_resp.delete('1.0','end')
            self._flow_ai_resp.insert('end',text)
            self._flow_ai_resp.config(state='disabled')
        except Exception: _exc('_flow_ai_set')

    def _flow_ai_apply_provider_ui(self):
        """Show the model box for local (Ollama) or the key box for Anthropic."""
        try:
            prov=self._flow_ai_provider_var.get()
            self._flow_ai_model_entry.pack_forget()
            self._flow_ai_key_entry.pack_forget()
            if prov=='anthropic':
                if hasattr(self,'_flow_ai_io_label'):
                    self._flow_ai_io_label.config(text='key:')
                self._flow_ai_key_entry.pack(side='left',padx=(2,0),ipady=3)
            else:
                if hasattr(self,'_flow_ai_io_label'):
                    self._flow_ai_io_label.config(text='model:')
                self._flow_ai_model_entry.pack(side='left',padx=(2,0),ipady=3)
        except Exception: _exc('_flow_ai_apply_provider_ui')

    def _on_flow_select(self,event=None):
        sel=self._flow_tree.selection()
        if not sel: return
        iid=sel[0]
        try: src,dst,proto=iid.split('|',2)
        except ValueError: return
        self._show_flow_detail(src,dst,proto)

    def _resolve(self,ip):
        if not self._resolve_names: return ip
        if ip in self._dns_cache: return self._dns_cache[ip]

        # Multicast/broadcast/public-resolver addresses: name them directly,
        # reverse DNS either fails or returns something useless.
        _sp = _nm_special_ip(ip)
        if _sp:
            self._dns_cache[ip]=_sp; self._dns_src[ip]='special'
            return _sp

        self._dns_cache[ip]=ip          # placeholder until the lookup lands
        if ip in self._dns_inflight:
            return ip
        self._dns_inflight.add(ip)
        def _r(addr=ip):
            try:
                # Keep the FULL name — truncating at 20 chars was cutting
                # 'ec2-...compute.amazonaws.com' down to 'ec2-54-167-136-58.co'.
                raw = socket.gethostbyaddr(addr)[0].rstrip('.')
                self._dns_raw[addr]=raw
                if self._dns_src.get(addr) != 'dns':      # don't clobber a sniffed name
                    self._dns_cache[addr]=_nm_friendly_host(addr, raw)
                    self._dns_src[addr]='ptr'
            except Exception:
                self._dns_cache.setdefault(addr, addr)
            finally:
                self._dns_inflight.discard(addr)
        threading.Thread(target=_r,daemon=True).start()
        return ip


