    def __init__(self):
        _nm_pick_mono()   # font family must be resolved before widgets
        import tkinter as tk
        from tkinter import ttk
        self._tk  = tk
        self._ttk = ttk

        self.root = tk.Toplevel()
        self.root.title('Vanguard Flow NetSentinel — User Guide')
        self.root.configure(bg=self._BG)
        self.root.geometry('1060x760')
        self.root.minsize(700, 500)
        self.root.lift()
        self.root.focus_force()

        self._build_ui()

    def _build_ui(self):
        tk  = self._tk
        ttk = self._ttk
        r   = self.root

        # Header
        hdr = tk.Frame(r, bg='#020810', height=52)
        hdr.pack(fill='x'); hdr.pack_propagate(False)
        tk.Label(hdr, text='  ? Vanguard Flow NetSentinel  —  User Guide',
                 bg='#020810', fg=self._ACC,
                 font=(_NM_MONO, 14, 'bold')).pack(side='left', padx=16, pady=10)
        tk.Label(hdr, text='Complete reference for all features',
                 bg='#020810', fg=self._TICK,
                 font=(_NM_MONO, 9)).pack(side='left', pady=16)
        tk.Button(hdr, text='Close', command=self.root.destroy,
                  bg='#1a1a2a', fg='#8899aa', relief='flat',
                  font=(_NM_MONO, 9), cursor='hand2',
                  padx=12).pack(side='right', padx=12, pady=10)
        tk.Frame(r, bg=self._SPIN, height=1).pack(fill='x')

        # Main split: nav left, content right
        pw = tk.PanedWindow(r, orient='horizontal', bg='#0a1828',
                            sashwidth=5, sashrelief='raised', handlesize=8)
        pw.pack(fill='both', expand=True)

        # Nav panel
        nf = tk.Frame(pw, bg='#040c1a')
        pw.add(nf, width=200)
        tk.Label(nf, text='  Contents', bg='#040c1a', fg=self._ACC,
                 font=(_NM_MONO, 9, 'bold')).pack(fill='x', pady=(6, 4))
        tk.Frame(nf, bg=self._SPIN, height=1).pack(fill='x', padx=6)

        s = ttk.Style(r)
        s.theme_use('clam')
        s.configure('Nav.Treeview',
                    background='#040c1a', fieldbackground='#040c1a',
                    foreground=self._TEXT, font=(_NM_MONO, 9),
                    rowheight=24, borderwidth=0)
        s.map('Nav.Treeview',
              background=[('selected', '#0a3060')],
              foreground=[('selected', 'white')])

        nav = ttk.Treeview(nf, style='Nav.Treeview', show='tree',
                           selectmode='browse')
        nav.pack(fill='both', expand=True, padx=2, pady=4)
        for title, key in self.SECTIONS:
            nav.insert('', 'end', iid=key, text=f'  {title}')

        # Content panel
        cf = tk.Frame(pw, bg=self._PANEL)
        pw.add(cf)

        self._txt = tk.Text(
            cf, bg='#04080e', fg=self._TEXT,
            font=(_NM_MONO, 10), relief='flat',
            wrap='word', state='disabled',
            padx=24, pady=16,
            selectbackground='#0a3060',
            spacing1=2, spacing3=4)

        vsb = ttk.Scrollbar(cf, orient='vertical', command=self._txt.yview)
        self._txt.configure(yscrollcommand=vsb.set)
        vsb.pack(side='right', fill='y')
        self._txt.pack(fill='both', expand=True)

        # Text tags
        self._txt.tag_configure('h1',
            foreground=self._ACC, font=(_NM_MONO, 14, 'bold'),
            spacing1=14, spacing3=8)
        self._txt.tag_configure('h2',
            foreground='#38f0a8', font=(_NM_MONO, 11, 'bold'),
            spacing1=12, spacing3=4)
        self._txt.tag_configure('p',
            foreground=self._TEXT, font=(_NM_MONO, 10),
            spacing3=8)
        self._txt.tag_configure('bullet',
            foreground='#c8dff0', font=(_NM_MONO, 10),
            lmargin1=20, lmargin2=34, spacing3=3)
        self._txt.tag_configure('bullet_dot',
            foreground='#38b8f0', font=(_NM_MONO, 10, 'bold'))
        self._txt.tag_configure('code',
            foreground='#ffd93d', font=(_NM_MONO, 10),
            background='#0a1828')
        self._txt.tag_configure('rule',
            foreground='#0a1828')
        self._txt.tag_configure('diagram',
            foreground='#38b8f0', font=(_NM_MONO, 8),
            background='#030810', lmargin1=10, lmargin2=10,
            spacing1=2, spacing3=2)
        self._txt.tag_configure('step_num',
            foreground='#38b8f0', font=(_NM_MONO, 10, 'bold'))
        self._txt.tag_configure('tip',
            foreground='#38f0a8', font=(_NM_MONO, 9),
            lmargin1=20, lmargin2=20, spacing3=2)
        self._txt.tag_configure('tip_icon',
            foreground='#38f0a8', font=(_NM_MONO, 10, 'bold'))
        self._txt.tag_configure('warn',
            foreground='#ff9f43', font=(_NM_MONO, 9),
            lmargin1=20, lmargin2=20, spacing3=2)
        self._txt.tag_configure('warn_icon',
            foreground='#ff9f43', font=(_NM_MONO, 10, 'bold'))

        # Show first section on open
        nav.selection_set('overview')
        self._show_section('overview')

        def _on_nav_select(event):
            sel = nav.selection()
            if sel:
                self._show_section(sel[0])

        nav.bind('<<TreeviewSelect>>', _on_nav_select)

        # Search bar
        sf = tk.Frame(r, bg='#020810', height=28)
        sf.pack(fill='x', side='bottom'); sf.pack_propagate(False)
        tk.Label(sf, text='  Search:', bg='#020810', fg=self._TICK,
                 font=(_NM_MONO, 8)).pack(side='left', padx=(8, 4))
        self._search_var = tk.StringVar()
        se = tk.Entry(sf, textvariable=self._search_var, width=30,
                      bg='#0d2235', fg=self._TEXT, insertbackground=self._TEXT,
                      relief='flat', font=(_NM_MONO, 9),
                      highlightthickness=1, highlightcolor=self._ACC,
                      highlightbackground='#1a3050')
        se.pack(side='left', ipady=2)
        se.bind('<Return>', lambda e: self._search())
        tk.Button(sf, text='Find', command=self._search,
                  bg='#062040', fg=self._ACC, relief='flat',
                  font=(_NM_MONO, 8), cursor='hand2',
                  padx=8).pack(side='left', padx=4)
        self._search_result = tk.Label(sf, text='', bg='#020810',
                                        fg=self._TICK, font=(_NM_MONO, 8))
        self._search_result.pack(side='left', padx=8)

    def _show_section(self, key):
        content = self.CONTENT.get(key, [])
        txt = self._txt
        txt.config(state='normal')
        txt.delete('1.0', 'end')
        for kind, text in content:
            if kind == 'h1':
                txt.insert('end', text + '\n', 'h1')
                txt.insert('end', '\u2500' * 55 + '\n', 'rule')
            elif kind == 'h2':
                txt.insert('end', '\n' + text + '\n', 'h2')
            elif kind == 'p':
                txt.insert('end', text + '\n', 'p')
            elif kind == 'bullet':
                txt.insert('end', '  \u2022 ', 'bullet_dot')
                txt.insert('end', text + '\n', 'bullet')
            elif kind == 'diagram':
                txt.insert('end', '\n', 'p')
                txt.insert('end', text + '\n', 'diagram')
                txt.insert('end', '\n', 'p')
            elif kind == 'step':
                # text = "N|step body"
                parts = text.split('|', 1)
                num = parts[0]; body = parts[1] if len(parts) > 1 else text
                txt.insert('end', f'  [{num}] ', 'step_num')
                txt.insert('end', body + '\n', 'bullet')
            elif kind == 'tip':
                txt.insert('end', '\n  \u2139 ', 'tip_icon')
                txt.insert('end', text + '\n\n', 'tip')
            elif kind == 'warn':
                txt.insert('end', '\n  \u26a0 ', 'warn_icon')
                txt.insert('end', text + '\n\n', 'warn')
        txt.config(state='disabled')
        txt.yview_moveto(0)

    def _search(self):
        query = self._search_var.get().strip().lower()
        if not query:
            return
        # Search all sections, find first match
        for title, key in self.SECTIONS:
            for kind, text in self.CONTENT.get(key, []):
                if query in text.lower():
                    # Navigate to section and highlight
                    for nav_widget in self.root.winfo_children():
                        pass  # just show the section
                    self._show_section(key)
                    # Highlight in text widget
                    txt = self._txt
                    txt.config(state='normal')
                    idx = '1.0'
                    found = 0
                    while True:
                        idx = txt.search(query, idx, nocase=True, stopindex='end')
                        if not idx:
                            break
                        end_idx = f'{idx}+{len(query)}c'
                        txt.tag_add('search_hl', idx, end_idx)
                        found += 1
                        idx = end_idx
                    txt.tag_configure('search_hl',
                        background='#1a3a00', foreground='#39ff14')
                    if found:
                        # Jump to first hit
                        first = txt.search(query, '1.0', nocase=True)
                        if first:
                            txt.see(first)
                    txt.config(state='disabled')
                    self._search_result.config(
                        text=f'{found} match{"es" if found!=1 else ""} in "{title}"')
                    return
        self._search_result.config(text=f'Not found: "{query}"')


