def _nm_ai_complete(prompt, want_json=False, timeout=30):
    """Module-level provider-agnostic AI completion, shared by the 3D server and
    any non-widget caller. Reads provider/model from ~/.nm_ai_* files. Returns
    (text, error): text is None on failure with a human-readable error string.
    Keyless by default via local Ollama; nothing leaves the machine."""
    import json as _j, urllib.request, urllib.error
    from pathlib import Path as _P

    def _rf(name, dflt=''):
        try:
            p = _P.home() / name
            return p.read_text().strip() if p.exists() else dflt
        except Exception:
            return dflt

    provider = (_rf('.nm_ai_provider', 'ollama') or 'ollama').lower()

    if provider in ('ollama', 'local'):
        model = _rf('.nm_ai_model', 'llama3.2') or 'llama3.2'
        base = (_rf('.nm_ai_url', 'http://localhost:11434')
                or 'http://localhost:11434').rstrip('/')
        try:
            body = {'model': model, 'prompt': prompt, 'stream': False,
                    # Keep the model resident so later asks don't cold-load, and
                    # cap the reply so a "thinking" model can't run for minutes.
                    'keep_alive': '30m',
                    'options': {'num_predict': 700, 'num_ctx': 8192,
                                'temperature': 0.4}}
            if want_json:
                body['format'] = 'json'
            req = urllib.request.Request(
                base + '/api/generate', data=_j.dumps(body).encode(),
                headers={'Content-Type': 'application/json'}, method='POST')
            with urllib.request.urlopen(req, timeout=timeout) as r:
                out = _j.loads(r.read().decode())
            resp = out.get('response', '')
            if resp:
                return resp, ''
            return None, (out.get('error', '') or 'Ollama returned an empty response.')
        except urllib.error.HTTPError as e:
            try: detail = e.read().decode(errors='replace')[:300]
            except Exception: detail = ''
            if e.code == 404 or 'not found' in detail.lower():
                return None, ("Ollama has no model '%s'. Pull it with "
                              "`ollama pull %s`." % (model, model))
            return None, 'Ollama HTTP %s: %s' % (e.code, detail)
        except urllib.error.URLError as e:
            # "Start it with ollama serve" is useless advice when Ollama is not
            # installed at all, which is the normal state on a fresh Linux box.
            if _nm_which('ollama'):
                return None, ("Can't reach Ollama at %s (%s). Start it with "
                              "`ollama serve`." % (base, e.reason))
            if _NM_IS_WIN:
                how = 'Download it from https://ollama.com/download'
            elif _NM_IS_MAC:
                how = 'brew install ollama   (or https://ollama.com/download)'
            else:
                how = 'curl -fsSL https://ollama.com/install.sh | sh'
            return None, ("Ollama is not installed, so AI analysis is "
                          "unavailable. Everything else works normally.\n\n"
                          "To enable it:\n    %s\n    ollama pull llama3.2\n\n"
                          "Or switch the provider to Anthropic in the AI settings "
                          "if you have an API key." % how)
        except TimeoutError:
            return None, ('Ollama timed out after %ss. For a big prompt like a '
                          'capture summary this usually means the model is too '
                          'slow on this machine \u2014 try a smaller one (e.g. '
                          '`ollama pull llama3.2`, then set model to llama3.2). '
                          'Thinking models such as qwen3 are much slower. The '
                          'model now stays loaded for 30 minutes, so a second '
                          'attempt is normally much quicker.' % timeout)
        except Exception as e:
            return None, 'Ollama error: %s' % e

    if provider == 'anthropic':
        key = _rf('.nm_anthropic_key', '')
        if not key:
            return None, 'No Anthropic API key saved.'
        model = _rf('.nm_ai_model_anthropic', 'claude-haiku-4-5-20251001') \
            or 'claude-haiku-4-5-20251001'
        try:
            body = {'model': model, 'max_tokens': 800,
                    'messages': [{'role': 'user', 'content': prompt}]}
            req = urllib.request.Request(
                'https://api.anthropic.com/v1/messages',
                data=_j.dumps(body).encode(),
                headers={'Content-Type': 'application/json', 'x-api-key': key,
                         'anthropic-version': '2023-06-01'}, method='POST')
            with urllib.request.urlopen(req, timeout=timeout) as r:
                resp = _j.loads(r.read().decode())
            txt = ''.join(b.get('text', '') for b in resp.get('content', []))
            return (txt, '') if txt else (None, 'Empty Anthropic response.')
        except Exception as e:
            return None, 'Anthropic error: %s' % e

    return None, "Unknown AI provider '%s'." % provider


# =============================================================================
#  Monitoring add-ons (Batch 1): persistent store + device inventory +
#  connection-quality (latency) prober + alert engine. Self-contained; uses its
#  own SQLite file so it can never disturb the speed database.
# =============================================================================
class _NMStore:
    """Thread-safe SQLite store for devices, latency history and alerts."""
    def __init__(self, path=None):
        import pathlib, threading as _th
        self._path = str(path or (pathlib.Path.home() / '.nm_monitor.db'))
        self._local = _th.local()
        self._init()

    def _conn(self):
        c = getattr(self._local, 'c', None)
        if c is None:
            import sqlite3
            c = sqlite3.connect(self._path, check_same_thread=False, timeout=5)
            c.row_factory = sqlite3.Row
            try: c.execute('PRAGMA journal_mode=WAL')
            except Exception: _exc_debug('_conn')
            self._local.c = c
        return c

    def _init(self):
        self._conn().executescript(
            'CREATE TABLE IF NOT EXISTS devices('
            ' ip TEXT PRIMARY KEY, mac TEXT, vendor TEXT, name TEXT, hostname TEXT,'
            ' first_seen REAL, last_seen REAL, online INTEGER DEFAULT 1);'
            'CREATE TABLE IF NOT EXISTS alerts('
            ' id INTEGER PRIMARY KEY AUTOINCREMENT, ts REAL, sev TEXT,'
            ' kind TEXT, msg TEXT, ack INTEGER DEFAULT 0);'
            'CREATE TABLE IF NOT EXISTS latency('
            ' ts REAL, target TEXT, rtt REAL, loss REAL, jitter REAL);'
            'CREATE TABLE IF NOT EXISTS geo('
            ' country TEXT PRIMARY KEY, first_seen REAL, cnt INTEGER DEFAULT 0);'
            'CREATE TABLE IF NOT EXISTS traffic(ts REAL, ip TEXT, bytes REAL);'
            'CREATE TABLE IF NOT EXISTS honeypot_hits('
            ' id INTEGER PRIMARY KEY AUTOINCREMENT, ts REAL, ip TEXT, port INTEGER,'
            ' proto TEXT, service TEXT, known INTEGER DEFAULT 0, sample TEXT, tool TEXT);'
            'CREATE INDEX IF NOT EXISTS idx_hp_ts ON honeypot_hits(ts);'
            'CREATE INDEX IF NOT EXISTS idx_hp_ip ON honeypot_hits(ip);'
            'CREATE TABLE IF NOT EXISTS briefings(id INTEGER PRIMARY KEY AUTOINCREMENT, ts REAL, text TEXT);')
        self._conn().commit()
        try:
            cols = [r[1] for r in self._conn().execute('PRAGMA table_info(devices)')]
            if 'hostname' not in cols:
                self._conn().execute('ALTER TABLE devices ADD COLUMN hostname TEXT')
                self._conn().commit()
        except Exception: _exc_debug('_init')

    # ── devices ──────────────────────────────────────────────────────────
    def upsert_device(self, ip, mac=None, vendor=None, name=None, hostname=None):
        import time
        c = self._conn(); now = time.time()
        new = c.execute('SELECT ip FROM devices WHERE ip=?', (ip,)).fetchone() is None
        if new:
            c.execute('INSERT INTO devices(ip,mac,vendor,name,hostname,first_seen,last_seen,online)'
                      ' VALUES(?,?,?,?,?,?,?,1)', (ip, mac, vendor, name, hostname, now, now))
        else:
            c.execute('UPDATE devices SET last_seen=?,online=1,'
                      'mac=COALESCE(?,mac),vendor=COALESCE(?,vendor),'
                      'hostname=COALESCE(?,hostname) WHERE ip=?',
                      (now, mac, vendor, hostname, ip))
        c.commit(); return new

    def mark_stale_offline(self, older_than=180):
        import time
        c = self._conn()
        c.execute('UPDATE devices SET online=0 WHERE last_seen<?', (time.time()-older_than,))
        c.commit()

    def set_device_name(self, ip, name):
        c = self._conn(); c.execute('UPDATE devices SET name=? WHERE ip=?', (name, ip)); c.commit()

    def list_devices(self):
        return [dict(r) for r in self._conn().execute(
            'SELECT * FROM devices ORDER BY online DESC, last_seen DESC')]

    # ── alerts ───────────────────────────────────────────────────────────
    def insert_honeypot_hit(self, rec):
        """Persist a honeypot hit so history survives a restart."""
        c = self._conn()
        c.execute('INSERT INTO honeypot_hits(ts,ip,port,proto,service,known,sample,tool)'
                  ' VALUES(?,?,?,?,?,?,?,?)',
                  (rec.get('time'), rec.get('ip'), rec.get('port'),
                   rec.get('proto', 'tcp'), rec.get('service'),
                   1 if rec.get('known') else 0, rec.get('sample'), rec.get('tool')))
        c.commit()
        # keep it bounded so the file cannot grow without limit
        c.execute('DELETE FROM honeypot_hits WHERE id NOT IN '
                  '(SELECT id FROM honeypot_hits ORDER BY ts DESC LIMIT 20000)')
        c.commit()

    def honeypot_hits(self, since=None, limit=1000):
        q = ('SELECT ts,ip,port,proto,service,known,sample,tool FROM honeypot_hits')
        args = []
        if since is not None:
            q += ' WHERE ts>=?'; args.append(since)
        q += ' ORDER BY ts DESC LIMIT ?'; args.append(limit)
        rows = self._conn().execute(q, args).fetchall()
        return [{'time': r[0], 'ip': r[1], 'port': r[2], 'proto': r[3],
                 'service': r[4], 'known': bool(r[5]), 'sample': r[6],
                 'tool': r[7]} for r in rows]

    def honeypot_top_sources(self, since=None, limit=20):
        q = 'SELECT ip,COUNT(*),MIN(ts),MAX(ts) FROM honeypot_hits'
        args = []
        if since is not None:
            q += ' WHERE ts>=?'; args.append(since)
        q += ' GROUP BY ip ORDER BY COUNT(*) DESC LIMIT ?'; args.append(limit)
        rows = self._conn().execute(q, args).fetchall()
        return [{'ip': r[0], 'hits': r[1], 'first': r[2], 'last': r[3]}
                for r in rows]

    def honeypot_stats(self, since=None):
        q = 'SELECT COUNT(*),COUNT(DISTINCT ip) FROM honeypot_hits'
        args = []
        if since is not None:
            q += ' WHERE ts>=?'; args.append(since)
        row = self._conn().execute(q, args).fetchone()
        return {'total': row[0] or 0, 'unique_ips': row[1] or 0}

    def add_alert(self, sev, kind, msg, dedup_sec=300):
        import time
        c = self._conn(); now = time.time()
        if dedup_sec:
            if c.execute('SELECT id FROM alerts WHERE kind=? AND msg=? AND ts>?',
                         (kind, msg, now-dedup_sec)).fetchone():
                return None
        rid = c.execute('INSERT INTO alerts(ts,sev,kind,msg) VALUES(?,?,?,?)',
                        (now, sev, kind, msg)).lastrowid
        c.commit()
        # keep the table bounded
        c.execute('DELETE FROM alerts WHERE id NOT IN '
                  '(SELECT id FROM alerts ORDER BY ts DESC LIMIT 500)'); c.commit()
        try: _nm_notify_async('Vanguard Flow NetSentinel', msg, sev, kind)
        except Exception: _exc_debug('add_alert')
        return rid

    def list_alerts(self, limit=100, unacked_only=False):
        q = 'SELECT * FROM alerts'
        if unacked_only:
            q += ' WHERE ack=0'
        q += ' ORDER BY ts DESC LIMIT ?'
        return [dict(r) for r in self._conn().execute(q, (limit,))]

    def ack_alert(self, aid):
        c = self._conn()
        if aid == 'all':
            c.execute('UPDATE alerts SET ack=1')     # "Clear all" = mark all read
        else:
            c.execute('UPDATE alerts SET ack=1 WHERE id=?', (aid,))
        c.commit()

    def unacked_count(self):
        return self._conn().execute('SELECT COUNT(*) FROM alerts WHERE ack=0').fetchone()[0]

    # ── latency ──────────────────────────────────────────────────────────
    def add_latency(self, target, rtt, loss, jitter):
        import time
        c = self._conn(); now = time.time()
        c.execute('INSERT INTO latency(ts,target,rtt,loss,jitter) VALUES(?,?,?,?,?)',
                  (now, target, rtt, loss, jitter))
        c.execute('DELETE FROM latency WHERE ts<?', (now-86400,)); c.commit()

    def latency_recent(self, target, limit=120):
        rows = [dict(r) for r in self._conn().execute(
            'SELECT * FROM latency WHERE target=? ORDER BY ts DESC LIMIT ?', (target, limit))]
        return list(reversed(rows))

    def latency_latest(self):
        out = {}
        for r in self._conn().execute(
                'SELECT target,rtt,loss,jitter,ts FROM latency ORDER BY ts DESC LIMIT 60'):
            if r['target'] not in out: out[r['target']] = dict(r)
        return out

    # ── geo baseline ─────────────────────────────────────────────────────
    def geo_seen(self, country):
        """Record a country observation; return True if never seen before."""
        if not country: return False
        import time
        c = self._conn(); now = time.time()
        new = c.execute('SELECT country FROM geo WHERE country=?', (country,)).fetchone() is None
        if new:
            c.execute('INSERT INTO geo(country,first_seen,cnt) VALUES(?,?,1)', (country, now))
        else:
            c.execute('UPDATE geo SET cnt=cnt+1 WHERE country=?', (country,))
        c.commit(); return new

    def geo_count(self):
        return self._conn().execute('SELECT COUNT(*) FROM geo').fetchone()[0]

    def list_geo(self):
        return [dict(r) for r in self._conn().execute('SELECT * FROM geo ORDER BY cnt DESC')]

    # ── per-device traffic + uptime + briefings ──────────────────────────
    def add_traffic(self, ip, nbytes):
        import time
        c = self._conn(); now = time.time()
        c.execute('INSERT INTO traffic(ts,ip,bytes) VALUES(?,?,?)', (now, ip, nbytes))
        c.execute('DELETE FROM traffic WHERE ts<?', (now - 7 * 86400,)); c.commit()

    def top_traffic(self, since_sec=86400, limit=10):
        import time
        return [dict(r) for r in self._conn().execute(
            'SELECT ip, SUM(bytes) AS total FROM traffic WHERE ts>? '
            'GROUP BY ip ORDER BY total DESC LIMIT ?', (time.time() - since_sec, limit))]

    def uptime(self, target, since_sec=86400):
        import time
        rows = self._conn().execute('SELECT loss FROM latency WHERE target=? AND ts>?',
                                    (target, time.time() - since_sec)).fetchall()
        if not rows: return None
        up = sum(1 for r in rows if (r['loss'] or 0) < 100)
        return 100.0 * up / len(rows)

    def add_briefing(self, text):
        import time
        c = self._conn()
        c.execute('INSERT INTO briefings(ts,text) VALUES(?,?)', (time.time(), text))
        c.execute('DELETE FROM briefings WHERE id NOT IN '
                  '(SELECT id FROM briefings ORDER BY ts DESC LIMIT 30)'); c.commit()

    def latest_briefing(self):
        r = self._conn().execute('SELECT * FROM briefings ORDER BY ts DESC LIMIT 1').fetchone()
        return dict(r) if r else None


_NM_STORE = None
def _nm_store():
    global _NM_STORE
    if _NM_STORE is None:
        try: _NM_STORE = _NMStore()
        except Exception: _exc('_nm_store')
    return _NM_STORE


# _NM_OUI itself now lives in one place only (§4, "Device inventory" above) —
# this used to be a second, differently-populated copy of the same name that
# silently shadowed the first at module load. Merged into one; see the note
# above that dict's definition.
_NM_OUI_DB = {}


def _nm_load_oui():
    """Download + cache the full IEEE OUI vendor database into _NM_OUI_DB
    (~35k prefixes). Falls back silently to the small curated map if offline."""
    import urllib.request, pathlib, json, time, csv, io
    global _NM_OUI_DB
    cache = pathlib.Path.home() / '.nm_oui.json'
    try:
        if cache.exists() and time.time() - cache.stat().st_mtime < 30 * 86400:
            d = json.loads(cache.read_text())
            if d: _NM_OUI_DB = d; return
    except Exception:
        _exc_debug('_nm_load_oui')
    try:
        req = urllib.request.Request('https://standards-oui.ieee.org/oui/oui.csv',
                                     headers={'User-Agent': 'NetworkMonitor/1.0'})
        data = urllib.request.urlopen(req, timeout=90).read().decode('utf-8', 'replace')
        db = {}
        rdr = csv.reader(io.StringIO(data)); next(rdr, None)
        for row in rdr:
            if len(row) >= 3:
                asn = row[1].strip().upper()
                if len(asn) >= 6:
                    db[('%s:%s:%s' % (asn[0:2], asn[2:4], asn[4:6])).lower()] = row[2].strip()
        if db:
            _NM_OUI_DB = db
            try: cache.write_text(json.dumps(db))
            except Exception: _exc_debug('_nm_load_oui')
    except Exception:
        _exc('_nm_load_oui')


def _nm_oui_vendor(mac):
    if not mac: return ''
    p = mac.lower()[:8]
    return _NM_OUI_DB.get(p) or _NM_OUI.get(p, '')


def _nm_arp_scan():
    """Return [(ip, mac)] of hosts in the ARP/neighbour table. Cross-platform."""
    import subprocess, re
    out = ''
    for cmd in (['arp', '-a'], ['ip', 'neigh']):
        try:
            r = subprocess.run(cmd, capture_output=True, text=True, timeout=8)
            if r.stdout.strip(): out = r.stdout; break
        except Exception:
            continue
    ip_re = re.compile(r'(\d{1,3}(?:\.\d{1,3}){3})')
    mac_re = re.compile(r'([0-9a-fA-F]{2}(?:[:-][0-9a-fA-F]{2}){5})')
    seen, entries = set(), []
    for line in out.splitlines():
        ipm = ip_re.search(line); macm = mac_re.search(line)
        if not (ipm and macm): continue
        ip = ipm.group(1); mac = macm.group(1).lower().replace('-', ':')
        if mac in ('ff:ff:ff:ff:ff:ff', '00:00:00:00:00:00'): continue
        if ip.startswith(('224.', '239.', '255.', '0.')): continue
        if ip in seen: continue
        seen.add(ip); entries.append((ip, mac))
    return entries


def _nm_default_gateway():
    import subprocess, os, re
    try:
        if os.name == 'nt':
            out = subprocess.run(['ipconfig'], capture_output=True, text=True, timeout=8).stdout
            m = re.search(r'Default Gateway[ .]*:\s*(\d{1,3}(?:\.\d{1,3}){3})', out)
            if m: return m.group(1)
        else:
            out = subprocess.run(['ip', 'route'], capture_output=True, text=True, timeout=8).stdout
            m = re.search(r'default via (\d{1,3}(?:\.\d{1,3}){3})', out)
            if m: return m.group(1)
    except Exception:
        _exc_debug('_nm_default_gateway')
    return ''


def _nm_ping(host, count=5):
    """Return (rtt_ms, loss_pct, jitter_ms). rtt is None if unreachable."""
    import subprocess, os, re
    win = os.name == 'nt'
    cmd = (['ping', '-n', str(count), host] if win
           else ['ping', '-c', str(count), '-w', str(count + 3), host])
    try:
        out = subprocess.run(cmd, capture_output=True, text=True,
                             timeout=count * 2 + 8).stdout
    except Exception:
        return None, 100.0, 0.0
    rtt, loss, jitter = None, 100.0, 0.0
    if win:
        m = re.search(r'Average = (\d+)ms', out)
        if m: rtt = float(m.group(1))
        m = re.search(r'\((\d+)% loss\)', out)
        loss = float(m.group(1)) if m else (0.0 if rtt is not None else 100.0)
        mm = re.search(r'Minimum = (\d+)ms, Maximum = (\d+)ms', out)
        if mm: jitter = float(mm.group(2)) - float(mm.group(1))
    else:
        m = re.search(r'=\s*[\d.]+/([\d.]+)/[\d.]+/([\d.]+)', out)
        if m: rtt = float(m.group(1)); jitter = float(m.group(2))
        m = re.search(r'([\d.]+)% packet loss', out)
        if m: loss = float(m.group(1))
    return rtt, loss, jitter


def _nm_latency_targets(monitor):
    tgts = []
    gw = _nm_default_gateway()
    if gw: tgts.append(('Gateway', gw))
    tgts.append(('Cloudflare', '1.1.1.1'))
    tgts.append(('Google DNS', '8.8.8.8'))
    try:
        extra = monitor.config.get('latency_targets') or []
        for t in extra:
            if isinstance(t, (list, tuple)) and len(t) == 2: tgts.append((str(t[0]), str(t[1])))
    except Exception:
        _exc_debug('_nm_latency_targets')
    return tgts


def _nm_capture_topo(monitor):
    """Current topology as {nodes,edges,total_packets}. Prefer the live Wireshark
    capture; if it has no nodes, convert the active EtherApe window's live
    nodes/flows into the same shape so the report has something to show."""
    try:
        t = monitor._ws_get_topology()
        if t and t.get('nodes'):
            return t
    except Exception:
        _exc('_nm_capture_topo ws')
    try:
        ea = _active_ea()
        if ea is not None and getattr(ea, '_nodes', None):
            _nodes = dict(ea._nodes); _flows = dict(getattr(ea, '_flows', {}))
            nodes = [{'id': ip,
                      'bytes': int(nd.get('bytes', 0) or 0),
                      'pkts': int(nd.get('pkts', 0) or 0),
                      'protos': [nd.get('proto', 'other')]}
                     for ip, nd in _nodes.items()]
            edges = [{'src': k[0], 'dst': k[1],
                      'bytes': int(fl.get('bytes', 0) or 0),
                      'pkts': int(fl.get('pkts', 0) or 0),
                      'proto': fl.get('proto', 'other')}
                     for k, fl in _flows.items() if isinstance(k, tuple) and len(k) >= 2]
            if nodes:
                return {'nodes': nodes, 'edges': edges,
                        'total_packets': sum(e['pkts'] for e in edges)}
    except Exception:
        _exc('_nm_capture_topo ea')
    return {'nodes': [], 'edges': [], 'total_packets': 0}


def _nm_save_topo_snapshot(topo):
    """Persist a topology snapshot (with timestamp) for later report fallback."""
    try:
        import json, time
        if not topo or not topo.get('nodes'):
            return
        (Path.home() / '.nm_topology_snapshot.json').write_text(
            json.dumps({'ts': time.time(), 'topo': topo}))
    except Exception:
        _exc('_nm_save_topo_snapshot')


def _nm_load_topo_snapshot():
    """Return (topo, ts) from the most recent snapshot, or (None, 0)."""
    try:
        import json
        p = Path.home() / '.nm_topology_snapshot.json'
        if not p.exists():
            return None, 0
        d = json.loads(p.read_text())
        return d.get('topo'), d.get('ts', 0)
    except Exception:
        _exc('_nm_load_topo_snapshot')
        return None, 0


def _nm_topo_worker(monitor):
    """Every ~60s snapshot the current capture topology when it has data, so the
    HTML report can show the most recent capture even when none is live."""
    import time
    while True:
        try:
            topo = _nm_capture_topo(monitor)
            if topo and topo.get('nodes'):
                _nm_save_topo_snapshot(topo)
        except Exception:
            _exc('_nm_topo_worker')
        time.sleep(60)


def _nm_device_worker(monitor):
    import time, socket
    store = _nm_store()
    if store is None: return
    try: _nm_load_oui()
    except Exception: _exc_debug('_nm_device_worker')
    rdns = {}; cyc = 0; first_pass = True
    while True:
        try:
            if cyc % 20 == 0:
                rdns = {}   # periodically re-resolve so late DNS/PTR entries appear
            for ip, mac in _nm_arp_scan():
                vendor = _nm_oui_vendor(mac)
                if ip not in rdns:
                    host = ''
                    try:
                        h = socket.gethostbyaddr(ip)[0]
                        if h and h != ip: host = h.rstrip('.')
                    except Exception:
                        host = ''
                    rdns[ip] = host
                host = rdns[ip]
                is_new = store.upsert_device(ip, mac=mac, vendor=vendor, hostname=host or None)
                if is_new and not first_pass:
                    label = host or vendor or ip
                    store.add_alert('warn', 'new_device',
                                    'New device joined: %s (%s)' % (label, ip),
                                    dedup_sec=3600)
            store.mark_stale_offline(180)
            first_pass = False; cyc += 1
        except Exception:
            _exc('_nm_device_worker')
        time.sleep(30)


def _nm_latency_worker(monitor):
    import time
    store = _nm_store()
    if store is None: return
    while True:
        try:
            for name, host in _nm_latency_targets(monitor):
                rtt, loss, jitter = _nm_ping(host, count=5)
                if rtt is None and loss >= 100:
                    store.add_latency(name, 0.0, 100.0, 0.0)
                    store.add_alert('warn', 'latency', '%s (%s) is unreachable' % (name, host))
                    continue
                store.add_latency(name, rtt or 0.0, loss, jitter)
                if loss >= 40:
                    store.add_alert('warn', 'latency', '%s: %.0f%% packet loss' % (name, loss))
                elif name == 'Gateway' and rtt and rtt > 120:
                    store.add_alert('info', 'latency', 'Gateway latency high: %.0f ms' % rtt)
        except Exception:
            _exc('_nm_latency_worker')
        time.sleep(15)


# =============================================================================
#  Monitoring add-ons (Batch 2): push notifications (relay) + firewall block
#  helpers callable from any thread (e.g. the web server).
# =============================================================================
_SEV_RANK = {'info': 0, 'warn': 1, 'crit': 2}


def _nm_notify_config():
    import json, pathlib
    p = pathlib.Path.home() / '.nm_notify.json'
    try:
        if p.exists(): return json.loads(p.read_text())
    except Exception:
        _exc_debug('_nm_notify_config')
    return {}


def _nm_notify_config_save(cfg):
    import json, pathlib
    try:
        (pathlib.Path.home() / '.nm_notify.json').write_text(json.dumps(cfg, indent=2))
        return True
    except Exception:
        _exc('_nm_notify_config_save'); return False


def _nm_notify(title, message, sev='warn', tags='', force=False):
    """Send a push notification via the configured relay. No-op if unconfigured
    or if the alert is below the configured minimum severity. Backends: ntfy
    (default, free, has an iOS/Android app), Pushover, or a generic webhook.
    Pass force=True for user-requested pings (e.g. report ready) so they are
    not suppressed by the alert min-severity threshold."""
    import json, urllib.request, urllib.parse
    cfg = _nm_notify_config()
    backend = (cfg.get('backend') or 'none').lower()
    if backend in ('none', ''):
        return False, 'notifications not configured'
    min_sev = (cfg.get('min_sev') or 'warn').lower()
    if not force and _SEV_RANK.get(sev, 1) < _SEV_RANK.get(min_sev, 1):
        return False, 'below min severity'
    try:
        if backend == 'ntfy':
            topic = (cfg.get('ntfy_topic') or '').strip()
            if not topic: return False, 'no ntfy topic set'
            server = (cfg.get('ntfy_server') or 'https://ntfy.sh').rstrip('/')
            prio = {'info': 'low', 'warn': 'default', 'crit': 'high'}.get(sev, 'default')
            req = urllib.request.Request(
                server + '/' + topic, data=message.encode('utf-8'),
                headers={'Title': title, 'Priority': prio,
                         'Tags': tags or 'warning'}, method='POST')
            urllib.request.urlopen(req, timeout=10).read()
            return True, ''
        if backend == 'pushover':
            tok = cfg.get('pushover_token', ''); usr = cfg.get('pushover_user', '')
            if not (tok and usr): return False, 'pushover token/user missing'
            data = urllib.parse.urlencode({
                'token': tok, 'user': usr, 'title': title, 'message': message,
                'priority': {'info': -1, 'warn': 0, 'crit': 1}.get(sev, 0)}).encode()
            req = urllib.request.Request('https://api.pushover.net/1/messages.json',
                                         data=data, method='POST')
            urllib.request.urlopen(req, timeout=10).read()
            return True, ''
        if backend == 'webhook':
            url = (cfg.get('webhook_url') or '').strip()
            if not url: return False, 'no webhook url set'
            body = json.dumps({'title': title, 'message': message, 'severity': sev}).encode()
            req = urllib.request.Request(url, data=body,
                                         headers={'Content-Type': 'application/json'},
                                         method='POST')
            urllib.request.urlopen(req, timeout=10).read()
            return True, ''
    except Exception as e:
        return False, str(e)
    return False, 'unknown backend'


def _nm_notify_async(title, message, sev='warn', tags='', force=False):
    import threading
    threading.Thread(target=lambda: _nm_notify(title, message, sev, tags, force),
                     daemon=True).start()


# ── Report scheduler (app-lifetime) ────────────────────────────────────────────
# The scheduler used to be bootstrapped only from inside the Report dialog, so it
# never ran after a restart (or unless that window was opened). These module-level
# helpers are started once at app launch and re-read the schedule file each cycle.

def _nm_report_schedule_cfg():
    """Read the persisted report-schedule config (~/.nm_report_schedule.json)."""
    import json, pathlib
    p = pathlib.Path.home() / '.nm_report_schedule.json'
    try:
        if p.exists():
            return json.loads(p.read_text())
    except Exception:
        _exc_debug('_nm_report_schedule_cfg')
    return {}


def _nm_report_next_run(cfg, now=None):
    """Next datetime the schedule should fire (strictly in the future)."""
    from datetime import datetime, timedelta
    now = now or datetime.now()
    freq = (cfg.get('freq') or 'daily').lower()
    try:
        h = int(cfg.get('hour', 6)); m = int(cfg.get('min', 0))
    except Exception:
        h, m = 6, 0
    if freq == 'hourly':
        nxt = now.replace(minute=m, second=0, microsecond=0)
        if nxt <= now:
            nxt += timedelta(hours=1)
    elif freq == 'weekly':
        nxt = now.replace(hour=h, minute=m, second=0, microsecond=0)
        days_ahead = (0 - now.weekday()) % 7          # weekly on Mondays
        if days_ahead == 0 and nxt <= now:            # today already passed -> next week
            days_ahead = 7
        nxt += timedelta(days=days_ahead)
    else:  # daily
        nxt = now.replace(hour=h, minute=m, second=0, microsecond=0)
        if nxt <= now:
            nxt += timedelta(days=1)
    return nxt


def _nm_report_notify(dest):
    """Push a notification that a report was generated. force=True so it is not
    gated by the alert min-severity threshold (the user opts into report pings)."""
    import pathlib
    try:
        name = pathlib.Path(dest).name
        _nm_notify_async('Vanguard Flow NetSentinel',
                         'Network report generated: ' + name,
                         sev='info', tags='page_facing_up', force=True)
    except Exception:
        _exc_debug('_nm_report_notify')


def _nm_run_report_now(monitor, cfg):
    """Generate + save a scheduled report, then notify. Returns the dest path."""
    import pathlib, shutil
    from datetime import datetime
    try:
        hours = int(cfg.get('period', '24') or 24)
    except Exception:
        hours = 24
    save_dir = pathlib.Path(cfg.get('location')
                            or (pathlib.Path.home() / 'Documents' / 'NetworkMonitor'))
    save_dir.mkdir(parents=True, exist_ok=True)
    fname = 'nm_report_' + datetime.now().strftime('%Y%m%d_%H%M%S') + '.html'
    dest = save_dir / fname
    tmp_path = _do_generate(monitor, {'full'}, hours)
    shutil.copy(tmp_path, str(dest))
    _nm_report_notify(dest)
    return dest


def _nm_start_report_scheduler(monitor):
    """Start (once) the app-lifetime report scheduler. Re-reads the schedule file
    every cycle so edits take effect without a restart, and fires at the configured
    time. Launched at startup — this is what makes the scheduler actually run."""
    import threading, time
    from datetime import datetime
    existing = getattr(monitor, '_report_sched_thread', None)
    if existing is not None and existing.is_alive():
        return existing

    def _worker():
        last_key = None
        while True:
            try:
                cfg = _nm_report_schedule_cfg()
                if cfg.get('enabled'):
                    now = datetime.now()
                    nxt = _nm_report_next_run(cfg, now)
                    secs = (nxt - now).total_seconds()
                    if secs <= 30:
                        if secs > 0:
                            time.sleep(secs)
                        key = nxt.strftime('%Y%m%d%H%M')
                        if key != last_key:               # fire once per slot
                            last_key = key
                            try:
                                _nm_run_report_now(monitor, _nm_report_schedule_cfg())
                            except Exception as ex:
                                print('[Scheduler] report error:', ex)
                                _exc('_nm_start_report_scheduler.fire')
                        time.sleep(60)                    # step past this minute
                        continue
                time.sleep(30)                            # re-poll (picks up edits)
            except Exception:
                _exc('_nm_start_report_scheduler.loop')
                time.sleep(60)

    t = threading.Thread(target=_worker, daemon=True, name='nm_report_scheduler')
    t.start()
    monitor._report_sched_thread = t
    return t


def _nm_whois(ip):
    """Raw WHOIS lookup via IANA referral. Returns (summary_dict, raw_text).
    Private/reserved addresses short-circuit (no public WHOIS to query)."""
    import socket, ipaddress
    try:
        ipobj = ipaddress.ip_address(ip)
    except Exception:
        return {'error': 'invalid IP address'}, ''
    if (ipobj.is_private or ipobj.is_loopback or ipobj.is_link_local
            or ipobj.is_reserved or ipobj.is_multicast):
        return {'note': 'Private / local address \u2014 no public WHOIS record'}, ''

    def _q(server, query):
        s = socket.create_connection((server, 43), timeout=6)
        try:
            s.sendall((query + '\r\n').encode())
            data = b''
            while len(data) < 131072:
                chunk = s.recv(8192)
                if not chunk:
                    break
                data += chunk
        finally:
            try: s.close()
            except Exception: _exc_debug('_q')
        return data.decode('utf-8', 'replace')

    try:
        r = _q('whois.iana.org', ip)
        refer = None
        for line in r.splitlines():
            ll = line.lower()
            if ll.startswith('refer:') or ll.startswith('whois:'):
                refer = line.split(':', 1)[1].strip()
        if refer:
            try:
                r = _q(refer, ip)
            except Exception:
                _exc_debug('_nm_whois')
        fields = {}
        wanted = {'netname': 'netname', 'orgname': 'org', 'org-name': 'org',
                  'organisation': 'org', 'organization': 'org', 'owner': 'org',
                  'descr': 'descr', 'country': 'country', 'inetnum': 'range',
                  'netrange': 'range', 'cidr': 'cidr'}
        for line in r.splitlines():
            if ':' not in line or line[:1] in ('%', '#'):
                continue
            k, v = line.split(':', 1)
            k = k.strip().lower(); v = v.strip()
            if v and k in wanted and wanted[k] not in fields:
                fields[wanted[k]] = v
        return fields, r
    except Exception as e:
        return {'error': str(e)}, ''


_NM_FW_LOG_PATHS = [
    r'C:\Windows\System32\LogFiles\Firewall\pfirewall.log',
    r'C:\Windows\SysWOW64\LogFiles\Firewall\pfirewall.log',
]


def _nm_firewall_log_path():
    """Return the Windows Firewall log file, or None if it doesn't exist."""
    from pathlib import Path
    import os
    if os.name != 'nt':
        return None
    for p in _NM_FW_LOG_PATHS:
        try:
            if Path(p).exists():
                return p
        except Exception:
            _exc_debug('_nm_firewall_log_path')
    return None


def _nm_firewall_logging_status():
    """Is the firewall logging dropped packets? Returns (on, error).

    Callers unpack this as a tuple, so the shape must not change.
    """
    be = _nm_fw_backend()
    if not be:
        return False, ('firewall logging needs nftables on Linux'
                       if not _NM_IS_WIN else 'firewall unavailable')
    st = _nm_fw_logging_status()
    if not st.get('ok'):
        return False, 'could not read the firewall logging state'
    return bool(st.get('dropped')), ''


def _nm_firewall_enable_logging():
    """Turn on dropped-packet logging (needs Administrator / root)."""
    return _nm_fw_set_logging(True)


def _nm_parse_fw_log(hours=24, limit_lines=400000):
    """Parse pfirewall.log and return DROP events as dicts.

    Format: #Fields: date time action protocol src-ip dst-ip src-port dst-port ...
    Reads the tail of the file so a large log stays fast.
    """
    from datetime import datetime, timedelta
    path = _nm_firewall_log_path()
    if not path:
        return [], 'Firewall log not found (enable logging, then block something).'
    try:
        with open(path, 'r', errors='replace') as f:
            lines = f.readlines()[-limit_lines:]
    except PermissionError:
        return [], 'Access denied reading the firewall log — run the app as Administrator.'
    except Exception as e:
        return [], 'Could not read firewall log: %s' % e
    fields = []
    cutoff = datetime.now() - timedelta(hours=hours) if hours else None
    out = []
    for line in lines:
        line = line.strip()
        if not line:
            continue
        if line.startswith('#'):
            if line.lower().startswith('#fields:'):
                fields = line[8:].strip().split()
            continue
        parts = line.split()
        row = dict(zip(fields, parts)) if fields else dict(zip(
            ['date', 'time', 'action', 'protocol', 'src-ip', 'dst-ip',
             'src-port', 'dst-port'], parts))
        if (row.get('action', '') or '').upper() != 'DROP':
            continue
        if cutoff is not None:
            try:
                ts = datetime.strptime('%s %s' % (row.get('date', ''), row.get('time', '')),
                                       '%Y-%m-%d %H:%M:%S')
                if ts < cutoff:
                    continue
                row['_ts'] = ts
            except Exception:
                _exc_debug('_nm_parse_fw_log ts')
        out.append(row)
    return out, ''


def _nm_firewall_hits(hours=24):
    """How many times each IP was blocked, from the firewall's DROP log.

    Returns (dict ip -> {count, last, ports, dirs}, error). Counts both an IP
    appearing as the source (inbound attempt) and as the destination (this
    machine trying to reach it outbound).
    """
    rows, err = _nm_parse_fw_log(hours=hours)
    if err:
        return {}, err
    hits = {}
    for r in rows:
        for key, direction in (('src-ip', 'in'), ('dst-ip', 'out')):
            ip = r.get(key, '')
            if not ip or ip in ('-', '0.0.0.0'):
                continue
            h = hits.setdefault(ip, {'count': 0, 'last': '', 'ports': {}, 'dirs': set()})
            h['count'] += 1
            h['dirs'].add(direction)
            ts = '%s %s' % (r.get('date', ''), r.get('time', ''))
            if ts.strip() and ts > h['last']:
                h['last'] = ts.strip()
            port = r.get('dst-port', '')
            if port and port != '-':
                h['ports'][port] = h['ports'].get(port, 0) + 1
    for h in hits.values():
        h['dirs'] = sorted(h['dirs'])
        h['top_ports'] = sorted(h['ports'].items(), key=lambda x: -x[1])[:5]
        del h['ports']
    return hits, ''


_NM_FW_HITS_CACHE = {'t': 0.0, 'hits': {}, 'err': '', 'logging': None}


def _nm_fw_hits_cached(hours=24, ttl=10.0):
    """_nm_firewall_hits with a short TTL cache — a menu popup shouldn't
    re-parse the whole firewall log on every right-click."""
    import time
    c = _NM_FW_HITS_CACHE
    if time.time() - c['t'] < ttl and c['logging'] is not None:
        return c['hits'], c['err'], c['logging']
    hits, err = _nm_firewall_hits(hours=hours)
    on, _ = _nm_firewall_logging_status()
    c.update({'t': time.time(), 'hits': hits, 'err': err, 'logging': on})
    return hits, err, on


def _nm_fw_menu_lines(ip):
    """Status lines describing this IP's blocked-connection attempts, for the
    right-click menus. Always returns something so 'no attempts' is visibly
    different from the feature being broken. Returns (lines, offer_enable)."""
    try:
        hits, err, logging_on = _nm_fw_hits_cached()
    except Exception:
        _exc_debug('_nm_fw_menu_lines')
        return ['\u26a0  Could not read the firewall log'], False
    h = hits.get(ip)
    if h:
        lines = ['\u26d4  %d blocked attempts (24h)  \u00b7  last %s'
                 % (h['count'], h['last'] or '?')]
        if h.get('top_ports'):
            lines.append('     ports: ' + ', '.join('%s(%d)' % (p, c)
                                                    for p, c in h['top_ports']))
        return lines, False
    if err:
        # Most common: log missing, or not running as Administrator.
        return ['\u26a0  ' + err[:70]], ('not found' in err.lower())
    if not logging_on:
        return ['\u26a0  Firewall drop logging is OFF \u2014 nothing is counted'], True
    return ['\u2713  No blocked attempts logged (24h)'], False


def _nm_list_blocked():
    """IPs currently blocked by this app's NM_BLOCK_ rules."""
    out = []
    for name in _nm_fw_list_rules('NM_BLOCK_'):
        ip = name[len('NM_BLOCK_'):].replace('_', '.')
        if ip and ip not in out:
            out.append(ip)
    return out


# ── Attack drill (server-side) ───────────────────────────────────────────────
# Single source of truth so every view — web 3D/radar, web Sankey and the
# desktop EtherApe window — shows the same synthetic hostiles. Addresses come
# from the reserved TEST-NET documentation ranges and are labelled SIM, so a
# drill can never be confused with real traffic or block a real host.
_NM_ATTACK_ON = False
_NM_ATTACK_HOSTS = []
_NM_ATTACK_LOCK = threading.Lock()
_NM_ATTACK_LAST = 0.0
_NM_ATTACK_POOL = [
    ('198.51.100.7',   'Moscow',      55.75,  37.62,  'tcp', 'SSH brute force'),
    ('198.51.100.23',  'Beijing',     39.91,  116.39, 'tcp', 'port scan'),
    ('203.0.113.44',   'Sao Paulo',  -23.55, -46.63,  'udp', 'UDP flood'),
    ('192.0.2.88',     'Lagos',        6.52,   3.38,  'tcp', 'RDP probe'),
    ('203.0.113.101',  'Mumbai',      19.08,  72.88,  'tcp', 'SMB exploit'),
    ('198.51.100.66',  'Kyiv',        50.45,  30.52,  'tcp', 'credential stuffing'),
    ('192.0.2.150',    'Seoul',       37.57, 126.98,  'udp', 'DNS amplification'),
    ('203.0.113.9',    'Amsterdam',   52.37,   4.90,  'tcp', 'vuln scanner'),
    ('198.51.100.201', 'Istanbul',    41.01,  28.98,  'tcp', 'web shell probe'),
    ('192.0.2.33',     'Jakarta',     -6.21, 106.85,  'tcp', 'botnet beacon'),
    ('203.0.113.222',  'Mexico City', 19.43, -99.13,  'udp', 'NTP reflection'),
    ('198.51.100.140', 'Sydney',     -33.87, 151.21,  'tcp', 'SQL injection'),
    ('192.0.2.210',    'Cairo',       30.04,  31.24,  'tcp', 'telnet sweep'),
    ('203.0.113.77',   'Toronto',     43.65, -79.38,  'tcp', 'proxy abuse'),
]


_NM_ATTACK_THREAD = None


def _nm_attack_worker():
    """Advance the drill on its own clock. Previously it only ticked inside the
    topology endpoint, which early-returns when no capture is running — so
    nothing ever spawned."""
    while True:
        try:
            if not _NM_ATTACK_ON:
                return
            _nm_attack_tick()
        except Exception:
            _exc_debug('_nm_attack_worker')
        time.sleep(0.4)


def _nm_attack_set(on):
    """Turn the drill on or off. Off clears hostiles immediately."""
    global _NM_ATTACK_ON, _NM_ATTACK_THREAD
    with _NM_ATTACK_LOCK:
        _NM_ATTACK_ON = bool(on)
        if not _NM_ATTACK_ON:
            _NM_ATTACK_HOSTS[:] = []
    if _NM_ATTACK_ON and (_NM_ATTACK_THREAD is None or not _NM_ATTACK_THREAD.is_alive()):
        _NM_ATTACK_THREAD = threading.Thread(target=_nm_attack_worker, daemon=True)
        _NM_ATTACK_THREAD.start()
    return _NM_ATTACK_ON


def _nm_attack_tick():
    """Advance the drill: spawn hostiles, ramp traffic, block and retire them."""
    global _NM_ATTACK_LAST
    import random
    now = time.time()
    with _NM_ATTACK_LOCK:
        if _NM_ATTACK_ON and now - _NM_ATTACK_LAST > 0.85 and len(_NM_ATTACK_HOSTS) < 12:
            _NM_ATTACK_LAST = now
            live = {h['ip'] for h in _NM_ATTACK_HOSTS}
            free = [p for p in _NM_ATTACK_POOL if p[0] not in live]
            if free:
                ip, city, lat, lon, proto, kind = random.choice(free)
                _NM_ATTACK_HOSTS.append({
                    'ip': ip, 'city': city, 'lat': lat, 'lon': lon,
                    'proto': proto, 'kind': kind, 'state': 'detected',
                    'bytes': 12000 + random.random() * 40000,
                    'pkts': 20 + int(random.random() * 60),
                    'born': now, 'block_at': now + 1.2 + random.random() * 2.8,
                })
        for h in list(_NM_ATTACK_HOSTS):
            if h['state'] == 'detected':
                h['bytes'] += 18000 + random.random() * 70000
                h['pkts'] += 5 + int(random.random() * 25)
                if now >= h['block_at']:
                    h['state'] = 'blocked'
                    h['blocked_at'] = now
                    # Same event stream real blocks use, so the UI treats them alike.
                    _nm_record_block(h['ip'], 'SIM drill: ' + h['kind'],
                                     lat=h['lat'], lon=h['lon'], city=h['city'])
            elif now - h.get('blocked_at', now) > 1.2:
                _NM_ATTACK_HOSTS.remove(h)
        return [dict(h) for h in _NM_ATTACK_HOSTS]


def _nm_attack_hosts():
    with _NM_ATTACK_LOCK:
        return [dict(h) for h in _NM_ATTACK_HOSTS]


# Recent firewall blocks, newest last. The 3D/radar view detonates a marker for
# each one, so an explosion on screen always means a real rule was written.
_NM_BLOCK_EVENTS = []
_NM_BLOCK_EVENTS_LOCK = threading.Lock()


def _nm_record_block(ip, reason='', lat=None, lon=None, city=''):
    """Log that a firewall rule was written for `ip` so the UI can show it.
    lat/lon may be supplied when the caller already knows them (drill hosts are
    retired within a couple of seconds, so the geo cache cannot be relied on)."""
    try:
        with _NM_BLOCK_EVENTS_LOCK:
            _NM_BLOCK_EVENTS.append({'ip': ip, 'ts': time.time(),
                                     'reason': reason or 'firewall rule added',
                                     'lat': lat, 'lon': lon, 'city': city})
            if len(_NM_BLOCK_EVENTS) > 200:
                del _NM_BLOCK_EVENTS[:-200]
    except Exception:
        _exc_debug('_nm_record_block')


def _nm_block_events_geo(geo=None):
    """Recent blocks with lat/lon attached where the geo cache knows them."""
    out = []
    try:
        geo = geo or {}
        for e in _nm_recent_blocks(20.0):
            # geo is the caller's resolved cache; there is no module-level one.
            g = geo.get(e['ip']) or {}
            out.append({'ip': e['ip'], 'ts': round(e['ts'], 2),
                        'reason': e.get('reason', ''),
                        # coordinates recorded with the event win, since the host
                        # may already have been retired from the geo cache
                        'lat': e.get('lat') if e.get('lat') is not None else g.get('lat'),
                        'lon': e.get('lon') if e.get('lon') is not None else g.get('lon'),
                        'city': e.get('city') or g.get('city', ''),
                        'country': g.get('country', '')})
    except Exception:
        _exc_debug('_nm_block_events_geo')
    return out


def _nm_recent_blocks(within=20.0):
    """Blocks written in the last `within` seconds."""
    try:
        cut = time.time() - within
        with _NM_BLOCK_EVENTS_LOCK:
            return [dict(e) for e in _NM_BLOCK_EVENTS if e['ts'] >= cut]
    except Exception:
        _exc_debug('_nm_recent_blocks')
        return []


def _nm_firewall_block(ip):
    """Block a remote IP in both directions. Returns (ok, error).

    Backend-agnostic: netsh on Windows, nftables on Linux. Rule naming
    (NM_BLOCK_<ip>) is preserved on both so existing rules keep working.
    """
    import re
    if not re.match(r'^\d{1,3}(?:\.\d{1,3}){3}$', ip or ''):
        return False, 'invalid IPv4 address'
    be = _nm_fw_backend()
    if not be:
        return False, ('firewall control needs nftables on Linux'
                       if not _NM_IS_WIN else 'firewall unavailable')
    rule = 'NM_BLOCK_' + ip.replace('.', '_')
    ok, err = _nm_fw_add_block(rule, ip, ('in', 'out'))
    if ok:
        _nm_record_block(ip)          # drives the on-screen detonation
    return ok, err


def _nm_firewall_unblock(ip):
    import re
    if not re.match(r'^\d{1,3}(?:\.\d{1,3}){3}$', ip or ''):
        return False, 'invalid IPv4 address'
    if not _nm_fw_backend():
        return False, 'firewall unavailable'
    return _nm_fw_delete_rule('NM_BLOCK_' + ip.replace('.', '_'))


_NM_KILL_RULE = 'NM_KILLSWITCH'


def _nm_killswitch_active():
    """True when the block-all kill-switch rules are installed."""
    return _nm_fw_rule_exists(_NM_KILL_RULE)


def _nm_killswitch_set(on):
    """Cut (or restore) all network traffic.

    Loopback is never filtered by either backend, so the local dashboard on
    127.0.0.1 stays reachable and the connection can be restored from the same
    UI that cut it.
    """
    be = _nm_fw_backend()
    if not be:
        return False, ('kill switch needs nftables on Linux'
                       if not _NM_IS_WIN else 'firewall unavailable')
    if on:
        return _nm_fw_add_block(_NM_KILL_RULE, None, ('in', 'out'))
    ok, err = _nm_fw_delete_rule(_NM_KILL_RULE)
    return ok, ('' if ok else err)


# =============================================================================
#  Monitoring add-ons (Batch 3): threat-intel feeds + GeoIP anomaly detection.
# =============================================================================
_NM_THREAT_META = {'ips': 0, 'ranges': 0, 'refreshed': 0, 'sources': []}


class _ThreatMatcher:
    """Fast membership test for a set of malicious IPs + CIDR ranges."""
    def __init__(self):
        self.ips = set()
        self._starts = []; self._ends = []
        self.meta = {'ips': 0, 'ranges': 0, 'refreshed': 0, 'sources': []}

    def load_lines(self, lines, source):
        import ipaddress, re
        for ln in lines:
            ln = ln.strip()
            if not ln or ln[0] in ';#': continue
            tok = ln.split()[0].split(';')[0].strip()
            if '/' in tok:
                try:
                    net = ipaddress.ip_network(tok, strict=False)
                    if net.version == 4:
                        self._starts.append(int(net.network_address))
                        self._ends.append(int(net.broadcast_address))
                except Exception:
                    _exc_debug('load_lines')
            elif re.match(r'^\d{1,3}(?:\.\d{1,3}){3}$', tok):
                self.ips.add(tok)

    def finalize(self):
        if self._starts:
            order = sorted(range(len(self._starts)), key=lambda i: self._starts[i])
            self._starts = [self._starts[i] for i in order]
            self._ends = [self._ends[i] for i in order]
        self.meta['ips'] = len(self.ips); self.meta['ranges'] = len(self._starts)

    def match(self, ip):
        import bisect, ipaddress
        if ip in self.ips: return True
        if not self._starts: return False
        try: v = int(ipaddress.IPv4Address(ip))
        except Exception: return False
        i = bisect.bisect_right(self._starts, v) - 1
        return 0 <= i < len(self._starts) and v <= self._ends[i]


def _nm_threat_feeds(monitor):
    feeds = [
        ('Emerging Threats', 'https://rules.emergingthreats.net/fwrules/emerging-Block-IPs.txt'),
        ('Feodo C2', 'https://feodotracker.abuse.ch/downloads/ipblocklist.txt'),
        ('ET Compromised', 'https://rules.emergingthreats.net/blockrules/compromised-ips.txt'),
    ]
    try:
        for e in (monitor.config.get('threat_feeds') or []):
            if isinstance(e, (list, tuple)) and len(e) == 2:
                feeds.append((str(e[0]), str(e[1])))
    except Exception:
        _exc_debug('_nm_threat_feeds')
    return feeds


def _nm_build_matcher(feeds):
    """Download each feed (cache to disk; fall back to cached copy offline),
    parse into a matcher."""
    import urllib.request, pathlib, time, re
    cache = pathlib.Path.home() / '.nm_threatintel'
    try: cache.mkdir(exist_ok=True)
    except Exception: _exc_debug('_nm_build_matcher')
    m = _ThreatMatcher(); srcs = []
    for name, url in feeds:
        fn = cache / (re.sub(r'[^a-zA-Z0-9]', '_', name) + '.txt')
        text = None
        try:
            req = urllib.request.Request(url, headers={'User-Agent': 'NetworkMonitor/1.0'})
            text = urllib.request.urlopen(req, timeout=25).read().decode('utf-8', 'replace')
            try: fn.write_text(text)
            except Exception: _exc_debug('_nm_build_matcher')
        except Exception:
            try: text = fn.read_text()
            except Exception: text = None
        if text:
            m.load_lines(text.splitlines(), name); srcs.append(name)
    m.finalize(); m.meta['refreshed'] = time.time(); m.meta['sources'] = srcs
    return m


def _nm_active_externals(monitor):
    """Return {ip: country} for external flow endpoints of the active capture."""
    import ipaddress
    ea = _active_ea()
    if not ea: return {}
    try:
        flows = dict(ea._flows); geo = dict(ea._geo_cache)
    except Exception:
        return {}
    def _pub(ip):
        try:
            a = ipaddress.ip_address(ip)
            return not (a.is_private or a.is_loopback or a.is_link_local
                        or a.is_multicast or a.is_reserved or a.is_unspecified)
        except Exception:
            return False
    out = {}
    for key in list(flows.keys()):
        try: s, d, _p = key
        except Exception: continue
        for ip in (s, d):
            if _pub(ip):
                out[ip] = (geo.get(ip, {}) or {}).get('country', '')
    return out


def _nm_intel_worker(monitor):
    import time
    store = _nm_store()
    if store is None: return
    matcher = None; last_refresh = 0.0; first_pass = True; hit_seen = set()
    while True:
        try:
            now = time.time()
            if matcher is None or now - last_refresh > 8 * 3600:
                try:
                    matcher = _nm_build_matcher(_nm_threat_feeds(monitor))
                    _NM_THREAT_META.update(matcher.meta)
                except Exception:
                    _exc('_nm_build_matcher')
                last_refresh = now
            for ip, country in _nm_active_externals(monitor).items():
                if matcher and ip not in hit_seen and matcher.match(ip):
                    hit_seen.add(ip)
                    store.add_alert('crit', 'threatintel',
                                    'Traffic to known-malicious IP %s' % ip, dedup_sec=3600)
                if country:
                    prior = store.geo_count()
                    new = store.geo_seen(country)
                    if new and not first_pass and prior >= 4:
                        store.add_alert('warn', 'geo',
                                        'First-ever traffic to %s (%s)' % (country, ip),
                                        dedup_sec=6 * 3600)
            first_pass = False
        except Exception:
            _exc('_nm_intel_worker')
        time.sleep(60)


# =============================================================================
#  Monitoring add-ons (Batch 4): historical analytics + scheduled AI briefing.
# =============================================================================
def _nm_human(b):
    b = float(b or 0)
    if b >= 1e9: return '%.1f GB' % (b / 1e9)
    if b >= 1e6: return '%.1f MB' % (b / 1e6)
    if b >= 1e3: return '%.0f KB' % (b / 1e3)
    return '%.0f B' % b


def _nm_traffic_worker(monitor):
    """Sample per-local-device cumulative bytes from the active capture and
    store deltas, for 'who's hogging the line' analytics."""
    import time, ipaddress
    store = _nm_store()
    if store is None: return
    prev = {}
    def _priv(ip):
        try: return ipaddress.ip_address(ip).is_private
        except Exception: return False
    while True:
        try:
            ea = _active_ea()
            if ea:
                nodes = dict(ea._nodes)
                for ip, nd in nodes.items():
                    if not _priv(ip): continue
                    b = float((nd or {}).get('bytes', 0) or 0)
                    p = prev.get(ip)
                    if p is not None:
                        delta = (b - p) if b >= p else b   # capture reset -> use current
                        if delta > 0: store.add_traffic(ip, delta)
                    prev[ip] = b
        except Exception:
            _exc('_nm_traffic_worker')
        time.sleep(60)


def _nm_analytics(monitor, store):
    out = {'ok': True}
    def _stats(a):
        a = [float(x) for x in a if x is not None]
        if not a: return {}
        s = sorted(a); n = len(s)
        return {'avg': sum(s) / n, 'min': s[0], 'max': s[-1], 'p50': s[n // 2], 'count': n}
    try:
        db = getattr(monitor, '_db', None)
        data = db.load_data(limit=5000) if db else {}
        dl = data.get('download', []) or []; ul = data.get('upload', []) or []
        pg = data.get('ping', []) or []
        out['speed'] = {'download': _stats(dl), 'upload': _stats(ul), 'ping': _stats(pg),
                        'download_series': [x for x in dl[-60:] if x is not None]}
    except Exception as e:
        out['speed'] = {'error': str(e)}
    try: out['latency'] = store.latency_latest()
    except Exception: out['latency'] = {}
    try: out['uptime'] = store.uptime('Gateway', 86400)
    except Exception: out['uptime'] = None
    try:
        tt = store.top_traffic(86400, 8)
        dm = {d['ip']: (d.get('name') or d.get('vendor') or d['ip']) for d in store.list_devices()}
        out['top_devices'] = [{'ip': r['ip'], 'name': dm.get(r['ip'], r['ip']),
                               'bytes': r['total']} for r in tt]
    except Exception:
        out['top_devices'] = []
    return out


def _nm_briefing_context(monitor, store):
    import time
    an = _nm_analytics(monitor, store)
    L = []
    sp = an.get('speed', {}) or {}
    if sp.get('download'):
        L.append('Speed (recent): download avg %.0f / max %.0f Mbps, upload avg %.0f Mbps, ping avg %.0f ms.'
                 % (sp['download'].get('avg', 0), sp['download'].get('max', 0),
                    sp.get('upload', {}).get('avg', 0), sp.get('ping', {}).get('avg', 0)))
    up = an.get('uptime')
    if up is not None: L.append('Gateway reachability last 24h: %.1f%%.' % up)
    alerts = [a for a in store.list_alerts(300) if a['ts'] > time.time() - 86400]
    if alerts:
        bk = {}
        for a in alerts: bk[a['kind']] = bk.get(a['kind'], 0) + 1
        L.append('Alerts (24h): ' + ', '.join('%s=%d' % (k, v) for k, v in bk.items()) + '.')
    else:
        L.append('No alerts in the last 24 hours.')
    nd = [d for d in store.list_devices() if (d.get('first_seen') or 0) > time.time() - 86400]
    if nd:
        L.append('New devices seen: ' + ', '.join(
            (d.get('name') or d.get('vendor') or d['ip']) for d in nd[:8]) + '.')
    td = an.get('top_devices', [])
    if td:
        L.append('Top local talkers today: ' + ', '.join(
            '%s (%s)' % (t['name'], _nm_human(t['bytes'])) for t in td[:5]) + '.')
    lat = an.get('latency', {}) or {}
    if lat:
        L.append('Latency now: ' + ', '.join(
            '%s %.0fms/%.0f%%loss' % (k, v.get('rtt', 0), v.get('loss', 0))
            for k, v in lat.items()) + '.')
    L.append('Threat feeds: %d malicious IPs / %d ranges loaded; %d countries seen total.'
             % (_NM_THREAT_META.get('ips', 0), _NM_THREAT_META.get('ranges', 0), store.geo_count()))
    return '\n'.join(L)


def _nm_generate_briefing(monitor, store):
    ctx = _nm_briefing_context(monitor, store)
    prompt = ('You are a friendly network-operations assistant. Write a short daily '
              'briefing (4-7 sentences, plain text, no markdown) summarising this home '
              "network's last 24 hours and calling out anything worth attention. "
              'Be reassuring if all is normal. Data:\n\n' + ctx)
    text, err = _nm_ai_complete(prompt, want_json=False, timeout=120)
    if not text:
        text = ('AI briefing unavailable (' + (err or 'no response') +
                ').\n\nRaw summary:\n' + ctx)
    try: store.add_briefing(text)
    except Exception: _exc('_nm_generate_briefing')
    return text


def _nm_briefing_worker(monitor):
    import time, datetime
    store = _nm_store()
    if store is None: return
    while True:
        try:
            try: hour = int(monitor.config.get('briefing_hour', 8) or 8)
            except Exception: hour = 8
            now = datetime.datetime.now()
            last = store.latest_briefing()
            done_today = bool(last and
                              datetime.datetime.fromtimestamp(last['ts']).date() == now.date())
            if now.hour >= hour and not done_today:
                text = _nm_generate_briefing(monitor, store)
                _nm_notify_async('Daily network briefing', text[:380], 'info', 'briefing')
        except Exception:
            _exc('_nm_briefing_worker')
        time.sleep(600)


# =============================================================================
#  Monitoring add-ons (Batch 5): VDI session monitoring (Blast / PCoIP / RDP).
#  Sessions are detected from active TCP connections (netstat/ss) on VDI display
#  ports; latency comes from pinging the host, bandwidth from correlating the
#  host with live capture byte counts. Health is scored to VDI thresholds.
# =============================================================================
_NM_VDI_PORTS = {3389: 'RDP', 4172: 'PCoIP', 22443: 'Blast Extreme', 8443: 'Blast (UAG)'}
_NM_VDI_SESSIONS = {'ts': 0, 'sessions': []}


def _nm_vdi_ports(monitor):
    ports = dict(_NM_VDI_PORTS)
    try:
        for e in (monitor.config.get('vdi_ports') or []):
            if isinstance(e, (list, tuple)) and len(e) == 2:
                ports[int(e[0])] = str(e[1])
    except Exception:
        _exc_debug('_nm_vdi_ports')
    return ports


def _nm_netstat_conns():
    """Established TCP connections as [{local_ip,local_port,remote_ip,remote_port}].
    Works with Windows netstat and Linux/mac ss/netstat output."""
    import subprocess, re
    out = ''
    for cmd in (['netstat', '-n'], ['ss', '-tn'], ['netstat', '-tn']):
        try:
            r = subprocess.run(cmd, capture_output=True, text=True, timeout=8)
            if r.stdout.strip(): out = r.stdout; break
        except Exception:
            continue
    pair = re.compile(r'(\d{1,3}(?:\.\d{1,3}){3}):(\d+)')
    conns = []
    for line in out.splitlines():
        if 'estab' not in line.lower():
            continue
        m = pair.findall(line)
        if len(m) >= 2:
            (lip, lport), (rip, rport) = m[0], m[1]
            conns.append({'local_ip': lip, 'local_port': int(lport),
                          'remote_ip': rip, 'remote_port': int(rport)})
    return conns


def _nm_vdi_health(rtt, loss):
    if rtt is None:
        return ('unknown', '#6a9ab8')
    if (loss or 0) >= 5 or rtt >= 150:
        return ('poor', '#ff5b5b')
    if (loss or 0) >= 1 or rtt >= 80:
        return ('fair', '#ff9f43')
    return ('good', '#39ff14')


def _nm_vdi_detect(monitor):
    """Group established connections on VDI ports by remote host."""
    ports = _nm_vdi_ports(monitor)
    hosts = {}
    for c in _nm_netstat_conns():
        p = (c['remote_port'] if c['remote_port'] in ports
             else (c['local_port'] if c['local_port'] in ports else None))
        if p is None:
            continue
        rip = c['remote_ip']
        h = hosts.get(rip)
        if h is None:
            hosts[rip] = {'host': rip, 'proto': ports[p], 'port': p,
                          'client': c['local_ip'], 'conns': 1}
        else:
            h['conns'] += 1
    return hosts


def _nm_vdi_worker(monitor):
    import time
    store = _nm_store()
    prev_bytes = {}; prev_ts = {}; poor_alerted = {}
    while True:
        try:
            hosts = _nm_vdi_detect(monitor)
            nodes = {}
            ea = _active_ea()
            if ea:
                try: nodes = dict(ea._nodes)
                except Exception: nodes = {}
            now = time.time(); sessions = []
            live = set(hosts.keys())
            for rip, s in hosts.items():
                rtt, loss, _j = _nm_ping(rip, count=4)
                bw = None
                nd = nodes.get(rip)
                if nd is not None:
                    b = float((nd or {}).get('bytes', 0) or 0)
                    pb = prev_bytes.get(rip); pt = prev_ts.get(rip)
                    if pb is not None and pt and now > pt and b >= pb:
                        bw = (b - pb) / (now - pt)
                    prev_bytes[rip] = b; prev_ts[rip] = now
                health, color = _nm_vdi_health(rtt, loss)
                sessions.append({'host': rip, 'client': s['client'], 'proto': s['proto'],
                                 'port': s['port'], 'conns': s['conns'], 'rtt': rtt,
                                 'loss': loss, 'bw': bw, 'health': health, 'color': color})
                if health == 'poor' and not poor_alerted.get(rip):
                    poor_alerted[rip] = True
                    if store:
                        store.add_alert('warn', 'vdi',
                            '%s VDI session to %s degraded: %s ms / %s%% loss' % (
                                s['proto'], rip,
                                ('%.0f' % rtt) if rtt is not None else '?',
                                ('%.0f' % loss) if loss is not None else '?'),
                            dedup_sec=600)
                elif health in ('good', 'fair'):
                    poor_alerted.pop(rip, None)
            for k in list(poor_alerted.keys()):
                if k not in live: poor_alerted.pop(k, None)
            _NM_VDI_SESSIONS['ts'] = now
            _NM_VDI_SESSIONS['sessions'] = sorted(
                sessions, key=lambda x: {'poor': 0, 'fair': 1, 'good': 2, 'unknown': 3}[x['health']])
        except Exception:
            _exc('_nm_vdi_worker')
        time.sleep(15)


def _nm_find_ollama():
    """Locate the ollama binary. PATH first, then the standard install
    locations — on Windows especially, Ollama is often installed but not on the
    PATH of the running process, which would otherwise silently skip start-up."""
    import os, shutil
    from pathlib import Path
    exe = shutil.which('ollama')
    if exe:
        return exe
    cands = []
    if os.name == 'nt':
        for env in ('LOCALAPPDATA', 'PROGRAMFILES', 'PROGRAMFILES(X86)', 'USERPROFILE'):
            base = os.environ.get(env)
            if not base:
                continue
            cands += [Path(base) / 'Programs' / 'Ollama' / 'ollama.exe',
                      Path(base) / 'Ollama' / 'ollama.exe',
                      Path(base) / 'AppData' / 'Local' / 'Programs' / 'Ollama' / 'ollama.exe']
    else:
        cands += [Path('/usr/local/bin/ollama'), Path('/usr/bin/ollama'),
                  Path('/opt/homebrew/bin/ollama'),
                  Path('/Applications/Ollama.app/Contents/Resources/ollama'),
                  Path.home() / '.ollama' / 'bin' / 'ollama']
    for c in cands:
        try:
            if c.is_file():
                return str(c)
        except Exception:
            continue
    return None


_NM_DEFAULT_MODEL = 'llama3.2'


def _nm_ensure_model(base, exe=None):
    """Make sure the default model (llama3.2) is installed in Ollama, pulling it
    if missing, and make it the app's model on first run. llama3.2 is small and
    non-'thinking', so capture/AI prompts answer in seconds rather than minutes.
    A marker file records that the default was applied once, so any model the
    user picks later is respected and never silently overwritten."""
    import json as _j, urllib.request, subprocess, os
    from pathlib import Path
    model = _NM_DEFAULT_MODEL
    mf = Path.home() / '.nm_ai_model'
    marker = Path.home() / '.nm_ai_model_defaulted'

    def _installed():
        """Return the set of model names Ollama currently has."""
        try:
            with urllib.request.urlopen(base + '/api/tags', timeout=8) as r:
                data = _j.loads(r.read().decode())
            return {(m.get('name') or '') for m in (data.get('models') or [])}
        except Exception:
            return None

    names = _installed()
    if names is None:
        log.info('[ollama] could not list models; skipping model provisioning')
        return
    have = any(n == model or n.startswith(model + ':') for n in names)

    if not have:
        log.info('[ollama] default model %r missing \u2014 pulling it now '
                 '(first run only, ~2GB)', model)
        pulled = False
        try:                      # preferred: pull through the HTTP API
            req = urllib.request.Request(
                base + '/api/pull',
                data=_j.dumps({'name': model, 'stream': False}).encode(),
                headers={'Content-Type': 'application/json'}, method='POST')
            with urllib.request.urlopen(req, timeout=3600) as r:
                r.read()
            pulled = True
        except Exception:
            _exc('[ollama] api pull')
        if not pulled and exe:    # fallback: the CLI
            try:
                kw = {'stdout': subprocess.DEVNULL, 'stderr': subprocess.DEVNULL,
                      'stdin': subprocess.DEVNULL}
                if os.name == 'nt':
                    kw['creationflags'] = getattr(subprocess, 'CREATE_NO_WINDOW', 0)
                pulled = subprocess.call([exe, 'pull', model], **kw) == 0
            except Exception:
                _exc('[ollama] cli pull')
        names = _installed() or set()
        have = any(n == model or n.startswith(model + ':') for n in names)
        log.info('[ollama] pull %s', 'succeeded' if have else 'did not complete')

    if not have:
        return

    # Make it the app default: on first run, or if the configured model is gone.
    try:
        current = mf.read_text().strip() if mf.exists() else ''
    except Exception:
        current = ''
    cur_ok = bool(current) and any(n == current or n.startswith(current + ':')
                                  for n in (names or set()))
    if (not marker.exists()) or (not current) or (not cur_ok):
        try:
            mf.write_text(model)
            marker.write_text('1')
            log.info('[ollama] default model set to %r', model)
        except Exception:
            _exc('[ollama] set default model')
    else:
        log.info('[ollama] keeping user-selected model %r', current)


def _nm_ensure_ollama():
    """Best-effort: if the AI provider is local Ollama and its server isn't
    already listening, launch `ollama serve` in the background so the app's AI
    features work without the user starting it by hand. Silent no-op if Ollama
    isn't installed, the provider isn't Ollama, or the server is already up.
    Runs on a daemon thread; the spawned server is detached so it survives."""
    import os, time, shutil, subprocess, urllib.request
    from pathlib import Path
    try:
        pf = Path.home() / '.nm_ai_provider'
        provider = (pf.read_text().strip().lower() if pf.exists() else 'ollama')
    except Exception:
        provider = 'ollama'
    if provider not in ('ollama', 'local'):
        return
    try:
        uf = Path.home() / '.nm_ai_url'
        base = ((uf.read_text().strip() if uf.exists() else '')
                or 'http://localhost:11434').rstrip('/')
    except Exception:
        base = 'http://localhost:11434'

    def _up():
        try:
            with urllib.request.urlopen(base + '/api/tags', timeout=2) as r:
                r.read(1); return True
        except Exception:
            return False

    if _up():
        log.info('[ollama] already running')
        _nm_ensure_model(base, _nm_find_ollama())
        return
    exe = _nm_find_ollama()
    if not exe:
        log.warning('[ollama] binary not found on PATH or in the usual install '
                    'locations; skipping auto-start (install from ollama.com)')
        return
    log.info('[ollama] using binary: %s', exe)
    try:
        kw = {'stdout': subprocess.DEVNULL, 'stderr': subprocess.DEVNULL,
              'stdin': subprocess.DEVNULL}
        if os.name == 'nt':
            kw['creationflags'] = (getattr(subprocess, 'CREATE_NO_WINDOW', 0) |
                                   getattr(subprocess, 'DETACHED_PROCESS', 0))
        else:
            kw['start_new_session'] = True
        subprocess.Popen([exe, 'serve'], **kw)
        log.info('[ollama] launched `ollama serve`')
    except Exception:
        _exc('[ollama] auto-start')
        return
    for _ in range(30):          # wait up to ~15s for it to come up
        time.sleep(0.5)
        if _up():
            log.info('[ollama] server is up')
            _nm_ensure_model(base, exe)
            return
    log.info('[ollama] did not report ready within timeout')



