      +'border:1px solid #7a1f1f;border-radius:6px;background:rgba(120,20,10,'+(0.42*op).toFixed(2)+');'
      +'color:#ffb3a0;font-size:11px;white-space:nowrap">\u2620 BLOCKED '
      +esc(b.city)+' <span style="color:#ff8a7a">'+esc(b.ip)+'</span>'
